static bool TryApplyV82OverlayDescriptorForNaturalCall(uintptr_t contextAddress)
{
    InterlockedIncrement(&g_v82OverlaySearchAttempts);

    HMODULE exe = GetModuleHandleA(nullptr);
    if (!exe || getGameVersion() != 1012)
        return false;

    uint8_t* base = reinterpret_cast<uint8_t*>(exe);
    uint8_t* end = nullptr;

    __try
    {
        const IMAGE_DOS_HEADER* dos =
            reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
        if (dos->e_magic != IMAGE_DOS_SIGNATURE)
            return false;

        const IMAGE_NT_HEADERS64* nt =
            reinterpret_cast<const IMAGE_NT_HEADERS64*>(base + dos->e_lfanew);
        if (nt->Signature != IMAGE_NT_SIGNATURE)
            return false;

        end = base + nt->OptionalHeader.SizeOfImage;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        return false;
    }

    uintptr_t record = 0;
    uint32_t currentGroup = 0;
    uint32_t flags = 0;
    uint32_t exactHits = 0;
    uintptr_t windowStart = 0;
    uintptr_t windowEnd = 0;
    uint64_t bytesScanned = 0;
    uint32_t regionsScanned = 0;

    const bool unique =
        ScanExactBennyDescriptorNearSetup2Context(
            contextAddress,
            record,
            currentGroup,
            flags,
            exactHits,
            windowStart,
            windowEnd,
            bytesScanned,
            regionsScanned);

    g_v82OverlayObservedExactHits = exactHits;
    g_v82OverlayRecord = record;
    g_v82OverlayOriginalGroup = currentGroup;
    g_v83OverlaySearchWindowStart = windowStart;
    g_v83OverlaySearchWindowEnd = windowEnd;
    g_v83OverlayBytesScanned = bytesScanned;
    g_v83OverlayRegionsScanned = regionsScanned;
    g_v83OverlayMatchedFlags = flags;

    if (!unique || !record)
        return false;

    InterlockedIncrement(&g_v82OverlayUniqueHits);

    constexpr uint32_t groupMap = 0xBCC89179U;
    constexpr uint32_t groupMapSp = 0x578F99E2U;

    if (currentGroup == groupMapSp)
    {
        g_v82OverlayGroupAddress = record + 0x0C;
        g_v82OverlayGroupDuringCall = groupMapSp;
        return true;
    }

    if (currentGroup != groupMap)
        return false;

    const uintptr_t groupAddress = record + 0x0C;
    MEMORY_BASIC_INFORMATION mbi{};
    if (VirtualQuery(
            reinterpret_cast<LPCVOID>(groupAddress),
            &mbi,
            sizeof(mbi)) == 0
        || mbi.State != MEM_COMMIT
        || mbi.Type == MEM_IMAGE)
    {
        return false;
    }

    DWORD oldProtect = 0;
    bool changedProtect = false;
    const DWORD protection = mbi.Protect & 0xFFU;
    const bool writable =
        protection == PAGE_READWRITE
        || protection == PAGE_WRITECOPY
        || protection == PAGE_EXECUTE_READWRITE
        || protection == PAGE_EXECUTE_WRITECOPY;

    if (!writable)
    {
        changedProtect =
            VirtualProtect(
                reinterpret_cast<LPVOID>(groupAddress),
                sizeof(uint32_t),
                PAGE_READWRITE,
                &oldProtect) != FALSE;
        if (!changedProtect)
            return false;
    }

    bool wrote = false;
    __try
    {
        memcpy(
            reinterpret_cast<void*>(groupAddress),
            &groupMapSp,
            sizeof(groupMapSp));
        wrote = true;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        wrote = false;
    }

    if (changedProtect)
    {
        DWORD ignored = 0;
        VirtualProtect(
            reinterpret_cast<LPVOID>(groupAddress),
            sizeof(uint32_t),
            oldProtect,
            &ignored);
    }

    if (!wrote)
    {
        InterlockedIncrement(&g_v82OverlayWriteFaults);
        return false;
    }

    uint32_t verify = 0;
    __try
    {
        memcpy(
            &verify,
            reinterpret_cast<const void*>(groupAddress),
            sizeof(verify));
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        verify = 0;
    }

    if (verify != groupMapSp)
    {
        InterlockedIncrement(&g_v82OverlayWriteFaults);
        return false;
    }

    g_v82OverlayGroupAddress = groupAddress;
    g_v82OverlayGroupDuringCall = verify;
    InterlockedIncrement(&g_v82OverlayAppliedHits);
    return true;
}

static bool RestoreV82OverlayDescriptorAfterNaturalCall()
{
    if (!g_v82OverlayGroupAddress)
        return false;

    if (g_v82OverlayOriginalGroup == 0x578F99E2U)
        return true;

    if (g_v82OverlayOriginalGroup != 0xBCC89179U)
        return false;

    InterlockedIncrement(&g_v82OverlayRestoreAttempts);

    MEMORY_BASIC_INFORMATION mbi{};
    if (VirtualQuery(
            reinterpret_cast<LPCVOID>(g_v82OverlayGroupAddress),
            &mbi,
            sizeof(mbi)) == 0
        || mbi.State != MEM_COMMIT
        || mbi.Type == MEM_IMAGE)
    {
        InterlockedIncrement(&g_v82OverlayRestoreFailures);
        return false;
    }

    DWORD oldProtect = 0;
    bool changedProtect = false;
    const DWORD protection = mbi.Protect & 0xFFU;
    const bool writable =
        protection == PAGE_READWRITE
        || protection == PAGE_WRITECOPY
        || protection == PAGE_EXECUTE_READWRITE
        || protection == PAGE_EXECUTE_WRITECOPY;

    if (!writable)
    {
        changedProtect =
            VirtualProtect(
                reinterpret_cast<LPVOID>(g_v82OverlayGroupAddress),
                sizeof(uint32_t),
                PAGE_READWRITE,
                &oldProtect) != FALSE;
        if (!changedProtect)
        {
            InterlockedIncrement(&g_v82OverlayRestoreFailures);
            return false;
        }
    }

    bool restored = false;
    __try
    {
        memcpy(
            reinterpret_cast<void*>(g_v82OverlayGroupAddress),
            &g_v82OverlayOriginalGroup,
            sizeof(g_v82OverlayOriginalGroup));

        uint32_t verify = 0;
        memcpy(
            &verify,
            reinterpret_cast<const void*>(g_v82OverlayGroupAddress),
            sizeof(verify));
        restored = verify == g_v82OverlayOriginalGroup;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        restored = false;
    }

    if (changedProtect)
    {
        DWORD ignored = 0;
        VirtualProtect(
            reinterpret_cast<LPVOID>(g_v82OverlayGroupAddress),
            sizeof(uint32_t),
            oldProtect,
            &ignored);
    }

    if (restored)
        InterlockedIncrement(&g_v82OverlayRestoreVerifiedHits);
    else
        InterlockedIncrement(&g_v82OverlayRestoreFailures);

    return restored;
}

