static bool IsEnhancedExecutableImage()
{
    char path[MAX_PATH]{};
    const DWORD length =
        GetModuleFileNameA(
            GetModuleHandleA(nullptr),
            path,
            MAX_PATH);

    if (length == 0
        || length >= MAX_PATH)
    {
        return false;
    }

    const char* fileName = strrchr(path, '\\');
    fileName = fileName ? fileName + 1 : path;

    return _stricmp(
        fileName,
        "GTA5_Enhanced.exe") == 0;
}

static bool IsLegacyExecutableImage()
{
    char path[MAX_PATH]{};
    const DWORD length =
        GetModuleFileNameA(
            GetModuleHandleA(nullptr),
            path,
            MAX_PATH);

    if (length == 0
        || length >= MAX_PATH)
    {
        return false;
    }

    const char* fileName = strrchr(path, '\\');
    fileName = fileName ? fileName + 1 : path;

    return _stricmp(
        fileName,
        "GTA5.exe") == 0;
}

struct EarlyConstructionSnapshot
{
    bool attempted = false;
    bool imageValidated = false;
    bool faulted = false;
    uintptr_t exeBase = 0;
    uintptr_t mapState = 0;
    uintptr_t childArray = 0;
    uint16_t childCount = 0;
    uintptr_t child64 = 0;
    uintptr_t child64Table = 0;
    uint16_t child64Count = 0;
    uint16_t child64Capacity = 0;
    bool exactBennyPairPresent = false;

    EarlyConstructionSnapshot()
    {
        if (!IsEnhancedExecutableImage())
            return;

        attempted = true;

        HMODULE exe = GetModuleHandleA(nullptr);
        if (!exe)
            return;

        exeBase = reinterpret_cast<uintptr_t>(exe);

        __try
        {
            const IMAGE_DOS_HEADER* dos =
                reinterpret_cast<const IMAGE_DOS_HEADER*>(exeBase);
            if (dos->e_magic != IMAGE_DOS_SIGNATURE)
                return;

            const IMAGE_NT_HEADERS64* nt =
                reinterpret_cast<const IMAGE_NT_HEADERS64*>(
                    exeBase + dos->e_lfanew);
            if (nt->Signature != IMAGE_NT_SIGNATURE)
                return;

            const uint64_t imageSize =
                static_cast<uint64_t>(nt->OptionalHeader.SizeOfImage);

            const uint64_t mapStateGlobalRva =
                0x029CAFC8ULL;

            if (mapStateGlobalRva + sizeof(uintptr_t) > imageSize)
                return;

            imageValidated = true;

            memcpy(
                &mapState,
                reinterpret_cast<const void*>(
                    exeBase + mapStateGlobalRva),
                sizeof(mapState));

            if (!mapState)
                return;

            memcpy(
                &childArray,
                reinterpret_cast<const void*>(mapState + 0x28),
                sizeof(childArray));
            memcpy(
                &childCount,
                reinterpret_cast<const void*>(mapState + 0x30),
                sizeof(childCount));

            if (!childArray
                || childCount <= 64
                || childCount > 4096)
                return;

            child64 =
                childArray
                + (static_cast<uintptr_t>(64) * 0x120);

            memcpy(
                &child64Table,
                reinterpret_cast<const void*>(child64 + 0x108),
                sizeof(child64Table));
            memcpy(
                &child64Count,
                reinterpret_cast<const void*>(child64 + 0x110),
                sizeof(child64Count));
            memcpy(
                &child64Capacity,
                reinterpret_cast<const void*>(child64 + 0x112),
                sizeof(child64Capacity));

            if (!child64Table
                || child64Count == 0
                || child64Count > 4096)
                return;

            for (uint16_t i = 0;
                 i < child64Count;
                 ++i)
            {
                uint32_t pair[2]{};
                memcpy(
                    pair,
                    reinterpret_cast<const void*>(
                        child64Table
                        + (static_cast<uintptr_t>(i) * 8)),
                    sizeof(pair));

                if (pair[0] == 0x578F99E2U
                    && pair[1] == 0x4CDFC843U)
                {
                    exactBennyPairPresent = true;
                    break;
                }
            }
        }
        __except(EXCEPTION_EXECUTE_HANDLER)
        {
            faulted = true;
        }
    }
};

