static void LogSetup2LoaderChild64Resolution(
    const char* phase)
{
    HMODULE exe = GetModuleHandleA(nullptr);
    if (!exe)
        return;

    uintptr_t mapState = 0;
    uintptr_t childArray = 0;
    uint16_t childCount = 0;

    __try
    {
        memcpy(
            &mapState,
            reinterpret_cast<uint8_t*>(exe)
                + 0x029CAFC8ULL,
            sizeof(mapState));
        if (!mapState)
            return;

        memcpy(
            &childArray,
            reinterpret_cast<const void*>(
                mapState + 0x28),
            sizeof(childArray));
        memcpy(
            &childCount,
            reinterpret_cast<const void*>(
                mapState + 0x30),
            sizeof(childCount));
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        return;
    }

    if (!childArray
        || childCount <= 64
        || childCount > 4096)
    {
        return;
    }

    const uintptr_t child64 =
        childArray
        + (static_cast<uintptr_t>(64) * 0x120);

    const LONG historyCountRaw =
        g_setup2LoaderCallHistoryCount;
    const LONG historyCapacity =
        static_cast<LONG>(
            sizeof(g_setup2LoaderCallHistory)
            / sizeof(g_setup2LoaderCallHistory[0]));
    const LONG historyCount =
        historyCountRaw < historyCapacity
            ? historyCountRaw
            : historyCapacity;

    int exactMatches = 0;
    for (LONG i = 0; i < historyCount; ++i)
    {
        const Setup2CallObservation& observation =
            g_setup2LoaderCallHistory[i];
        if (observation.context != child64)
            continue;

        ++exactMatches;
        Logf(
            "[Setup2Child64] %s EXACT final-child64 match call=%ld sequence=%ld sequenceIndex=%ld context=%p callerArg2=0x%08X field80=0x%08X state100=%u->%u table108=%p count110=%u capacity112=%u result=%s.",
            phase ? phase : "state",
            static_cast<long>(observation.callNumber),
            static_cast<long>(observation.sequence),
            static_cast<long>(observation.sequenceIndex),
            reinterpret_cast<void*>(observation.context),
            observation.callerArg2,
            observation.field80,
            observation.state100Before,
            observation.state100After,
            reinterpret_cast<void*>(observation.table108After),
            static_cast<unsigned int>(
                observation.count110After),
            static_cast<unsigned int>(
                observation.capacity112After),
            observation.result ? "true" : "false");
    }

    Logf(
        "[Setup2Child64] %s final mapState=%p childArray=%p childCount=%u child64=%p exactHistoryMatches=%d historyStored=%ld historySeen=%ld.",
        phase ? phase : "state",
        reinterpret_cast<void*>(mapState),
        reinterpret_cast<void*>(childArray),
        static_cast<unsigned int>(childCount),
        reinterpret_cast<void*>(child64),
        exactMatches,
        static_cast<long>(historyCount),
        static_cast<long>(historyCountRaw));
}

static void LogSetup2LoaderProbeState(
    const char* phase)
{
    Logf(
        "[Setup2SequenceProbe] %s attempted=%s installed=%s prefixVerified=%s callsiteVerified=%s mapStateWasNullAtInstall=%s failure=%lu(%s) trampoline=%p totalCalls=%ld sequences=%ld currentSequenceIndex=%ld child64CandidateCalls=%ld scans=%ld timingAttempts=%ld targetPhase=%ld timingExactHits=%u timingRewriteAttempted=%s timingRewriteVerified=%s lastScanCall=%ld lastContext=%p lastResult=%s postMapState=%p targetFound=%s targetCall=%ld targetSequence=%ld targetSequenceIndex=%ld targetMapState=%p record=%p group=0x%08X flags=0x%08X scanWindow=%p..%p scanned=%llu MiB regions=%u.",
        phase ? phase : "state",
        g_setup2LoaderHookAttempted ? "yes" : "no",
        g_setup2LoaderHookInstalled ? "yes" : "no",
        g_setup2LoaderPrefixVerified ? "yes" : "no",
        g_setup2LoaderCallsiteVerified ? "yes" : "no",
        g_setup2LoaderMapStateWasNull ? "yes" : "no",
        static_cast<unsigned long>(
            g_setup2LoaderFailureCode),
        GetSetup2LoaderHookFailureReason(),
        g_setup2LoaderTrampoline,
        static_cast<long>(
            g_setup2LoaderTotalCalls),
        static_cast<long>(
            InterlockedCompareExchange(
                &g_setup2LoaderCurrentSequence,
                0,
                0)),
        static_cast<long>(
            g_setup2LoaderCurrentSequenceIndex),
        static_cast<long>(
            g_setup2LoaderChild64CandidateCalls),
        static_cast<long>(
            g_setup2LoaderDescriptorScans),
        static_cast<long>(
            g_setup2LoaderTimingScanAttempts),
        static_cast<long>(
            g_setup2LoaderTargetScanPhase),
        g_setup2LoaderTimingExactHits,
        g_setup2LoaderTimingRewriteAttempted ? "yes" : "no",
        g_setup2LoaderTimingRewriteVerified ? "yes" : "no",
        static_cast<long>(
            g_setup2LoaderLastScanCall),
        reinterpret_cast<void*>(
            g_setup2LoaderLastContext),
        g_setup2LoaderLastResult ? "true" : "false",
        reinterpret_cast<void*>(
            g_setup2LoaderPostMapState),
        g_setup2LoaderTargetFound ? "yes" : "no",
        static_cast<long>(
            g_setup2LoaderTargetCall),
        static_cast<long>(
            g_setup2LoaderTargetSequence),
        static_cast<long>(
            g_setup2LoaderTargetSequenceIndex),
        reinterpret_cast<void*>(
            g_setup2LoaderTargetMapState),
        reinterpret_cast<void*>(
            g_setup2LoaderTargetRecord),
        g_setup2LoaderTargetGroup,
        g_setup2LoaderTargetFlags,
        reinterpret_cast<void*>(
            g_setup2LoaderScanWindowStart),
        reinterpret_cast<void*>(
            g_setup2LoaderScanWindowEnd),
        static_cast<unsigned long long>(
            g_setup2LoaderBytesScanned
                / (1024ULL * 1024ULL)),
        static_cast<unsigned int>(
            g_setup2LoaderRegionsScanned));

    const LONG historyCountRaw =
        g_setup2LoaderCallHistoryCount;
    const LONG historyCapacity =
        static_cast<LONG>(
            sizeof(g_setup2LoaderCallHistory)
            / sizeof(g_setup2LoaderCallHistory[0]));
    const LONG historyCount =
        historyCountRaw < historyCapacity
            ? historyCountRaw
            : historyCapacity;

    for (LONG i = 0; i < historyCount; ++i)
    {
        const Setup2CallObservation& observation =
            g_setup2LoaderCallHistory[i];
        if (observation.sequenceIndex != 64)
            continue;

        Logf(
            "[Setup2SequenceProbe] child64-candidate call=%ld sequence=%ld context=%p callerArg2=0x%08X field80=0x%08X state100=%u->%u table108=%p count110=%u capacity112=%u result=%s.",
            static_cast<long>(observation.callNumber),
            static_cast<long>(observation.sequence),
            reinterpret_cast<void*>(observation.context),
            observation.callerArg2,
            observation.field80,
            observation.state100Before,
            observation.state100After,
            reinterpret_cast<void*>(observation.table108After),
            static_cast<unsigned int>(
                observation.count110After),
            static_cast<unsigned int>(
                observation.capacity112After),
            observation.result ? "true" : "false");
    }

    if (g_setup2LoaderTargetFound)
    {
        Logf(
            "[Setup2SequenceProbe] CONSTRUCTION descriptor target captured phase=%s C2A890 call=%ld sequence=%ld index=%ld originalGroup=%s record=%p mapStateAtCapture=%p exactHits=%u rewriteAttempted=%s rewriteVerified=%s.",
            g_setup2LoaderTargetScanPhase == 1
                ? "pre"
                : (g_setup2LoaderTargetScanPhase == 2
                    ? "post"
                    : "unknown"),
            static_cast<long>(
                g_setup2LoaderTargetCall),
            static_cast<long>(
                g_setup2LoaderTargetSequence),
            static_cast<long>(
                g_setup2LoaderTargetSequenceIndex),
            g_setup2LoaderTargetGroup
                    == 0x578F99E2U
                ? "GROUP_MAP_SP"
                : "GROUP_MAP",
            reinterpret_cast<void*>(
                g_setup2LoaderTargetRecord),
            reinterpret_cast<void*>(
                g_setup2LoaderTargetMapState),
            g_setup2LoaderTimingExactHits,
            g_setup2LoaderTimingRewriteAttempted ? "yes" : "no",
            g_setup2LoaderTimingRewriteVerified ? "yes" : "no");
    }

    LogSetup2LoaderChild64Resolution(phase);
}

static void TryV38ConstructionInsertAfterStockBaseline(
    void* child,
    RockstarGroupPairMutator1012 original)
{
    if (!child
        || !original
        || InterlockedCompareExchange(
               &g_v38ConstructionInsertState,
               0,
               0) != 0)
    {
        return;
    }

    uint32_t field80 = 0;
    uintptr_t tableBefore = 0;
    uint16_t countBefore = 0;
    uint16_t capacityBefore = 0;
    uint32_t entry0First = 0;
    uint32_t entry0Second = 0;
    uint32_t entry1First = 0;
    uint32_t entry1Second = 0;

    __try
    {
        uint8_t* p =
            reinterpret_cast<uint8_t*>(child);

        memcpy(&field80, p + 0x80, sizeof(field80));
        memcpy(&tableBefore, p + 0x108, sizeof(tableBefore));
        memcpy(&countBefore, p + 0x110, sizeof(countBefore));
        memcpy(&capacityBefore, p + 0x112, sizeof(capacityBefore));

        if (field80 != 0x61322A35U)
            return;

        InterlockedIncrement(
            &g_v38LowriderPostCalls);

        if (!tableBefore
            || countBefore != 2)
        {
            return;
        }

        memcpy(&entry0First, reinterpret_cast<const void*>(tableBefore + 0), sizeof(entry0First));
        memcpy(&entry0Second, reinterpret_cast<const void*>(tableBefore + 4), sizeof(entry0Second));
        memcpy(&entry1First, reinterpret_cast<const void*>(tableBefore + 8), sizeof(entry1First));
        memcpy(&entry1Second, reinterpret_cast<const void*>(tableBefore + 12), sizeof(entry1Second));
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        return;
    }

    if (entry0First != 0x5BF6578FU
        || entry0Second != 0xA0DF2C6FU
        || entry1First != 0x5BF6578FU
        || entry1Second != 0x37B569AAU)
    {
        return;
    }

    InterlockedIncrement(
        &g_v38ExactBaselineHits);

    if (InterlockedCompareExchange(
            &g_v38ConstructionInsertState,
            1,
            0) != 0)
    {
        return;
    }

    g_v38InsertChild = reinterpret_cast<uintptr_t>(child);
    g_v38InsertTableBefore = tableBefore;
    g_v38InsertCountBefore = countBefore;
    g_v38InsertCapacityBefore = capacityBefore;

    uint32_t storyGroup = 0x578F99E2U;
    uint32_t bennyKey = 0x4CDFC843U;

    __try
    {
        original(
            child,
            &storyGroup,
            &bennyKey,
            true);
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        InterlockedExchange(
            &g_v38ConstructionInsertState,
            4);
        return;
    }

    uintptr_t tableAfter = 0;
    uint16_t countAfter = 0;
    uint16_t capacityAfter = 0;
    uint32_t entry0AfterFirst = 0;
    uint32_t entry0AfterSecond = 0;
    uint32_t entry1AfterFirst = 0;
    uint32_t entry1AfterSecond = 0;
    uint32_t entry2First = 0;
    uint32_t entry2Second = 0;
    bool verified = false;

    __try
    {
        uint8_t* p =
            reinterpret_cast<uint8_t*>(child);

        memcpy(&tableAfter, p + 0x108, sizeof(tableAfter));
        memcpy(&countAfter, p + 0x110, sizeof(countAfter));
        memcpy(&capacityAfter, p + 0x112, sizeof(capacityAfter));

        if (tableAfter
            && countAfter == 3)
        {
            memcpy(&entry0AfterFirst, reinterpret_cast<const void*>(tableAfter + 0), sizeof(entry0AfterFirst));
            memcpy(&entry0AfterSecond, reinterpret_cast<const void*>(tableAfter + 4), sizeof(entry0AfterSecond));
            memcpy(&entry1AfterFirst, reinterpret_cast<const void*>(tableAfter + 8), sizeof(entry1AfterFirst));
            memcpy(&entry1AfterSecond, reinterpret_cast<const void*>(tableAfter + 12), sizeof(entry1AfterSecond));
            memcpy(&entry2First, reinterpret_cast<const void*>(tableAfter + 16), sizeof(entry2First));
            memcpy(&entry2Second, reinterpret_cast<const void*>(tableAfter + 20), sizeof(entry2Second));

            verified =
                entry0AfterFirst == 0x5BF6578FU
                && entry0AfterSecond == 0xA0DF2C6FU
                && entry1AfterFirst == 0x5BF6578FU
                && entry1AfterSecond == 0x37B569AAU
                && entry2First == 0x578F99E2U
                && entry2Second == 0x4CDFC843U;
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        verified = false;
    }

    g_v38InsertTableAfter = tableAfter;
    g_v38InsertCountAfter = countAfter;
    g_v38InsertCapacityAfter = capacityAfter;
    g_v38InsertEntry2Group = entry2First;
    g_v38InsertEntry2Key = entry2Second;

    InterlockedExchange(
        &g_v38ConstructionInsertState,
        verified ? 2 : 3);
}

static void ConstructionC2F090Detour(
    void* child,
    uint32_t* first,
    uint32_t* second,
    bool addPair)
{
    InterlockedIncrement(
        &g_constructionHookTotalCalls);

    if (addPair)
        InterlockedIncrement(
            &g_constructionHookAddCalls);

    uint32_t firstValue = 0;
    uint32_t secondValue = 0;
    bool valuesReadable = false;

    __try
    {
        if (first && second)
        {
            firstValue = *first;
            secondValue = *second;
            valuesReadable = true;
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        valuesReadable = false;
    }

    if (valuesReadable)
    {
        if (firstValue == 0xBCC89179U)
            InterlockedIncrement(
                &g_constructionHookMapGroupCalls);
        else if (firstValue == 0x578F99E2U)
            InterlockedIncrement(
                &g_constructionHookStoryMapGroupCalls);

        if (secondValue == 0x4CDFC843U)
        {
            InterlockedIncrement(
                &g_constructionHookBennyCalls);

            g_constructionHookSawBenny = true;
            g_constructionHookBennyOriginalGroup =
                firstValue;
            g_constructionHookBennyChild =
                reinterpret_cast<uintptr_t>(child);

            if (firstValue == 0xBCC89179U)
                g_constructionHookSawBennyAsMap = true;
            else if (firstValue == 0x578F99E2U)
                g_constructionHookSawBennyAsStoryMap = true;
        }
    }

    RockstarGroupPairMutator1012 original =
        g_constructionOriginalC2F090;

    if (!original)
        return;

    if (g_constructionHookAllowRewrite
        && addPair
        && valuesReadable
        && firstValue == 0xBCC89179U
        && secondValue == 0x4CDFC843U)
    {
        uint32_t storyGroup =
            0x578F99E2U;

        g_constructionHookRewroteBenny = true;

        original(
            child,
            &storyGroup,
            second,
            addPair);
        return;
    }

    original(
        child,
        first,
        second,
        addPair);

}

static void InstallConstructionC2F090HookAtModuleLoad()
{
    if (!IsEnhancedExecutableImage())
        return;

    g_constructionHookAttempted = true;

    HMODULE exe =
        GetModuleHandleA(nullptr);
    if (!exe)
    {
        g_constructionHookFailureCode = 1;
        return;
    }

    uint8_t* base =
        reinterpret_cast<uint8_t*>(exe);

    __try
    {
        const IMAGE_DOS_HEADER* dos =
            reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
        if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        {
            g_constructionHookFailureCode = 2;
            return;
        }

        const IMAGE_NT_HEADERS64* nt =
            reinterpret_cast<const IMAGE_NT_HEADERS64*>(
                base + dos->e_lfanew);
        if (nt->Signature != IMAGE_NT_SIGNATURE)
        {
            g_constructionHookFailureCode = 3;
            return;
        }

        const uint64_t imageSize =
            static_cast<uint64_t>(
                nt->OptionalHeader.SizeOfImage);

        const uint64_t mutatorRva =
            0x00C2F090ULL;
        const uint64_t callsiteRva =
            0x00C27E6FULL;
        const uint64_t mapStateGlobalRva =
            0x029CAFC8ULL;

        if (mutatorRva + 32 > imageSize
            || callsiteRva + 5 > imageSize
            || mapStateGlobalRva + sizeof(uintptr_t) > imageSize)
        {
            g_constructionHookFailureCode = 4;
            return;
        }

        static const uint8_t expectedPrefix[16] =
        {
            0x41, 0x57,
            0x41, 0x56,
            0x41, 0x55,
            0x41, 0x54,
            0x56,
            0x57,
            0x55,
            0x53,
            0x48, 0x83, 0xEC, 0x28
        };

        uint8_t* mutator =
            base + mutatorRva;

        if (memcmp(
                mutator,
                expectedPrefix,
                sizeof(expectedPrefix)) != 0)
        {
            g_constructionHookFailureCode = 5;
            return;
        }

        g_constructionHookSignatureVerified =
            true;

        uint8_t* callsite =
            base + callsiteRva;

        if (callsite[0] != 0xE8)
        {
            g_constructionHookFailureCode = 6;
            return;
        }

        int32_t relative = 0;
        memcpy(
            &relative,
            callsite + 1,
            sizeof(relative));

        uint8_t* resolved =
            callsite + 5 + relative;

        if (resolved != mutator)
        {
            g_constructionHookFailureCode = 7;
            return;
        }

        g_constructionHookCallsiteVerified =
            true;

        uintptr_t mapState = 0;
        memcpy(
            &mapState,
            base + mapStateGlobalRva,
            sizeof(mapState));

        g_constructionHookMapStateWasNull =
            (mapState == 0);

        if (mapState != 0)
        {
            g_constructionHookFailureCode = 8;
            return;
        }

        constexpr size_t stolenSize =
            16;
        constexpr size_t trampolineSize =
            stolenSize + 16;

        uint8_t* trampoline =
            reinterpret_cast<uint8_t*>(
                VirtualAlloc(
                    nullptr,
                    trampolineSize,
                    MEM_COMMIT | MEM_RESERVE,
                    PAGE_EXECUTE_READWRITE));

        if (!trampoline)
        {
            g_constructionHookFailureCode = 9;
            return;
        }

        memcpy(
            trampoline,
            mutator,
            stolenSize);

        WriteAbsoluteJump12(
            trampoline + stolenSize,
            mutator + stolenSize);

        for (size_t i = stolenSize + 12;
             i < trampolineSize;
             ++i)
        {
            trampoline[i] = 0x90;
        }

        FlushInstructionCache(
            GetCurrentProcess(),
            trampoline,
            trampolineSize);

        g_constructionHookTrampoline =
            trampoline;
        g_constructionOriginalC2F090 =
            reinterpret_cast<RockstarGroupPairMutator1012>(
                trampoline);

        uint8_t patch[stolenSize]{};
        WriteAbsoluteJump12(
            patch,
            reinterpret_cast<const void*>(
                &ConstructionC2F090Detour));

        for (size_t i = 12;
             i < stolenSize;
             ++i)
        {
            patch[i] = 0x90;
        }

        DWORD oldProtect = 0;
        if (!VirtualProtect(
                mutator,
                stolenSize,
                PAGE_EXECUTE_READWRITE,
                &oldProtect))
        {
            g_constructionOriginalC2F090 = nullptr;
            g_constructionHookTrampoline = nullptr;
            VirtualFree(
                trampoline,
                0,
                MEM_RELEASE);
            g_constructionHookFailureCode = 10;
            return;
        }

        memcpy(
            mutator,
            patch,
            stolenSize);

        FlushInstructionCache(
            GetCurrentProcess(),
            mutator,
            stolenSize);

        DWORD ignoredProtect = 0;
        VirtualProtect(
            mutator,
            stolenSize,
            oldProtect,
            &ignoredProtect);

        g_constructionHookInstalled =
            true;
        g_constructionHookFailureCode = 0;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        g_constructionHookFailureCode = 11;
    }
}

