static const char* GetConstructionHookFailureReason()
{
    switch (g_constructionHookFailureCode)
    {
    case 0:  return "none";
    case 1:  return "exe-module-unavailable";
    case 2:  return "bad-dos-signature";
    case 3:  return "bad-nt-signature";
    case 4:  return "verified-rva-outside-image";
    case 5:  return "C2F090-prefix-mismatch";
    case 6:  return "C27E6F-not-E8";
    case 7:  return "C27E6F-target-mismatch";
    case 8:  return "mapState-already-constructed";
    case 9:  return "trampoline-allocation-failed";
    case 10: return "VirtualProtect-failed";
    case 11: return "seh-exception";
    default: return "unknown";
    }
}

