static bool VerifyV46BennyPairOnChild(
    void* child)
{
    if (!child)
        return false;

    __try
    {
        uint8_t* p =
            reinterpret_cast<uint8_t*>(child);

        uintptr_t table = 0;
        uint16_t count = 0;

        memcpy(
            &table,
            p + 0x108,
            sizeof(table));
        memcpy(
            &count,
            p + 0x110,
            sizeof(count));

        if (!table
            || count == 0
            || count > 4096)
        {
            return false;
        }

        for (uint16_t i = 0;
             i < count;
             ++i)
        {
            uint32_t pair[2]{};
            memcpy(
                pair,
                reinterpret_cast<const void*>(
                    table
                    + (static_cast<uintptr_t>(i) * 8)),
                sizeof(pair));

            if (pair[0] == 0x578F99E2U
                && pair[1] == 0x4CDFC843U)
            {
                return true;
            }
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        return false;
    }

    return false;
}

static uintptr_t V46C27740SourcePairDetour(
    void* child,
    uint32_t* group,
    uint32_t* associated)
{
    const LONG globalCallNumber =
        InterlockedIncrement(
            &g_v46C27740TotalCalls);

    const uintptr_t callerReturn =
        reinterpret_cast<uintptr_t>(
            _ReturnAddress());
    const uintptr_t callsite =
        callerReturn >= 5
            ? callerReturn - 5
            : 0;

    uint32_t field80 = 0;
    uint32_t groupValue = 0;
    uint32_t associatedValue = 0;
    bool readable = false;

    __try
    {
        if (child
            && group
            && associated)
        {
            uint8_t* p =
                reinterpret_cast<uint8_t*>(
                    child);

            memcpy(
                &field80,
                p + 0x80,
                sizeof(field80));

            groupValue = *group;
            associatedValue = *associated;
            readable = true;
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        readable = false;
    }

    if (readable
        && field80 == 0x61322A35U)
    {
        const LONG lowriderOrdinal =
            InterlockedIncrement(
                &g_v46LowriderCalls);

        const LONG slot =
            InterlockedIncrement(
                &g_v50LowriderObservationCount)
            - 1;

        if (slot >= 0
            && slot < static_cast<LONG>(
                sizeof(g_v50LowriderCallerObservations)
                / sizeof(g_v50LowriderCallerObservations[0])))
        {
            V50LowriderCallerObservation& o =
                g_v50LowriderCallerObservations[slot];

            o.globalCallNumber =
                globalCallNumber;
            o.lowriderOrdinal =
                lowriderOrdinal;
            o.callerReturn =
                callerReturn;
            o.callsite =
                callsite;
            o.child =
                reinterpret_cast<uintptr_t>(
                    child);
            o.group =
                groupValue;
            o.associated =
                associatedValue;
        }

        if (groupValue == 0x5BF6578FU
            && associatedValue == 0x37B569AAU)
        {
            InterlockedIncrement(
                &g_v46TriggerPairHits);

            g_v50TriggerCallerReturn =
                callerReturn;
            g_v50TriggerCallsite =
                callsite;
            g_v50TriggerGlobalCallNumber =
                globalCallNumber;
        }
    }

    RockstarGroupPairProcessor1012 original =
        g_v46OriginalC27740;

    if (!original)
        return 0;

    uintptr_t originalResult = 0;

    __try
    {

        originalResult =
            original(
                child,
                group,
                associated);
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        return 0;
    }

    return originalResult;
}

