static bool FindEnhancedV93UniqueDirectCall(
    uint8_t* functionStart,
    uint8_t* functionEnd,
    uint8_t* target,
    uint8_t*& callsite,
    uint32_t& matches)
{
    callsite = nullptr;
    matches = 0;

    if (!functionStart
        || !functionEnd
        || functionEnd <= functionStart
        || !target)
    {
        return false;
    }

    for (uint8_t* p = functionStart;
         p + 5 <= functionEnd;
         ++p)
    {
        if (p[0] != 0xE8)
            continue;

        int32_t relative = 0;
        memcpy(
            &relative,
            p + 1,
            sizeof(relative));

        if (p + 5 + relative != target)
            continue;

        ++matches;
        if (matches == 1)
            callsite = p;
    }

    return matches == 1 && callsite != nullptr;
}

static bool ValidateEnhancedV94DirectCallsite(
    uint8_t* functionStart,
    uint8_t* functionEnd,
    uint8_t* callsite,
    uint8_t* expectedTarget)
{
    if (!functionStart
        || !functionEnd
        || functionEnd <= functionStart
        || !callsite
        || !expectedTarget
        || callsite < functionStart
        || callsite + 5 > functionEnd
        || callsite[0] != 0xE8)
    {
        return false;
    }

    int32_t relative = 0;
    memcpy(
        &relative,
        callsite + 1,
        sizeof(relative));

    return callsite + 5 + relative
        == expectedTarget;
}

static bool ResolveEnhancedV93StructuralPathAtModuleLoad()
{
    g_enhancedV93 = EnhancedV93StructuralSemanticState{};
    g_enhancedV93.attempted = true;
    g_enhancedV93.enhancedImage =
        IsEnhancedExecutableImage();

    if (!g_enhancedV93.enhancedImage)
        return false;

    uint8_t* base = nullptr;
    uint8_t* end = nullptr;
    if (!GetExeRange(base, end)
        || !base
        || !end
        || end <= base)
    {
        return false;
    }

    g_enhancedV93.imageRangeValid = true;

    constexpr uint64_t c25610Rva = 0x00C25610ULL;
    constexpr uint64_t c26f00Rva = 0x00C26F00ULL;
    constexpr uint64_t c272a0Rva = 0x00C272A0ULL;
    constexpr uint64_t expectedC25f4eRva = 0x00C25F4EULL;
    constexpr uint64_t expectedC26f83Rva = 0x00C26F83ULL;

    const uint64_t imageSize =
        static_cast<uint64_t>(end - base);
    if (c25610Rva >= imageSize
        || c26f00Rva >= imageSize
        || c272a0Rva >= imageSize)
    {
        return false;
    }

    uint8_t* c25610 = base + c25610Rva;
    uint8_t* c26f00 = base + c26f00Rva;
    uint8_t* c272a0 = base + c272a0Rva;

    uint8_t* c25610Start = nullptr;
    uint8_t* c25610End = nullptr;
    uint8_t* c26f00Start = nullptr;
    uint8_t* c26f00End = nullptr;
    uint8_t* c272a0Start = nullptr;
    uint8_t* c272a0End = nullptr;

    g_enhancedV93.c25610Bounds =
        FindRuntimeFunctionBounds(
            base,
            end,
            c25610,
            c25610Start,
            c25610End)
        && c25610Start == c25610
        && c25610End
        && c25610End > c25610Start;

    g_enhancedV93.c26f00Bounds =
        FindRuntimeFunctionBounds(
            base,
            end,
            c26f00,
            c26f00Start,
            c26f00End)
        && c26f00Start == c26f00
        && c26f00End
        && c26f00End > c26f00Start;

    g_enhancedV93.c272a0Bounds =
        FindRuntimeFunctionBounds(
            base,
            end,
            c272a0,
            c272a0Start,
            c272a0End)
        && c272a0Start == c272a0
        && c272a0End
        && c272a0End > c272a0Start;

    if (!g_enhancedV93.c25610Bounds
        || !g_enhancedV93.c26f00Bounds
        || !g_enhancedV93.c272a0Bounds)
    {
        return false;
    }

    g_enhancedV93.c25610Start =
        reinterpret_cast<uintptr_t>(c25610Start);
    g_enhancedV93.c25610End =
        reinterpret_cast<uintptr_t>(c25610End);
    g_enhancedV93.c26f00Start =
        reinterpret_cast<uintptr_t>(c26f00Start);
    g_enhancedV93.c26f00End =
        reinterpret_cast<uintptr_t>(c26f00End);
    g_enhancedV93.c272a0Start =
        reinterpret_cast<uintptr_t>(c272a0Start);
    g_enhancedV93.c272a0End =
        reinterpret_cast<uintptr_t>(c272a0End);

    uint8_t* ownerFirstCallsite = nullptr;
    uint32_t ownerMatches = 0;
    g_enhancedV93.uniqueOwnerCall =
        FindEnhancedV93UniqueDirectCall(
            c25610Start,
            c25610End,
            c26f00,
            ownerFirstCallsite,
            ownerMatches);
    g_enhancedV93.ownerCallMatches =
        ownerMatches;

    uint8_t* workerCallsite = nullptr;
    uint32_t workerMatches = 0;
    g_enhancedV93.uniqueWorkerCall =
        FindEnhancedV93UniqueDirectCall(
            c26f00Start,
            c26f00End,
            c272a0,
            workerCallsite,
            workerMatches);
    g_enhancedV93.workerCallMatches =
        workerMatches;

    uint8_t* expectedOwnerCallsite =
        base + expectedC25f4eRva;
    uint8_t* expectedWorkerCallsite =
        base + expectedC26f83Rva;

    g_enhancedV93.expectedOwnerCall =
        ValidateEnhancedV94DirectCallsite(
            c25610Start,
            c25610End,
            expectedOwnerCallsite,
            c26f00);
    g_enhancedV93.expectedWorkerCall =
        ValidateEnhancedV94DirectCallsite(
            c26f00Start,
            c26f00End,
            expectedWorkerCallsite,
            c272a0);

    if (g_enhancedV93.expectedOwnerCall)
    {
        g_enhancedV93.c25f4eCallsite =
            reinterpret_cast<uintptr_t>(
                expectedOwnerCallsite);
    }

    if (g_enhancedV93.expectedWorkerCall)
    {
        g_enhancedV93.c26f83Callsite =
            reinterpret_cast<uintptr_t>(
                expectedWorkerCallsite);
    }

    g_enhancedV93.knownCallsites =
        g_enhancedV93.expectedOwnerCall
        && g_enhancedV93.expectedWorkerCall;

    static const uint8_t expectedPrefix[16] =
    {
        0x41, 0x57,
        0x41, 0x56,
        0x41, 0x55,
        0x41, 0x54,
        0x56,
        0x57,
        0x55,
        0x53,
        0x48, 0x83, 0xEC, 0x48
    };

    g_enhancedV93.hookPrefixSafe =
        static_cast<size_t>(
            c26f00End - c26f00Start)
            >= sizeof(expectedPrefix)
        && memcmp(
            c26f00Start,
            expectedPrefix,
            sizeof(expectedPrefix)) == 0;

    g_enhancedV93.structuralVerified =
        g_enhancedV93.c25610Bounds
        && g_enhancedV93.c26f00Bounds
        && g_enhancedV93.c272a0Bounds
        && g_enhancedV93.expectedOwnerCall
        && g_enhancedV93.uniqueWorkerCall
        && g_enhancedV93.expectedWorkerCall
        && g_enhancedV93.knownCallsites
        && g_enhancedV93.hookPrefixSafe;

    return g_enhancedV93.structuralVerified;
}

static void EvaluateEnhancedV93SemanticContextFromV52Observations()
{
    constexpr uint32_t storyGroup = 0x578F99E2U;
    constexpr uint32_t mplowrider = 0x61322A35U;
    constexpr uintptr_t childStride = 0x120ULL;

    LONG storyCalls = 0;
    LONG lowriderStoryCalls = 0;
    LONG contextReadable = 0;
    LONG childMembership = 0;
    LONG child64 = 0;

    const LONG observed =
        InterlockedCompareExchange(
            &g_v52C26F00ObservationCount,
            0,
            0);
    const LONG capacity =
        static_cast<LONG>(
            sizeof(g_v52C26F00CallerObservations)
            / sizeof(g_v52C26F00CallerObservations[0]));
    const LONG count =
        observed < capacity ? observed : capacity;

    for (LONG i = 0; i < count; ++i)
    {
        const V52C26F00CallerObservation& o =
            g_v52C26F00CallerObservations[i];

        if (o.groupHashValue != storyGroup)
            continue;

        ++storyCalls;

        if (o.childField80 != mplowrider
            || o.callsite
                != g_enhancedV93.c25f4eCallsite)
        {
            continue;
        }

        ++lowriderStoryCalls;

        g_enhancedV93.lastContext = o.context;
        g_enhancedV93.lastChild = o.child;
        g_enhancedV93.lastCallsite = o.callsite;
        g_enhancedV93.lastGroup = o.groupHashValue;
        g_enhancedV93.lastChildField80 =
            o.childField80;
        g_enhancedV93.lastChildIndex = -1;

        if (!o.context || !o.child)
            continue;

        uintptr_t childArray = 0;
        uint16_t childCount = 0;
        if (!ReadProcessExact(
                o.context + 0x28,
                &childArray,
                sizeof(childArray))
            || !ReadProcessExact(
                o.context + 0x30,
                &childCount,
                sizeof(childCount))
            || !childArray
            || childCount == 0
            || childCount > 4096)
        {
            continue;
        }

        ++contextReadable;

        g_enhancedV93.lastChildArray =
            childArray;
        g_enhancedV93.lastChildCount =
            childCount;

        if (o.child < childArray)
            continue;

        const uintptr_t delta =
            o.child - childArray;
        if ((delta % childStride) != 0)
            continue;

        const uintptr_t index =
            delta / childStride;
        if (index >= childCount)
            continue;

        ++childMembership;
        g_enhancedV93.lastChildIndex =
            static_cast<LONG>(index);

        if (index == 64)
            ++child64;
    }

    InterlockedExchange(
        &g_enhancedV93.storyContextCalls,
        storyCalls);
    InterlockedExchange(
        &g_enhancedV93.lowriderStoryCalls,
        lowriderStoryCalls);
    InterlockedExchange(
        &g_enhancedV93.contextArrayReadableHits,
        contextReadable);
    InterlockedExchange(
        &g_enhancedV93.childMembershipVerifiedHits,
        childMembership);
    InterlockedExchange(
        &g_enhancedV93.childIndex64Hits,
        child64);

    g_enhancedV93.semanticVerified =
        g_enhancedV93.gameVersionConfirmed
        && g_enhancedV93.structuralVerified
        && storyCalls > 0
        && lowriderStoryCalls > 0
        && contextReadable > 0
        && childMembership > 0;
}

