static uint8_t* AllocateExecutableNearV78Callsite(
    uintptr_t callsite,
    size_t size)
{
    if (!callsite || size == 0)
        return nullptr;

    SYSTEM_INFO systemInfo{};
    GetSystemInfo(&systemInfo);

    const uintptr_t minimumAddress =
        reinterpret_cast<uintptr_t>(
            systemInfo.lpMinimumApplicationAddress);
    const uintptr_t maximumAddress =
        reinterpret_cast<uintptr_t>(
            systemInfo.lpMaximumApplicationAddress);
    const uintptr_t granularity =
        static_cast<uintptr_t>(
            systemInfo.dwAllocationGranularity);

    constexpr uintptr_t rel32Radius =
        0x7FFF0000ULL;

    uintptr_t low =
        callsite > rel32Radius
            ? callsite - rel32Radius
            : minimumAddress;
    if (low < minimumAddress)
        low = minimumAddress;

    uintptr_t high =
        callsite <= maximumAddress - rel32Radius
            ? callsite + rel32Radius
            : maximumAddress;

    uintptr_t cursor = low;
    while (cursor < high)
    {
        MEMORY_BASIC_INFORMATION mbi{};
        if (VirtualQuery(
                reinterpret_cast<LPCVOID>(cursor),
                &mbi,
                sizeof(mbi)) != sizeof(mbi))
        {
            break;
        }

        const uintptr_t regionBase =
            reinterpret_cast<uintptr_t>(
                mbi.BaseAddress);
        const uintptr_t regionSize =
            static_cast<uintptr_t>(
                mbi.RegionSize);
        const uintptr_t regionEnd =
            regionBase + regionSize;

        if (regionEnd <= cursor)
            break;

        if (mbi.State == MEM_FREE)
        {
            uintptr_t candidate =
                (regionBase + granularity - 1)
                & ~(granularity - 1);

            if (candidate < low)
            {
                candidate =
                    (low + granularity - 1)
                    & ~(granularity - 1);
            }

            if (candidate <= high
                && candidate <= regionEnd
                && size <= regionEnd - candidate)
            {
                void* allocation =
                    VirtualAlloc(
                        reinterpret_cast<LPVOID>(candidate),
                        size,
                        MEM_COMMIT | MEM_RESERVE,
                        PAGE_EXECUTE_READWRITE);

                if (allocation)
                    return reinterpret_cast<uint8_t*>(allocation);
            }
        }

        cursor = regionEnd;
    }

    return nullptr;
}

static bool EmitV78StoreRegToR11Disp32(
    uint8_t* code,
    size_t capacity,
    size_t& position,
    uint8_t rex,
    uint8_t modrm,
    uint32_t displacement)
{
    if (!code || position + 7 > capacity)
        return false;

    code[position++] = rex;
    code[position++] = 0x89;
    code[position++] = modrm;
    memcpy(
        code + position,
        &displacement,
        sizeof(displacement));
    position += sizeof(displacement);
    return true;
}

static bool EmitV78Byte(
    uint8_t* code,
    size_t capacity,
    size_t& position,
    uint8_t value)
{
    if (!code || position >= capacity)
        return false;

    code[position++] = value;
    return true;
}

static bool EmitV78Dword(
    uint8_t* code,
    size_t capacity,
    size_t& position,
    uint32_t value)
{
    if (!code || position + sizeof(value) > capacity)
        return false;

    memcpy(code + position, &value, sizeof(value));
    position += sizeof(value);
    return true;
}

static bool EmitV78Qword(
    uint8_t* code,
    size_t capacity,
    size_t& position,
    uint64_t value)
{
    if (!code || position + sizeof(value) > capacity)
        return false;

    memcpy(code + position, &value, sizeof(value));
    position += sizeof(value);
    return true;
}

