static const char* GetPreDiscardPairFailureReason()
{
    switch (g_preDiscardPairFailureCode)
    {
    case 0:  return "none";
    case 1:  return "exe-module-unavailable";
    case 2:  return "bad-dos-signature";
    case 3:  return "bad-nt-signature";
    case 4:  return "verified-rva-outside-image";
    case 5:  return "C27FCB-group-gate-mismatch";
    case 6:  return "C27EAC-group-load-mismatch";
    case 7:  return "C27FB0-registry-key-loop-mismatch";
    case 8:  return "mapState-already-constructed";
    case 9:  return "near-stub-allocation-failed";
    case 10: return "stub-too-large";
    case 11: return "VirtualProtect-failed";
    case 12: return "seh-exception";
    default: return "unknown";
    }
}

static void InstallC27E80PreDiscardPairProbeAtModuleLoad()
{
    if (!IsEnhancedExecutableImage())
        return;

    g_preDiscardPairHookAttempted = true;

    HMODULE exe = GetModuleHandleA(nullptr);
    if (!exe)
    {
        g_preDiscardPairFailureCode = 1;
        return;
    }

    uint8_t* base = reinterpret_cast<uint8_t*>(exe);

    __try
    {
        const IMAGE_DOS_HEADER* dos =
            reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
        if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        {
            g_preDiscardPairFailureCode = 2;
            return;
        }

        const IMAGE_NT_HEADERS64* nt =
            reinterpret_cast<const IMAGE_NT_HEADERS64*>(
                base + dos->e_lfanew);
        if (nt->Signature != IMAGE_NT_SIGNATURE)
        {
            g_preDiscardPairFailureCode = 3;
            return;
        }

        const uint64_t imageSize =
            static_cast<uint64_t>(nt->OptionalHeader.SizeOfImage);

        const uint64_t siteRva = 0x00C27FCBULL;
        const uint64_t groupLoadRva = 0x00C27EA3ULL;
        const uint64_t registryKeyLoopRva = 0x00C27FB0ULL;
        const uint64_t mapStateGlobalRva = 0x029CAFC8ULL;

        if (siteRva + 16 > imageSize
            || groupLoadRva + 12 > imageSize
            || registryKeyLoopRva + 18 > imageSize
            || mapStateGlobalRva + sizeof(uintptr_t) > imageSize)
        {
            g_preDiscardPairFailureCode = 4;
            return;
        }

        static const uint8_t expectedSite[16] =
        {
            0x81, 0xFB, 0xE2, 0x99, 0x8F, 0x57,
            0x74, 0x0C,
            0x81, 0xFB, 0x79, 0x91, 0xC8, 0xBC,
            0x0F, 0x85
        };

        uint8_t* site = base + siteRva;
        if (memcmp(site, expectedSite, sizeof(expectedSite)) != 0)
        {
            g_preDiscardPairFailureCode = 5;
            return;
        }
        g_preDiscardPairSiteVerified = true;

        static const uint8_t expectedGroupLoad[11] =
        {
            0x45, 0x89, 0xCE,
            0x4D, 0x89, 0xC5,
            0x49, 0x89, 0xD4,
            0x8B, 0x1A
        };

        if (memcmp(
                base + groupLoadRva,
                expectedGroupLoad,
                sizeof(expectedGroupLoad)) != 0)
        {
            g_preDiscardPairFailureCode = 6;
            return;
        }
        g_preDiscardPairGroupLoadVerified = true;

        static const uint8_t expectedRegistryLoop[18] =
        {
            0x44, 0x3B, 0x45, 0x00,
            0x74, 0x11,
            0x48, 0x8B, 0xAD, 0xD0, 0x00, 0x00, 0x00,
            0x48, 0x85, 0xED,
            0x75, 0xEE
        };

        if (memcmp(
                base + registryKeyLoopRva,
                expectedRegistryLoop,
                sizeof(expectedRegistryLoop)) != 0)
        {
            g_preDiscardPairFailureCode = 7;
            return;
        }
        g_preDiscardPairRegistryKeyVerified = true;

        uintptr_t mapState = 0;
        memcpy(
            &mapState,
            base + mapStateGlobalRva,
            sizeof(mapState));
        g_preDiscardPairMapStateWasNull = (mapState == 0);
        if (mapState != 0)
        {
            g_preDiscardPairFailureCode = 8;
            return;
        }

        constexpr size_t stolenSize = 6;
        constexpr size_t stubCapacity = 512;

        uint8_t* stub =
            reinterpret_cast<uint8_t*>(
                AllocateExecutableNearRel32(site, stubCapacity));
        if (!stub)
        {
            g_preDiscardPairFailureCode = 9;
            return;
        }

        uint8_t stubBytes[stubCapacity]{};
        size_t p = 0;

        auto emitCounterIncrement =
            [&](volatile LONG* counter)
        {
            EmitMovRaxImm64(
                stubBytes,
                p,
                reinterpret_cast<uint64_t>(counter));
            stubBytes[p++] = 0xF0;
            stubBytes[p++] = 0xFF;
            stubBytes[p++] = 0x00;
        };

        auto emitEbxCompareAndCount =
            [&](uint32_t value, volatile LONG* counter)
        {

            stubBytes[p++] = 0x81;
            stubBytes[p++] = 0xFB;
            memcpy(stubBytes + p, &value, sizeof(value));
            p += sizeof(value);
            const size_t jne = p;
            stubBytes[p++] = 0x0F;
            stubBytes[p++] = 0x85;
            p += 4;
            emitCounterIncrement(counter);
            PatchRel32(stubBytes, jne, 6, p);
        };

        auto emitR8dCompareAndCount =
            [&](uint32_t value, volatile LONG* counter)
        {

            stubBytes[p++] = 0x41;
            stubBytes[p++] = 0x81;
            stubBytes[p++] = 0xF8;
            memcpy(stubBytes + p, &value, sizeof(value));
            p += sizeof(value);
            const size_t jne = p;
            stubBytes[p++] = 0x0F;
            stubBytes[p++] = 0x85;
            p += 4;
            emitCounterIncrement(counter);
            PatchRel32(stubBytes, jne, 6, p);
        };

        const uint32_t groupMap = 0xBCC89179U;
        const uint32_t groupMapSp = 0x578F99E2U;
        const uint32_t benny = 0x4CDFC843U;
        const uint32_t dlc = 0x61322A35U;

        stubBytes[p++] = 0x50;
        stubBytes[p++] = 0x41;
        stubBytes[p++] = 0x52;

        emitCounterIncrement(&g_preDiscardPairTotalHits);
        emitEbxCompareAndCount(
            groupMap,
            &g_preDiscardPairGroupMapHits);
        emitEbxCompareAndCount(
            groupMapSp,
            &g_preDiscardPairStoryMapHits);
        emitR8dCompareAndCount(
            benny,
            &g_preDiscardPairBennyKeyHits);
        emitR8dCompareAndCount(
            dlc,
            &g_preDiscardPairDlcKeyHits);

        stubBytes[p++] = 0x81;
        stubBytes[p++] = 0xFB;
        memcpy(stubBytes + p, &groupMap, sizeof(groupMap));
        p += sizeof(groupMap);
        const size_t jneMapCapture = p;
        stubBytes[p++] = 0x0F;
        stubBytes[p++] = 0x85;
        p += 4;
        stubBytes[p++] = 0x45;
        stubBytes[p++] = 0x89;
        stubBytes[p++] = 0xC2;
        EmitMovRaxImm64(
            stubBytes,
            p,
            reinterpret_cast<uint64_t>(
                &g_preDiscardPairLastAssociatedWhenMap));
        stubBytes[p++] = 0x44;
        stubBytes[p++] = 0x89;
        stubBytes[p++] = 0x10;
        PatchRel32(stubBytes, jneMapCapture, 6, p);

        stubBytes[p++] = 0x81;
        stubBytes[p++] = 0xFB;
        memcpy(stubBytes + p, &groupMapSp, sizeof(groupMapSp));
        p += sizeof(groupMapSp);
        const size_t jneStoryCapture = p;
        stubBytes[p++] = 0x0F;
        stubBytes[p++] = 0x85;
        p += 4;
        stubBytes[p++] = 0x45;
        stubBytes[p++] = 0x89;
        stubBytes[p++] = 0xC2;
        EmitMovRaxImm64(
            stubBytes,
            p,
            reinterpret_cast<uint64_t>(
                &g_preDiscardPairLastAssociatedWhenStory));
        stubBytes[p++] = 0x44;
        stubBytes[p++] = 0x89;
        stubBytes[p++] = 0x10;
        PatchRel32(stubBytes, jneStoryCapture, 6, p);

        stubBytes[p++] = 0x41;
        stubBytes[p++] = 0x81;
        stubBytes[p++] = 0xF8;
        memcpy(stubBytes + p, &benny, sizeof(benny));
        p += sizeof(benny);
        const size_t jneBennyCapture = p;
        stubBytes[p++] = 0x0F;
        stubBytes[p++] = 0x85;
        p += 4;
        stubBytes[p++] = 0x41;
        stubBytes[p++] = 0x89;
        stubBytes[p++] = 0xDA;
        EmitMovRaxImm64(
            stubBytes,
            p,
            reinterpret_cast<uint64_t>(
                &g_preDiscardPairLastGroupWhenBenny));
        stubBytes[p++] = 0x44;
        stubBytes[p++] = 0x89;
        stubBytes[p++] = 0x10;
        stubBytes[p++] = 0x4D;
        stubBytes[p++] = 0x89;
        stubBytes[p++] = 0xE2;
        EmitMovRaxImm64(
            stubBytes,
            p,
            reinterpret_cast<uint64_t>(
                &g_preDiscardPairLastGroupPointerWhenBenny));
        stubBytes[p++] = 0x4C;
        stubBytes[p++] = 0x89;
        stubBytes[p++] = 0x10;
        PatchRel32(stubBytes, jneBennyCapture, 6, p);

        stubBytes[p++] = 0x81;
        stubBytes[p++] = 0xFB;
        memcpy(stubBytes + p, &groupMap, sizeof(groupMap));
        p += sizeof(groupMap);
        const size_t jneExactMapGroup = p;
        stubBytes[p++] = 0x0F;
        stubBytes[p++] = 0x85;
        p += 4;
        stubBytes[p++] = 0x41;
        stubBytes[p++] = 0x81;
        stubBytes[p++] = 0xF8;
        memcpy(stubBytes + p, &benny, sizeof(benny));
        p += sizeof(benny);
        const size_t jneExactMapBenny = p;
        stubBytes[p++] = 0x0F;
        stubBytes[p++] = 0x85;
        p += 4;
        emitCounterIncrement(&g_preDiscardPairExactMapBennyHits);
        PatchRel32(stubBytes, jneExactMapBenny, 6, p);
        PatchRel32(stubBytes, jneExactMapGroup, 6, p);

        stubBytes[p++] = 0x81;
        stubBytes[p++] = 0xFB;
        memcpy(stubBytes + p, &groupMapSp, sizeof(groupMapSp));
        p += sizeof(groupMapSp);
        const size_t jneExactStoryGroup = p;
        stubBytes[p++] = 0x0F;
        stubBytes[p++] = 0x85;
        p += 4;
        stubBytes[p++] = 0x41;
        stubBytes[p++] = 0x81;
        stubBytes[p++] = 0xF8;
        memcpy(stubBytes + p, &benny, sizeof(benny));
        p += sizeof(benny);
        const size_t jneExactStoryBenny = p;
        stubBytes[p++] = 0x0F;
        stubBytes[p++] = 0x85;
        p += 4;
        emitCounterIncrement(&g_preDiscardPairExactStoryBennyHits);
        PatchRel32(stubBytes, jneExactStoryBenny, 6, p);
        PatchRel32(stubBytes, jneExactStoryGroup, 6, p);

        stubBytes[p++] = 0x41;
        stubBytes[p++] = 0x5A;
        stubBytes[p++] = 0x58;

        stubBytes[p++] = 0x81;
        stubBytes[p++] = 0xFB;
        memcpy(stubBytes + p, &groupMapSp, sizeof(groupMapSp));
        p += sizeof(groupMapSp);

        const size_t returnJumpStart = p;
        stubBytes[p++] = 0xE9;
        const int64_t returnDisplacement64 =
            reinterpret_cast<int64_t>(site + stolenSize)
            - reinterpret_cast<int64_t>(stub + returnJumpStart + 5);
        if (returnDisplacement64 < -0x7FFFFFFFLL
            || returnDisplacement64 > 0x7FFFFFFFLL)
        {
            VirtualFree(stub, 0, MEM_RELEASE);
            g_preDiscardPairFailureCode = 9;
            return;
        }
        const int32_t returnDisplacement =
            static_cast<int32_t>(returnDisplacement64);
        memcpy(
            stubBytes + p,
            &returnDisplacement,
            sizeof(returnDisplacement));
        p += sizeof(returnDisplacement);

        if (p > stubCapacity)
        {
            VirtualFree(stub, 0, MEM_RELEASE);
            g_preDiscardPairFailureCode = 10;
            return;
        }

        memcpy(stub, stubBytes, p);
        FlushInstructionCache(GetCurrentProcess(), stub, p);

        uint8_t patch[stolenSize]{};
        patch[0] = 0xE9;
        const int64_t patchDisplacement64 =
            reinterpret_cast<int64_t>(stub)
            - reinterpret_cast<int64_t>(site + 5);
        if (patchDisplacement64 < -0x7FFFFFFFLL
            || patchDisplacement64 > 0x7FFFFFFFLL)
        {
            VirtualFree(stub, 0, MEM_RELEASE);
            g_preDiscardPairFailureCode = 9;
            return;
        }
        const int32_t patchDisplacement =
            static_cast<int32_t>(patchDisplacement64);
        memcpy(
            patch + 1,
            &patchDisplacement,
            sizeof(patchDisplacement));
        patch[5] = 0x90;

        g_preDiscardPairStub = stub;

        DWORD oldProtect = 0;
        if (!VirtualProtect(
                site,
                stolenSize,
                PAGE_EXECUTE_READWRITE,
                &oldProtect))
        {
            g_preDiscardPairStub = nullptr;
            VirtualFree(stub, 0, MEM_RELEASE);
            g_preDiscardPairFailureCode = 11;
            return;
        }

        memcpy(site, patch, stolenSize);
        FlushInstructionCache(
            GetCurrentProcess(),
            site,
            stolenSize);

        DWORD ignoredProtect = 0;
        VirtualProtect(
            site,
            stolenSize,
            oldProtect,
            &ignoredProtect);

        g_preDiscardPairHookInstalled = true;
        g_preDiscardPairFailureCode = 0;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        g_preDiscardPairFailureCode = 12;
    }
}

struct C27E80PreDiscardPairProbeInstaller
{
    C27E80PreDiscardPairProbeInstaller()
    {
        InstallC27E80PreDiscardPairProbeAtModuleLoad();
    }
};

static C27E80PreDiscardPairProbeInstaller*
    g_c27e80PreDiscardPairProbeInstallerDisabled = nullptr;

static void LogC27E80PreDiscardPairProbeState(
    const char* phase)
{
    Logf(
        "[PreDiscardPairProbe] %s attempted=%s installed=%s siteVerified=%s groupLoadVerified=%s registryKeyVerified=%s mapStateWasNull=%s failure=%lu(%s) stub=%p hits=%ld groups{GROUP_MAP=%ld GROUP_MAP_SP=%ld} keys{Benny=%ld mplowrider=%ld} exact{GROUP_MAP+Benny=%ld GROUP_MAP_SP+Benny=%ld} lastAssociatedWhenMap=0x%08X lastAssociatedWhenStory=0x%08X lastGroupWhenBenny=0x%08X lastGroupPtrWhenBenny=%p rewrites=0.",
        phase ? phase : "state",
        g_preDiscardPairHookAttempted ? "yes" : "no",
        g_preDiscardPairHookInstalled ? "yes" : "no",
        g_preDiscardPairSiteVerified ? "yes" : "no",
        g_preDiscardPairGroupLoadVerified ? "yes" : "no",
        g_preDiscardPairRegistryKeyVerified ? "yes" : "no",
        g_preDiscardPairMapStateWasNull ? "yes" : "no",
        static_cast<unsigned long>(g_preDiscardPairFailureCode),
        GetPreDiscardPairFailureReason(),
        g_preDiscardPairStub,
        static_cast<long>(g_preDiscardPairTotalHits),
        static_cast<long>(g_preDiscardPairGroupMapHits),
        static_cast<long>(g_preDiscardPairStoryMapHits),
        static_cast<long>(g_preDiscardPairBennyKeyHits),
        static_cast<long>(g_preDiscardPairDlcKeyHits),
        static_cast<long>(g_preDiscardPairExactMapBennyHits),
        static_cast<long>(g_preDiscardPairExactStoryBennyHits),
        g_preDiscardPairLastAssociatedWhenMap,
        g_preDiscardPairLastAssociatedWhenStory,
        g_preDiscardPairLastGroupWhenBenny,
        reinterpret_cast<void*>(g_preDiscardPairLastGroupPointerWhenBenny));
}

static const char* GetPreFilterFailureReason()
{
    switch (g_preFilterFailureCode)
    {
    case 0:  return "none";
    case 1:  return "exe-module-unavailable";
    case 2:  return "bad-dos-signature";
    case 3:  return "bad-nt-signature";
    case 4:  return "verified-rva-outside-image";
    case 5:  return "C27740-prefix-mismatch";
    case 6:  return "C27931-group-compare-mismatch";
    case 7:  return "C27E50-tail-arg-shape-mismatch";
    case 8:  return "mapState-already-constructed";
    case 9:  return "trampoline-allocation-failed";
    case 10: return "stub-allocation-failed";
    case 11: return "VirtualProtect-failed";
    case 12: return "seh-exception";
    default: return "unknown";
    }
}

static void InstallC27740PreFilterHookAtModuleLoad()
{
    if (!IsEnhancedExecutableImage())
        return;

    g_preFilterHookAttempted = true;

    HMODULE exe =
        GetModuleHandleA(nullptr);
    if (!exe)
    {
        g_preFilterFailureCode = 1;
        return;
    }

    uint8_t* base =
        reinterpret_cast<uint8_t*>(exe);

    __try
    {
        const IMAGE_DOS_HEADER* dos =
            reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
        if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        {
            g_preFilterFailureCode = 2;
            return;
        }

        const IMAGE_NT_HEADERS64* nt =
            reinterpret_cast<const IMAGE_NT_HEADERS64*>(
                base + dos->e_lfanew);
        if (nt->Signature != IMAGE_NT_SIGNATURE)
        {
            g_preFilterFailureCode = 3;
            return;
        }

        const uint64_t imageSize =
            static_cast<uint64_t>(
                nt->OptionalHeader.SizeOfImage);

        const uint64_t targetRva =
            0x00C27740ULL;
        const uint64_t compareRva =
            0x00C27931ULL;
        const uint64_t tailArgsRva =
            0x00C27E50ULL;
        const uint64_t mapStateGlobalRva =
            0x029CAFC8ULL;

        if (targetRva + 32 > imageSize
            || compareRva + 16 > imageSize
            || tailArgsRva + 32 > imageSize
            || mapStateGlobalRva + sizeof(uintptr_t) > imageSize)
        {
            g_preFilterFailureCode = 4;
            return;
        }

        static const uint8_t expectedPrefix[19] =
        {
            0x41, 0x57,
            0x41, 0x56,
            0x41, 0x55,
            0x41, 0x54,
            0x56,
            0x57,
            0x55,
            0x53,
            0x48, 0x81, 0xEC,
            0x78, 0x03, 0x00, 0x00
        };

        uint8_t* target =
            base + targetRva;

        if (memcmp(
                target,
                expectedPrefix,
                sizeof(expectedPrefix)) != 0)
        {
            g_preFilterFailureCode = 5;
            return;
        }

        g_preFilterPrefixVerified = true;

        static const uint8_t expectedCompare[16] =
        {
            0x41, 0x8B, 0x04, 0x24,
            0x3D, 0xE2, 0x99, 0x8F, 0x57,
            0x74, 0x0B,
            0x3D, 0x79, 0x91, 0xC8, 0xBC
        };

        if (memcmp(
                base + compareRva,
                expectedCompare,
                sizeof(expectedCompare)) != 0)
        {
            g_preFilterFailureCode = 6;
            return;
        }

        g_preFilterCompareVerified = true;

        static const uint8_t expectedTailArgs[29] =
        {
            0x41, 0x8B, 0x07,
            0x89, 0x44, 0x24, 0x38,
            0x41, 0x8B, 0x04, 0x24,
            0x89, 0x44, 0x24, 0x30,
            0x48, 0x8D, 0x54, 0x24, 0x30,
            0x4C, 0x8D, 0x44, 0x24, 0x38,
            0x4C, 0x89, 0xF1,
            0x41
        };

        if (memcmp(
                base + tailArgsRva,
                expectedTailArgs,
                sizeof(expectedTailArgs)) != 0)
        {
            g_preFilterFailureCode = 7;
            return;
        }

        g_preFilterTailArgsVerified = true;

        uintptr_t mapState = 0;
        memcpy(
            &mapState,
            base + mapStateGlobalRva,
            sizeof(mapState));

        g_preFilterMapStateWasNull =
            (mapState == 0);

        if (mapState != 0)
        {
            g_preFilterFailureCode = 8;
            return;
        }

        constexpr size_t stolenSize = 19;
        constexpr size_t trampolineSize =
            stolenSize + 16;

        uint8_t* trampoline =
            reinterpret_cast<uint8_t*>(
                VirtualAlloc(
                    nullptr,
                    trampolineSize,
                    MEM_COMMIT | MEM_RESERVE,
                    PAGE_EXECUTE_READWRITE));

        if (!trampoline)
        {
            g_preFilterFailureCode = 9;
            return;
        }

        memcpy(
            trampoline,
            target,
            stolenSize);

        WriteAbsoluteJump12(
            trampoline + stolenSize,
            target + stolenSize);

        for (size_t i = stolenSize + 12;
             i < trampolineSize;
             ++i)
        {
            trampoline[i] = 0x90;
        }

        FlushInstructionCache(
            GetCurrentProcess(),
            trampoline,
            trampolineSize);

        uint8_t stubBytes[512]{};
        size_t p = 0;

        auto emitCounterIncrement =
            [&](volatile LONG* counter)
        {
            EmitMovRaxImm64(
                stubBytes,
                p,
                reinterpret_cast<uint64_t>(counter));
            stubBytes[p++] = 0xF0;
            stubBytes[p++] = 0xFF;
            stubBytes[p++] = 0x00;
        };

        auto emitRdxCompareAndCount =
            [&](uint32_t value, volatile LONG* counter)
        {

            stubBytes[p++] = 0x81;
            stubBytes[p++] = 0x3A;
            memcpy(stubBytes + p, &value, sizeof(value));
            p += sizeof(value);

            const size_t jne = p;
            stubBytes[p++] = 0x0F;
            stubBytes[p++] = 0x85;
            p += 4;

            emitCounterIncrement(counter);
            PatchRel32(stubBytes, jne, 6, p);
        };

        auto emitR8CompareAndCount =
            [&](uint32_t value, volatile LONG* counter)
        {

            stubBytes[p++] = 0x41;
            stubBytes[p++] = 0x81;
            stubBytes[p++] = 0x38;
            memcpy(stubBytes + p, &value, sizeof(value));
            p += sizeof(value);

            const size_t jne = p;
            stubBytes[p++] = 0x0F;
            stubBytes[p++] = 0x85;
            p += 4;

            emitCounterIncrement(counter);
            PatchRel32(stubBytes, jne, 6, p);
        };

        emitCounterIncrement(&g_preFilterTotalCalls);

        stubBytes[p++] = 0x48;
        stubBytes[p++] = 0x85;
        stubBytes[p++] = 0xD2;
        const size_t jzRdx = p;
        stubBytes[p++] = 0x0F;
        stubBytes[p++] = 0x84;
        p += 4;

        stubBytes[p++] = 0x4D;
        stubBytes[p++] = 0x85;
        stubBytes[p++] = 0xC0;
        const size_t jzR8 = p;
        stubBytes[p++] = 0x0F;
        stubBytes[p++] = 0x84;
        p += 4;

        const uint32_t groupMap = 0xBCC89179U;
        const uint32_t groupMapSp = 0x578F99E2U;
        const uint32_t benny = 0x4CDFC843U;
        const uint32_t dlc = 0x61322A35U;

        emitRdxCompareAndCount(groupMap, &g_preFilterRdxGroupMap);
        emitRdxCompareAndCount(groupMapSp, &g_preFilterRdxGroupMapSp);
        emitRdxCompareAndCount(benny, &g_preFilterRdxBenny);
        emitRdxCompareAndCount(dlc, &g_preFilterRdxDlc);

        emitR8CompareAndCount(groupMap, &g_preFilterR8GroupMap);
        emitR8CompareAndCount(groupMapSp, &g_preFilterR8GroupMapSp);
        emitR8CompareAndCount(benny, &g_preFilterR8Benny);
        emitR8CompareAndCount(dlc, &g_preFilterR8Dlc);

        stubBytes[p++] = 0x41;
        stubBytes[p++] = 0x81;
        stubBytes[p++] = 0x38;
        memcpy(stubBytes + p, &benny, sizeof(benny));
        p += sizeof(benny);
        const size_t jneR8BennyCapture = p;
        stubBytes[p++] = 0x0F;
        stubBytes[p++] = 0x85;
        p += 4;

        EmitMovRaxImm64(
            stubBytes,
            p,
            reinterpret_cast<uint64_t>(&g_preFilterLastContext));
        stubBytes[p++] = 0x48;
        stubBytes[p++] = 0x89;
        stubBytes[p++] = 0x08;

        EmitMovRaxImm64(
            stubBytes,
            p,
            reinterpret_cast<uint64_t>(&g_preFilterLastGroupPtr));
        stubBytes[p++] = 0x48;
        stubBytes[p++] = 0x89;
        stubBytes[p++] = 0x10;

        EmitMovRaxImm64(
            stubBytes,
            p,
            reinterpret_cast<uint64_t>(&g_preFilterLastAssociatedPtr));
        stubBytes[p++] = 0x4C;
        stubBytes[p++] = 0x89;
        stubBytes[p++] = 0x00;

        stubBytes[p++] = 0x44;
        stubBytes[p++] = 0x8B;
        stubBytes[p++] = 0x12;
        EmitMovRaxImm64(
            stubBytes,
            p,
            reinterpret_cast<uint64_t>(&g_preFilterGroupWhenR8Benny));

        stubBytes[p++] = 0x44;
        stubBytes[p++] = 0x89;
        stubBytes[p++] = 0x10;

        PatchRel32(
            stubBytes,
            jneR8BennyCapture,
            6,
            p);

        stubBytes[p++] = 0x81;
        stubBytes[p++] = 0x3A;
        memcpy(stubBytes + p, &benny, sizeof(benny));
        p += sizeof(benny);
        const size_t jneRdxBennyCapture = p;
        stubBytes[p++] = 0x0F;
        stubBytes[p++] = 0x85;
        p += 4;

        stubBytes[p++] = 0x45;
        stubBytes[p++] = 0x8B;
        stubBytes[p++] = 0x10;
        EmitMovRaxImm64(
            stubBytes,
            p,
            reinterpret_cast<uint64_t>(&g_preFilterR8WhenRdxBenny));
        stubBytes[p++] = 0x44;
        stubBytes[p++] = 0x89;
        stubBytes[p++] = 0x10;

        PatchRel32(
            stubBytes,
            jneRdxBennyCapture,
            6,
            p);

        const size_t passThrough = p;

        EmitMovRaxImm64(
            stubBytes,
            p,
            reinterpret_cast<uint64_t>(trampoline));
        stubBytes[p++] = 0xFF;
        stubBytes[p++] = 0xE0;

        PatchRel32(stubBytes, jzRdx, 6, passThrough);
        PatchRel32(stubBytes, jzR8, 6, passThrough);

        uint8_t* stub =
            reinterpret_cast<uint8_t*>(
                VirtualAlloc(
                    nullptr,
                    512,
                    MEM_COMMIT | MEM_RESERVE,
                    PAGE_EXECUTE_READWRITE));

        if (!stub)
        {
            VirtualFree(
                trampoline,
                0,
                MEM_RELEASE);
            g_preFilterFailureCode = 10;
            return;
        }

        memcpy(
            stub,
            stubBytes,
            p);

        FlushInstructionCache(
            GetCurrentProcess(),
            stub,
            p);

        uint8_t patch[stolenSize]{};
        WriteAbsoluteJump12(
            patch,
            stub);

        for (size_t i = 12;
             i < stolenSize;
             ++i)
        {
            patch[i] = 0x90;
        }

        DWORD oldProtect = 0;
        if (!VirtualProtect(
                target,
                stolenSize,
                PAGE_EXECUTE_READWRITE,
                &oldProtect))
        {
            VirtualFree(
                stub,
                0,
                MEM_RELEASE);
            VirtualFree(
                trampoline,
                0,
                MEM_RELEASE);
            g_preFilterFailureCode = 11;
            return;
        }

        memcpy(
            target,
            patch,
            stolenSize);

        FlushInstructionCache(
            GetCurrentProcess(),
            target,
            stolenSize);

        DWORD ignoredProtect = 0;
        VirtualProtect(
            target,
            stolenSize,
            oldProtect,
            &ignoredProtect);

        g_preFilterTrampoline =
            trampoline;
        g_preFilterStub =
            stub;
        g_preFilterHookInstalled =
            true;
        g_preFilterFailureCode = 0;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        g_preFilterFailureCode = 12;
    }
}

struct C27740PreFilterHookInstaller
{
    C27740PreFilterHookInstaller()
    {
        InstallC27740PreFilterHookAtModuleLoad();
    }
};

static C27740PreFilterHookInstaller*
    g_c27740PreFilterHookInstallerDisabled = nullptr;

