{
    Logf(
        "[PreFilterProbe] %s attempted=%s installed=%s prefixVerified=%s compareVerified=%s tailArgsVerified=%s mapStateWasNull=%s failure=%lu(%s) trampoline=%p stub=%p totalCalls=%ld RDX{GROUP_MAP=%ld GROUP_MAP_SP=%ld Benny=%ld mplowrider=%ld} R8{GROUP_MAP=%ld GROUP_MAP_SP=%ld Benny=%ld mplowrider=%ld} groupWhenR8Benny=0x%08X r8WhenRdxBenny=0x%08X lastContext=%p lastGroupPtr=%p lastAssociatedPtr=%p rewrites=%ld.",
        phase ? phase : "state",
        g_preFilterHookAttempted ? "yes" : "no",
        g_preFilterHookInstalled ? "yes" : "no",
        g_preFilterPrefixVerified ? "yes" : "no",
        g_preFilterCompareVerified ? "yes" : "no",
        g_preFilterTailArgsVerified ? "yes" : "no",
        g_preFilterMapStateWasNull ? "yes" : "no",
        static_cast<unsigned long>(g_preFilterFailureCode),
        GetPreFilterFailureReason(),
        g_preFilterTrampoline,
        g_preFilterStub,
        static_cast<long>(g_preFilterTotalCalls),
        static_cast<long>(g_preFilterRdxGroupMap),
        static_cast<long>(g_preFilterRdxGroupMapSp),
        static_cast<long>(g_preFilterRdxBenny),
        static_cast<long>(g_preFilterRdxDlc),
        static_cast<long>(g_preFilterR8GroupMap),
        static_cast<long>(g_preFilterR8GroupMapSp),
        static_cast<long>(g_preFilterR8Benny),
        static_cast<long>(g_preFilterR8Dlc),
        g_preFilterGroupWhenR8Benny,
        g_preFilterR8WhenRdxBenny,
        reinterpret_cast<void*>(g_preFilterLastContext),
        reinterpret_cast<void*>(g_preFilterLastGroupPtr),
        reinterpret_cast<void*>(g_preFilterLastAssociatedPtr),
        static_cast<long>(g_preFilterRewrites));
}

static void DumpBuild1012OwnerGateState()
{
    if (!IsEnhancedVersion()
        || getGameVersion() != 1012)
        return;

    uint8_t* base = nullptr;
    uint8_t* end = nullptr;
    if (!GetExeRange(base, end)
        || !base
        || !end)
        return;

    const uint64_t imageSize =
        static_cast<uint64_t>(end - base);

    const uint64_t ownerStateRva = 0x03E31ACCULL;
    const uint64_t ownerSubStateRva = 0x03E31AD0ULL;
    const uint64_t ownerModeRva = 0x03E320E8ULL;
    const uint64_t ownerFlagRva = 0x03E31F58ULL;

    if (ownerStateRva + sizeof(uint32_t) > imageSize
        || ownerSubStateRva + sizeof(uint32_t) > imageSize
        || ownerModeRva + sizeof(uint32_t) > imageSize
        || ownerFlagRva + sizeof(uint8_t) > imageSize)
        return;

    uint32_t ownerState = 0;
    uint32_t ownerSubState = 0;
    uint32_t ownerMode = 0;
    uint8_t ownerFlag = 0;

    memcpy(&ownerState, base + ownerStateRva, sizeof(ownerState));
    memcpy(&ownerSubState, base + ownerSubStateRva, sizeof(ownerSubState));
    memcpy(&ownerMode, base + ownerModeRva, sizeof(ownerMode));
    memcpy(&ownerFlag, base + ownerFlagRva, sizeof(ownerFlag));

    Logf(
        "[OwnerState] 7C75E0 build-1012 control snapshot state(3E31ACC)=%u subState(3E31AD0)=%u mode(3E320E8)=%u flag(3E31F58)=0x%02X initialGateStateEq4=%s.",
        ownerState,
        ownerSubState,
        ownerMode,
        static_cast<unsigned int>(ownerFlag),
        ownerState == 4 ? "yes" : "no");
}

static uint8_t* FindPatternSig(uint8_t* start, uint8_t* end, const char* signature)
{
    if (!start || !end || !signature)
        return nullptr;

    std::vector<int> pat;
    pat.reserve(64);

    const char* s = signature;
    while (*s)
    {
        while (*s == ' ')
            ++s;

        if (!*s)
            break;

        if (s[0] == '?')
        {
            pat.push_back(-1);
            s += (s[1] == '?') ? 2 : 1;
            continue;
        }

        auto hexVal = [](char c) -> int
        {
            if (c >= '0' && c <= '9') return c - '0';
            if (c >= 'a' && c <= 'f') return 10 + (c - 'a');
            if (c >= 'A' && c <= 'F') return 10 + (c - 'A');
            return -1;
        };

        if (!s[1])
            break;

        const int hi = hexVal(s[0]);
        const int lo = hexVal(s[1]);
        if (hi < 0 || lo < 0)
            break;

        pat.push_back((hi << 4) | lo);
        s += 2;
    }

    if (pat.empty())
        return nullptr;

    const size_t plen = pat.size();
    for (uint8_t* p = start; p + plen <= end; ++p)
    {
        bool ok = true;
        for (size_t i = 0; i < plen; ++i)
        {
            if (pat[i] != -1 && p[i] != static_cast<uint8_t>(pat[i]))
            {
                ok = false;
                break;
            }
        }

        if (ok)
            return p;
    }

    return nullptr;
}

static void LogBytes(const void* address, size_t count, const char* label)
{
    if (!address || count == 0)
        return;

    const uint8_t* bytes = reinterpret_cast<const uint8_t*>(address);
    char line[1024]{};
    size_t pos = 0;

    for (size_t i = 0; i < count && pos + 4 < sizeof(line); ++i)
        pos += static_cast<size_t>(sprintf_s(line + pos, sizeof(line) - pos, "%02X ", bytes[i]));

    Logf("[Diag] %s @ %p: %s", label, address, line);
}

