static bool IsReadableLegacyV57Protection(
    DWORD protect)
{
    if ((protect & PAGE_GUARD) != 0
        || (protect & PAGE_NOACCESS) != 0)
    {
        return false;
    }

    const DWORD basic =
        protect & 0xFFU;
    return basic == PAGE_READONLY
        || basic == PAGE_READWRITE
        || basic == PAGE_WRITECOPY
        || basic == PAGE_EXECUTE_READ
        || basic == PAGE_EXECUTE_READWRITE
        || basic == PAGE_EXECUTE_WRITECOPY;
}

static bool GetLegacyV57ReadableSpan(
    uintptr_t address,
    size_t requested,
    size_t& readable)
{
    readable = 0;
    if (!address
        || requested == 0)
    {
        return false;
    }

    MEMORY_BASIC_INFORMATION mbi{};
    if (VirtualQuery(
            reinterpret_cast<LPCVOID>(address),
            &mbi,
            sizeof(mbi)) != sizeof(mbi)
        || mbi.State != MEM_COMMIT
        || !IsReadableLegacyV57Protection(
            mbi.Protect))
    {
        return false;
    }

    const uintptr_t regionBase =
        reinterpret_cast<uintptr_t>(
            mbi.BaseAddress);
    const uintptr_t regionEnd =
        regionBase
        + static_cast<uintptr_t>(
            mbi.RegionSize);

    if (address < regionBase
        || address >= regionEnd)
    {
        return false;
    }

    const size_t remaining =
        static_cast<size_t>(
            regionEnd - address);
    readable = remaining < requested
        ? remaining
        : requested;
    return readable != 0;
}

static void CaptureLegacyV57LowriderRecord(
    uintptr_t child,
    LONG index,
    uint32_t groupHash)
{
    if (!child
        || InterlockedCompareExchange(
            &g_legacyV57LowriderRecordCaptured,
            1,
            0) != 0)
    {
        return;
    }

    constexpr uint32_t mapGroup =
        0xBCC89179U;
    constexpr uint32_t storyGroup =
        0x578F99E2U;
    constexpr uint32_t benny =
        0x4CDFC843U;
    constexpr uint32_t mplowrider =
        0x61322A35U;
    constexpr size_t childSize =
        0xF0;
    constexpr size_t descriptorStride =
        0x18;

    bool success = false;

    __try
    {
        memcpy(
            g_legacyV57LowriderRecord,
            reinterpret_cast<const void*>(
                child),
            childSize);

        g_legacyV57LowriderChild =
            child;
        g_legacyV57LowriderIndex =
            index;
        g_legacyV57LowriderGroup =
            groupHash;

        for (uint16_t offset = 0;
             offset + sizeof(uint32_t)
                <= childSize;
             offset = static_cast<uint16_t>(
                offset + sizeof(uint32_t)))
        {
            uint32_t value = 0;
            memcpy(
                &value,
                g_legacyV57LowriderRecord
                    + offset,
                sizeof(value));

            if (value != mapGroup
                && value != storyGroup
                && value != benny
                && value != mplowrider)
            {
                continue;
            }

            if (g_legacyV57HashHitCount
                < static_cast<uint16_t>(
                    sizeof(g_legacyV57HashHits)
                    / sizeof(g_legacyV57HashHits[0])))
            {
                LegacyV57HashHit& hit =
                    g_legacyV57HashHits[
                        g_legacyV57HashHitCount++];
                hit.childOffset = offset;
                hit.value = value;
            }
        }

        for (uint16_t offset = 0;
             offset + sizeof(uintptr_t)
                <= childSize;
             offset = static_cast<uint16_t>(
                offset + sizeof(uintptr_t)))
        {
            uintptr_t pointerValue = 0;
            memcpy(
                &pointerValue,
                g_legacyV57LowriderRecord
                    + offset,
                sizeof(pointerValue));

            size_t readable = 0;
            if (!GetLegacyV57ReadableSpan(
                    pointerValue,
                    0x400,
                    readable)
                || readable < sizeof(uint32_t))
            {
                continue;
            }

            uint16_t mapHits = 0;
            uint16_t storyHits = 0;
            uint16_t bennyHits = 0;
            uint16_t dlcHits = 0;

            for (size_t scanOffset = 0;
                 scanOffset + sizeof(uint32_t)
                    <= readable;
                 scanOffset += sizeof(uint32_t))
            {
                uint32_t value = 0;
                memcpy(
                    &value,
                    reinterpret_cast<const void*>(
                        pointerValue + scanOffset),
                    sizeof(value));

                if (value == mapGroup)
                    ++mapHits;
                else if (value == storyGroup)
                    ++storyHits;
                else if (value == benny)
                    ++bennyHits;
                else if (value == mplowrider)
                    ++dlcHits;
            }

            if (mapHits == 0
                && storyHits == 0
                && bennyHits == 0
                && dlcHits == 0)
            {
                continue;
            }

            if (g_legacyV57PointerProbeCount
                < static_cast<uint16_t>(
                    sizeof(g_legacyV57PointerProbes)
                    / sizeof(g_legacyV57PointerProbes[0])))
            {
                LegacyV57PointerProbe& probe =
                    g_legacyV57PointerProbes[
                        g_legacyV57PointerProbeCount++];
                probe.childOffset = offset;
                probe.pointerValue = pointerValue;
                probe.bytesExamined =
                    static_cast<uint16_t>(
                        readable > 0xFFFF
                            ? 0xFFFF
                            : readable);
                probe.mapHits = mapHits;
                probe.storyHits = storyHits;
                probe.bennyHits = bennyHits;
                probe.dlcHits = dlcHits;
            }
        }

        for (uint16_t offset = 0;
             offset + sizeof(uintptr_t)
                    + sizeof(uint16_t)
                <= childSize;
             offset = static_cast<uint16_t>(
                offset + sizeof(uintptr_t)))
        {
            uintptr_t table = 0;
            uint16_t count = 0;
            memcpy(
                &table,
                g_legacyV57LowriderRecord
                    + offset,
                sizeof(table));
            memcpy(
                &count,
                g_legacyV57LowriderRecord
                    + offset
                    + sizeof(uintptr_t),
                sizeof(count));

            if (!table
                || count == 0
                || count > 64)
            {
                continue;
            }

            const size_t needed =
                static_cast<size_t>(count)
                * descriptorStride;
            size_t readable = 0;
            if (!GetLegacyV57ReadableSpan(
                    table,
                    needed,
                    readable)
                || readable < needed)
            {
                continue;
            }

            LegacyV57DescriptorCandidate candidate{};
            candidate.childOffset = offset;
            candidate.table = table;
            candidate.count = count;

            for (uint16_t i = 0;
                 i < count;
                 ++i)
            {
                const uintptr_t descriptor =
                    table
                    + (static_cast<uintptr_t>(i)
                        * descriptorStride);

                uint32_t descriptorGroup = 0;
                uintptr_t associatedTable = 0;
                uint16_t associatedCount = 0;
                memcpy(
                    &descriptorGroup,
                    reinterpret_cast<const void*>(
                        descriptor + 0x00),
                    sizeof(descriptorGroup));
                memcpy(
                    &associatedTable,
                    reinterpret_cast<const void*>(
                        descriptor + 0x08),
                    sizeof(associatedTable));
                memcpy(
                    &associatedCount,
                    reinterpret_cast<const void*>(
                        descriptor + 0x10),
                    sizeof(associatedCount));

                if (candidate.descriptorsCaptured
                    < static_cast<uint16_t>(
                        sizeof(candidate.groups)
                        / sizeof(candidate.groups[0])))
                {
                    const uint16_t slot =
                        candidate.descriptorsCaptured++;
                    candidate.groups[slot] =
                        descriptorGroup;
                    candidate.associatedCounts[slot] =
                        associatedCount;
                }

                if (descriptorGroup == mapGroup)
                {
                    ++candidate.knownGroupDescriptors;
                    ++candidate.mapDescriptors;
                }
                else if (descriptorGroup == storyGroup)
                {
                    ++candidate.knownGroupDescriptors;
                    ++candidate.storyDescriptors;
                }

                if ((descriptorGroup != mapGroup
                        && descriptorGroup != storyGroup)
                    || !associatedTable
                    || associatedCount == 0
                    || associatedCount > 512)
                {
                    continue;
                }

                size_t associatedReadable = 0;
                const size_t associatedBytes =
                    static_cast<size_t>(
                        associatedCount)
                    * sizeof(uint32_t);
                if (!GetLegacyV57ReadableSpan(
                        associatedTable,
                        associatedBytes,
                        associatedReadable)
                    || associatedReadable
                        < associatedBytes)
                {
                    continue;
                }

                for (uint16_t j = 0;
                     j < associatedCount;
                     ++j)
                {
                    uint32_t associated = 0;
                    memcpy(
                        &associated,
                        reinterpret_cast<const void*>(
                            associatedTable
                            + (static_cast<uintptr_t>(j)
                                * sizeof(uint32_t))),
                        sizeof(associated));

                    if (associated == benny)
                        ++candidate.bennyAssociations;
                }
            }

            if (candidate.knownGroupDescriptors == 0)
                continue;

            if (g_legacyV57DescriptorCandidateCount
                < static_cast<uint16_t>(
                    sizeof(g_legacyV57DescriptorCandidates)
                    / sizeof(g_legacyV57DescriptorCandidates[0])))
            {
                g_legacyV57DescriptorCandidates[
                    g_legacyV57DescriptorCandidateCount++] =
                    candidate;
            }
        }

        success = true;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        success = false;
    }

    if (!success)
    {
        InterlockedIncrement(
            &g_legacyV57CaptureFaults);
        InterlockedExchange(
            &g_legacyV57LowriderRecordCaptured,
            0);
    }
}

static bool IsWritableLegacyV59PrivateProtection(
    DWORD protect)
{
    if ((protect & PAGE_GUARD) != 0
        || (protect & PAGE_NOACCESS) != 0)
    {
        return false;
    }

    const DWORD basic =
        protect & 0xFFU;
    return basic == PAGE_READWRITE
        || basic == PAGE_WRITECOPY;
}

static uint16_t CountReadableLegacyV59PointerFields(
    uintptr_t child)
{
    if (!child)
        return 0;

    uint16_t count = 0;

    __try
    {
        for (uint16_t offset = 0;
             offset + sizeof(uintptr_t) <= 0xF0;
             offset = static_cast<uint16_t>(
                 offset + sizeof(uintptr_t)))
        {
            uintptr_t value = 0;
            memcpy(
                &value,
                reinterpret_cast<const void*>(
                    child + offset),
                sizeof(value));

            size_t readable = 0;
            if (GetLegacyV57ReadableSpan(
                    value,
                    sizeof(uint32_t),
                    readable)
                && readable >= sizeof(uint32_t))
            {
                ++count;
            }
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        return 0;
    }

    return count;
}

static bool ReadLegacyV59NeighborField60(
    uintptr_t child,
    intptr_t delta,
    uint32_t& value)
{
    value = 0;

    const intptr_t childSigned =
        static_cast<intptr_t>(child);
    const intptr_t neighborSigned =
        childSigned + delta;
    if (neighborSigned <= 0)
        return false;

    const uintptr_t address =
        static_cast<uintptr_t>(
            neighborSigned)
        + 0x60;

    size_t readable = 0;
    if (!GetLegacyV57ReadableSpan(
            address,
            sizeof(value),
            readable)
        || readable < sizeof(value))
    {
        return false;
    }

    __try
    {
        memcpy(
            &value,
            reinterpret_cast<const void*>(
                address),
            sizeof(value));
        return true;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        value = 0;
        return false;
    }
}

static void ResetLegacyV59HeapScanTelemetry()
{
    g_legacyV59HeapScanCompleted = false;
    g_legacyV59HeapScanTruncated = false;
    g_legacyV59HeapRegionsScanned = 0;
    g_legacyV59HeapBytesScanned = 0;
    g_legacyV59RawHashHits = 0;
    g_legacyV59AlignedRecordHits = 0;
    g_legacyV59PlausibleRecordHits = 0;
    g_legacyV59ScanFaults = 0;
    g_legacyV59CandidateCount = 0;
    memset(
        g_legacyV59Candidates,
        0,
        sizeof(g_legacyV59Candidates));
    g_legacyV59SelectedChild = 0;
    g_legacyV59SelectedScore = 0;
    g_legacyV59BestScoreTies = 0;
    g_legacyV59SelectedUnique = false;
}

static void DiscoverLegacyV59PostConstructionLowriderRecord(
    bool forceRescan)
{
    if (!IsLegacyExecutableImage()
        || getGameVersion() != 102)
    {
        return;
    }

    if (g_legacyV57LowriderRecordCaptured)
        return;

    if (g_legacyV59HeapScanAttempted
        && !forceRescan)
    {
        return;
    }

    g_legacyV59HeapScanAttempted = true;
    ResetLegacyV59HeapScanTelemetry();

    constexpr uint32_t mplowrider =
        0x61322A35U;
    constexpr uintptr_t childKeyOffset =
        0x60;
    constexpr intptr_t childStride =
        0xF0;
    constexpr uint64_t maxScanBytes =
        3ULL * 1024ULL * 1024ULL * 1024ULL;

    uint32_t stackMarker = mplowrider;
    MEMORY_BASIC_INFORMATION stackMbi{};
    uintptr_t stackAllocationBase = 0;
    if (VirtualQuery(
            &stackMarker,
            &stackMbi,
            sizeof(stackMbi)) == sizeof(stackMbi))
    {
        stackAllocationBase =
            reinterpret_cast<uintptr_t>(
                stackMbi.AllocationBase);
    }

    SYSTEM_INFO systemInfo{};
    GetSystemInfo(&systemInfo);

    uintptr_t cursor =
        reinterpret_cast<uintptr_t>(
            systemInfo.lpMinimumApplicationAddress);
    const uintptr_t maximum =
        reinterpret_cast<uintptr_t>(
            systemInfo.lpMaximumApplicationAddress);

    while (cursor < maximum)
    {
        MEMORY_BASIC_INFORMATION mbi{};
        if (VirtualQuery(
                reinterpret_cast<LPCVOID>(cursor),
                &mbi,
                sizeof(mbi)) != sizeof(mbi))
        {
            break;
        }

        const uintptr_t regionBase =
            reinterpret_cast<uintptr_t>(
                mbi.BaseAddress);
        const uintptr_t regionSize =
            static_cast<uintptr_t>(
                mbi.RegionSize);
        const uintptr_t regionEnd =
            regionBase + regionSize;

        if (regionEnd <= cursor)
            break;

        const uintptr_t allocationBase =
            reinterpret_cast<uintptr_t>(
                mbi.AllocationBase);

        const bool eligible =
            mbi.State == MEM_COMMIT
            && mbi.Type == MEM_PRIVATE
            && allocationBase != 0
            && allocationBase != stackAllocationBase
            && IsWritableLegacyV59PrivateProtection(
                mbi.Protect);

        if (eligible)
        {
            if (g_legacyV59HeapBytesScanned
                    + static_cast<uint64_t>(
                        regionSize)
                > maxScanBytes)
            {
                g_legacyV59HeapScanTruncated = true;
                break;
            }

            ++g_legacyV59HeapRegionsScanned;
            g_legacyV59HeapBytesScanned +=
                static_cast<uint64_t>(
                    regionSize);

            bool regionFaulted = false;

            __try
            {
                const uint8_t* begin =
                    reinterpret_cast<const uint8_t*>(
                        regionBase);
                const uint8_t* end =
                    reinterpret_cast<const uint8_t*>(
                        regionEnd);
                const uint8_t* search =
                    begin;

                while (search + sizeof(uint32_t)
                    <= end)
                {
                    const void* firstByteHit =
                        memchr(
                            search,
                            static_cast<int>(
                                mplowrider & 0xFFU),
                            static_cast<size_t>(
                                end - search));
                    if (!firstByteHit)
                        break;

                    const uint8_t* hit =
                        reinterpret_cast<const uint8_t*>(
                            firstByteHit);
                    if (hit + sizeof(uint32_t)
                        > end)
                    {
                        break;
                    }

                    uint32_t value = 0;
                    memcpy(
                        &value,
                        hit,
                        sizeof(value));

                    if (value == mplowrider)
                    {
                        ++g_legacyV59RawHashHits;

                        const uintptr_t hashAddress =
                            reinterpret_cast<uintptr_t>(
                                hit);

                        if (hashAddress >= childKeyOffset)
                        {
                            const uintptr_t child =
                                hashAddress
                                - childKeyOffset;

                            size_t childReadable = 0;
                            if ((child & 0x0FULL) == 0
                                && GetLegacyV57ReadableSpan(
                                    child,
                                    0xF0,
                                    childReadable)
                                && childReadable >= 0xF0)
                            {
                                ++g_legacyV59AlignedRecordHits;

                                MEMORY_BASIC_INFORMATION childMbi{};
                                if (VirtualQuery(
                                        reinterpret_cast<LPCVOID>(
                                            child),
                                        &childMbi,
                                        sizeof(childMbi))
                                        == sizeof(childMbi)
                                    && childMbi.State == MEM_COMMIT
                                    && childMbi.Type == MEM_PRIVATE)
                                {
                                    const uint16_t pointerFields =
                                        CountReadableLegacyV59PointerFields(
                                            child);

                                    uint32_t previousField60 = 0;
                                    uint32_t nextField60 = 0;
                                    const bool havePrevious =
                                        ReadLegacyV59NeighborField60(
                                            child,
                                            -childStride,
                                            previousField60);
                                    const bool haveNext =
                                        ReadLegacyV59NeighborField60(
                                            child,
                                            childStride,
                                            nextField60);

                                    uint16_t score = 4;
                                    if (pointerFields >= 1)
                                        score += 1;
                                    if (pointerFields >= 2)
                                        score += 1;
                                    if (pointerFields >= 4)
                                        score += 1;
                                    if (havePrevious
                                        && previousField60 != 0)
                                    {
                                        score += 2;
                                    }
                                    if (haveNext
                                        && nextField60 != 0)
                                    {
                                        score += 2;
                                    }

                                    if (pointerFields >= 2
                                        && ((havePrevious
                                                && previousField60 != 0)
                                            || (haveNext
                                                && nextField60 != 0)))
                                    {
                                        ++g_legacyV59PlausibleRecordHits;

                                        if (g_legacyV59CandidateCount
                                            < static_cast<uint16_t>(
                                                sizeof(g_legacyV59Candidates)
                                                / sizeof(g_legacyV59Candidates[0])))
                                        {
                                            LegacyV59HeapRecordCandidate&
                                                candidate =
                                                    g_legacyV59Candidates[
                                                        g_legacyV59CandidateCount++];
                                            candidate.hashAddress =
                                                hashAddress;
                                            candidate.child =
                                                child;
                                            candidate.allocationBase =
                                                reinterpret_cast<uintptr_t>(
                                                    childMbi.AllocationBase);
                                            candidate.protect =
                                                childMbi.Protect;
                                            candidate.readablePointerFields =
                                                pointerFields;
                                            candidate.score =
                                                score;
                                            candidate.previousField60 =
                                                previousField60;
                                            candidate.nextField60 =
                                                nextField60;
                                        }

                                        if (score
                                            > g_legacyV59SelectedScore)
                                        {
                                            g_legacyV59SelectedScore =
                                                score;
                                            g_legacyV59SelectedChild =
                                                child;
                                            g_legacyV59BestScoreTies =
                                                1;
                                        }
                                        else if (score
                                            == g_legacyV59SelectedScore)
                                        {
                                            ++g_legacyV59BestScoreTies;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    search = hit + 1;
                }
            }
            __except(EXCEPTION_EXECUTE_HANDLER)
            {
                regionFaulted = true;
            }

            if (regionFaulted)
                ++g_legacyV59ScanFaults;
        }

        cursor = regionEnd;
    }

    g_legacyV59SelectedUnique =
        g_legacyV59SelectedChild != 0
        && g_legacyV59BestScoreTies == 1;

    if (g_legacyV59SelectedUnique)
    {
        CaptureLegacyV57LowriderRecord(
            g_legacyV59SelectedChild,
            -1,
            0);
    }

    g_legacyV59HeapScanCompleted = true;
}

static void LogLegacyV59PostConstructionState(
    const char* phase)
{
    Logf(
        "[LegacyHeapV59] %s attempted=%s completed=%s truncated=%s regions=%u scannedMiB=%llu rawMplowriderHits=%u alignedChild60Hits=%u plausibleRecords=%u candidatesStored=%u faults=%u selected=%p score=%u bestScoreTies=%u selectedUnique=%s detailedRecordCaptured=%s descriptorCandidates=%u.",
        phase ? phase : "state",
        g_legacyV59HeapScanAttempted ? "yes" : "no",
        g_legacyV59HeapScanCompleted ? "yes" : "no",
        g_legacyV59HeapScanTruncated ? "yes" : "no",
        g_legacyV59HeapRegionsScanned,
        static_cast<unsigned long long>(
            g_legacyV59HeapBytesScanned
            / (1024ULL * 1024ULL)),
        g_legacyV59RawHashHits,
        g_legacyV59AlignedRecordHits,
        g_legacyV59PlausibleRecordHits,
        static_cast<unsigned int>(
            g_legacyV59CandidateCount),
        g_legacyV59ScanFaults,
        reinterpret_cast<void*>(
            g_legacyV59SelectedChild),
        static_cast<unsigned int>(
            g_legacyV59SelectedScore),
        static_cast<unsigned int>(
            g_legacyV59BestScoreTies),
        g_legacyV59SelectedUnique ? "yes" : "no",
        g_legacyV57LowriderRecordCaptured ? "yes" : "no",
        static_cast<unsigned int>(
            g_legacyV57DescriptorCandidateCount));

    for (uint16_t i = 0;
         i < g_legacyV59CandidateCount;
         ++i)
    {
        const LegacyV59HeapRecordCandidate& candidate =
            g_legacyV59Candidates[i];

        Logf(
            "[LegacyHeapV59] candidate[%u] hash=%p child=%p allocationBase=%p protect=0x%08lX readablePointerFields=%u score=%u neighborField60{prev=0x%08X next=0x%08X}%s.",
            static_cast<unsigned int>(i),
            reinterpret_cast<void*>(
                candidate.hashAddress),
            reinterpret_cast<void*>(
                candidate.child),
            reinterpret_cast<void*>(
                candidate.allocationBase),
            static_cast<unsigned long>(
                candidate.protect),
            static_cast<unsigned int>(
                candidate.readablePointerFields),
            static_cast<unsigned int>(
                candidate.score),
            candidate.previousField60,
            candidate.nextField60,
            candidate.child == g_legacyV59SelectedChild
                ? " SELECTED"
                : "");
    }
}

static void LogLegacyV60DeepCandidateAnalysis(
    const char* phase)
{
    constexpr uint32_t mapGroup = 0xBCC89179U;
    constexpr uint32_t storyGroup = 0x578F99E2U;
    constexpr uint32_t benny = 0x4CDFC843U;
    constexpr uint32_t mplowrider = 0x61322A35U;
    constexpr size_t childSize = 0xF0;
    constexpr size_t descriptorStride = 0x18;

    Logf(
        "[LegacyDeepV60] %s candidates=%u scanCompleted=%s truncated=%s. All analysis below is read-only.",
        phase ? phase : "state",
        static_cast<unsigned int>(g_legacyV59CandidateCount),
        g_legacyV59HeapScanCompleted ? "yes" : "no",
        g_legacyV59HeapScanTruncated ? "yes" : "no");

    for (uint16_t candidateIndex = 0;
         candidateIndex < g_legacyV59CandidateCount;
         ++candidateIndex)
    {
        const LegacyV59HeapRecordCandidate& candidate =
            g_legacyV59Candidates[candidateIndex];

        uint16_t directMap = 0;
        uint16_t directStory = 0;
        uint16_t directBenny = 0;
        uint16_t directDlc = 0;
        uint16_t pointerFieldsWithKnownHashes = 0;
        uint32_t reachableMap = 0;
        uint32_t reachableStory = 0;
        uint32_t reachableBenny = 0;
        uint32_t reachableDlc = 0;
        uint16_t descriptorViews = 0;
        uint16_t descriptorMap = 0;
        uint16_t descriptorStory = 0;
        uint16_t descriptorBennyAssociations = 0;
        bool faulted = false;

        __try
        {
            for (uint16_t offset = 0;
                 offset + sizeof(uint32_t) <= childSize;
                 offset = static_cast<uint16_t>(
                     offset + sizeof(uint32_t)))
            {
                uint32_t value = 0;
                memcpy(
                    &value,
                    reinterpret_cast<const void*>(
                        candidate.child + offset),
                    sizeof(value));

                if (value == mapGroup)
                    ++directMap;
                else if (value == storyGroup)
                    ++directStory;
                else if (value == benny)
                    ++directBenny;
                else if (value == mplowrider)
                    ++directDlc;
            }

            for (uint16_t offset = 0;
                 offset + sizeof(uintptr_t) <= childSize;
                 offset = static_cast<uint16_t>(
                     offset + sizeof(uintptr_t)))
            {
                uintptr_t pointerValue = 0;
                memcpy(
                    &pointerValue,
                    reinterpret_cast<const void*>(
                        candidate.child + offset),
                    sizeof(pointerValue));

                size_t readable = 0;
                if (GetLegacyV57ReadableSpan(
                        pointerValue,
                        0x400,
                        readable)
                    && readable >= sizeof(uint32_t))
                {
                    uint16_t localMap = 0;
                    uint16_t localStory = 0;
                    uint16_t localBenny = 0;
                    uint16_t localDlc = 0;

                    for (size_t scanOffset = 0;
                         scanOffset + sizeof(uint32_t) <= readable;
                         scanOffset += sizeof(uint32_t))
                    {
                        uint32_t value = 0;
                        memcpy(
                            &value,
                            reinterpret_cast<const void*>(
                                pointerValue + scanOffset),
                            sizeof(value));

                        if (value == mapGroup)
                            ++localMap;
                        else if (value == storyGroup)
                            ++localStory;
                        else if (value == benny)
                            ++localBenny;
                        else if (value == mplowrider)
                            ++localDlc;
                    }

                    if (localMap != 0
                        || localStory != 0
                        || localBenny != 0
                        || localDlc != 0)
                    {
                        ++pointerFieldsWithKnownHashes;
                        reachableMap += localMap;
                        reachableStory += localStory;
                        reachableBenny += localBenny;
                        reachableDlc += localDlc;

                        Logf(
                            "[LegacyDeepV60] candidate[%u] pointer childOffset=0x%X pointer=%p readable=0x%X hits{GROUP_MAP=%u GROUP_MAP_SP=%u Benny=%u mplowrider=%u}.",
                            static_cast<unsigned int>(candidateIndex),
                            static_cast<unsigned int>(offset),
                            reinterpret_cast<void*>(pointerValue),
                            static_cast<unsigned int>(readable),
                            static_cast<unsigned int>(localMap),
                            static_cast<unsigned int>(localStory),
                            static_cast<unsigned int>(localBenny),
                            static_cast<unsigned int>(localDlc));
                    }
                }

                if (offset + sizeof(uintptr_t) + sizeof(uint16_t)
                    > childSize)
                {
                    continue;
                }

                uint16_t count = 0;
                memcpy(
                    &count,
                    reinterpret_cast<const void*>(
                        candidate.child + offset + sizeof(uintptr_t)),
                    sizeof(count));

                if (!pointerValue || count == 0 || count > 64)
                    continue;

                const size_t needed =
                    static_cast<size_t>(count) * descriptorStride;
                size_t descriptorReadable = 0;
                if (!GetLegacyV57ReadableSpan(
                        pointerValue,
                        needed,
                        descriptorReadable)
                    || descriptorReadable < needed)
                {
                    continue;
                }

                uint16_t localMapDescriptors = 0;
                uint16_t localStoryDescriptors = 0;
                uint16_t localBennyAssociations = 0;

                for (uint16_t descriptorIndex = 0;
                     descriptorIndex < count;
                     ++descriptorIndex)
                {
                    const uintptr_t descriptor =
                        pointerValue
                        + (static_cast<uintptr_t>(descriptorIndex)
                            * descriptorStride);

                    uint32_t descriptorGroup = 0;
                    uintptr_t associatedTable = 0;
                    uint16_t associatedCount = 0;
                    memcpy(
                        &descriptorGroup,
                        reinterpret_cast<const void*>(descriptor + 0x00),
                        sizeof(descriptorGroup));
                    memcpy(
                        &associatedTable,
                        reinterpret_cast<const void*>(descriptor + 0x08),
                        sizeof(associatedTable));
                    memcpy(
                        &associatedCount,
                        reinterpret_cast<const void*>(descriptor + 0x10),
                        sizeof(associatedCount));

                    if (descriptorGroup != mapGroup
                        && descriptorGroup != storyGroup)
                    {
                        continue;
                    }

                    if (descriptorGroup == mapGroup)
                        ++localMapDescriptors;
                    else
                        ++localStoryDescriptors;

                    uint16_t localDescriptorBenny = 0;
                    if (associatedTable
                        && associatedCount != 0
                        && associatedCount <= 512)
                    {
                        const size_t associatedBytes =
                            static_cast<size_t>(associatedCount)
                            * sizeof(uint32_t);
                        size_t associatedReadable = 0;
                        if (GetLegacyV57ReadableSpan(
                                associatedTable,
                                associatedBytes,
                                associatedReadable)
                            && associatedReadable >= associatedBytes)
                        {
                            for (uint16_t associatedIndex = 0;
                                 associatedIndex < associatedCount;
                                 ++associatedIndex)
                            {
                                uint32_t associated = 0;
                                memcpy(
                                    &associated,
                                    reinterpret_cast<const void*>(
                                        associatedTable
                                        + (static_cast<uintptr_t>(
                                            associatedIndex)
                                            * sizeof(uint32_t))),
                                    sizeof(associated));

                                if (associated == benny)
                                {
                                    ++localDescriptorBenny;
                                    ++localBennyAssociations;
                                }
                            }
                        }
                    }

                    Logf(
                        "[LegacyDeepV60] candidate[%u] descriptorView childOffset=0x%X table=%p count=%u descriptor[%u]{group=0x%08X associatedTable=%p associatedCount=%u Benny=%u}.",
                        static_cast<unsigned int>(candidateIndex),
                        static_cast<unsigned int>(offset),
                        reinterpret_cast<void*>(pointerValue),
                        static_cast<unsigned int>(count),
                        static_cast<unsigned int>(descriptorIndex),
                        descriptorGroup,
                        reinterpret_cast<void*>(associatedTable),
                        static_cast<unsigned int>(associatedCount),
                        static_cast<unsigned int>(localDescriptorBenny));
                }

                if (localMapDescriptors != 0
                    || localStoryDescriptors != 0)
                {
                    ++descriptorViews;
                    descriptorMap += localMapDescriptors;
                    descriptorStory += localStoryDescriptors;
                    descriptorBennyAssociations +=
                        localBennyAssociations;

                    Logf(
                        "[LegacyDeepV60] candidate[%u] descriptorViewSummary childOffset=0x%X table=%p count=%u GROUP_MAP=%u GROUP_MAP_SP=%u BennyAssociations=%u.",
                        static_cast<unsigned int>(candidateIndex),
                        static_cast<unsigned int>(offset),
                        reinterpret_cast<void*>(pointerValue),
                        static_cast<unsigned int>(count),
                        static_cast<unsigned int>(localMapDescriptors),
                        static_cast<unsigned int>(localStoryDescriptors),
                        static_cast<unsigned int>(localBennyAssociations));
                }
            }
        }
        __except(EXCEPTION_EXECUTE_HANDLER)
        {
            faulted = true;
        }

        Logf(
            "[LegacyDeepV60] candidate[%u] SUMMARY child=%p coarseScore=%u knownPointers=%u direct{GROUP_MAP=%u GROUP_MAP_SP=%u Benny=%u mplowrider=%u} reachable{GROUP_MAP=%u GROUP_MAP_SP=%u Benny=%u mplowrider=%u} descriptorViews=%u descriptorGroups{GROUP_MAP=%u GROUP_MAP_SP=%u} descriptorBennyAssociations=%u faulted=%s.",
            static_cast<unsigned int>(candidateIndex),
            reinterpret_cast<void*>(candidate.child),
            static_cast<unsigned int>(candidate.score),
            static_cast<unsigned int>(pointerFieldsWithKnownHashes),
            static_cast<unsigned int>(directMap),
            static_cast<unsigned int>(directStory),
            static_cast<unsigned int>(directBenny),
            static_cast<unsigned int>(directDlc),
            static_cast<unsigned int>(reachableMap),
            static_cast<unsigned int>(reachableStory),
            static_cast<unsigned int>(reachableBenny),
            static_cast<unsigned int>(reachableDlc),
            static_cast<unsigned int>(descriptorViews),
            static_cast<unsigned int>(descriptorMap),
            static_cast<unsigned int>(descriptorStory),
            static_cast<unsigned int>(descriptorBennyAssociations),
            faulted ? "yes" : "no");
    }
}

struct LegacyV61DescriptorState
{
    bool attempted;
    bool candidateUnique;
    bool applied;
    bool alreadyPresent;
    bool verified;
    bool restoreAttempted;
    bool restoreVerified;
    bool restoreFailed;
    bool faulted;
    uint16_t matchingCandidates;
    uintptr_t child;
    uintptr_t originalTable;
    uint16_t originalCount;
    uint16_t originalCapacity;
    uintptr_t temporaryTable;
    uint16_t temporaryCount;
    uint16_t temporaryCapacity;
    uint16_t mapDescriptorIndex;
    uintptr_t originalMapAssociatedTable;
    uint16_t originalMapAssociatedCount;
    uint16_t originalMapAssociatedCapacity;
    uint16_t temporaryMapAssociatedCount;
    uint16_t temporaryMapAssociatedCapacity;
    uint16_t temporaryStoryAssociatedCapacity;
    uint16_t originalMapBennyCount;
    uint16_t storyBennyBefore;
};

static LegacyV61DescriptorState g_legacyV61{};
static bool g_legacyV61AllowUniversalOlderBuild = false;
static uint8_t g_legacyV61DescriptorScratch[65 * 0x18]{};
static uint32_t g_legacyV61MapAssociatedScratch[512]{};
static uint32_t g_legacyV61StoryAssociatedScratch[1] = { 0x4CDFC843U };

static bool InspectLegacyV61DescriptorFingerprint(
    uintptr_t child,
    bool requireStock,
    uintptr_t& descriptorTable,
    uint16_t& descriptorCount,
    uint16_t& mapDescriptorIndex,
    uintptr_t& mapAssociatedTable,
    uint16_t& mapAssociatedCount,
    uint16_t& mapBennyCount,
    uint16_t& storyBennyCount)
{
    descriptorTable = 0;
    descriptorCount = 0;
    mapDescriptorIndex = 0xFFFF;
    mapAssociatedTable = 0;
    mapAssociatedCount = 0;
    mapBennyCount = 0;
    storyBennyCount = 0;

    if (!child)
        return false;

    constexpr uint32_t mplowrider = 0x61322A35U;
    constexpr uint32_t mapGroup = 0xBCC89179U;
    constexpr uint32_t storyGroup = 0x578F99E2U;
    constexpr uint32_t benny = 0x4CDFC843U;
    constexpr size_t descriptorStride = 0x18;

    bool valid = false;

    __try
    {
        uint32_t field60 = 0;
        memcpy(
            &field60,
            reinterpret_cast<const void*>(child + 0x60),
            sizeof(field60));
        if (field60 != mplowrider)
            return false;

        memcpy(
            &descriptorTable,
            reinterpret_cast<const void*>(child + 0x78),
            sizeof(descriptorTable));
        memcpy(
            &descriptorCount,
            reinterpret_cast<const void*>(child + 0x80),
            sizeof(descriptorCount));

        if (!descriptorTable
            || descriptorCount == 0
            || descriptorCount > 64)
        {
            return false;
        }

        const size_t descriptorBytes =
            static_cast<size_t>(descriptorCount)
            * descriptorStride;
        size_t descriptorReadable = 0;
        if (!GetLegacyV57ReadableSpan(
                descriptorTable,
                descriptorBytes,
                descriptorReadable)
            || descriptorReadable < descriptorBytes)
        {
            return false;
        }

        uint16_t mapDescriptors = 0;

        for (uint16_t i = 0;
             i < descriptorCount;
             ++i)
        {
            const uintptr_t descriptor =
                descriptorTable
                + (static_cast<uintptr_t>(i)
                    * descriptorStride);

            uint32_t group = 0;
            uintptr_t associatedTable = 0;
            uint16_t associatedCount = 0;
            memcpy(
                &group,
                reinterpret_cast<const void*>(descriptor + 0x00),
                sizeof(group));
            memcpy(
                &associatedTable,
                reinterpret_cast<const void*>(descriptor + 0x08),
                sizeof(associatedTable));
            memcpy(
                &associatedCount,
                reinterpret_cast<const void*>(descriptor + 0x10),
                sizeof(associatedCount));

            if (group != mapGroup
                && group != storyGroup)
            {
                continue;
            }

            if (!associatedTable
                || associatedCount == 0
                || associatedCount > 512)
            {
                return false;
            }

            const size_t associatedBytes =
                static_cast<size_t>(associatedCount)
                * sizeof(uint32_t);
            size_t associatedReadable = 0;
            if (!GetLegacyV57ReadableSpan(
                    associatedTable,
                    associatedBytes,
                    associatedReadable)
                || associatedReadable < associatedBytes)
            {
                return false;
            }

            uint16_t localBenny = 0;
            for (uint16_t j = 0;
                 j < associatedCount;
                 ++j)
            {
                uint32_t associated = 0;
                memcpy(
                    &associated,
                    reinterpret_cast<const void*>(
                        associatedTable
                        + (static_cast<uintptr_t>(j)
                            * sizeof(uint32_t))),
                    sizeof(associated));
                if (associated == benny)
                    ++localBenny;
            }

            if (group == mapGroup)
            {
                ++mapDescriptors;
                mapDescriptorIndex = i;
                mapAssociatedTable = associatedTable;
                mapAssociatedCount = associatedCount;
                mapBennyCount = localBenny;
            }
            else
            {
                storyBennyCount = static_cast<uint16_t>(
                    storyBennyCount + localBenny);
            }
        }

        if (mapDescriptors != 1)
            return false;

        if (requireStock)
        {

            valid = descriptorCount == 2
                && mapDescriptorIndex == 1
                && mapAssociatedCount == 4
                && mapBennyCount == 1
                && storyBennyCount == 0;
        }
        else
        {
            valid = storyBennyCount != 0;
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        valid = false;
    }

    return valid;
}

static bool RestoreLegacyV61DescriptorView()
{
    if (!g_legacyV61.applied)
        return true;

    g_legacyV61.restoreAttempted = true;
    bool restored = false;

    __try
    {
        memcpy(
            reinterpret_cast<void*>(g_legacyV61.child + 0x78),
            &g_legacyV61.originalTable,
            sizeof(g_legacyV61.originalTable));
        memcpy(
            reinterpret_cast<void*>(g_legacyV61.child + 0x80),
            &g_legacyV61.originalCount,
            sizeof(g_legacyV61.originalCount));
        memcpy(
            reinterpret_cast<void*>(g_legacyV61.child + 0x82),
            &g_legacyV61.originalCapacity,
            sizeof(g_legacyV61.originalCapacity));

        uintptr_t verifyTable = 0;
        uint16_t verifyCount = 0;
        uint16_t verifyCapacity = 0;
        memcpy(
            &verifyTable,
            reinterpret_cast<const void*>(g_legacyV61.child + 0x78),
            sizeof(verifyTable));
        memcpy(
            &verifyCount,
            reinterpret_cast<const void*>(g_legacyV61.child + 0x80),
            sizeof(verifyCount));
        memcpy(
            &verifyCapacity,
            reinterpret_cast<const void*>(g_legacyV61.child + 0x82),
            sizeof(verifyCapacity));

        restored = verifyTable == g_legacyV61.originalTable
            && verifyCount == g_legacyV61.originalCount
            && verifyCapacity == g_legacyV61.originalCapacity;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        restored = false;
    }

    g_legacyV61.restoreVerified = restored;
    g_legacyV61.restoreFailed = !restored;
    if (restored)
        g_legacyV61.applied = false;

    Logf(
        "[LegacyDescriptorV61] restore attempted=yes verified=%s child=%p table=%p count=%u capacity=%u.",
        restored ? "yes" : "no",
        reinterpret_cast<void*>(g_legacyV61.child),
        reinterpret_cast<void*>(g_legacyV61.originalTable),
        static_cast<unsigned int>(g_legacyV61.originalCount),
        static_cast<unsigned int>(g_legacyV61.originalCapacity));

    return restored;
}

static bool ApplyLegacyV61DescriptorView(uintptr_t expectedChild = 0)
{
    if (!IsLegacyExecutableImage()
        || (getGameVersion() != 102
            && !g_legacyV61AllowUniversalOlderBuild))
    {
        return false;
    }

    if (g_legacyV61.restoreFailed)
    {
        Logf(
            "[LegacyDescriptorV61] REFUSED: a prior restore failed; no further Legacy mutation is allowed this session.");
        return false;
    }

    if (g_legacyV61.applied)
        return true;

    g_legacyV61 = LegacyV61DescriptorState{};
    g_legacyV61.attempted = true;

    uintptr_t selectedChild = 0;
    uintptr_t selectedTable = 0;
    uint16_t selectedCount = 0;
    uint16_t selectedMapDescriptor = 0xFFFF;
    uintptr_t selectedMapAssociated = 0;
    uint16_t selectedMapAssociatedCount = 0;
    uint16_t selectedMapBennyCount = 0;
    uint16_t selectedStoryBennyCount = 0;

    if (expectedChild != 0)
    {
        if (InspectLegacyV61DescriptorFingerprint(
                expectedChild,
                true,
                selectedTable,
                selectedCount,
                selectedMapDescriptor,
                selectedMapAssociated,
                selectedMapAssociatedCount,
                selectedMapBennyCount,
                selectedStoryBennyCount))
        {
            g_legacyV61.matchingCandidates = 1;
            selectedChild = expectedChild;
        }
    }
    else
    {

        DiscoverLegacyV59PostConstructionLowriderRecord(false);

        for (uint16_t i = 0;
             i < g_legacyV59CandidateCount;
             ++i)
        {
            uintptr_t table = 0;
            uint16_t count = 0;
            uint16_t mapDescriptor = 0xFFFF;
            uintptr_t mapAssociated = 0;
            uint16_t mapAssociatedCount = 0;
            uint16_t mapBennyCount = 0;
            uint16_t storyBennyCount = 0;

            if (InspectLegacyV61DescriptorFingerprint(
                    g_legacyV59Candidates[i].child,
                    true,
                    table,
                    count,
                    mapDescriptor,
                    mapAssociated,
                    mapAssociatedCount,
                    mapBennyCount,
                    storyBennyCount))
            {
                ++g_legacyV61.matchingCandidates;
                selectedChild = g_legacyV59Candidates[i].child;
                selectedTable = table;
                selectedCount = count;
                selectedMapDescriptor = mapDescriptor;
                selectedMapAssociated = mapAssociated;
                selectedMapAssociatedCount = mapAssociatedCount;
                selectedMapBennyCount = mapBennyCount;
                selectedStoryBennyCount = storyBennyCount;
            }
        }
    }

    g_legacyV61.candidateUnique =
        g_legacyV61.matchingCandidates == 1;

    if (!g_legacyV61.candidateUnique)
    {
        Logf(
            "[LegacyDescriptorV61] REFUSED: stock descriptor fingerprint matched %u candidates (expected exactly 1). No write performed.",
            static_cast<unsigned int>(
                g_legacyV61.matchingCandidates));
        return false;
    }

    g_legacyV61.child = selectedChild;
    g_legacyV61.originalTable = selectedTable;
    g_legacyV61.originalCount = selectedCount;
    g_legacyV61.mapDescriptorIndex = selectedMapDescriptor;
    g_legacyV61.originalMapAssociatedTable = selectedMapAssociated;
    g_legacyV61.originalMapAssociatedCount =
        selectedMapAssociatedCount;
    g_legacyV61.originalMapBennyCount =
        selectedMapBennyCount;
    g_legacyV61.storyBennyBefore =
        selectedStoryBennyCount;

    uint16_t selectedDescriptorCapacity = 0;
    uint16_t selectedMapAssociatedCapacity = 0;
    bool capacityMetadataReadable = false;
    __try
    {
        memcpy(
            &selectedDescriptorCapacity,
            reinterpret_cast<const void*>(selectedChild + 0x82),
            sizeof(selectedDescriptorCapacity));

        const uintptr_t selectedMapDescriptorAddress =
            selectedTable
            + (static_cast<uintptr_t>(selectedMapDescriptor)
                * 0x18U);
        memcpy(
            &selectedMapAssociatedCapacity,
            reinterpret_cast<const void*>(
                selectedMapDescriptorAddress + 0x12),
            sizeof(selectedMapAssociatedCapacity));

        capacityMetadataReadable = true;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        capacityMetadataReadable = false;
    }

    if (!capacityMetadataReadable
        || selectedDescriptorCapacity < selectedCount
        || selectedMapAssociatedCapacity
            < selectedMapAssociatedCount)
    {
        Logf(
            "[LegacySetup2V66] REFUSED: stock vector metadata is not sane/readable. descriptor{count=%u capacity=%u} GROUP_MAP associated{count=%u capacity=%u}.",
            static_cast<unsigned int>(selectedCount),
            static_cast<unsigned int>(selectedDescriptorCapacity),
            static_cast<unsigned int>(selectedMapAssociatedCount),
            static_cast<unsigned int>(selectedMapAssociatedCapacity));
        return false;
    }

    g_legacyV61.originalCapacity =
        selectedDescriptorCapacity;
    g_legacyV61.originalMapAssociatedCapacity =
        selectedMapAssociatedCapacity;

    constexpr size_t descriptorStride = 0x18;
    constexpr uint32_t storyGroup = 0x578F99E2U;
    constexpr uint32_t benny = 0x4CDFC843U;

    bool applied = false;

    __try
    {
        memcpy(
            g_legacyV61DescriptorScratch,
            reinterpret_cast<const void*>(selectedTable),
            static_cast<size_t>(selectedCount)
                * descriptorStride);

        uint16_t mapScratchCount = 0;
        for (uint16_t i = 0;
             i < selectedMapAssociatedCount;
             ++i)
        {
            uint32_t associated = 0;
            memcpy(
                &associated,
                reinterpret_cast<const void*>(
                    selectedMapAssociated
                    + (static_cast<uintptr_t>(i)
                        * sizeof(uint32_t))),
                sizeof(associated));

            if (associated == benny)
                continue;

            if (mapScratchCount >= 512)
                return false;

            g_legacyV61MapAssociatedScratch[
                mapScratchCount++] = associated;
        }

        if (mapScratchCount + 1
            != selectedMapAssociatedCount)
        {
            Logf(
                "[LegacyDescriptorV61] REFUSED: expected to remove exactly one Benny association from GROUP_MAP; sourceCount=%u remaining=%u.",
                static_cast<unsigned int>(
                    selectedMapAssociatedCount),
                static_cast<unsigned int>(mapScratchCount));
            return false;
        }

        uint8_t* mapDescriptor =
            g_legacyV61DescriptorScratch
            + (static_cast<size_t>(selectedMapDescriptor)
                * descriptorStride);
        const uintptr_t mapAssociatedScratchPointer =
            reinterpret_cast<uintptr_t>(
                g_legacyV61MapAssociatedScratch);
        memcpy(
            mapDescriptor + 0x08,
            &mapAssociatedScratchPointer,
            sizeof(mapAssociatedScratchPointer));
        memcpy(
            mapDescriptor + 0x10,
            &mapScratchCount,
            sizeof(mapScratchCount));

        memcpy(
            mapDescriptor + 0x12,
            &selectedMapAssociatedCapacity,
            sizeof(selectedMapAssociatedCapacity));

        uint8_t* storyDescriptor =
            g_legacyV61DescriptorScratch
            + (static_cast<size_t>(selectedCount)
                * descriptorStride);
        memset(storyDescriptor, 0, descriptorStride);
        memcpy(
            storyDescriptor + 0x00,
            &storyGroup,
            sizeof(storyGroup));
        const uintptr_t storyAssociatedPointer =
            reinterpret_cast<uintptr_t>(
                g_legacyV61StoryAssociatedScratch);
        memcpy(
            storyDescriptor + 0x08,
            &storyAssociatedPointer,
            sizeof(storyAssociatedPointer));
        const uint16_t one = 1;
        memcpy(
            storyDescriptor + 0x10,
            &one,
            sizeof(one));

        memcpy(
            storyDescriptor + 0x12,
            &one,
            sizeof(one));

        const uintptr_t temporaryTable =
            reinterpret_cast<uintptr_t>(
                g_legacyV61DescriptorScratch);
        const uint16_t temporaryCount =
            static_cast<uint16_t>(selectedCount + 1);

        uint16_t temporaryCapacity =
            selectedDescriptorCapacity;
        if (temporaryCapacity == 0)
            temporaryCapacity = 1;
        while (temporaryCapacity < temporaryCount)
        {
            if (temporaryCapacity > 0x7FFFU)
            {
                temporaryCapacity = temporaryCount;
                break;
            }
            temporaryCapacity =
                static_cast<uint16_t>(
                    temporaryCapacity * 2U);
        }

        memcpy(
            reinterpret_cast<void*>(selectedChild + 0x78),
            &temporaryTable,
            sizeof(temporaryTable));
        memcpy(
            reinterpret_cast<void*>(selectedChild + 0x80),
            &temporaryCount,
            sizeof(temporaryCount));
        memcpy(
            reinterpret_cast<void*>(selectedChild + 0x82),
            &temporaryCapacity,
            sizeof(temporaryCapacity));

        uintptr_t verifyTable = 0;
        uint16_t verifyCount = 0;
        uint16_t verifyCapacity = 0;
        memcpy(
            &verifyTable,
            reinterpret_cast<const void*>(selectedChild + 0x78),
            sizeof(verifyTable));
        memcpy(
            &verifyCount,
            reinterpret_cast<const void*>(selectedChild + 0x80),
            sizeof(verifyCount));
        memcpy(
            &verifyCapacity,
            reinterpret_cast<const void*>(selectedChild + 0x82),
            sizeof(verifyCapacity));

        g_legacyV61.temporaryTable = temporaryTable;
        g_legacyV61.temporaryCount = temporaryCount;
        g_legacyV61.temporaryCapacity = temporaryCapacity;
        g_legacyV61.temporaryMapAssociatedCount =
            mapScratchCount;
        g_legacyV61.temporaryMapAssociatedCapacity =
            selectedMapAssociatedCapacity;
        g_legacyV61.temporaryStoryAssociatedCapacity =
            one;
        g_legacyV61.verified =
            verifyTable == temporaryTable
            && verifyCount == temporaryCount
            && verifyCapacity == temporaryCapacity
            && temporaryCapacity >= temporaryCount
            && selectedMapAssociatedCapacity >= mapScratchCount
            && one >= 1;
        applied = g_legacyV61.verified;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        g_legacyV61.faulted = true;
        applied = false;
    }

    g_legacyV61.applied = applied;

    Logf(
        "[LegacyDescriptorV61] apply attempted=yes unique=%s matches=%u applied=%s verified=%s faulted=%s child=%p viewOffset=0x78 table=%p->%p count=%u->%u capacity=%u->%u mapDescriptor=%u mapAssociated=%p count=%u->%u capacity=%u BennyRemoved=%u appended{GROUP_MAP_SP=0x%08X Benny=0x%08X count=1 capacity=%u}.",
        g_legacyV61.candidateUnique ? "yes" : "no",
        static_cast<unsigned int>(g_legacyV61.matchingCandidates),
        g_legacyV61.applied ? "yes" : "no",
        g_legacyV61.verified ? "yes" : "no",
        g_legacyV61.faulted ? "yes" : "no",
        reinterpret_cast<void*>(g_legacyV61.child),
        reinterpret_cast<void*>(g_legacyV61.originalTable),
        reinterpret_cast<void*>(g_legacyV61.temporaryTable),
        static_cast<unsigned int>(g_legacyV61.originalCount),
        static_cast<unsigned int>(g_legacyV61.temporaryCount),
        static_cast<unsigned int>(g_legacyV61.originalCapacity),
        static_cast<unsigned int>(g_legacyV61.temporaryCapacity),
        static_cast<unsigned int>(g_legacyV61.mapDescriptorIndex),
        reinterpret_cast<void*>(
            g_legacyV61.originalMapAssociatedTable),
        static_cast<unsigned int>(
            g_legacyV61.originalMapAssociatedCount),
        static_cast<unsigned int>(
            g_legacyV61.temporaryMapAssociatedCount),
        static_cast<unsigned int>(
            g_legacyV61.temporaryMapAssociatedCapacity),
        static_cast<unsigned int>(
            g_legacyV61.originalMapBennyCount),
        storyGroup,
        benny,
        static_cast<unsigned int>(
            g_legacyV61.temporaryStoryAssociatedCapacity));

    if (!applied)
    {
        if (g_legacyV61.child
            && g_legacyV61.originalTable
            && g_legacyV61.originalCount != 0)
        {
            g_legacyV61.applied = true;
            RestoreLegacyV61DescriptorView();
        }
        return false;
    }

    return true;
}

