static uintptr_t LegacyNaturalGroupLoopDetour(
    void* context,
    uint32_t groupHash)
{
    const LONG globalCallNumber =
        InterlockedIncrement(
            &g_legacyNaturalTotalCalls);

    RockstarLegacyNaturalGroupLoop original =
        g_legacyNaturalOriginal;
    if (!original)
        return 0;

    constexpr uint32_t mapGroup =
        0xBCC89179U;
    constexpr uint32_t storyGroup =
        0x578F99E2U;
    constexpr uint32_t mplowrider =
        0x61322A35U;
    constexpr uintptr_t childStride =
        0xF0;

    if (groupHash == mapGroup)
        InterlockedIncrement(&g_legacyV57MapCalls);
    else if (groupHash == storyGroup)
        InterlockedIncrement(&g_legacyV57StoryCalls);

    const bool relevantGroup =
        groupHash == mapGroup
        || groupHash == storyGroup;

    if (relevantGroup
        && context)
    {
        LegacyV57GroupCallObservation observation{};
        observation.globalCallNumber =
            globalCallNumber;
        observation.context =
            reinterpret_cast<uintptr_t>(
                context);
        observation.groupHash =
            groupHash;
        observation.lowriderIndex = -1;

        const uintptr_t callerReturn =
            reinterpret_cast<uintptr_t>(
                _ReturnAddress());
        observation.callerReturn =
            callerReturn;
        observation.callerCallsite =
            ResolveDirectCallsiteToTarget(
                callerReturn,
                g_legacyNaturalTarget);

        __try
        {
            const uint8_t* p =
                reinterpret_cast<const uint8_t*>(
                    context);
            memcpy(
                &observation.childArray,
                p + 0x28,
                sizeof(observation.childArray));
            memcpy(
                &observation.childCount,
                p + 0x30,
                sizeof(observation.childCount));

            if (!observation.childArray
                || observation.childCount == 0
                || observation.childCount > 4096)
            {
                observation.faulted = true;
            }
            else
            {
                for (uint16_t i = 0;
                     i < observation.childCount;
                     ++i)
                {
                    const uintptr_t child =
                        observation.childArray
                        + (static_cast<uintptr_t>(i)
                            * childStride);
                    uint32_t field60 = 0;
                    memcpy(
                        &field60,
                        reinterpret_cast<const void*>(
                            child + 0x60),
                        sizeof(field60));

                    if (field60 != mplowrider)
                        continue;

                    observation.lowriderIndex =
                        static_cast<LONG>(i);
                    observation.lowriderChild =
                        child;
                    observation.lowriderField60 =
                        field60;
                    InterlockedIncrement(
                        &g_legacyV57LowriderObservations);

                    CaptureLegacyV57LowriderRecord(
                        child,
                        static_cast<LONG>(i),
                        groupHash);
                    break;
                }
            }
        }
        __except(EXCEPTION_EXECUTE_HANDLER)
        {
            observation.faulted = true;
            InterlockedIncrement(
                &g_legacyV57CaptureFaults);
        }

        const LONG slot =
            InterlockedIncrement(
                &g_legacyV57ObservationCount) - 1;
        if (slot >= 0
            && slot < static_cast<LONG>(
                sizeof(g_legacyV57Observations)
                / sizeof(g_legacyV57Observations[0])))
        {
            g_legacyV57Observations[slot] =
                observation;
        }
    }

    return original(
        context,
        groupHash);
}

static const char* GetLegacyNaturalFailureReason()
{
    switch (g_legacyNaturalFailureCode)
    {
    case 0: return "none";
    case 1: return "exe-module-unavailable";
    case 2: return "bad-dos-signature";
    case 3: return "bad-nt-signature";
    case 4: return "executable-section-unavailable";
    case 5: return "legacy-wrapper-anchor-not-unique";
    case 6: return "per-child-worker-target-outside-executable";
    case 7: return "legacy-group-loop-prefix-mismatch";
    case 8: return "trampoline-allocation-failed";
    case 9: return "VirtualProtect-failed";
    case 10: return "seh-exception";
    default: return "unknown";
    }
}

static bool IsAddressInExecutableSectionV57(
    const IMAGE_NT_HEADERS64* nt,
    uint8_t* base,
    uintptr_t address,
    size_t bytes)
{
    if (!nt
        || !base
        || !address)
    {
        return false;
    }

    const IMAGE_SECTION_HEADER* section =
        IMAGE_FIRST_SECTION(nt);
    for (WORD i = 0;
         i < nt->FileHeader.NumberOfSections;
         ++i)
    {
        if ((section[i].Characteristics
                & IMAGE_SCN_MEM_EXECUTE) == 0)
        {
            continue;
        }

        const uintptr_t sectionStart =
            reinterpret_cast<uintptr_t>(
                base + section[i].VirtualAddress);
        const uintptr_t sectionEnd =
            sectionStart
            + static_cast<uintptr_t>(
                section[i].Misc.VirtualSize);

        if (address >= sectionStart
            && address + bytes <= sectionEnd)
        {
            return true;
        }
    }

    return false;
}

static void InstallLegacyNaturalDescriptorHookAtModuleLoad()
{
    if (!IsLegacyExecutableImage())
        return;

    g_legacyNaturalHookAttempted = true;

    HMODULE exe =
        GetModuleHandleA(nullptr);
    if (!exe)
    {
        g_legacyNaturalFailureCode = 1;
        return;
    }

    uint8_t* base =
        reinterpret_cast<uint8_t*>(
            exe);

    __try
    {
        const IMAGE_DOS_HEADER* dos =
            reinterpret_cast<const IMAGE_DOS_HEADER*>(
                base);
        if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        {
            g_legacyNaturalFailureCode = 2;
            return;
        }

        const IMAGE_NT_HEADERS64* nt =
            reinterpret_cast<const IMAGE_NT_HEADERS64*>(
                base + dos->e_lfanew);
        if (nt->Signature != IMAGE_NT_SIGNATURE)
        {
            g_legacyNaturalFailureCode = 3;
            return;
        }

        static const uint8_t groupLoopSignature[] =
        {
            0x48, 0x89, 0x5C, 0x24, 0x08,
            0x48, 0x89, 0x74, 0x24, 0x10,
            0x57,
            0x48, 0x83, 0xEC, 0x20,
            0x33, 0xDB,
            0x8B, 0xF2,
            0x48, 0x8B, 0xF9,
            0x66, 0x3B, 0x59, 0x30,
            0x73, 0x26,
            0x48, 0x8B, 0x47, 0x28,
            0x8B, 0xD3,
            0x44, 0x8B, 0xC6,
            0x48, 0x8B, 0xCF,
            0x48, 0x69, 0xD2, 0xF0,
            0x00, 0x00, 0x00,
            0x8B, 0x54, 0x02, 0x60,
            0xE8
        };

        static const uint8_t wrapperPrefix[] =
        {
            0x40, 0x53, 0x48, 0x83, 0xEC, 0x20,
            0xBA, 0xE2, 0x99, 0x8F, 0x57,
            0x48, 0x8B, 0xD9
        };
        static const uint8_t wrapperMiddle[] =
        {
            0xBA, 0x79, 0x91, 0xC8, 0xBC,
            0x48, 0x8B, 0xCB
        };
        static const uint8_t wrapperTail[] =
        {
            0x48, 0x8D, 0x0D
        };

        uint32_t bodyMatches = 0;
        uint32_t wrapperMatches = 0;
        uint32_t verifiedAnchors = 0;
        uintptr_t selectedWrapper = 0;
        uintptr_t selectedStoryCall = 0;
        uintptr_t selectedMapCall = 0;
        uintptr_t selectedTarget = 0;
        bool sawExecutableSection = false;

        const IMAGE_SECTION_HEADER* section =
            IMAGE_FIRST_SECTION(nt);
        for (WORD i = 0;
             i < nt->FileHeader.NumberOfSections;
             ++i)
        {
            if ((section[i].Characteristics
                    & IMAGE_SCN_MEM_EXECUTE) == 0)
            {
                continue;
            }

            const size_t sectionSize =
                static_cast<size_t>(
                    section[i].Misc.VirtualSize);
            if (sectionSize < sizeof(groupLoopSignature) + 4)
                continue;

            sawExecutableSection = true;
            uint8_t* sectionStart =
                base + section[i].VirtualAddress;
            uint8_t* sectionEnd =
                sectionStart + sectionSize;

            for (uint8_t* p = sectionStart;
                 p + sizeof(groupLoopSignature) + 4
                    <= sectionEnd;
                 ++p)
            {
                if (memcmp(
                        p,
                        groupLoopSignature,
                        sizeof(groupLoopSignature)) == 0)
                {
                    ++bodyMatches;
                }
            }

            for (uint8_t* p = sectionStart;
                 p + 35 <= sectionEnd;
                 ++p)
            {
                if (memcmp(
                        p,
                        wrapperPrefix,
                        sizeof(wrapperPrefix)) != 0
                    || p[14] != 0xE8
                    || memcmp(
                        p + 19,
                        wrapperMiddle,
                        sizeof(wrapperMiddle)) != 0
                    || p[27] != 0xE8
                    || memcmp(
                        p + 32,
                        wrapperTail,
                        sizeof(wrapperTail)) != 0)
                {
                    continue;
                }

                ++wrapperMatches;

                int32_t storyRelative = 0;
                int32_t mapRelative = 0;
                memcpy(
                    &storyRelative,
                    p + 15,
                    sizeof(storyRelative));
                memcpy(
                    &mapRelative,
                    p + 28,
                    sizeof(mapRelative));

                uint8_t* storyTarget =
                    p + 19 + storyRelative;
                uint8_t* mapTarget =
                    p + 32 + mapRelative;

                if (storyTarget != mapTarget
                    || !IsAddressInExecutableSectionV57(
                        nt,
                        base,
                        reinterpret_cast<uintptr_t>(
                            storyTarget),
                        sizeof(groupLoopSignature) + 4)
                    || memcmp(
                        storyTarget,
                        groupLoopSignature,
                        sizeof(groupLoopSignature)) != 0)
                {
                    continue;
                }

                ++verifiedAnchors;
                selectedWrapper =
                    reinterpret_cast<uintptr_t>(p);
                selectedStoryCall =
                    reinterpret_cast<uintptr_t>(p + 14);
                selectedMapCall =
                    reinterpret_cast<uintptr_t>(p + 27);
                selectedTarget =
                    reinterpret_cast<uintptr_t>(storyTarget);
            }
        }

        if (!sawExecutableSection)
        {
            g_legacyNaturalFailureCode = 4;
            return;
        }

        g_legacyNaturalSignatureMatches =
            bodyMatches;
        g_legacyV58WrapperMatches =
            wrapperMatches;
        g_legacyNaturalVerifiedTargetMatches =
            verifiedAnchors;
        g_legacyNaturalSignatureAddress =
            selectedWrapper;
        g_legacyV58WrapperAddress =
            selectedWrapper;
        g_legacyV58StoryCallsite =
            selectedStoryCall;
        g_legacyV58MapCallsite =
            selectedMapCall;
        g_legacyNaturalTarget =
            selectedTarget;

        if (verifiedAnchors != 1
            || !selectedWrapper
            || !selectedStoryCall
            || !selectedMapCall
            || !selectedTarget)
        {
            g_legacyNaturalFailureCode = 5;
            return;
        }

        g_legacyNaturalSignatureUnique = true;
        g_legacyNaturalTargetPrefixVerified = true;

        uint8_t* target =
            reinterpret_cast<uint8_t*>(
                selectedTarget);
        memcpy(
            g_legacyNaturalTargetPrefix,
            target,
            sizeof(g_legacyNaturalTargetPrefix));

        uint8_t* workerCallsite =
            target + (sizeof(groupLoopSignature) - 1);
        int32_t workerRelative = 0;
        memcpy(
            &workerRelative,
            workerCallsite + 1,
            sizeof(workerRelative));
        uint8_t* workerTarget =
            workerCallsite + 5
            + workerRelative;

        g_legacyNaturalCallsite =
            reinterpret_cast<uintptr_t>(
                workerCallsite);
        g_legacyV57WorkerTarget =
            reinterpret_cast<uintptr_t>(
                workerTarget);

        if (!IsAddressInExecutableSectionV57(
                nt,
                base,
                g_legacyV57WorkerTarget,
                sizeof(g_legacyV57WorkerPrefix)))
        {
            g_legacyNaturalFailureCode = 6;
            return;
        }

        memcpy(
            g_legacyV57WorkerPrefix,
            workerTarget,
            sizeof(g_legacyV57WorkerPrefix));

        constexpr size_t stolenSize = 15;
        static const uint8_t expectedPrefix[stolenSize] =
        {
            0x48, 0x89, 0x5C, 0x24, 0x08,
            0x48, 0x89, 0x74, 0x24, 0x10,
            0x57,
            0x48, 0x83, 0xEC, 0x20
        };

        if (memcmp(
                target,
                expectedPrefix,
                stolenSize) != 0)
        {
            g_legacyNaturalTargetPrefixVerified = false;
            g_legacyNaturalFailureCode = 7;
            return;
        }

        constexpr size_t trampolineSize =
            stolenSize + 16;
        uint8_t* trampoline =
            reinterpret_cast<uint8_t*>(
                VirtualAlloc(
                    nullptr,
                    trampolineSize,
                    MEM_COMMIT | MEM_RESERVE,
                    PAGE_EXECUTE_READWRITE));
        if (!trampoline)
        {
            g_legacyNaturalFailureCode = 8;
            return;
        }

        memcpy(
            trampoline,
            target,
            stolenSize);
        WriteAbsoluteJump12(
            trampoline + stolenSize,
            target + stolenSize);
        for (size_t i = stolenSize + 12;
             i < trampolineSize;
             ++i)
        {
            trampoline[i] = 0x90;
        }

        FlushInstructionCache(
            GetCurrentProcess(),
            trampoline,
            trampolineSize);

        g_legacyNaturalTrampoline =
            trampoline;
        g_legacyNaturalOriginal =
            reinterpret_cast<
                RockstarLegacyNaturalGroupLoop>(
                    trampoline);

        uint8_t patch[stolenSize]{};
        WriteAbsoluteJump12(
            patch,
            reinterpret_cast<const void*>(
                &LegacyNaturalGroupLoopDetour));
        for (size_t i = 12;
             i < stolenSize;
             ++i)
        {
            patch[i] = 0x90;
        }

        DWORD oldProtect = 0;
        if (!VirtualProtect(
                target,
                stolenSize,
                PAGE_EXECUTE_READWRITE,
                &oldProtect))
        {
            g_legacyNaturalOriginal = nullptr;
            g_legacyNaturalTrampoline = nullptr;
            VirtualFree(
                trampoline,
                0,
                MEM_RELEASE);
            g_legacyNaturalFailureCode = 9;
            return;
        }

        memcpy(
            target,
            patch,
            stolenSize);
        FlushInstructionCache(
            GetCurrentProcess(),
            target,
            stolenSize);

        DWORD ignoredProtect = 0;
        VirtualProtect(
            target,
            stolenSize,
            oldProtect,
            &ignoredProtect);

        g_legacyNaturalHookInstalled = true;
        g_legacyNaturalFailureCode = 0;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        g_legacyNaturalFailureCode = 10;
    }
}

