static LegacyNaturalDescriptorHookInstaller
    g_legacyNaturalDescriptorHookInstaller;

static void LogLegacyNaturalDescriptorState(
    const char* phase)
{
    HMODULE exe =
        GetModuleHandleA(nullptr);
    const uintptr_t base =
        reinterpret_cast<uintptr_t>(
            exe);

    Logf(
        "[LegacyObserveV60] %s attempted=%s installed=%s anchorUnique=%s prefixVerified=%s failure=%lu(%s) bodyMatches=%u wrapperMatches=%u verifiedAnchors=%u wrapper=%p(rva=0x%llX) storyCall=%p(rva=0x%llX) mapCall=%p(rva=0x%llX) groupLoop=%p(rva=0x%llX) workerCallsite=%p(rva=0x%llX) workerTarget=%p(rva=0x%llX) trampoline=%p calls{total=%ld GROUP_MAP=%ld GROUP_MAP_SP=%ld observations=%ld lowrider=%ld faults=%ld} lowriderRecord{captured=%s index=%ld child=%p group=0x%08X hashHits=%u pointerProbes=%u descriptorCandidates=%u}.",
        phase ? phase : "state",
        g_legacyNaturalHookAttempted ? "yes" : "no",
        g_legacyNaturalHookInstalled ? "yes" : "no",
        g_legacyNaturalSignatureUnique ? "yes" : "no",
        g_legacyNaturalTargetPrefixVerified ? "yes" : "no",
        static_cast<unsigned long>(
            g_legacyNaturalFailureCode),
        GetLegacyNaturalFailureReason(),
        g_legacyNaturalSignatureMatches,
        g_legacyV58WrapperMatches,
        g_legacyNaturalVerifiedTargetMatches,
        reinterpret_cast<void*>(
            g_legacyV58WrapperAddress),
        base && g_legacyV58WrapperAddress >= base
            ? static_cast<unsigned long long>(
                g_legacyV58WrapperAddress - base)
            : 0ULL,
        reinterpret_cast<void*>(
            g_legacyV58StoryCallsite),
        base && g_legacyV58StoryCallsite >= base
            ? static_cast<unsigned long long>(
                g_legacyV58StoryCallsite - base)
            : 0ULL,
        reinterpret_cast<void*>(
            g_legacyV58MapCallsite),
        base && g_legacyV58MapCallsite >= base
            ? static_cast<unsigned long long>(
                g_legacyV58MapCallsite - base)
            : 0ULL,
        reinterpret_cast<void*>(
            g_legacyNaturalTarget),
        base && g_legacyNaturalTarget >= base
            ? static_cast<unsigned long long>(
                g_legacyNaturalTarget - base)
            : 0ULL,
        reinterpret_cast<void*>(
            g_legacyNaturalCallsite),
        base && g_legacyNaturalCallsite >= base
            ? static_cast<unsigned long long>(
                g_legacyNaturalCallsite - base)
            : 0ULL,
        reinterpret_cast<void*>(
            g_legacyV57WorkerTarget),
        base && g_legacyV57WorkerTarget >= base
            ? static_cast<unsigned long long>(
                g_legacyV57WorkerTarget - base)
            : 0ULL,
        g_legacyNaturalTrampoline,
        static_cast<long>(
            g_legacyNaturalTotalCalls),
        static_cast<long>(
            g_legacyV57MapCalls),
        static_cast<long>(
            g_legacyV57StoryCalls),
        static_cast<long>(
            g_legacyV57ObservationCount),
        static_cast<long>(
            g_legacyV57LowriderObservations),
        static_cast<long>(
            g_legacyV57CaptureFaults),
        g_legacyV57LowriderRecordCaptured
            ? "yes"
            : "no",
        static_cast<long>(
            g_legacyV57LowriderIndex),
        reinterpret_cast<void*>(
            g_legacyV57LowriderChild),
        g_legacyV57LowriderGroup,
        static_cast<unsigned int>(
            g_legacyV57HashHitCount),
        static_cast<unsigned int>(
            g_legacyV57PointerProbeCount),
        static_cast<unsigned int>(
            g_legacyV57DescriptorCandidateCount));

    const LONG observationCount =
        g_legacyV57ObservationCount
            < static_cast<LONG>(
                sizeof(g_legacyV57Observations)
                / sizeof(g_legacyV57Observations[0]))
            ? g_legacyV57ObservationCount
            : static_cast<LONG>(
                sizeof(g_legacyV57Observations)
                / sizeof(g_legacyV57Observations[0]));

    for (LONG i = 0;
         i < observationCount;
         ++i)
    {
        const LegacyV57GroupCallObservation& observation =
            g_legacyV57Observations[i];
        Logf(
            "[LegacyObserveV60] call[%ld] global=%ld group=0x%08X callerReturn=%p(rva=0x%llX) callsite=%p(rva=0x%llX) context=%p childArray=%p childCount=%u lowrider{index=%ld child=%p field60=0x%08X} faulted=%s.",
            static_cast<long>(i),
            static_cast<long>(
                observation.globalCallNumber),
            observation.groupHash,
            reinterpret_cast<void*>(
                observation.callerReturn),
            base && observation.callerReturn >= base
                ? static_cast<unsigned long long>(
                    observation.callerReturn - base)
                : 0ULL,
            reinterpret_cast<void*>(
                observation.callerCallsite),
            base && observation.callerCallsite >= base
                ? static_cast<unsigned long long>(
                    observation.callerCallsite - base)
                : 0ULL,
            reinterpret_cast<void*>(
                observation.context),
            reinterpret_cast<void*>(
                observation.childArray),
            static_cast<unsigned int>(
                observation.childCount),
            static_cast<long>(
                observation.lowriderIndex),
            reinterpret_cast<void*>(
                observation.lowriderChild),
            observation.lowriderField60,
            observation.faulted ? "yes" : "no");
    }

    if (g_legacyNaturalTarget != 0)
    {
        LogBytes(
            g_legacyNaturalTargetPrefix,
            sizeof(g_legacyNaturalTargetPrefix),
            "Legacy v60 group-loop prefix");
    }

    if (g_legacyV57WorkerTarget != 0)
    {
        LogBytes(
            g_legacyV57WorkerPrefix,
            sizeof(g_legacyV57WorkerPrefix),
            "Legacy v60 per-child worker prefix");
    }

    if (!g_legacyV57LowriderRecordCaptured)
        return;

    LogBytes(
        g_legacyV57LowriderRecord,
        sizeof(g_legacyV57LowriderRecord),
        "Legacy v60 mplowrider 0xF0 record");

    for (uint16_t i = 0;
         i < g_legacyV57HashHitCount;
         ++i)
    {
        const LegacyV57HashHit& hit =
            g_legacyV57HashHits[i];
        Logf(
            "[LegacyObserveV60] lowrider directHash[%u] childOffset=0x%X value=0x%08X.",
            static_cast<unsigned int>(i),
            static_cast<unsigned int>(
                hit.childOffset),
            hit.value);
    }

    for (uint16_t i = 0;
         i < g_legacyV57PointerProbeCount;
         ++i)
    {
        const LegacyV57PointerProbe& probe =
            g_legacyV57PointerProbes[i];
        Logf(
            "[LegacyObserveV60] pointerProbe[%u] childOffset=0x%X pointer=%p examined=0x%X hits{GROUP_MAP=%u GROUP_MAP_SP=%u Benny=%u mplowrider=%u}.",
            static_cast<unsigned int>(i),
            static_cast<unsigned int>(
                probe.childOffset),
            reinterpret_cast<void*>(
                probe.pointerValue),
            static_cast<unsigned int>(
                probe.bytesExamined),
            static_cast<unsigned int>(
                probe.mapHits),
            static_cast<unsigned int>(
                probe.storyHits),
            static_cast<unsigned int>(
                probe.bennyHits),
            static_cast<unsigned int>(
                probe.dlcHits));
    }

    for (uint16_t i = 0;
         i < g_legacyV57DescriptorCandidateCount;
         ++i)
    {
        const LegacyV57DescriptorCandidate& candidate =
            g_legacyV57DescriptorCandidates[i];
        Logf(
            "[LegacyObserveV60] descriptorCandidate[%u] childOffset=0x%X table=%p count=%u knownGroups=%u GROUP_MAP=%u GROUP_MAP_SP=%u BennyAssociations=%u captured=%u.",
            static_cast<unsigned int>(i),
            static_cast<unsigned int>(
                candidate.childOffset),
            reinterpret_cast<void*>(
                candidate.table),
            static_cast<unsigned int>(
                candidate.count),
            static_cast<unsigned int>(
                candidate.knownGroupDescriptors),
            static_cast<unsigned int>(
                candidate.mapDescriptors),
            static_cast<unsigned int>(
                candidate.storyDescriptors),
            static_cast<unsigned int>(
                candidate.bennyAssociations),
            static_cast<unsigned int>(
                candidate.descriptorsCaptured));

        for (uint16_t j = 0;
             j < candidate.descriptorsCaptured;
             ++j)
        {
            Logf(
                "[LegacyObserveV60] descriptorCandidate[%u].descriptor[%u] group=0x%08X associatedCount=%u.",
                static_cast<unsigned int>(i),
                static_cast<unsigned int>(j),
                candidate.groups[j],
                static_cast<unsigned int>(
                    candidate.associatedCounts[j]));
        }
    }
}

static void DumpPeSections(uint8_t* base)
{
    if (!base)
        return;

    const IMAGE_DOS_HEADER* dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
    if (dos->e_magic != IMAGE_DOS_SIGNATURE)
    {
        Logf("[Diag] PE section dump aborted: DOS signature mismatch.");
        return;
    }

    const IMAGE_NT_HEADERS64* nt = reinterpret_cast<const IMAGE_NT_HEADERS64*>(base + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE)
    {
        Logf("[Diag] PE section dump aborted: NT signature mismatch.");
        return;
    }

    const IMAGE_SECTION_HEADER* section = IMAGE_FIRST_SECTION(nt);
    for (WORD i = 0; i < nt->FileHeader.NumberOfSections; ++i)
    {
        char name[9]{};
        memcpy(name, section[i].Name, 8);
        Logf(
            "[Diag] PE section %-8s RVA=0x%08lX size=0x%08lX chars=0x%08lX",
            name,
            static_cast<unsigned long>(section[i].VirtualAddress),
            static_cast<unsigned long>(section[i].Misc.VirtualSize),
            static_cast<unsigned long>(section[i].Characteristics));
    }
}

static void DumpDwordHitsInExe(uint8_t* base, uint8_t* end, uint32_t value, const char* label)
{
    if (!base || !end || end <= base + sizeof(value))
        return;

    int hitCount = 0;
    const int maxHits = 16;

    for (uint8_t* p = base; p + sizeof(value) <= end; ++p)
    {
        uint32_t current = 0;
        memcpy(&current, p, sizeof(current));
        if (current != value)
            continue;

        Logf(
            "[Diag] Immediate/hash hit %-38s value=0x%08X address=%p RVA=0x%llX",
            label,
            value,
            p,
            static_cast<unsigned long long>(p - base));

        ++hitCount;
        if (hitCount >= maxHits)
        {
            Logf("[Diag] Immediate/hash hit limit reached for %s.", label);
            break;
        }
    }

    if (hitCount == 0)
        Logf("[Diag] No executable image hit for %-38s value=0x%08X", label, value);
}

static void DumpQwordHitsInRange(
    uint8_t* base,
    uint8_t* end,
    uint64_t value,
    const char* label,
    const char* rangeLabel)
{
    if (!base || !end || end <= base + sizeof(value))
        return;

    int hitCount = 0;
    const int maxHits = 16;

    for (uint8_t* p = base; p + sizeof(value) <= end; ++p)
    {
        uint64_t current = 0;
        memcpy(&current, p, sizeof(current));
        if (current != value)
            continue;

        Logf(
            "[Diag] 64-bit hash hit %-37s value=0x%016llX scope=%s address=%p RVA=0x%llX",
            label,
            static_cast<unsigned long long>(value),
            rangeLabel ? rangeLabel : "unknown",
            p,
            static_cast<unsigned long long>(p - base));

        ++hitCount;
        if (hitCount >= maxHits)
        {
            Logf("[Diag] 64-bit hash hit limit reached for %s in %s.", label, rangeLabel ? rangeLabel : "unknown");
            break;
        }
    }

    if (hitCount == 0)
    {
        Logf(
            "[Diag] No 64-bit hash hit for %-37s value=0x%016llX scope=%s",
            label,
            static_cast<unsigned long long>(value),
            rangeLabel ? rangeLabel : "unknown");
    }
}

static bool FindRuntimeFunctionBounds(
    uint8_t* base,
    uint8_t* end,
    uint8_t* address,
    uint8_t*& functionStart,
    uint8_t*& functionEnd)
{
    functionStart = nullptr;
    functionEnd = nullptr;

    if (!base || !end || !address || address < base || address >= end)
        return false;

    const IMAGE_DOS_HEADER* dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
    if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        return false;

    const IMAGE_NT_HEADERS64* nt =
        reinterpret_cast<const IMAGE_NT_HEADERS64*>(base + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE)
        return false;

    const IMAGE_DATA_DIRECTORY& exceptionDirectory =
        nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXCEPTION];
    if (exceptionDirectory.VirtualAddress == 0
        || exceptionDirectory.Size < sizeof(RUNTIME_FUNCTION))
        return false;

    const uint64_t tableEndRva =
        static_cast<uint64_t>(exceptionDirectory.VirtualAddress)
        + static_cast<uint64_t>(exceptionDirectory.Size);
    if (tableEndRva > static_cast<uint64_t>(end - base))
        return false;

    const RUNTIME_FUNCTION* table = reinterpret_cast<const RUNTIME_FUNCTION*>(
        base + exceptionDirectory.VirtualAddress);
    const size_t count = exceptionDirectory.Size / sizeof(RUNTIME_FUNCTION);
    const uint32_t addressRva = static_cast<uint32_t>(address - base);

    size_t low = 0;
    size_t high = count;
    while (low < high)
    {
        const size_t mid = low + ((high - low) / 2);
        const RUNTIME_FUNCTION& entry = table[mid];

        if (addressRva < entry.BeginAddress)
        {
            high = mid;
        }
        else if (addressRva >= entry.EndAddress)
        {
            low = mid + 1;
        }
        else
        {
            if (entry.BeginAddress >= entry.EndAddress
                || entry.EndAddress > static_cast<uint32_t>(end - base))
                return false;

            functionStart = base + entry.BeginAddress;
            functionEnd = base + entry.EndAddress;
            return true;
        }
    }

    return false;
}

static void DumpContainingRuntimeFunction(
    uint8_t* base,
    uint8_t* end,
    uint8_t* address,
    const char* label)
{
    uint8_t* functionStart = nullptr;
    uint8_t* functionEnd = nullptr;
    if (!FindRuntimeFunctionBounds(base, end, address, functionStart, functionEnd))
    {
        Logf(
            "[Diag] No PE runtime-function boundary found for %s at RVA=0x%llX",
            label ? label : "candidate",
            address && base && address >= base
                ? static_cast<unsigned long long>(address - base)
                : 0ULL);
        return;
    }

    Logf(
        "[Diag] Function bounds %-28s startRVA=0x%llX endRVA=0x%llX size=0x%llX candidateOffset=0x%llX",
        label ? label : "candidate",
        static_cast<unsigned long long>(functionStart - base),
        static_cast<unsigned long long>(functionEnd - base),
        static_cast<unsigned long long>(functionEnd - functionStart),
        static_cast<unsigned long long>(address - functionStart));

    const size_t functionSize = static_cast<size_t>(functionEnd - functionStart);
    const size_t bytesToDump = functionSize < 64 ? functionSize : 64;
    if (bytesToDump != 0)
        LogBytes(functionStart, bytesToDump, "Function start bytes");
}
static void LogBoundedBytes(
    uint8_t* base,
    uint8_t* end,
    uint8_t* center,
    size_t before,
    size_t after,
    const char* label)
{
    if (!base || !end || !center || center < base || center >= end)
        return;

    uint8_t* start = center;
    if (static_cast<size_t>(center - base) > before)
        start = center - before;
    else
        start = base;

    uint8_t* finish = center + after;
    if (finish > end)
        finish = end;

    if (finish <= start)
        return;

    const size_t count = static_cast<size_t>(finish - start);
    Logf(
        "[Diag] %s center=%p centerRVA=0x%llX windowStartRVA=0x%llX bytes=%llu",
        label ? label : "bounded byte window",
        center,
        static_cast<unsigned long long>(center - base),
        static_cast<unsigned long long>(start - base),
        static_cast<unsigned long long>(count));

    const size_t rowSize = 16;
    for (size_t offset = 0; offset < count; offset += rowSize)
    {
        const size_t rowCount = ((count - offset) < rowSize) ? (count - offset) : rowSize;
        char hex[rowSize * 3 + 1]{};
        char ascii[rowSize + 1]{};
        size_t hexPos = 0;

        for (size_t i = 0; i < rowCount; ++i)
        {
            const uint8_t b = start[offset + i];
            hexPos += static_cast<size_t>(
                sprintf_s(hex + hexPos, sizeof(hex) - hexPos, "%02X ", b));
            ascii[i] = (b >= 32 && b <= 126) ? static_cast<char>(b) : '.';
        }

        ascii[rowCount] = '\0';
        Logf(
            "[Diag]   RVA 0x%08llX  %-48s |%s|",
            static_cast<unsigned long long>((start + offset) - base),
            hex,
            ascii);
    }
}

static void DumpNearbyRelativeCalls(
    uint8_t* base,
    uint8_t* end,
    uint8_t* center,
    size_t radius,
    const char* label)
{
    if (!base || !end || !center || center < base || center >= end)
        return;

    uint8_t* start = center;
    if (static_cast<size_t>(center - base) > radius)
        start = center - radius;
    else
        start = base;

    uint8_t* finish = center + radius;
    if (finish > end)
        finish = end;

    int hits = 0;
    const int maxHits = 12;

    for (uint8_t* p = start; p + 5 <= finish; ++p)
    {
        if (p[0] != 0xE8)
            continue;

        int32_t relative = 0;
        memcpy(&relative, p + 1, sizeof(relative));
        uint8_t* target = p + 5 + relative;

        if (target < base || target >= end)
            continue;

        Logf(
            "[Diag] Nearby CALL %-24s instructionRVA=0x%llX targetRVA=0x%llX",
            label ? label : "",
            static_cast<unsigned long long>(p - base),
            static_cast<unsigned long long>(target - base));

        DumpContainingRuntimeFunction(base, end, target, "CALL target");
        LogBoundedBytes(base, end, target, 0, 32, "CALL target bytes");

        if (++hits >= maxHits)
        {
            Logf("[Diag] Nearby CALL limit reached for %s.", label ? label : "candidate");
            break;
        }
    }

    if (hits == 0)
        Logf("[Diag] No nearby E8 CALL targets found for %s.", label ? label : "candidate");
}

static void DumpNearbyRipRelativeTargets(
    uint8_t* base,
    uint8_t* end,
    uint8_t* center,
    size_t radius,
    const char* label)
{
    if (!base || !end || !center || center < base || center >= end)
        return;

    uint8_t* start = center;
    if (static_cast<size_t>(center - base) > radius)
        start = center - radius;
    else
        start = base;

    uint8_t* finish = center + radius;
    if (finish > end)
        finish = end;

    int hits = 0;
    const int maxHits = 24;

    for (uint8_t* p = start; p + 6 <= finish; ++p)
    {
        size_t prefixSize = 0;
        uint8_t* opcodePtr = p;

        if ((p[0] & 0xF0) == 0x40)
        {
            prefixSize = 1;
            opcodePtr = p + 1;
            if (p + 7 > finish)
                continue;
        }

        const uint8_t opcode = opcodePtr[0];
        if (opcode != 0x8D && opcode != 0x8B && opcode != 0x89)
            continue;

        if (prefixSize == 0
            && p > start
            && ((p[-1] & 0xF0) == 0x40))
            continue;

        const uint8_t modrm = opcodePtr[1];
        if ((modrm & 0xC7) != 0x05)
            continue;

        int32_t displacement = 0;
        memcpy(&displacement, opcodePtr + 2, sizeof(displacement));

        const size_t instructionLength = prefixSize + 6;
        uint8_t* resolved = p + instructionLength + displacement;
        if (resolved < base || resolved >= end)
            continue;

        Logf(
            "[Diag] Nearby RIP target %-18s instructionRVA=0x%llX targetRVA=0x%llX opcode=%02X modrm=%02X",
            label ? label : "",
            static_cast<unsigned long long>(p - base),
            static_cast<unsigned long long>(resolved - base),
            opcode,
            modrm);

        if (++hits >= maxHits)
        {
            Logf("[Diag] Nearby RIP-target limit reached for %s.", label ? label : "candidate");
            break;
        }
    }

    if (hits == 0)
        Logf("[Diag] No nearby RIP-relative data targets found for %s.", label ? label : "candidate");
}

static void DumpEnhancedMapGroupPairCandidates(uint8_t* base, uint8_t* end)
{
    if (!base || !end)
        return;

    const uint32_t storyHash = Joaat(kStoryMapGroup);
    const uint32_t mpHash = Joaat(kMapGroup);
    const size_t maxPairDistance = 16;
    int pairCount = 0;
    const int maxPairs = 16;

    Logf(
        "[Diag] Searching for Enhanced GROUP_MAP_SP/GROUP_MAP immediate pairs (SP=0x%08X MP=0x%08X).",
        storyHash,
        mpHash);

    for (uint8_t* p = base; p + sizeof(uint32_t) <= end; ++p)
    {
        uint32_t current = 0;
        memcpy(&current, p, sizeof(current));
        if (current != storyHash)
            continue;

        uint8_t* searchEnd = p + maxPairDistance + sizeof(uint32_t);
        if (searchEnd > end)
            searchEnd = end;

        for (uint8_t* q = p + sizeof(uint32_t); q + sizeof(uint32_t) <= searchEnd; ++q)
        {
            uint32_t candidate = 0;
            memcpy(&candidate, q, sizeof(candidate));
            if (candidate != mpHash)
                continue;

            Logf(
                "[Diag] MAP GROUP PAIR #%d SP_RVA=0x%llX MP_RVA=0x%llX distance=%llu",
                pairCount + 1,
                static_cast<unsigned long long>(p - base),
                static_cast<unsigned long long>(q - base),
                static_cast<unsigned long long>(q - p));

            DumpContainingRuntimeFunction(base, end, p, "Enhanced map-group pair");
            LogBoundedBytes(base, end, p, 48, 96, "Enhanced map-group pair bytes");
            DumpNearbyRelativeCalls(base, end, p, 128, "Enhanced map-group pair");
            DumpNearbyRipRelativeTargets(base, end, p, 128, "Enhanced map-group pair");

            ++pairCount;
            break;
        }

        if (pairCount >= maxPairs)
            break;
    }

    if (pairCount == 0)
        Logf("[Diag] No close GROUP_MAP_SP/GROUP_MAP immediate pairs found.");
    else
        Logf("[Diag] Enhanced map-group pair scan complete; pairs=%d.", pairCount);
}

static uint8_t* FindAsciiFirstInRange(uint8_t* base, uint8_t* end, const char* text)
{
    if (!base || !end || !text || !*text)
        return nullptr;

    const size_t length = strlen(text);
    if (length == 0 || static_cast<size_t>(end - base) < length)
        return nullptr;

    for (uint8_t* p = base; p + length <= end; ++p)
    {
        if (*p == static_cast<uint8_t>(text[0]) && memcmp(p, text, length) == 0)
            return p;
    }

    return nullptr;
}

static void DumpRipRelativeReferences(
    uint8_t* base,
    uint8_t* end,
    uint8_t* target,
    const char* label)
{
    if (!base || !end || !target || target < base || target >= end)
        return;

    int hits = 0;
    const int maxHits = 16;

    for (uint8_t* p = base; p + 7 <= end; ++p)
    {
        const uint8_t rex = p[0];
        const uint8_t opcode = p[1];
        const uint8_t modrm = p[2];

        const bool rexOk = (rex & 0xF0) == 0x40;
        const bool opcodeOk = opcode == 0x8D || opcode == 0x8B;
        const bool ripRelative = (modrm & 0xC7) == 0x05;

        if (!rexOk || !opcodeOk || !ripRelative)
            continue;

        int32_t displacement = 0;
        memcpy(&displacement, p + 3, sizeof(displacement));
        uint8_t* resolved = p + 7 + displacement;

        if (resolved != target)
            continue;

        Logf(
            "[Diag] RIP-relative xref %-24s instructionRVA=0x%llX targetRVA=0x%llX opcode=%02X %02X %02X",
            label ? label : "",
            static_cast<unsigned long long>(p - base),
            static_cast<unsigned long long>(target - base),
            p[0],
            p[1],
            p[2]);

        DumpContainingRuntimeFunction(base, end, p, "setup2.xml xref");
        LogBoundedBytes(base, end, p, 48, 96, "RIP-relative xref bytes");
        DumpNearbyRelativeCalls(base, end, p, 128, "RIP-relative xref");
        DumpNearbyRipRelativeTargets(base, end, p, 128, "setup2.xml xref");

        if (++hits >= maxHits)
            break;
    }

    if (hits == 0)
        Logf("[Diag] No common RIP-relative xrefs found for %s.", label ? label : "target");
}

static bool g_legacyV62ConsumerMapLogged = false;

static void DumpLegacyV62DirectCallXrefs(
    uint8_t* base,
    uint8_t* end,
    uint8_t* target,
    const char* label)
{
    if (!base || !end || end <= base || !target
        || target < base || target >= end)
        return;

    const IMAGE_DOS_HEADER* dos =
        reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
    if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        return;

    const IMAGE_NT_HEADERS64* nt =
        reinterpret_cast<const IMAGE_NT_HEADERS64*>(
            base + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE)
        return;

    const IMAGE_SECTION_HEADER* sections =
        IMAGE_FIRST_SECTION(nt);

    unsigned int hits = 0;
    constexpr unsigned int maxHits = 32;

    Logf(
        "[LegacyConsumerV62] direct-call xrefs target=%s address=%p rva=0x%llX.",
        label ? label : "target",
        target,
        static_cast<unsigned long long>(target - base));

    for (WORD sectionIndex = 0;
         sectionIndex < nt->FileHeader.NumberOfSections
             && hits < maxHits;
         ++sectionIndex)
    {
        if ((sections[sectionIndex].Characteristics
                & IMAGE_SCN_MEM_EXECUTE) == 0)
            continue;

        const uint64_t sectionRva =
            sections[sectionIndex].VirtualAddress;
        const uint64_t sectionSize =
            sections[sectionIndex].Misc.VirtualSize;
        if (sectionSize < 5
            || sectionRva >= static_cast<uint64_t>(end - base))
            continue;

        uint8_t* scanStart =
            base + static_cast<size_t>(sectionRva);
        uint8_t* scanEnd =
            scanStart + static_cast<size_t>(sectionSize);
        if (scanEnd > end)
            scanEnd = end;

        for (uint8_t* p = scanStart;
             p + 5 <= scanEnd && hits < maxHits;
             ++p)
        {
            if (p[0] != 0xE8)
                continue;

            int32_t relative = 0;
            memcpy(&relative, p + 1, sizeof(relative));
            uint8_t* resolved =
                p + 5 + relative;
            if (resolved != target)
                continue;

            uint8_t* functionStart = nullptr;
            uint8_t* functionEnd = nullptr;
            const bool bounds =
                FindRuntimeFunctionBounds(
                    base,
                    end,
                    p,
                    functionStart,
                    functionEnd);

            Logf(
                "[LegacyConsumerV62] xref[%u] %s callsiteRVA=0x%llX callerStartRVA=0x%llX callerEndRVA=0x%llX callerSize=0x%llX.",
                hits,
                label ? label : "target",
                static_cast<unsigned long long>(p - base),
                bounds && functionStart
                    ? static_cast<unsigned long long>(
                        functionStart - base)
                    : 0ULL,
                bounds && functionEnd
                    ? static_cast<unsigned long long>(
                        functionEnd - base)
                    : 0ULL,
                bounds && functionStart && functionEnd
                    ? static_cast<unsigned long long>(
                        functionEnd - functionStart)
                    : 0ULL);

            LogBoundedBytes(
                base,
                end,
                p,
                40,
                72,
                "Legacy v62 direct-call xref");
            DumpNearbyRipRelativeTargets(
                base,
                end,
                p,
                80,
                "Legacy v62 caller");

            ++hits;
        }
    }

    Logf(
        "[LegacyConsumerV62] direct-call xref summary target=%s hits=%u.",
        label ? label : "target",
        hits);
}

static uint8_t* FindLegacyV62FiveMGroupLoop(
    uint8_t* base,
    uint8_t* end)
{
    if (!base || !end || end <= base)
        return nullptr;

    const IMAGE_DOS_HEADER* dos =
        reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
    if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        return nullptr;

    const IMAGE_NT_HEADERS64* nt =
        reinterpret_cast<const IMAGE_NT_HEADERS64*>(
            base + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE)
        return nullptr;

    const IMAGE_SECTION_HEADER* sections =
        IMAGE_FIRST_SECTION(nt);
    constexpr uint32_t storyGroup = 0x578F99E2U;

    uint8_t* resolvedTarget = nullptr;
    unsigned int matches = 0;

    for (WORD sectionIndex = 0;
         sectionIndex < nt->FileHeader.NumberOfSections;
         ++sectionIndex)
    {
        if ((sections[sectionIndex].Characteristics
                & IMAGE_SCN_MEM_EXECUTE) == 0)
            continue;

        const uint64_t sectionRva =
            sections[sectionIndex].VirtualAddress;
        const uint64_t sectionSize =
            sections[sectionIndex].Misc.VirtualSize;
        if (sectionSize < 15
            || sectionRva >= static_cast<uint64_t>(end - base))
            continue;

        uint8_t* scanStart =
            base + static_cast<size_t>(sectionRva);
        uint8_t* scanEnd =
            scanStart + static_cast<size_t>(sectionSize);
        if (scanEnd > end)
            scanEnd = end;

        for (uint8_t* p = scanStart;
             p + 15 <= scanEnd;
             ++p)
        {

            if (p[0] != 0x75
                || p[1] != 0x0D
                || p[2] != 0xBA
                || p[7] != 0x48
                || p[8] != 0x8B
                || p[9] != 0xCE
                || p[10] != 0xE8)
                continue;

            uint32_t immediate = 0;
            memcpy(&immediate, p + 3, sizeof(immediate));
            if (immediate != storyGroup)
                continue;

            int32_t relative = 0;
            memcpy(&relative, p + 11, sizeof(relative));
            uint8_t* target =
                p + 15 + relative;
            if (target < base || target >= end)
                continue;

            ++matches;
            resolvedTarget = target;

            Logf(
                "[LegacyConsumerV62] FiveM-style locator match[%u] locatorRVA=0x%llX callsiteRVA=0x%llX targetRVA=0x%llX.",
                matches - 1,
                static_cast<unsigned long long>(p - base),
                static_cast<unsigned long long>((p + 10) - base),
                static_cast<unsigned long long>(target - base));
            DumpContainingRuntimeFunction(
                base,
                end,
                p,
                "Legacy v62 FiveM locator");
            LogBoundedBytes(
                base,
                end,
                p,
                48,
                96,
                "Legacy v62 FiveM locator");
        }
    }

    Logf(
        "[LegacyConsumerV62] FiveM-style locator summary matches=%u selectedTarget=%p rva=0x%llX.",
        matches,
        resolvedTarget,
        resolvedTarget
            ? static_cast<unsigned long long>(
                resolvedTarget - base)
            : 0ULL);

    return matches == 1
        ? resolvedTarget
        : nullptr;
}

static void DumpLegacyV62GroupPairFunctions(
    uint8_t* base,
    uint8_t* end)
{
    if (!base || !end || end <= base)
        return;

    const IMAGE_DOS_HEADER* dos =
        reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
    if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        return;

    const IMAGE_NT_HEADERS64* nt =
        reinterpret_cast<const IMAGE_NT_HEADERS64*>(
            base + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE)
        return;

    const IMAGE_SECTION_HEADER* sections =
        IMAGE_FIRST_SECTION(nt);

    constexpr uint32_t storyGroup = 0x578F99E2U;
    constexpr uint32_t mapGroup = 0xBCC89179U;

    struct PairFunction
    {
        uint8_t* start;
        uint8_t* end;
        uint8_t* storyImmediate;
        uint8_t* mapImmediate;
    };

    std::vector<PairFunction> functions;

    for (WORD sectionIndex = 0;
         sectionIndex < nt->FileHeader.NumberOfSections;
         ++sectionIndex)
    {
        if ((sections[sectionIndex].Characteristics
                & IMAGE_SCN_MEM_EXECUTE) == 0)
            continue;

        const uint64_t sectionRva =
            sections[sectionIndex].VirtualAddress;
        const uint64_t sectionSize =
            sections[sectionIndex].Misc.VirtualSize;
        if (sectionSize < sizeof(uint32_t)
            || sectionRva >= static_cast<uint64_t>(end - base))
            continue;

        uint8_t* scanStart =
            base + static_cast<size_t>(sectionRva);
        uint8_t* scanEnd =
            scanStart + static_cast<size_t>(sectionSize);
        if (scanEnd > end)
            scanEnd = end;

        for (uint8_t* p = scanStart;
             p + sizeof(uint32_t) <= scanEnd;
             ++p)
        {
            uint32_t immediate = 0;
            memcpy(&immediate, p, sizeof(immediate));
            if (immediate != storyGroup)
                continue;

            uint8_t* functionStart = nullptr;
            uint8_t* functionEnd = nullptr;
            if (!FindRuntimeFunctionBounds(
                    base,
                    end,
                    p,
                    functionStart,
                    functionEnd)
                || !functionStart
                || !functionEnd
                || functionEnd <= functionStart
                || functionEnd - functionStart > 0x2000)
                continue;

            bool alreadyKnown = false;
            for (const PairFunction& existing : functions)
            {
                if (existing.start == functionStart)
                {
                    alreadyKnown = true;
                    break;
                }
            }
            if (alreadyKnown)
                continue;

            uint8_t* mapImmediateAddress = nullptr;
            for (uint8_t* q = functionStart;
                 q + sizeof(uint32_t) <= functionEnd;
                 ++q)
            {
                uint32_t candidate = 0;
                memcpy(&candidate, q, sizeof(candidate));
                if (candidate == mapGroup)
                {
                    mapImmediateAddress = q;
                    break;
                }
            }

            if (!mapImmediateAddress)
                continue;

            PairFunction found{};
            found.start = functionStart;
            found.end = functionEnd;
            found.storyImmediate = p;
            found.mapImmediate = mapImmediateAddress;
            functions.push_back(found);
        }
    }

    Logf(
        "[LegacyConsumerV62] executable GROUP_MAP_SP/GROUP_MAP containing-function summary count=%u.",
        static_cast<unsigned int>(functions.size()));

    for (size_t i = 0; i < functions.size(); ++i)
    {
        const PairFunction& function = functions[i];
        const long long distance =
            static_cast<long long>(
                function.mapImmediate
                - function.storyImmediate);

        Logf(
            "[LegacyConsumerV62] pairFunction[%u] startRVA=0x%llX endRVA=0x%llX size=0x%llX storyRVA=0x%llX storyOffset=0x%llX mapRVA=0x%llX mapOffset=0x%llX signedDistance=%lld.",
            static_cast<unsigned int>(i),
            static_cast<unsigned long long>(
                function.start - base),
            static_cast<unsigned long long>(
                function.end - base),
            static_cast<unsigned long long>(
                function.end - function.start),
            static_cast<unsigned long long>(
                function.storyImmediate - base),
            static_cast<unsigned long long>(
                function.storyImmediate - function.start),
            static_cast<unsigned long long>(
                function.mapImmediate - base),
            static_cast<unsigned long long>(
                function.mapImmediate - function.start),
            distance);

        LogBoundedBytes(
            base,
            end,
            function.storyImmediate,
            64,
            128,
            "Legacy v62 pair-function neighborhood");
        DumpNearbyRelativeCalls(
            base,
            end,
            function.storyImmediate,
            160,
            "Legacy v62 pair function");
        DumpNearbyRipRelativeTargets(
            base,
            end,
            function.storyImmediate,
            160,
            "Legacy v62 pair function");
    }
}

static void LogLegacyV62ConsumerMap(
    bool force)
{
    if (g_legacyV62ConsumerMapLogged && !force)
        return;

    if (!IsLegacyExecutableImage()
        || getGameVersion() != 102)
        return;

    HMODULE exe =
        GetModuleHandleA(nullptr);
    if (!exe)
        return;

    uint8_t* base =
        reinterpret_cast<uint8_t*>(exe);

    const IMAGE_DOS_HEADER* dos =
        reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
    if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        return;

    const IMAGE_NT_HEADERS64* nt =
        reinterpret_cast<const IMAGE_NT_HEADERS64*>(
            base + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE
        || nt->OptionalHeader.SizeOfImage == 0)
        return;

    uint8_t* end =
        base + nt->OptionalHeader.SizeOfImage;

    g_legacyV62ConsumerMapLogged = true;

    Logf(
        "[LegacyConsumerV62] mapping start force=%s base=%p imageSize=0x%llX. Observation-only; no function is called or modified.",
        force ? "yes" : "no",
        base,
        static_cast<unsigned long long>(end - base));

    DumpLegacyV62GroupPairFunctions(
        base,
        end);

    if (g_legacyV58WrapperAddress >=
            reinterpret_cast<uintptr_t>(base)
        && g_legacyV58WrapperAddress <
            reinterpret_cast<uintptr_t>(end))
    {
        DumpLegacyV62DirectCallXrefs(
            base,
            end,
            reinterpret_cast<uint8_t*>(
                g_legacyV58WrapperAddress),
            "natural SP->MAP wrapper");
    }

    if (g_legacyNaturalTarget >=
            reinterpret_cast<uintptr_t>(base)
        && g_legacyNaturalTarget <
            reinterpret_cast<uintptr_t>(end))
    {
        DumpLegacyV62DirectCallXrefs(
            base,
            end,
            reinterpret_cast<uint8_t*>(
                g_legacyNaturalTarget),
            "natural group loop");
    }

    if (g_legacyV57WorkerTarget >=
            reinterpret_cast<uintptr_t>(base)
        && g_legacyV57WorkerTarget <
            reinterpret_cast<uintptr_t>(end))
    {
        DumpLegacyV62DirectCallXrefs(
            base,
            end,
            reinterpret_cast<uint8_t*>(
                g_legacyV57WorkerTarget),
            "natural per-child worker");
    }

    uint8_t* fiveMGroupLoop =
        FindLegacyV62FiveMGroupLoop(
            base,
            end);
    if (fiveMGroupLoop)
    {
        DumpLegacyV62DirectCallXrefs(
            base,
            end,
            fiveMGroupLoop,
            "FiveM-style GROUP_MAP_SP loop");
    }

    Logf(
        "[LegacyConsumerV62] mapping complete. Use pairFunction/xref caller boundaries to select the next state-transition observation point; v62 performs no Legacy descriptor mutation.");
}

static bool g_legacyV63StateOwnerMapLogged = false;

static bool FindLegacyV63SingleDirectCaller(
    uint8_t* base,
    uint8_t* end,
    uint8_t* target,
    uint8_t*& callsite,
    uint8_t*& callerStart,
    uint8_t*& callerEnd,
    unsigned int& hitCount)
{
    callsite = nullptr;
    callerStart = nullptr;
    callerEnd = nullptr;
    hitCount = 0;

    if (!base || !end || end <= base || !target
        || target < base || target >= end)
        return false;

    const IMAGE_DOS_HEADER* dos =
        reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
    if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        return false;

    const IMAGE_NT_HEADERS64* nt =
        reinterpret_cast<const IMAGE_NT_HEADERS64*>(
            base + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE)
        return false;

    const IMAGE_SECTION_HEADER* sections =
        IMAGE_FIRST_SECTION(nt);

    for (WORD sectionIndex = 0;
         sectionIndex < nt->FileHeader.NumberOfSections;
         ++sectionIndex)
    {
        if ((sections[sectionIndex].Characteristics
                & IMAGE_SCN_MEM_EXECUTE) == 0)
            continue;

        const uint64_t sectionRva =
            sections[sectionIndex].VirtualAddress;
        const uint64_t sectionSize =
            sections[sectionIndex].Misc.VirtualSize;
        if (sectionSize < 5
            || sectionRva >= static_cast<uint64_t>(end - base))
            continue;

        uint8_t* scanStart =
            base + static_cast<size_t>(sectionRva);
        uint8_t* scanEnd =
            scanStart + static_cast<size_t>(sectionSize);
        if (scanEnd > end)
            scanEnd = end;

        for (uint8_t* p = scanStart;
             p + 5 <= scanEnd;
             ++p)
        {
            if (p[0] != 0xE8)
                continue;

            int32_t relative = 0;
            memcpy(&relative, p + 1, sizeof(relative));
            if (p + 5 + relative != target)
                continue;

            ++hitCount;
            if (hitCount != 1)
                continue;

            callsite = p;
            FindRuntimeFunctionBounds(
                base,
                end,
                p,
                callerStart,
                callerEnd);
        }
    }

    return hitCount == 1
        && callsite
        && callerStart
        && callerEnd
        && callerEnd > callerStart;
}

static unsigned int DumpLegacyV63DirectCallXrefs(
    uint8_t* base,
    uint8_t* end,
    uint8_t* target,
    const char* label)
{
    if (!base || !end || end <= base || !target
        || target < base || target >= end)
        return 0;

    const IMAGE_DOS_HEADER* dos =
        reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
    if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        return 0;

    const IMAGE_NT_HEADERS64* nt =
        reinterpret_cast<const IMAGE_NT_HEADERS64*>(
            base + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE)
        return 0;

    const IMAGE_SECTION_HEADER* sections =
        IMAGE_FIRST_SECTION(nt);

    unsigned int hits = 0;
    constexpr unsigned int maxHits = 32;

    Logf(
        "[LegacyConsumerV63] direct-call xrefs target=%s address=%p rva=0x%llX.",
        label ? label : "target",
        target,
        static_cast<unsigned long long>(target - base));

    for (WORD sectionIndex = 0;
         sectionIndex < nt->FileHeader.NumberOfSections
             && hits < maxHits;
         ++sectionIndex)
    {
        if ((sections[sectionIndex].Characteristics
                & IMAGE_SCN_MEM_EXECUTE) == 0)
            continue;

        const uint64_t sectionRva =
            sections[sectionIndex].VirtualAddress;
        const uint64_t sectionSize =
            sections[sectionIndex].Misc.VirtualSize;
        if (sectionSize < 5
            || sectionRva >= static_cast<uint64_t>(end - base))
            continue;

        uint8_t* scanStart =
            base + static_cast<size_t>(sectionRva);
        uint8_t* scanEnd =
            scanStart + static_cast<size_t>(sectionSize);
        if (scanEnd > end)
            scanEnd = end;

        for (uint8_t* p = scanStart;
             p + 5 <= scanEnd && hits < maxHits;
             ++p)
        {
            if (p[0] != 0xE8)
                continue;

            int32_t relative = 0;
            memcpy(&relative, p + 1, sizeof(relative));
            if (p + 5 + relative != target)
                continue;

            uint8_t* functionStart = nullptr;
            uint8_t* functionEnd = nullptr;
            const bool bounds =
                FindRuntimeFunctionBounds(
                    base,
                    end,
                    p,
                    functionStart,
                    functionEnd);

            Logf(
                "[LegacyConsumerV63] xref[%u] %s callsiteRVA=0x%llX callerStartRVA=0x%llX callerEndRVA=0x%llX callerSize=0x%llX.",
                hits,
                label ? label : "target",
                static_cast<unsigned long long>(p - base),
                bounds && functionStart
                    ? static_cast<unsigned long long>(
                        functionStart - base)
                    : 0ULL,
                bounds && functionEnd
                    ? static_cast<unsigned long long>(
                        functionEnd - base)
                    : 0ULL,
                bounds && functionStart && functionEnd
                    ? static_cast<unsigned long long>(
                        functionEnd - functionStart)
                    : 0ULL);

            LogBoundedBytes(
                base,
                end,
                p,
                64,
                112,
                "Legacy v63 direct-call xref");
            DumpNearbyRelativeCalls(
                base,
                end,
                p,
                128,
                "Legacy v63 caller");
            DumpNearbyRipRelativeTargets(
                base,
                end,
                p,
                128,
                "Legacy v63 caller");

            ++hits;
        }
    }

    Logf(
        "[LegacyConsumerV63] direct-call xref summary target=%s hits=%u.",
        label ? label : "target",
        hits);
    return hits;
}

