static void ValidateLegacyV63WrapperOwnerContext(
    uint8_t* base,
    uint8_t* end,
    uint8_t* ownerStart,
    uint8_t* ownerEnd,
    uint8_t* wrapperCallsite,
    uint8_t* wrapperTarget)
{
    if (!base || !end || !ownerStart || !ownerEnd
        || ownerEnd <= ownerStart || !wrapperCallsite
        || !wrapperTarget)
        return;

    static const uint8_t expectedOwnerPrefix[] =
    {
        0x40, 0x53,
        0x48, 0x83, 0xEC, 0x20,
        0x8B, 0xD9
    };

    const bool ownerPrefixVerified =
        static_cast<size_t>(ownerEnd - ownerStart)
            >= sizeof(expectedOwnerPrefix)
        && memcmp(
            ownerStart,
            expectedOwnerPrefix,
            sizeof(expectedOwnerPrefix)) == 0;

    const bool wrapperEdxFromOwnerArg =
        wrapperCallsite >= ownerStart + 2
        && wrapperCallsite[-2] == 0x8B
        && wrapperCallsite[-1] == 0xD3;

    uintptr_t contextGlobal = 0;
    unsigned int contextGlobalLoads = 0;
    bool mixedContextGlobals = false;

    for (uint8_t* p = ownerStart;
         p + 7 <= ownerEnd;
         ++p)
    {
        if (p[0] != 0x48
            || p[1] != 0x8B
            || p[2] != 0x0D)
            continue;

        int32_t displacement = 0;
        memcpy(&displacement, p + 3, sizeof(displacement));
        const uintptr_t resolved =
            reinterpret_cast<uintptr_t>(p + 7 + displacement);

        if (!contextGlobal)
            contextGlobal = resolved;
        else if (resolved != contextGlobal)
            mixedContextGlobals = true;

        if (resolved == contextGlobal)
            ++contextGlobalLoads;
    }

    uintptr_t context = 0;
    uintptr_t childArray = 0;
    uint16_t childCount = 0;
    LONG lowriderIndex = -1;
    uintptr_t lowriderChild = 0;
    bool readFaulted = false;

    if (contextGlobal
        && !mixedContextGlobals
        && contextGlobalLoads >= 2)
    {
        __try
        {
            memcpy(
                &context,
                reinterpret_cast<const void*>(contextGlobal),
                sizeof(context));

            if (context)
            {
                memcpy(
                    &childArray,
                    reinterpret_cast<const void*>(context + 0x28),
                    sizeof(childArray));
                memcpy(
                    &childCount,
                    reinterpret_cast<const void*>(context + 0x30),
                    sizeof(childCount));

                if (childArray
                    && childCount != 0
                    && childCount <= 4096)
                {
                    for (uint16_t i = 0;
                         i < childCount;
                         ++i)
                    {
                        const uintptr_t child =
                            childArray
                            + (static_cast<uintptr_t>(i) * 0xF0);
                        uint32_t field60 = 0;
                        memcpy(
                            &field60,
                            reinterpret_cast<const void*>(child + 0x60),
                            sizeof(field60));
                        if (field60 == 0x61322A35U)
                        {
                            lowriderIndex = static_cast<LONG>(i);
                            lowriderChild = child;
                            break;
                        }
                    }
                }
            }
        }
        __except(EXCEPTION_EXECUTE_HANDLER)
        {
            readFaulted = true;
        }
    }

    uintptr_t descriptorTable = 0;
    uint16_t descriptorCount = 0;
    uint16_t mapDescriptorIndex = 0xFFFF;
    uintptr_t mapAssociatedTable = 0;
    uint16_t mapAssociatedCount = 0;
    uint16_t mapBennyCount = 0;
    uint16_t storyBennyCount = 0;
    const bool exactStockFingerprint =
        lowriderChild
        && InspectLegacyV61DescriptorFingerprint(
            lowriderChild,
            true,
            descriptorTable,
            descriptorCount,
            mapDescriptorIndex,
            mapAssociatedTable,
            mapAssociatedCount,
            mapBennyCount,
            storyBennyCount);

    unsigned int directCalls = 0;
    uint8_t* preWrapperTarget = nullptr;
    uint8_t* preWrapperCallsite = nullptr;

    for (uint8_t* p = ownerStart;
         p + 5 <= ownerEnd;
         ++p)
    {
        if (p[0] != 0xE8)
            continue;

        int32_t relative = 0;
        memcpy(&relative, p + 1, sizeof(relative));
        uint8_t* resolved = p + 5 + relative;
        if (resolved < base || resolved >= end)
            continue;

        ++directCalls;
        if (resolved != wrapperTarget
            && !preWrapperTarget)
        {
            preWrapperTarget = resolved;
            preWrapperCallsite = p;
        }
    }

    const bool preWrapperEdxFromOwnerArg =
        preWrapperCallsite
        && preWrapperCallsite >= ownerStart + 2
        && preWrapperCallsite[-2] == 0x8B
        && preWrapperCallsite[-1] == 0xD3;

    Logf(
        "[LegacyConsumerV63] wrapperOwnerValidation ownerRVA=0x%llX size=0x%llX prefixVerified=%s directCalls=%u wrapperCallRVA=0x%llX wrapperEdxFromInput=%s prePass=%p(rva=0x%llX) prePassEdxFromInput=%s contextGlobal=%p loads=%u sameGlobal=%s context=%p childArray=%p childCount=%u lowriderIndex=%ld lowriderChild=%p exactStockFingerprint=%s readFaulted=%s.",
        static_cast<unsigned long long>(ownerStart - base),
        static_cast<unsigned long long>(ownerEnd - ownerStart),
        ownerPrefixVerified ? "yes" : "no",
        directCalls,
        static_cast<unsigned long long>(wrapperCallsite - base),
        wrapperEdxFromOwnerArg ? "yes" : "no",
        preWrapperTarget,
        preWrapperTarget
            ? static_cast<unsigned long long>(preWrapperTarget - base)
            : 0ULL,
        preWrapperEdxFromOwnerArg ? "yes" : "no",
        reinterpret_cast<void*>(contextGlobal),
        contextGlobalLoads,
        contextGlobal && !mixedContextGlobals
            ? "yes"
            : "no",
        reinterpret_cast<void*>(context),
        reinterpret_cast<void*>(childArray),
        static_cast<unsigned int>(childCount),
        static_cast<long>(lowriderIndex),
        reinterpret_cast<void*>(lowriderChild),
        exactStockFingerprint ? "yes" : "no",
        readFaulted ? "yes" : "no");

    LogBoundedBytes(
        base,
        end,
        wrapperCallsite,
        64,
        96,
        "Legacy v63 wrapper owner");
    DumpNearbyRelativeCalls(
        base,
        end,
        wrapperCallsite,
        128,
        "Legacy v63 wrapper owner");
    DumpNearbyRipRelativeTargets(
        base,
        end,
        wrapperCallsite,
        128,
        "Legacy v63 wrapper owner");

    if (preWrapperTarget)
    {
        DumpContainingRuntimeFunction(
            base,
            end,
            preWrapperTarget,
            "Legacy v63 pre-wrapper pass");
        LogBoundedBytes(
            base,
            end,
            preWrapperTarget,
            0,
            160,
            "Legacy v63 pre-wrapper pass");
        DumpLegacyV63DirectCallXrefs(
            base,
            end,
            preWrapperTarget,
            "pre-wrapper pass");
    }
}

static void DumpLegacyV63DualLoopOwners(
    uint8_t* base,
    uint8_t* end,
    uint8_t* naturalLoop,
    uint8_t* alternateLoop)
{
    if (!base || !end || end <= base
        || !naturalLoop || !alternateLoop)
        return;

    const IMAGE_DOS_HEADER* dos =
        reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
    if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        return;

    const IMAGE_NT_HEADERS64* nt =
        reinterpret_cast<const IMAGE_NT_HEADERS64*>(
            base + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE)
        return;

    const IMAGE_SECTION_HEADER* sections =
        IMAGE_FIRST_SECTION(nt);
    std::vector<uint8_t*> owners;

    for (WORD sectionIndex = 0;
         sectionIndex < nt->FileHeader.NumberOfSections;
         ++sectionIndex)
    {
        if ((sections[sectionIndex].Characteristics
                & IMAGE_SCN_MEM_EXECUTE) == 0)
            continue;

        uint8_t* scanStart =
            base + sections[sectionIndex].VirtualAddress;
        uint8_t* scanEnd =
            scanStart + sections[sectionIndex].Misc.VirtualSize;
        if (scanEnd > end)
            scanEnd = end;

        for (uint8_t* p = scanStart;
             p + 5 <= scanEnd;
             ++p)
        {
            if (p[0] != 0xE8)
                continue;

            int32_t relative = 0;
            memcpy(&relative, p + 1, sizeof(relative));
            if (p + 5 + relative != naturalLoop)
                continue;

            uint8_t* functionStart = nullptr;
            uint8_t* functionEnd = nullptr;
            if (!FindRuntimeFunctionBounds(
                    base,
                    end,
                    p,
                    functionStart,
                    functionEnd)
                || !functionStart
                || !functionEnd
                || functionEnd <= functionStart)
                continue;

            bool hasAlternate = false;
            uint8_t* alternateCallsite = nullptr;
            for (uint8_t* q = functionStart;
                 q + 5 <= functionEnd;
                 ++q)
            {
                if (q[0] != 0xE8)
                    continue;
                int32_t qRelative = 0;
                memcpy(&qRelative, q + 1, sizeof(qRelative));
                if (q + 5 + qRelative == alternateLoop)
                {
                    hasAlternate = true;
                    alternateCallsite = q;
                    break;
                }
            }

            if (!hasAlternate)
                continue;

            bool duplicate = false;
            for (uint8_t* owner : owners)
            {
                if (owner == functionStart)
                {
                    duplicate = true;
                    break;
                }
            }
            if (duplicate)
                continue;

            owners.push_back(functionStart);
            const unsigned int index =
                static_cast<unsigned int>(owners.size() - 1);

            Logf(
                "[LegacyConsumerV63] dualLoopOwner[%u] startRVA=0x%llX endRVA=0x%llX size=0x%llX naturalCallRVA=0x%llX alternateCallRVA=0x%llX order=%s.",
                index,
                static_cast<unsigned long long>(functionStart - base),
                static_cast<unsigned long long>(functionEnd - base),
                static_cast<unsigned long long>(functionEnd - functionStart),
                static_cast<unsigned long long>(p - base),
                static_cast<unsigned long long>(alternateCallsite - base),
                p < alternateCallsite
                    ? "natural-then-alternate"
                    : "alternate-then-natural");

            LogBoundedBytes(
                base,
                end,
                functionStart,
                0,
                static_cast<size_t>(
                    (functionEnd - functionStart) < 192
                        ? (functionEnd - functionStart)
                        : 192),
                "Legacy v63 dual-loop owner");
            DumpNearbyRipRelativeTargets(
                base,
                end,
                functionStart,
                192,
                "Legacy v63 dual-loop owner");
            DumpLegacyV63DirectCallXrefs(
                base,
                end,
                functionStart,
                "dual-loop lifecycle owner");
        }
    }

    Logf(
        "[LegacyConsumerV63] dual-loop lifecycle owner summary count=%u.",
        static_cast<unsigned int>(owners.size()));
}

static void LogLegacyV63StateOwnerMap(
    bool force)
{
    if (g_legacyV63StateOwnerMapLogged && !force)
        return;

    if (!IsLegacyExecutableImage()
        || getGameVersion() != 102)
        return;

    HMODULE exe = GetModuleHandleA(nullptr);
    if (!exe)
        return;

    uint8_t* base = reinterpret_cast<uint8_t*>(exe);
    const IMAGE_DOS_HEADER* dos =
        reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
    if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        return;

    const IMAGE_NT_HEADERS64* nt =
        reinterpret_cast<const IMAGE_NT_HEADERS64*>(
            base + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE
        || nt->OptionalHeader.SizeOfImage == 0)
        return;

    uint8_t* end = base + nt->OptionalHeader.SizeOfImage;
    g_legacyV63StateOwnerMapLogged = true;

    Logf(
        "[LegacyConsumerV63] validation start force=%s base=%p imageSize=0x%llX. Read-only: no Legacy function is invoked and no runtime descriptor/state is modified.",
        force ? "yes" : "no",
        base,
        static_cast<unsigned long long>(end - base));

    uint8_t* wrapper = nullptr;
    if (g_legacyV58WrapperAddress >=
            reinterpret_cast<uintptr_t>(base)
        && g_legacyV58WrapperAddress <
            reinterpret_cast<uintptr_t>(end))
    {
        wrapper = reinterpret_cast<uint8_t*>(
            g_legacyV58WrapperAddress);
    }

    uint8_t* wrapperCallsite = nullptr;
    uint8_t* wrapperOwnerStart = nullptr;
    uint8_t* wrapperOwnerEnd = nullptr;
    unsigned int wrapperCallerHits = 0;
    const bool wrapperOwnerUnique =
        wrapper
        && FindLegacyV63SingleDirectCaller(
            base,
            end,
            wrapper,
            wrapperCallsite,
            wrapperOwnerStart,
            wrapperOwnerEnd,
            wrapperCallerHits);

    Logf(
        "[LegacyConsumerV63] naturalWrapper=%p(rva=0x%llX) directCallerHits=%u uniqueOwner=%s ownerStartRVA=0x%llX ownerEndRVA=0x%llX callsiteRVA=0x%llX.",
        wrapper,
        wrapper
            ? static_cast<unsigned long long>(wrapper - base)
            : 0ULL,
        wrapperCallerHits,
        wrapperOwnerUnique ? "yes" : "no",
        wrapperOwnerStart
            ? static_cast<unsigned long long>(wrapperOwnerStart - base)
            : 0ULL,
        wrapperOwnerEnd
            ? static_cast<unsigned long long>(wrapperOwnerEnd - base)
            : 0ULL,
        wrapperCallsite
            ? static_cast<unsigned long long>(wrapperCallsite - base)
            : 0ULL);

    if (wrapperOwnerUnique)
    {
        ValidateLegacyV63WrapperOwnerContext(
            base,
            end,
            wrapperOwnerStart,
            wrapperOwnerEnd,
            wrapperCallsite,
            wrapper);

        DumpLegacyV63DirectCallXrefs(
            base,
            end,
            wrapperOwnerStart,
            "natural-wrapper owner");
    }

    uint8_t* alternateLoop = nullptr;
    uint8_t* fiveMOwnerStart = nullptr;
    uint8_t* fiveMOwnerEnd = nullptr;
    uint8_t* fiveMCallsite = nullptr;
    unsigned int fiveMMatches = 0;
    const bool fiveMAnchorUnique =
        FindLegacyV63FiveMAnchor(
            base,
            end,
            alternateLoop,
            fiveMOwnerStart,
            fiveMOwnerEnd,
            fiveMCallsite,
            fiveMMatches);

    Logf(
        "[LegacyConsumerV63] FiveMAnchor matches=%u unique=%s loop=%p(rva=0x%llX) ownerStartRVA=0x%llX ownerEndRVA=0x%llX callsiteRVA=0x%llX.",
        fiveMMatches,
        fiveMAnchorUnique ? "yes" : "no",
        alternateLoop,
        alternateLoop
            ? static_cast<unsigned long long>(alternateLoop - base)
            : 0ULL,
        fiveMOwnerStart
            ? static_cast<unsigned long long>(fiveMOwnerStart - base)
            : 0ULL,
        fiveMOwnerEnd
            ? static_cast<unsigned long long>(fiveMOwnerEnd - base)
            : 0ULL,
        fiveMCallsite
            ? static_cast<unsigned long long>(fiveMCallsite - base)
            : 0ULL);

    if (fiveMAnchorUnique)
    {
        LogBoundedBytes(
            base,
            end,
            fiveMCallsite,
            96,
            128,
            "Legacy v63 FiveM state owner");
        DumpNearbyRelativeCalls(
            base,
            end,
            fiveMCallsite,
            160,
            "Legacy v63 FiveM state owner");
        DumpNearbyRipRelativeTargets(
            base,
            end,
            fiveMCallsite,
            160,
            "Legacy v63 FiveM state owner");
        DumpLegacyV63DirectCallXrefs(
            base,
            end,
            fiveMOwnerStart,
            "FiveM-locator state owner");
    }

    uint8_t* naturalLoop = nullptr;
    if (g_legacyNaturalTarget >=
            reinterpret_cast<uintptr_t>(base)
        && g_legacyNaturalTarget <
            reinterpret_cast<uintptr_t>(end))
    {
        naturalLoop = reinterpret_cast<uint8_t*>(
            g_legacyNaturalTarget);
    }

    if (naturalLoop && alternateLoop)
    {
        DumpLegacyV63DualLoopOwners(
            base,
            end,
            naturalLoop,
            alternateLoop);
    }

    Logf(
        "[LegacyConsumerV63] validation complete. Next decision should be based on owner caller relationships and the live-context fingerprint; v63 did not invoke any Legacy consumer or apply the v61 descriptor view.");
}

struct LegacyV66VectorInvariantState
{
    bool attempted;
    bool valid;
    bool faulted;
    uint16_t descriptorCount;
    uint16_t descriptorCapacity;
    uint16_t mapAssociatedCount;
    uint16_t mapAssociatedCapacity;
    uint16_t storyAssociatedCount;
    uint16_t storyAssociatedCapacity;
};

static LegacyV66VectorInvariantState
    g_legacyV66Vector{};

static bool InspectLegacyV66TemporaryVectorInvariants(
    uintptr_t child)
{
    g_legacyV66Vector =
        LegacyV66VectorInvariantState{};
    g_legacyV66Vector.attempted = true;

    constexpr uint32_t mapGroup = 0xBCC89179U;
    constexpr uint32_t storyGroup = 0x578F99E2U;
    constexpr size_t descriptorStride = 0x18;

    bool valid = false;

    __try
    {
        uintptr_t table = 0;
        memcpy(
            &table,
            reinterpret_cast<const void*>(child + 0x78),
            sizeof(table));
        memcpy(
            &g_legacyV66Vector.descriptorCount,
            reinterpret_cast<const void*>(child + 0x80),
            sizeof(g_legacyV66Vector.descriptorCount));
        memcpy(
            &g_legacyV66Vector.descriptorCapacity,
            reinterpret_cast<const void*>(child + 0x82),
            sizeof(g_legacyV66Vector.descriptorCapacity));

        if (!table
            || g_legacyV66Vector.descriptorCount != 3
            || g_legacyV66Vector.descriptorCapacity
                < g_legacyV66Vector.descriptorCount)
        {
            valid = false;
        }
        else
        {
            uint16_t mapDescriptors = 0;
            uint16_t storyDescriptors = 0;

            for (uint16_t i = 0;
                 i < g_legacyV66Vector.descriptorCount;
                 ++i)
            {
                const uintptr_t descriptor =
                    table
                    + (static_cast<uintptr_t>(i)
                        * descriptorStride);
                uint32_t group = 0;
                uint16_t count = 0;
                uint16_t capacity = 0;

                memcpy(
                    &group,
                    reinterpret_cast<const void*>(
                        descriptor + 0x00),
                    sizeof(group));
                memcpy(
                    &count,
                    reinterpret_cast<const void*>(
                        descriptor + 0x10),
                    sizeof(count));
                memcpy(
                    &capacity,
                    reinterpret_cast<const void*>(
                        descriptor + 0x12),
                    sizeof(capacity));

                if (group == mapGroup)
                {
                    ++mapDescriptors;
                    g_legacyV66Vector.mapAssociatedCount =
                        count;
                    g_legacyV66Vector.mapAssociatedCapacity =
                        capacity;
                }
                else if (group == storyGroup)
                {
                    ++storyDescriptors;
                    g_legacyV66Vector.storyAssociatedCount =
                        count;
                    g_legacyV66Vector.storyAssociatedCapacity =
                        capacity;
                }
            }

            valid = mapDescriptors == 1
                && storyDescriptors == 1
                && g_legacyV66Vector.mapAssociatedCount == 3
                && g_legacyV66Vector.mapAssociatedCapacity
                    >= g_legacyV66Vector.mapAssociatedCount
                && g_legacyV66Vector.storyAssociatedCount == 1
                && g_legacyV66Vector.storyAssociatedCapacity
                    >= g_legacyV66Vector.storyAssociatedCount;
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        g_legacyV66Vector.faulted = true;
        valid = false;
    }

    g_legacyV66Vector.valid = valid;

    Logf(
        "[LegacySetup2V66] temporaryVectorInvariant valid=%s faulted=%s descriptors{count=%u capacity=%u} GROUP_MAP{count=%u capacity=%u} GROUP_MAP_SP{count=%u capacity=%u}.",
        valid ? "yes" : "no",
        g_legacyV66Vector.faulted ? "yes" : "no",
        static_cast<unsigned int>(
            g_legacyV66Vector.descriptorCount),
        static_cast<unsigned int>(
            g_legacyV66Vector.descriptorCapacity),
        static_cast<unsigned int>(
            g_legacyV66Vector.mapAssociatedCount),
        static_cast<unsigned int>(
            g_legacyV66Vector.mapAssociatedCapacity),
        static_cast<unsigned int>(
            g_legacyV66Vector.storyAssociatedCount),
        static_cast<unsigned int>(
            g_legacyV66Vector.storyAssociatedCapacity));

    return valid;
}

struct LegacyV67DerivedSetup2Snapshot
{
    bool attempted;
    bool valid;
    bool faulted;
    uintptr_t child;
    uintptr_t table;
    uint16_t count;
    uint16_t capacity;
    uint8_t flagsE8;
    uint16_t captured;
    uint32_t first[16];
    uint32_t second[16];
};

static LegacyV67DerivedSetup2Snapshot
CaptureLegacyV67DerivedSetup2Snapshot(
    uintptr_t child,
    const char* phase)
{
    LegacyV67DerivedSetup2Snapshot snapshot{};
    snapshot.attempted = true;
    snapshot.child = child;

    __try
    {
        if (!child)
        {
            snapshot.valid = false;
        }
        else
        {
            memcpy(
                &snapshot.table,
                reinterpret_cast<const void*>(child + 0xD8),
                sizeof(snapshot.table));
            memcpy(
                &snapshot.count,
                reinterpret_cast<const void*>(child + 0xE0),
                sizeof(snapshot.count));
            memcpy(
                &snapshot.capacity,
                reinterpret_cast<const void*>(child + 0xE2),
                sizeof(snapshot.capacity));
            memcpy(
                &snapshot.flagsE8,
                reinterpret_cast<const void*>(child + 0xE8),
                sizeof(snapshot.flagsE8));

            snapshot.valid =
                snapshot.count <= snapshot.capacity
                && snapshot.count <= 0x400
                && (snapshot.count == 0 || snapshot.table != 0);

            if (snapshot.valid && snapshot.table)
            {
                snapshot.captured =
                    snapshot.count < 16
                        ? snapshot.count
                        : 16;

                for (uint16_t i = 0;
                     i < snapshot.captured;
                     ++i)
                {
                    const uintptr_t entry =
                        snapshot.table
                        + (static_cast<uintptr_t>(i) * 8U);
                    memcpy(
                        &snapshot.first[i],
                        reinterpret_cast<const void*>(entry + 0x00),
                        sizeof(snapshot.first[i]));
                    memcpy(
                        &snapshot.second[i],
                        reinterpret_cast<const void*>(entry + 0x04),
                        sizeof(snapshot.second[i]));
                }
            }
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        snapshot.faulted = true;
        snapshot.valid = false;
    }

    Logf(
        "[LegacyDerivedV67] %s child=%p vector{table=%p count=%u capacity=%u valid=%s faulted=%s} flagsE8=0x%02X captured=%u.",
        phase ? phase : "snapshot",
        reinterpret_cast<void*>(snapshot.child),
        reinterpret_cast<void*>(snapshot.table),
        static_cast<unsigned int>(snapshot.count),
        static_cast<unsigned int>(snapshot.capacity),
        snapshot.valid ? "yes" : "no",
        snapshot.faulted ? "yes" : "no",
        static_cast<unsigned int>(snapshot.flagsE8),
        static_cast<unsigned int>(snapshot.captured));

    constexpr uint32_t dlcHash = 0x61322A35U;
    constexpr uint32_t mapGroup = 0xBCC89179U;
    constexpr uint32_t storyGroup = 0x578F99E2U;
    constexpr uint32_t bennyHash = 0x4CDFC843U;

    for (uint16_t i = 0;
         i < snapshot.captured;
         ++i)
    {
        const uint32_t first = snapshot.first[i];
        const uint32_t second = snapshot.second[i];
        Logf(
            "[LegacyDerivedV67] %s entry[%u]={first=0x%08X second=0x%08X} known{firstDlc=%s firstMap=%s firstStory=%s firstBenny=%s secondDlc=%s secondMap=%s secondStory=%s secondBenny=%s}.",
            phase ? phase : "snapshot",
            static_cast<unsigned int>(i),
            first,
            second,
            first == dlcHash ? "yes" : "no",
            first == mapGroup ? "yes" : "no",
            first == storyGroup ? "yes" : "no",
            first == bennyHash ? "yes" : "no",
            second == dlcHash ? "yes" : "no",
            second == mapGroup ? "yes" : "no",
            second == storyGroup ? "yes" : "no",
            second == bennyHash ? "yes" : "no");
    }

    return snapshot;
}

static void LogLegacyV67DerivedCodeMap(
    uint8_t* base,
    uint8_t* end,
    uint8_t* prePass)
{
    if (!base || !end || end <= base || !prePass)
        return;

    uint8_t* helper = nullptr;
    bool helperCallVerified = false;
    bool helperFieldAccessVerified = false;

    __try
    {

        if (prePass + 0x37 <= end
            && prePass[0x29] == 0xF6
            && prePass[0x2A] == 0x81
            && prePass[0x2B] == 0xE8
            && prePass[0x2F] == 0x04
            && prePass[0x30] == 0x75
            && prePass[0x32] == 0xE8)
        {
            int32_t relative = 0;
            memcpy(
                &relative,
                prePass + 0x33,
                sizeof(relative));
            helper = prePass + 0x37 + relative;
            helperCallVerified =
                helper >= base && helper < end;
        }

        if (helperCallVerified
            && helper + 0x2D <= end)
        {
            static const uint8_t countLoad[] =
            {
                0x0F, 0xB7, 0x81,
                0xE0, 0x00, 0x00, 0x00
            };
            static const uint8_t tableLoad[] =
            {
                0x48, 0x8B, 0x8F,
                0xD8, 0x00, 0x00, 0x00
            };

            helperFieldAccessVerified =
                memcmp(
                    helper + 0x11,
                    countLoad,
                    sizeof(countLoad)) == 0
                && memcmp(
                    helper + 0x22,
                    tableLoad,
                    sizeof(tableLoad)) == 0;
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        helper = nullptr;
        helperCallVerified = false;
        helperFieldAccessVerified = false;
    }

    Logf(
        "[LegacyDerivedV67] codeMap prePass=%p(rva=0x%llX) childHelper=%p(rva=0x%llX) callVerified=%s derivedFieldAccess{D8/E0}=%s worker=%p(rva=0x%llX).",
        prePass,
        static_cast<unsigned long long>(prePass - base),
        helper,
        helper
            ? static_cast<unsigned long long>(helper - base)
            : 0ULL,
        helperCallVerified ? "yes" : "no",
        helperFieldAccessVerified ? "yes" : "no",
        reinterpret_cast<void*>(g_legacyV57WorkerTarget),
        g_legacyV57WorkerTarget >=
                reinterpret_cast<uintptr_t>(base)
            && g_legacyV57WorkerTarget <
                reinterpret_cast<uintptr_t>(end)
            ? static_cast<unsigned long long>(
                g_legacyV57WorkerTarget
                - reinterpret_cast<uintptr_t>(base))
            : 0ULL);

    if (helperCallVerified && helper)
    {
        uint8_t* helperStart = nullptr;
        uint8_t* helperEnd = nullptr;
        if (FindRuntimeFunctionBounds(
                base,
                end,
                helper,
                helperStart,
                helperEnd)
            && helperStart == helper
            && helperEnd > helperStart)
        {
            const size_t helperSize =
                static_cast<size_t>(helperEnd - helperStart);
            Logf(
                "[LegacyDerivedV67] childHelper bounds startRVA=0x%llX endRVA=0x%llX size=0x%llX.",
                static_cast<unsigned long long>(helperStart - base),
                static_cast<unsigned long long>(helperEnd - base),
                static_cast<unsigned long long>(helperSize));
            LogBoundedBytes(
                base,
                end,
                helperStart,
                0,
                helperSize < 0x100 ? helperSize : 0x100,
                "Legacy v67 derived child helper");
        }
    }

    if (helperCallVerified && helper && helper + 0x50 <= end)
    {
        bool pairDispatchVerified = false;
        uint32_t helperMode = 0xFFFFFFFFU;
        uint8_t* pairConsumer = nullptr;

        __try
        {
            if (helper[0x37] == 0x41
                && helper[0x38] == 0xB9
                && helper[0x4B] == 0xE8)
            {
                memcpy(&helperMode, helper + 0x39, sizeof(helperMode));
                int32_t relative = 0;
                memcpy(&relative, helper + 0x4C, sizeof(relative));
                pairConsumer = helper + 0x50 + relative;
                pairDispatchVerified = pairConsumer >= base && pairConsumer < end;
            }
        }
        __except(EXCEPTION_EXECUTE_HANDLER)
        {
            pairDispatchVerified = false;
            pairConsumer = nullptr;
            helperMode = 0xFFFFFFFFU;
        }

        Logf(
            "[LegacyDerivedV70] pairDispatch childHelper=%p(rva=0x%llX) consumer=%p(rva=0x%llX) callRVA=0x%llX helperModeKnown=%s helperMode=%u verified=%s.",
            helper,
            static_cast<unsigned long long>(helper - base),
            pairConsumer,
            pairConsumer ? static_cast<unsigned long long>(pairConsumer - base) : 0ULL,
            static_cast<unsigned long long>((helper + 0x4B) - base),
            helperMode != 0xFFFFFFFFU ? "yes" : "no",
            helperMode != 0xFFFFFFFFU ? static_cast<unsigned int>(helperMode) : 0U,
            pairDispatchVerified ? "yes" : "no");

        DumpLegacyV63DirectCallXrefs(base, end, helper, "v70 derived child helper");

        if (pairDispatchVerified && pairConsumer)
        {
            uint8_t* consumerStart = nullptr;
            uint8_t* consumerEnd = nullptr;
            const bool consumerBounds =
                FindRuntimeFunctionBounds(base, end, pairConsumer, consumerStart, consumerEnd)
                && consumerStart && consumerEnd && consumerEnd > consumerStart;

            Logf(
                "[LegacyDerivedV70] pairConsumer bounds=%s startRVA=0x%llX endRVA=0x%llX size=0x%llX.",
                consumerBounds ? "yes" : "no",
                consumerBounds ? static_cast<unsigned long long>(consumerStart - base) : 0ULL,
                consumerBounds ? static_cast<unsigned long long>(consumerEnd - base) : 0ULL,
                consumerBounds ? static_cast<unsigned long long>(consumerEnd - consumerStart) : 0ULL);

            if (consumerBounds)
            {
                const size_t consumerSize = static_cast<size_t>(consumerEnd - consumerStart);
                LogBoundedBytes(base, end, consumerStart, 0,
                    consumerSize < 0x400 ? consumerSize : 0x400,
                    "Legacy v70 derived pair consumer");
                DumpNearbyRelativeCalls(base, end, consumerStart,
                    consumerSize < 0x200 ? consumerSize : 0x200,
                    "Legacy v70 derived pair consumer");
                DumpNearbyRipRelativeTargets(base, end, consumerStart,
                    consumerSize < 0x200 ? consumerSize : 0x200,
                    "Legacy v70 derived pair consumer");
            }

            const unsigned int directConsumerCalls =
                DumpLegacyV63DirectCallXrefs(base, end, pairConsumer, "v70 derived pair consumer");
            const IMAGE_DOS_HEADER* dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
            const IMAGE_NT_HEADERS64* nt = dos->e_magic == IMAGE_DOS_SIGNATURE
                ? reinterpret_cast<const IMAGE_NT_HEADERS64*>(base + dos->e_lfanew) : nullptr;
            unsigned int classifiedCalls = 0;

            if (nt && nt->Signature == IMAGE_NT_SIGNATURE)
            {
                const IMAGE_SECTION_HEADER* sections = IMAGE_FIRST_SECTION(nt);
                for (WORD sectionIndex = 0; sectionIndex < nt->FileHeader.NumberOfSections; ++sectionIndex)
                {
                    if ((sections[sectionIndex].Characteristics & IMAGE_SCN_MEM_EXECUTE) == 0)
                        continue;
                    uint8_t* scanStart = base + sections[sectionIndex].VirtualAddress;
                    uint8_t* scanEnd = scanStart + sections[sectionIndex].Misc.VirtualSize;
                    if (scanEnd > end) scanEnd = end;

                    for (uint8_t* p = scanStart; p + 5 <= scanEnd; ++p)
                    {
                        if (p[0] != 0xE8) continue;
                        int32_t relative = 0;
                        memcpy(&relative, p + 1, sizeof(relative));
                        if (p + 5 + relative != pairConsumer) continue;

                        uint8_t* callerStart = nullptr;
                        uint8_t* callerEnd = nullptr;
                        const bool callerBounds =
                            FindRuntimeFunctionBounds(base, end, p, callerStart, callerEnd)
                            && callerStart && callerEnd && callerEnd > callerStart;
                        bool modeKnown = false;
                        uint32_t mode = 0;
                        uint8_t* lower = callerBounds ? callerStart : scanStart;
                        size_t available = static_cast<size_t>(p - lower);
                        uint8_t* searchStart = p - (available < 64 ? available : 64);
                        for (uint8_t* q = p; q > searchStart;)
                        {
                            --q;
                            if (q + 6 <= p && q[0] == 0x41 && q[1] == 0xB9)
                            {
                                memcpy(&mode, q + 2, sizeof(mode));
                                modeKnown = true;
                                break;
                            }
                            if (q + 3 <= p && q[0] == 0x45 && q[1] == 0x33 && q[2] == 0xC9)
                            {
                                mode = 0;
                                modeKnown = true;
                                break;
                            }
                        }

                        bool referencesD8 = false;
                        bool referencesE0 = false;
                        if (callerBounds)
                        {
                            for (uint8_t* q = callerStart; q + 4 <= callerEnd; ++q)
                            {
                                uint32_t disp = 0;
                                memcpy(&disp, q, sizeof(disp));
                                if (disp == 0x000000D8U) referencesD8 = true;
                                if (disp == 0x000000E0U) referencesE0 = true;
                            }
                        }

                        Logf(
                            "[LegacyDerivedV70] consumerCall[%u] callRVA=0x%llX callerStartRVA=0x%llX callerEndRVA=0x%llX nearestR9ModeKnown=%s mode=%u callerRefs{D8=%s E0=%s}.",
                            classifiedCalls,
                            static_cast<unsigned long long>(p - base),
                            callerBounds ? static_cast<unsigned long long>(callerStart - base) : 0ULL,
                            callerBounds ? static_cast<unsigned long long>(callerEnd - base) : 0ULL,
                            modeKnown ? "yes" : "no",
                            modeKnown ? static_cast<unsigned int>(mode) : 0U,
                            referencesD8 ? "yes" : "no",
                            referencesE0 ? "yes" : "no");
                        LogBoundedBytes(base, end, p, 64, 80, "Legacy v70 derived pair consumer callsite");
                        ++classifiedCalls;
                    }
                }
            }

            Logf(
                "[LegacyDerivedV70] consumerMap summary directCalls=%u classifiedCalls=%u helperMode=%u. Observation-only: no Legacy function was invoked and no descriptor/vector/runtime state was modified.",
                directConsumerCalls, classifiedCalls,
                helperMode != 0xFFFFFFFFU ? static_cast<unsigned int>(helperMode) : 0U);
        }
    }

    if (g_legacyV57WorkerTarget >=
            reinterpret_cast<uintptr_t>(base)
        && g_legacyV57WorkerTarget <
            reinterpret_cast<uintptr_t>(end))
    {
        uint8_t* worker =
            reinterpret_cast<uint8_t*>(
                g_legacyV57WorkerTarget);
        uint8_t* workerStart = nullptr;
        uint8_t* workerEnd = nullptr;
        if (FindRuntimeFunctionBounds(
                base,
                end,
                worker,
                workerStart,
                workerEnd)
            && workerStart == worker
            && workerEnd > workerStart)
        {
            const size_t workerSize =
                static_cast<size_t>(workerEnd - workerStart);
            Logf(
                "[LegacyDerivedV67] perChildWorker bounds startRVA=0x%llX endRVA=0x%llX size=0x%llX.",
                static_cast<unsigned long long>(workerStart - base),
                static_cast<unsigned long long>(workerEnd - base),
                static_cast<unsigned long long>(workerSize));
            LogBoundedBytes(
                base,
                end,
                workerStart,
                0,
                workerSize < 0x100 ? workerSize : 0x100,
                "Legacy v67 per-child worker");
        }
    }
}

