static bool IsBennysGarageDoorAlwaysDeniedVehicleClass(int vehicleClass)
{
    // Mirrors Helper.unWelcome: Cycles, Boats, Helicopters, Planes.
    return vehicleClass == 13
        || vehicleClass == 14
        || vehicleClass == 15
        || vehicleClass == 16;
}

static bool TryGetCachedBennysGarageDoorOversizeResult(
    uint32_t modelHash,
    bool& oversized)
{
    for (const BennysGarageDoorOversizeCacheEntry& entry
        : g_bennysGarageDoorOversizeCache)
    {
        if (entry.modelHash == modelHash)
        {
            oversized = entry.oversized;
            return true;
        }
    }

    return false;
}

static bool IsBennysGarageDoorOversizedVehicle(Vehicle vehicle)
{
    if (vehicle == 0
        || !ENTITY::DOES_ENTITY_EXIST(vehicle))
    {
        return false;
    }

    if (VEHICLE::IS_VEHICLE_ATTACHED_TO_TRAILER(vehicle))
        return true;

    const uint32_t modelHash =
        static_cast<uint32_t>(
            ENTITY::GET_ENTITY_MODEL(vehicle));

    if (modelHash == 0)
        return false;

    bool cachedOversized = false;
    if (TryGetCachedBennysGarageDoorOversizeResult(
            modelHash,
            cachedOversized))
    {
        return cachedOversized;
    }

    Vector3 minimum{};
    Vector3 maximum{};
    GAMEPLAY::GET_MODEL_DIMENSIONS(
        modelHash,
        &minimum,
        &maximum);

    const float widthRaw = maximum.x - minimum.x;
    const float lengthRaw = maximum.y - minimum.y;
    const float heightRaw = maximum.z - minimum.z;

    const float width = widthRaw >= 0.0f ? widthRaw : -widthRaw;
    const float length = lengthRaw >= 0.0f ? lengthRaw : -lengthRaw;
    const float height = heightRaw >= 0.0f ? heightRaw : -heightRaw;

    // Mirrors the current Helper.cs oversized-vehicle policy. Invalid model
    // dimensions are treated as non-oversized rather than blocking entry.
    if (!std::isfinite(width)
        || !std::isfinite(length)
        || !std::isfinite(height)
        || width <= 0.0f
        || length <= 0.0f
        || height <= 0.0f)
    {
        return false;
    }

    int exceededWorkshopDimensions = 0;
    if (width > kMaximumWorkshopVehicleWidth)
        ++exceededWorkshopDimensions;
    if (length > kMaximumWorkshopVehicleLength)
        ++exceededWorkshopDimensions;
    if (height > kMaximumWorkshopVehicleHeight)
        ++exceededWorkshopDimensions;

    const bool oversized =
        width > kAbsoluteMaximumWorkshopVehicleWidth
        || length > kAbsoluteMaximumWorkshopVehicleLength
        || height > kAbsoluteMaximumWorkshopVehicleHeight
        || exceededWorkshopDimensions >= 2;

    g_bennysGarageDoorOversizeCache.push_back(
        { modelHash, oversized });

    return oversized;
}

static bool IsCurrentBennysGarageDoorVehicleAllowed()
{
    const Ped playerPed = PLAYER::PLAYER_PED_ID();
    if (playerPed == 0
        || !PED::IS_PED_IN_ANY_VEHICLE(
            playerPed,
            false))
    {
        return false;
    }

    const Vehicle vehicle =
        PED::GET_VEHICLE_PED_IS_IN(
            playerPed,
            false);

    if (vehicle == 0
        || !ENTITY::DOES_ENTITY_EXIST(vehicle))
    {
        return false;
    }

    const int vehicleClass =
        VEHICLE::GET_VEHICLE_CLASS(vehicle);

    if (IsBennysGarageDoorAlwaysDeniedVehicleClass(
            vehicleClass))
    {
        return false;
    }

    // GTA vehicle classes: Utility=11, Service=17, Emergency=18.
    if (!g_bennysAllowEmergencyVehicles
        && vehicleClass == 18)
    {
        return false;
    }

    if (!g_bennysAllowServiceVehicles
        && vehicleClass == 17)
    {
        return false;
    }

    if (!g_bennysAllowUtilityVehicles
        && vehicleClass == 11)
    {
        return false;
    }

    // Keep the oversized policy independent of class policy: an allowed
    // Service/Utility vehicle is still denied when it is oversized and
    // AllowOversizedVehicles=false, matching Helper.cs.
    if (!g_bennysAllowOversizedVehicles
        && IsBennysGarageDoorOversizedVehicle(vehicle))
    {
        return false;
    }

    return true;
}

static bool GetBennysGarageDoorPlayerGeometry(
    float& distanceSquared,
    float& interiorDepth)
{
    distanceSquared = 0.0f;
    interiorDepth = 0.0f;

    const Ped playerPed = PLAYER::PLAYER_PED_ID();
    if (playerPed == 0)
        return false;

    const Vector3 playerPosition =
        ENTITY::GET_ENTITY_COORDS(
            playerPed,
            TRUE);

    const float dx =
        playerPosition.x - kBennysGarageDoorX;
    const float dy =
        playerPosition.y - kBennysGarageDoorY;
    const float dz =
        playerPosition.z - kBennysGarageDoorZ;

    distanceSquared =
        (dx * dx)
        + (dy * dy)
        + (dz * dz);

    interiorDepth =
        (dx * kBennysGarageDoorInteriorDirX)
        + (dy * kBennysGarageDoorInteriorDirY);

    return true;
}

static bool IsPlayerWithinBennysGarageDoorDistance(
    float distance)
{
    float distanceSquared = 0.0f;
    float interiorDepth = 0.0f;
    if (!GetBennysGarageDoorPlayerGeometry(
            distanceSquared,
            interiorDepth))
    {
        return false;
    }

    return distanceSquared <= (distance * distance);
}

static void ReleaseBennysGarageDoorRecovery()
{
    if (g_bennysGarageDoorSystemHash != 0)
    {
        if (g_bennysGarageDoorHoldOpen)
        {
            SetBennysGarageDoorHoldOpen(
                g_bennysGarageDoorSystemHash,
                false);
        }

        SetBennysGarageDoorState(
            g_bennysGarageDoorSystemHash,
            1);
    }

    SetBennysGarageDoorUnstreamedClosed();

    g_bennysGarageDoorSystemHash = 0;
    g_bennysGarageDoorAssistActive = false;
    g_bennysGarageDoorHoldOpen = false;
    g_bennysGarageDoorNextAttempt = 0;
}

static void MaintainBennysGarageDoorOpenRecovery(
    ULONGLONG now)
{
    if (!g_bennysGarageDoorAssistActive)
    {
        g_bennysGarageDoorAssistActive = true;
        g_bennysGarageDoorNextAttempt = 0;
    }

    if (now < g_bennysGarageDoorNextAttempt)
        return;

    g_bennysGarageDoorNextAttempt =
        now + kBennysGarageDoorRetryMs;

    SetBennysGarageDoorUnstreamedOpen();

    uint32_t doorHash = 0;
    if (!FindBennysGarageDoor(doorHash))
        return;

    g_bennysGarageDoorSystemHash = doorHash;

    if (!IsBennysGarageDoorPhysicsLoaded(doorHash))
        return;

    SetBennysGarageDoorState(
        doorHash,
        0);
    SetBennysGarageDoorOpenRatio(
        doorHash,
        1.0f);
    SetBennysGarageDoorHoldOpen(
        doorHash,
        true);
    g_bennysGarageDoorHoldOpen = true;
}

static void MaintainBennysGarageDoorClosedRecovery(
    ULONGLONG now)
{
    if (now < g_bennysGarageDoorNextAttempt)
        return;

    g_bennysGarageDoorNextAttempt =
        now + kBennysGarageDoorRetryMs;

    SetBennysGarageDoorUnstreamedClosed();

    uint32_t doorHash = g_bennysGarageDoorSystemHash;
    if (doorHash == 0
        && !FindBennysGarageDoor(doorHash))
    {
        return;
    }

    g_bennysGarageDoorSystemHash = doorHash;

    if (!IsBennysGarageDoorPhysicsLoaded(doorHash))
        return;

    if (g_bennysGarageDoorHoldOpen)
    {
        SetBennysGarageDoorHoldOpen(
            doorHash,
            false);
        g_bennysGarageDoorHoldOpen = false;
    }

    SetBennysGarageDoorOpenRatio(
        doorHash,
        0.0f);
    SetBennysGarageDoorState(
        doorHash,
        1);
}

static void MaintainBennysGarageDoorRecovery(
    ULONGLONG now)
{
    if (now < g_bennysGarageDoorNextUpdate)
        return;

    g_bennysGarageDoorNextUpdate =
        now + kBennysGarageDoorUpdateMs;

    if (!g_bennysGarageDoorRecoveryEnabled)
    {
        if (g_bennysGarageDoorAssistActive
            || g_bennysGarageDoorInsideLatched)
        {
            ReleaseBennysGarageDoorRecovery();
        }

        ReleaseBennysGarageDoorModel();
        g_bennysGarageDoorInsideLatched = false;
        g_bennysGarageDoorInsideExitOpening = false;
        g_bennysGarageDoorDepthSampleValid = false;
        return;
    }

    float distanceSquared = 0.0f;
    float interiorDepth = 0.0f;
    if (!GetBennysGarageDoorPlayerGeometry(
            distanceSquared,
            interiorDepth))
    {
        return;
    }

    const bool withinModelPreloadDistance =
        distanceSquared
        <= (kBennysGarageDoorModelPreloadDistance
            * kBennysGarageDoorModelPreloadDistance);

    if (withinModelPreloadDistance)
    {
        if (now >= g_bennysGarageDoorModelNextRequest)
        {
            if (!g_bennysGarageDoorModelRequested
                || !IsBennysGarageDoorModelLoaded())
            {
                RequestBennysGarageDoorModel();
            }

            g_bennysGarageDoorModelNextRequest =
                now + kBennysGarageDoorModelRetryMs;
        }
    }
    else if (distanceSquared
        > (kBennysGarageDoorModelReleaseDistance
            * kBennysGarageDoorModelReleaseDistance))
    {
        ReleaseBennysGarageDoorModel();
    }

    const bool movingTowardOutside =
        g_bennysGarageDoorDepthSampleValid
        && interiorDepth
            < (g_bennysGarageDoorLastInteriorDepth
                - kBennysGarageDoorDirectionEpsilon);

    const bool movingDeeperInside =
        g_bennysGarageDoorDepthSampleValid
        && interiorDepth
            > (g_bennysGarageDoorLastInteriorDepth
                + kBennysGarageDoorDirectionEpsilon);

    g_bennysGarageDoorLastInteriorDepth =
        interiorDepth;
    g_bennysGarageDoorDepthSampleValid = true;

    const bool withinDoorRetryDistance =
        distanceSquared
        <= (kBennysGarageDoorRetryDistance
            * kBennysGarageDoorRetryDistance);

    const bool withinOutsideAssistDistance =
        distanceSquared
        <= (kBennysGarageDoorAssistDistance
            * kBennysGarageDoorAssistDistance);

    const bool withinInsideExitAssistDistance =
        distanceSquared
        <= (kBennysGarageDoorInsideExitAssistDistance
            * kBennysGarageDoorInsideExitAssistDistance);

    const bool currentVehicleAllowed =
        withinDoorRetryDistance
        && IsCurrentBennysGarageDoorVehicleAllowed();

    if (!g_bennysGarageDoorInsideLatched
        && interiorDepth >= kBennysGarageDoorInsideCloseDepth)
    {
        g_bennysGarageDoorInsideLatched = true;
        g_bennysGarageDoorInsideExitOpening = false;

        g_bennysGarageDoorNextAttempt = 0;
        if (g_bennysGarageDoorAssistActive)
            ReleaseBennysGarageDoorRecovery();

        MaintainBennysGarageDoorClosedRecovery(now);
        return;
    }

    if (g_bennysGarageDoorInsideLatched)
    {
        if (!withinDoorRetryDistance)
            return;

        if (interiorDepth <= kBennysGarageDoorOutsideResetDepth)
        {
            g_bennysGarageDoorInsideLatched = false;
            g_bennysGarageDoorInsideExitOpening = false;
            g_bennysGarageDoorNextAttempt = 0;
        }
        else
        {
            if (!currentVehicleAllowed)
            {
                g_bennysGarageDoorInsideExitOpening = false;
                MaintainBennysGarageDoorClosedRecovery(now);
                return;
            }

            if (!g_bennysGarageDoorInsideExitOpening
                && movingTowardOutside
                && withinInsideExitAssistDistance)
            {
                g_bennysGarageDoorInsideExitOpening = true;
                g_bennysGarageDoorNextAttempt = 0;
            }

            if (g_bennysGarageDoorInsideExitOpening
                && movingDeeperInside
                && interiorDepth
                    >= kBennysGarageDoorInsideCloseDepth)
            {
                g_bennysGarageDoorInsideExitOpening = false;
                g_bennysGarageDoorNextAttempt = 0;
            }

            if (g_bennysGarageDoorInsideExitOpening)
                MaintainBennysGarageDoorOpenRecovery(now);
            else
                MaintainBennysGarageDoorClosedRecovery(now);

            return;
        }
    }

    if (withinOutsideAssistDistance
        && currentVehicleAllowed)
    {
        MaintainBennysGarageDoorOpenRecovery(now);
    }
    else if (g_bennysGarageDoorAssistActive)
    {
        ReleaseBennysGarageDoorRecovery();
    }
}

static void ActivateBennysInterior(const BennysMapState& state)
{
    if (!state.validInterior || state.selectedInteriorId == 0)
        return;

    INTERIOR::DISABLE_INTERIOR(state.selectedInteriorId, false);
    STREAMING::SET_INTERIOR_ACTIVE(state.selectedInteriorId, true);
    INTERIOR::REFRESH_INTERIOR(state.selectedInteriorId);
}

static void LogBennysMapState(const char* prefix, const BennysMapState& state)
{
    Logf(
        "%s referenceInteriorId=%d workshopInteriorId=%d selectedInteriorId=%d valid=%s ready=%s primaryIplActive=%s",
        prefix ? prefix : "[State]",
        state.referenceInteriorId,
        state.workshopInteriorId,
        state.selectedInteriorId,
        state.validInterior ? "yes" : "no",
        state.readyInterior ? "yes" : "no",
        state.primaryIplActive ? "yes" : "no");

    if (g_logEnabled)
    {
        for (size_t i = 0; i < sizeof(kBennysLowriderIpls) / sizeof(kBennysLowriderIpls[0]); ++i)
        {
            const bool active = STREAMING::IS_IPL_ACTIVE((char*)kBennysLowriderIpls[i]);
            Logf("[State] IPL %-48s active=%s", kBennysLowriderIpls[i], active ? "yes" : "no");
        }
    }
}

static const char* GetV79LateReplayFailureReason()
{
    switch (g_v79LateReplayFailureCode)
    {
    case 0:  return "none";
    case 1:  return "C26F00-original-trampoline-unavailable";
    case 2:  return "Benny-already-available-before-late-replay";
    case 3:  return "exe-or-mapState-unavailable";
    case 4:  return "mplowrider-child-not-unique";
    case 5:  return "descriptor-view-invalid";
    case 6:  return "GROUP_MAP_SP-Benny-already-present";
    case 7:  return "descriptor-write-fault-or-verify-failed";
    case 8:  return "C26F00-call-faulted";
    case 9:  return "descriptor-restore-failed";
    case 10: return "downstream-Benny-not-produced";
    case 11: return "Benny-unavailable-after-replay";
    case 12: return "seh-exception";
    default: return "unknown";
    }
}

static void LogV79LateReplayState(const char* phase)
{
    if (!IsEnhancedExecutableImage())
        return;

    Logf(
        "[EnhancedLateReplayV79] %s enabled=%s naturalSuppressed=%ld state=%ld failure=%lu(%s) mapState=%p child=%p descriptor{table=%p count=%u->%u writeComplete=%s restored=%s} call{completed=%s faulted=%s result=%p} downstream{C272=%ld->%ld mapBenny=%ld->%ld} finalPairs{GROUP_MAP+Benny=%u GROUP_MAP_SP+Benny=%u} available=%s->%s.",
        phase ? phase : "state",
        g_v79EnhancedLateReplayExperiment ? "yes" : "no",
        static_cast<long>(g_v79NaturalInjectionSuppressedHits),
        static_cast<long>(InterlockedCompareExchange(&g_v79LateReplayState, 0, 0)),
        static_cast<unsigned long>(g_v79LateReplayFailureCode),
        GetV79LateReplayFailureReason(),
        reinterpret_cast<void*>(g_v79LateReplayMapState),
        reinterpret_cast<void*>(g_v79LateReplayChild),
        reinterpret_cast<void*>(g_v79LateReplayOriginalDescriptorTable),
        static_cast<unsigned int>(g_v79LateReplayOriginalDescriptorCount),
        static_cast<unsigned int>(g_v79LateReplayTemporaryDescriptorCount),
        g_v79LateReplayDescriptorWriteComplete ? "yes" : "no",
        g_v79LateReplayDescriptorRestored ? "yes" : "no",
        g_v79LateReplayCallCompleted ? "yes" : "no",
        g_v79LateReplayCallFaulted ? "yes" : "no",
        reinterpret_cast<void*>(g_v79LateReplayResult),
        static_cast<long>(g_v79LateReplayC272Before),
        static_cast<long>(g_v79LateReplayC272After),
        static_cast<long>(g_v79LateReplayMapBennyBefore),
        static_cast<long>(g_v79LateReplayMapBennyAfter),
        g_v79LateReplayFinalMapBennyPairs,
        g_v79LateReplayFinalStoryBennyPairs,
        g_v79LateReplayAvailableBefore ? "yes" : "no",
        g_v79LateReplayAvailableAfter ? "yes" : "no");
}

static bool RunV79EnhancedLateC26F00Replay()
{

#pragma warning(suppress: 6236)
    if (!IsEnhancedExecutableImage()
        || !g_v79EnhancedLateReplayExperiment)
    {
        return false;
    }

    const LONG priorState =
        InterlockedCompareExchange(
            &g_v79LateReplayState,
            1,
            0);
    if (priorState != 0)
        return priorState == 2;

    constexpr uint32_t mplowrider = 0x61322A35U;
    constexpr uint32_t storyGroup = 0x578F99E2U;
    constexpr uint32_t mapGroup = 0xBCC89179U;
    constexpr uint32_t benny = 0x4CDFC843U;
    constexpr uint16_t maxDescriptors = 64;
    constexpr uint16_t maxAssociated = 256;
    constexpr size_t descriptorStride = 0x18;
    constexpr uintptr_t childStride = 0x120;

    bool descriptorSwapClaimed = false;
    uintptr_t originalDescriptorTable = 0;
    uint16_t originalDescriptorCount = 0;
    uintptr_t child = 0;
    uintptr_t mapState = 0;

    BennysMapState beforeState = CaptureBennysMapState();
    g_v79LateReplayAvailableBefore =
        IsBennysMapAvailable(beforeState);

    LogBennysMapState(
        "[EnhancedLateReplayV79] pre-replay stock-state",
        beforeState);

    if (!g_v52OriginalC26F00
        || !g_v52C26F00HookInstalled)
    {
        g_v79LateReplayFailureCode = 1;
        InterlockedExchange(&g_v79LateReplayState, 3);
        LogV79LateReplayState("C26F00 gate failed");
        return false;
    }

    if (g_v79LateReplayAvailableBefore)
    {
        g_v79LateReplayFailureCode = 2;
        InterlockedExchange(&g_v79LateReplayState, 3);
        LogV79LateReplayState("precondition failed");
        return false;
    }

    HMODULE exe = GetModuleHandleA(nullptr);
    if (!exe)
    {
        g_v79LateReplayFailureCode = 3;
        InterlockedExchange(&g_v79LateReplayState, 3);
        LogV79LateReplayState("exe unavailable");
        return false;
    }

    uint8_t* base = reinterpret_cast<uint8_t*>(exe);

    __try
    {
        memcpy(
            &mapState,
            base + 0x029CAFC8ULL,
            sizeof(mapState));
        if (!mapState)
        {
            g_v79LateReplayFailureCode = 3;
        }
        else
        {
            uintptr_t childArray = 0;
            uint16_t childCount = 0;
            memcpy(
                &childArray,
                reinterpret_cast<const void*>(mapState + 0x28),
                sizeof(childArray));
            memcpy(
                &childCount,
                reinterpret_cast<const void*>(mapState + 0x30),
                sizeof(childCount));

            uint32_t lowriderMatches = 0;
            if (childArray && childCount > 0 && childCount <= 4096)
            {
                for (uint16_t i = 0; i < childCount; ++i)
                {
                    const uintptr_t candidate =
                        childArray
                        + (static_cast<uintptr_t>(i) * childStride);
                    uint32_t field80 = 0;
                    memcpy(
                        &field80,
                        reinterpret_cast<const void*>(candidate + 0x80),
                        sizeof(field80));
                    if (field80 == mplowrider)
                    {
                        ++lowriderMatches;
                        child = candidate;
                    }
                }
            }

            if (lowriderMatches != 1 || !child)
            {
                g_v79LateReplayFailureCode = 4;
            }
            else
            {
                memcpy(
                    &originalDescriptorTable,
                    reinterpret_cast<const void*>(child + 0x98),
                    sizeof(originalDescriptorTable));
                memcpy(
                    &originalDescriptorCount,
                    reinterpret_cast<const void*>(child + 0xA0),
                    sizeof(originalDescriptorCount));

                g_v79LateReplayMapState = mapState;
                g_v79LateReplayChild = child;
                g_v79LateReplayOriginalDescriptorTable =
                    originalDescriptorTable;
                g_v79LateReplayOriginalDescriptorCount =
                    originalDescriptorCount;

                if (originalDescriptorCount >= maxDescriptors
                    || (originalDescriptorCount != 0
                        && originalDescriptorTable == 0))
                {
                    g_v79LateReplayFailureCode = 5;
                }
                else
                {
                    bool alreadyPresent = false;

                    if (originalDescriptorCount != 0)
                    {
                        memcpy(
                            g_v79DescriptorScratch,
                            reinterpret_cast<const void*>(
                                originalDescriptorTable),
                            static_cast<size_t>(originalDescriptorCount)
                                * descriptorStride);

                        for (uint16_t i = 0;
                             i < originalDescriptorCount && !alreadyPresent;
                             ++i)
                        {
                            const uint8_t* descriptor =
                                g_v79DescriptorScratch
                                + (static_cast<size_t>(i)
                                    * descriptorStride);
                            uint32_t group = 0;
                            uintptr_t associatedTable = 0;
                            uint16_t associatedCount = 0;
                            memcpy(&group, descriptor + 0x00, sizeof(group));
                            memcpy(
                                &associatedTable,
                                descriptor + 0x08,
                                sizeof(associatedTable));
                            memcpy(
                                &associatedCount,
                                descriptor + 0x10,
                                sizeof(associatedCount));

                            if (group != storyGroup
                                || !associatedTable
                                || associatedCount == 0
                                || associatedCount > maxAssociated)
                            {
                                continue;
                            }

                            for (uint16_t j = 0;
                                 j < associatedCount;
                                 ++j)
                            {
                                uint32_t associated = 0;
                                memcpy(
                                    &associated,
                                    reinterpret_cast<const void*>(
                                        associatedTable
                                        + (static_cast<uintptr_t>(j)
                                            * sizeof(uint32_t))),
                                    sizeof(associated));
                                if (associated == benny)
                                {
                                    alreadyPresent = true;
                                    break;
                                }
                            }
                        }
                    }

                    if (alreadyPresent)
                    {
                        g_v79LateReplayFailureCode = 6;
                    }
                    else
                    {
                        uint8_t* syntheticDescriptor =
                            g_v79DescriptorScratch
                            + (static_cast<size_t>(originalDescriptorCount)
                                * descriptorStride);
                        memset(
                            syntheticDescriptor,
                            0,
                            descriptorStride);
                        memcpy(
                            syntheticDescriptor + 0x00,
                            &storyGroup,
                            sizeof(storyGroup));

                        const uintptr_t associatedPointer =
                            reinterpret_cast<uintptr_t>(
                                g_v79SyntheticAssociated);
                        memcpy(
                            syntheticDescriptor + 0x08,
                            &associatedPointer,
                            sizeof(associatedPointer));
                        const uint16_t one = 1;
                        memcpy(
                            syntheticDescriptor + 0x10,
                            &one,
                            sizeof(one));

                        const uintptr_t temporaryTable =
                            reinterpret_cast<uintptr_t>(
                                g_v79DescriptorScratch);
                        const uint16_t temporaryCount =
                            static_cast<uint16_t>(
                                originalDescriptorCount + 1);
                        g_v79LateReplayTemporaryDescriptorCount =
                            temporaryCount;

                        descriptorSwapClaimed = true;
                        memcpy(
                            reinterpret_cast<void*>(child + 0x98),
                            &temporaryTable,
                            sizeof(temporaryTable));
                        memcpy(
                            reinterpret_cast<void*>(child + 0xA0),
                            &temporaryCount,
                            sizeof(temporaryCount));

                        uintptr_t verifyTable = 0;
                        uint16_t verifyCount = 0;
                        memcpy(
                            &verifyTable,
                            reinterpret_cast<const void*>(child + 0x98),
                            sizeof(verifyTable));
                        memcpy(
                            &verifyCount,
                            reinterpret_cast<const void*>(child + 0xA0),
                            sizeof(verifyCount));

                        g_v79LateReplayDescriptorWriteComplete =
                            verifyTable == temporaryTable
                            && verifyCount == temporaryCount;

                        if (!g_v79LateReplayDescriptorWriteComplete)
                        {
                            g_v79LateReplayFailureCode = 7;
                        }
                        else
                        {
                            g_v79LateReplayC272Before =
                                InterlockedCompareExchange(
                                    &g_v51C272A0LowriderCalls,
                                    0,
                                    0);
                            g_v79LateReplayMapBennyBefore =
                                InterlockedCompareExchange(
                                    &g_midFilterExactMapBennyHits,
                                    0,
                                    0);

                            uint32_t replayGroup = storyGroup;
                            g_v79LateReplayResult =
                                g_v52OriginalC26F00(
                                    reinterpret_cast<void*>(mapState),
                                    reinterpret_cast<void*>(child),
                                    &replayGroup);
                            g_v79LateReplayCallCompleted = true;
                        }
                    }
                }
            }
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        g_v79LateReplayCallFaulted =
            g_v79LateReplayDescriptorWriteComplete;
        if (g_v79LateReplayCallFaulted)
            g_v79LateReplayFailureCode = 8;
        else if (g_v79LateReplayFailureCode == 0)
            g_v79LateReplayFailureCode = 12;
    }

    if (descriptorSwapClaimed && child)
    {
        bool restored = false;
        for (int restoreTry = 0; restoreTry < 2 && !restored; ++restoreTry)
        {
            __try
            {
                memcpy(
                    reinterpret_cast<void*>(child + 0x98),
                    &originalDescriptorTable,
                    sizeof(originalDescriptorTable));
                memcpy(
                    reinterpret_cast<void*>(child + 0xA0),
                    &originalDescriptorCount,
                    sizeof(originalDescriptorCount));

                uintptr_t verifyTable = 0;
                uint16_t verifyCount = 0;
                memcpy(
                    &verifyTable,
                    reinterpret_cast<const void*>(child + 0x98),
                    sizeof(verifyTable));
                memcpy(
                    &verifyCount,
                    reinterpret_cast<const void*>(child + 0xA0),
                    sizeof(verifyCount));
                restored =
                    verifyTable == originalDescriptorTable
                    && verifyCount == originalDescriptorCount;
            }
            __except(EXCEPTION_EXECUTE_HANDLER)
            {
                restored = false;
            }
        }
        g_v79LateReplayDescriptorRestored = restored;
        if (!restored)
            g_v79LateReplayFailureCode = 9;
    }

    g_v79LateReplayC272After =
        InterlockedCompareExchange(
            &g_v51C272A0LowriderCalls,
            0,
            0);
    g_v79LateReplayMapBennyAfter =
        InterlockedCompareExchange(
            &g_midFilterExactMapBennyHits,
            0,
            0);

    if (child)
    {
        __try
        {
            uintptr_t pairTable = 0;
            uint16_t pairCount = 0;
            memcpy(
                &pairTable,
                reinterpret_cast<const void*>(child + 0x108),
                sizeof(pairTable));
            memcpy(
                &pairCount,
                reinterpret_cast<const void*>(child + 0x110),
                sizeof(pairCount));

            if (pairTable && pairCount <= 4096)
            {
                for (uint16_t i = 0; i < pairCount; ++i)
                {
                    uint32_t pair[2]{};
                    memcpy(
                        pair,
                        reinterpret_cast<const void*>(
                            pairTable
                            + (static_cast<uintptr_t>(i) * 8)),
                        sizeof(pair));
                    if (pair[0] == mapGroup && pair[1] == benny)
                        ++g_v79LateReplayFinalMapBennyPairs;
                    if (pair[0] == storyGroup && pair[1] == benny)
                        ++g_v79LateReplayFinalStoryBennyPairs;
                }
            }
        }
        __except(EXCEPTION_EXECUTE_HANDLER)
        {

        }
    }

    if (g_v79LateReplayCallCompleted
        && g_v79LateReplayDescriptorRestored)
    {
        WAIT(0);
    }

    BennysMapState afterState = CaptureBennysMapState();
    g_v79LateReplayAvailableAfter =
        IsBennysMapAvailable(afterState);
    LogBennysMapState(
        "[EnhancedLateReplayV79] post-replay state",
        afterState);

    if (g_v79LateReplayFailureCode == 0
        && (!g_v79LateReplayCallCompleted
            || g_v79LateReplayMapBennyAfter
                <= g_v79LateReplayMapBennyBefore
            || g_v79LateReplayFinalMapBennyPairs == 0))
    {
        g_v79LateReplayFailureCode = 10;
    }

    if (g_v79LateReplayFailureCode == 0
        && !g_v79LateReplayAvailableAfter)
    {
        g_v79LateReplayFailureCode = 11;
    }

    const bool success =
        g_v79LateReplayFailureCode == 0
        && g_v79LateReplayDescriptorWriteComplete
        && g_v79LateReplayDescriptorRestored
        && g_v79LateReplayCallCompleted
        && !g_v79LateReplayCallFaulted
        && g_v79LateReplayMapBennyAfter
            > g_v79LateReplayMapBennyBefore
        && g_v79LateReplayFinalMapBennyPairs == 1
        && g_v79LateReplayFinalStoryBennyPairs == 0
        && g_v79LateReplayAvailableAfter;

    if (success)
    {
        ActivateBennysInterior(afterState);
        InterlockedExchange(&g_v79LateReplayState, 2);
    }
    else
    {
        InterlockedExchange(&g_v79LateReplayState, 3);
    }

    LogV79LateReplayState(
        success
            ? "SUCCESS late C26F00 replay"
            : "FAILED late C26F00 replay");
    return success;
}

static void ExecuteBennysContentChangesetRaw()
{
    const uint32_t dlcHash = Joaat(kDlcName);
    const uint32_t groupHash = Joaat(kMapGroup);
    const uint32_t changeSetHash = Joaat(kBennysChangeSet);

    nativeInit(kExecuteContentChangesetNative);
    nativePush64(static_cast<uint64_t>(dlcHash));
    nativePush64(static_cast<uint64_t>(groupHash));
    nativePush64(static_cast<uint64_t>(changeSetHash));
    nativeCall();
}

static bool TryLoadBennysMapOlderLegacyIplFallback(bool manualRetry)
{
    if (!IsOlderLegacyLowridersBuild())
        return false;

    BennysMapState state = CaptureBennysMapState();
    if (IsBennysMapReadyForOlderLegacy(state))
    {
        ActivateBennysInterior(state);
        LogBennysMapState(
            "[OldLegacyFallback] Benny's was already fully streamed/ready.",
            state);
        return true;
    }

    Logf(
        "[OldLegacyFallback] %srequest for GTA Legacy gameVersion=%d. The frozen build-102 memory path is bypassed; requesting only Benny's Lowriders IPL set once.",
        manualRetry ? "Manual " : "Initial ",
        getGameVersion());

    for (size_t i = 0;
         i < sizeof(kBennysLowriderIpls) / sizeof(kBennysLowriderIpls[0]);
         ++i)
    {
        STREAMING::REQUEST_IPL((char*)kBennysLowriderIpls[i]);
    }

    const ULONGLONG deadline = GetTickCount64() + 5000ULL;
    while (GetTickCount64() < deadline)
    {
        WAIT(100);
        state = CaptureBennysMapState();

        if (!IsBennysMapReadyForOlderLegacy(state))
            continue;

        ActivateBennysInterior(state);
        WAIT(0);
        state = CaptureBennysMapState();
        LogBennysMapState(
            "[OldLegacyFallback] SUCCESS: targeted Benny's IPL set is streamed and the workshop interior was activated.",
            state);
        return true;
    }

    state = CaptureBennysMapState();
    LogBennysMapState(
        "[OldLegacyFallback] Targeted IPLs were requested once, but Benny's is not fully ready yet; passive probing will continue without re-requesting every frame.",
        state);
    return false;
}

static bool TryMutateBennyStoryGroupEntryViaRockstar1012(bool add)
{
    if (!IsEnhancedVersion()
        || getGameVersion() != 1012)
    {
        Logf(
            "[InternalAdd] Rockstar group-pair mutator experiment is restricted to verified Enhanced build 1012.");
        return false;
    }

    uint8_t* base = nullptr;
    uint8_t* end = nullptr;
    if (!GetExeRange(base, end)
        || !base
        || !end
        || end <= base)
    {
        Logf(
            "[InternalAdd] Unable to resolve GTA executable range.");
        return false;
    }

    const uint64_t imageSize =
        static_cast<uint64_t>(
            end - base);

    const uint64_t mutatorRva =
        0x00C2F090ULL;
    const uint64_t verifiedCallRva =
        0x00C27E6FULL;
    const uint64_t mapStateGlobalRva =
        0x029CAFC8ULL;

    if (mutatorRva + 32 > imageSize
        || verifiedCallRva + 5 > imageSize
        || mapStateGlobalRva + sizeof(uintptr_t) > imageSize)
    {
        Logf(
            "[InternalAdd] Verified build-1012 RVAs are outside the current executable image; aborting.");
        return false;
    }

    static const uint8_t expectedMutatorPrefix[] =
    {
        0x41, 0x57, 0x41, 0x56, 0x41, 0x55, 0x41, 0x54,
        0x56, 0x57, 0x55, 0x53, 0x48, 0x83, 0xEC, 0x28,
        0x49, 0x89, 0xCE, 0x0F, 0xB7, 0xA9, 0x10, 0x01,
        0x00, 0x00
    };

    uint8_t* mutatorAddress =
        base + static_cast<size_t>(
            mutatorRva);

    if (memcmp(
            mutatorAddress,
            expectedMutatorPrefix,
            sizeof(expectedMutatorPrefix)) != 0)
    {
        Logf(
            "[InternalAdd] C2F090 signature mismatch. No internal call will be attempted.");
        LogBytes(
            mutatorAddress,
            sizeof(expectedMutatorPrefix),
            "C2F090 actual prefix");
        return false;
    }

    uint8_t* verifiedCall =
        base + static_cast<size_t>(
            verifiedCallRva);

    if (verifiedCall[0] != 0xE8)
    {
        Logf(
            "[InternalAdd] Verified C27E6F callsite no longer begins with E8; aborting.");
        return false;
    }

    int32_t callRelative = 0;
    memcpy(
        &callRelative,
        verifiedCall + 1,
        sizeof(callRelative));

    uint8_t* resolvedCallTarget =
        verifiedCall + 5 + callRelative;

    if (resolvedCallTarget != mutatorAddress)
    {
        Logf(
            "[InternalAdd] Verified C27E6F callsite resolves to RVA=0x%llX instead of C2F090; aborting.",
            static_cast<unsigned long long>(
                resolvedCallTarget >= base
                    ? resolvedCallTarget - base
                    : 0));
        return false;
    }

    static const uint8_t expectedPointerStore[] =
    {
        0x49, 0x89, 0xBE, 0x08, 0x01, 0x00, 0x00
    };
    static const uint8_t expectedCountStore[] =
    {
        0x66, 0x41, 0x89, 0x86, 0x10, 0x01, 0x00, 0x00
    };

    if (memcmp(
            base + 0x00C2F2C7ULL,
            expectedPointerStore,
            sizeof(expectedPointerStore)) != 0
        || memcmp(
            base + 0x00C2F2D9ULL,
            expectedCountStore,
            sizeof(expectedCountStore)) != 0)
    {
        Logf(
            "[InternalAdd] C2F090 pointer/count store signature mismatch; aborting internal call.");
        return false;
    }

    uintptr_t mapState = 0;
    memcpy(
        &mapState,
        base + mapStateGlobalRva,
        sizeof(mapState));

    if (!IsReadablePointerValue(mapState))
    {
        Logf(
            "[InternalAdd] mapState global 0x29CAFC8 is not readable yet.");
        return false;
    }

    uintptr_t childArray = 0;
    uint16_t childCount = 0;

    if (!ReadProcessExact(
            mapState + 0x28,
            &childArray,
            sizeof(childArray))
        || !ReadProcessExact(
            mapState + 0x30,
            &childCount,
            sizeof(childCount))
        || !IsReadablePointerValue(childArray)
        || childCount <= 64
        || childCount > 4096)
    {
        Logf(
            "[InternalAdd] Invalid mapState child array/count mapState=%p childArray=%p childCount=%u.",
            reinterpret_cast<void*>(mapState),
            reinterpret_cast<void*>(childArray),
            static_cast<unsigned int>(childCount));
        return false;
    }

    const uintptr_t child64 =
        childArray
        + (static_cast<uintptr_t>(64) * 0x120);

    uintptr_t tableBefore = 0;
    uint16_t countBefore = 0;
    uint16_t capacityBefore = 0;

    if (!ReadProcessExact(
            child64 + 0x108,
            &tableBefore,
            sizeof(tableBefore))
        || !ReadProcessExact(
            child64 + 0x110,
            &countBefore,
            sizeof(countBefore))
        || !ReadProcessExact(
            child64 + 0x112,
            &capacityBefore,
            sizeof(capacityBefore)))
    {
        Logf(
            "[InternalAdd] Could not read child64 +0x108/+0x110/+0x112.");
        return false;
    }

    const uint32_t storyHash =
        Joaat(kStoryMapGroup);
    const uint32_t bennyHash =
        Joaat(kBennysChangeSet);

    bool exactPairBefore = false;

    if (countBefore != 0)
    {
        if (!IsReadablePointerValue(tableBefore)
            || countBefore > 4096)
        {
            Logf(
                "[InternalAdd] child64 table is invalid before mutation table=%p count=%u capacity=%u.",
                reinterpret_cast<void*>(tableBefore),
                static_cast<unsigned int>(countBefore),
                static_cast<unsigned int>(capacityBefore));
            return false;
        }

        for (uint16_t i = 0;
             i < countBefore;
             ++i)
        {
            uint32_t first = 0;
            uint32_t second = 0;

            if (!ReadProcessExact(
                    tableBefore
                        + (static_cast<uintptr_t>(i) * 8),
                    &first,
                    sizeof(first))
                || !ReadProcessExact(
                    tableBefore
                        + (static_cast<uintptr_t>(i) * 8)
                        + 4,
                    &second,
                    sizeof(second)))
            {
                Logf(
                    "[InternalAdd] Failed reading child64 entry %u before mutation.",
                    static_cast<unsigned int>(i));
                return false;
            }

            if (first == storyHash
                && second == bennyHash)
            {
                exactPairBefore = true;
                break;
            }
        }
    }

    if (add
        && exactPairBefore)
    {
        Logf(
            "[InternalAdd] Exact GROUP_MAP_SP -> Benny pair is already present in child64; no call required.");
        return true;
    }

    if (!add
        && !exactPairBefore)
    {
        Logf(
            "[InternalAdd] Exact GROUP_MAP_SP -> Benny pair is already absent from child64; no remove call required.");
        g_experimentalInternalGroupAddApplied = false;
        return true;
    }

    if (add)
    {
        if (countBefore != 2
            || (capacityBefore != 2
                && capacityBefore != 3))
        {
            Logf(
                "[InternalAdd] Refusing add because child64 baseline is not a verified two-entry state (expected count=2 and capacity=2 or 3; count=%u capacity=%u).",
                static_cast<unsigned int>(countBefore),
                static_cast<unsigned int>(capacityBefore));
            return false;
        }

        uint32_t entry0First = 0;
        uint32_t entry0Second = 0;
        uint32_t entry1First = 0;
        uint32_t entry1Second = 0;

        if (!ReadProcessExact(
                tableBefore,
                &entry0First,
                sizeof(entry0First))
            || !ReadProcessExact(
                tableBefore + 4,
                &entry0Second,
                sizeof(entry0Second))
            || !ReadProcessExact(
                tableBefore + 8,
                &entry1First,
                sizeof(entry1First))
            || !ReadProcessExact(
                tableBefore + 12,
                &entry1Second,
                sizeof(entry1Second)))
        {
            Logf(
                "[InternalAdd] Could not validate the two-entry child64 baseline.");
            return false;
        }

        if (entry0First != 0x5BF6578F
            || entry0Second != 0xA0DF2C6F
            || entry1First != 0x5BF6578F
            || entry1Second != 0x37B569AA)
        {
            Logf(
                "[InternalAdd] Refusing add because child64 baseline entries do not match the proven normal A/B fingerprint: [%08X,%08X] [%08X,%08X].",
                entry0First,
                entry0Second,
                entry1First,
                entry1Second);
            return false;
        }
    }

    Logf(
        "[InternalAdd] %s via verified Rockstar C2F090 helper child64=%p tableBefore=%p countBefore=%u capacityBefore=%u pair=[0x%08X,0x%08X].",
        add ? "ADDING" : "REMOVING",
        reinterpret_cast<void*>(child64),
        reinterpret_cast<void*>(tableBefore),
        static_cast<unsigned int>(countBefore),
        static_cast<unsigned int>(capacityBefore),
        storyHash,
        bennyHash);

    using RockstarGroupPairMutator1012 =
        void(*)(
            void* child,
            uint32_t* first,
            uint32_t* second,
            bool addPair);

    RockstarGroupPairMutator1012 mutator =
        reinterpret_cast<RockstarGroupPairMutator1012>(
            mutatorAddress);

    uint32_t firstArgument =
        storyHash;
    uint32_t secondArgument =
        bennyHash;

    __try
    {
        mutator(
            reinterpret_cast<void*>(child64),
            &firstArgument,
            &secondArgument,
            add);
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        Logf(
            "[InternalAdd] C2F090 raised SEH exception code=0x%08lX. Mutation result is unknown; aborting further experimental work.",
            static_cast<unsigned long>(
                GetExceptionCode()));
        return false;
    }

    uintptr_t tableAfter = 0;
    uint16_t countAfter = 0;
    uint16_t capacityAfter = 0;

    if (!ReadProcessExact(
            child64 + 0x108,
            &tableAfter,
            sizeof(tableAfter))
        || !ReadProcessExact(
            child64 + 0x110,
            &countAfter,
            sizeof(countAfter))
        || !ReadProcessExact(
            child64 + 0x112,
            &capacityAfter,
            sizeof(capacityAfter)))
    {
        Logf(
            "[InternalAdd] C2F090 returned, but child64 post-state could not be read.");
        return false;
    }

    bool exactPairAfter = false;

    if (countAfter != 0
        && IsReadablePointerValue(tableAfter)
        && countAfter <= 4096)
    {
        for (uint16_t i = 0;
             i < countAfter;
             ++i)
        {
            uint32_t first = 0;
            uint32_t second = 0;

            if (!ReadProcessExact(
                    tableAfter
                        + (static_cast<uintptr_t>(i) * 8),
                    &first,
                    sizeof(first))
                || !ReadProcessExact(
                    tableAfter
                        + (static_cast<uintptr_t>(i) * 8)
                        + 4,
                    &second,
                    sizeof(second)))
                break;

            Logf(
                "[InternalAdd] child64 post entry[%u]=[0x%08X,0x%08X]%s",
                static_cast<unsigned int>(i),
                first,
                second,
                first == storyHash
                    && second == bennyHash
                        ? "  <== TARGET"
                        : "");

            if (first == storyHash
                && second == bennyHash)
                exactPairAfter = true;
        }
    }

    const bool mutationVerified =
        add
            ? exactPairAfter
            : !exactPairAfter;

    Logf(
        "[InternalAdd] C2F090 returned tableAfter=%p countAfter=%u capacityAfter=%u exactPairAfter=%s mutationVerified=%s.",
        reinterpret_cast<void*>(tableAfter),
        static_cast<unsigned int>(countAfter),
        static_cast<unsigned int>(capacityAfter),
        exactPairAfter ? "yes" : "no",
        mutationVerified ? "yes" : "no");

    if (mutationVerified)
        g_experimentalInternalGroupAddApplied = add;

    return mutationVerified;
}

static bool TryReprocessEnhancedMapStateViaRockstar1012()
{
    if (!IsEnhancedVersion()
        || getGameVersion() != 1012)
    {
        Logf(
            "[Reprocess] C2B600 experiment is restricted to verified Enhanced build 1012.");
        return false;
    }

    uint8_t* base = nullptr;
    uint8_t* end = nullptr;
    if (!GetExeRange(base, end)
        || !base
        || !end
        || end <= base)
    {
        Logf(
            "[Reprocess] Unable to resolve GTA executable range.");
        return false;
    }

    const uint64_t imageSize =
        static_cast<uint64_t>(
            end - base);

    const uint64_t processorRva =
        0x00C2B600ULL;
    const uint64_t verifiedLoadRva =
        0x007C760FULL;
    const uint64_t verifiedCallRva =
        0x007C7616ULL;
    const uint64_t mapStateGlobalRva =
        0x029CAFC8ULL;

    if (processorRva + 32 > imageSize
        || verifiedLoadRva + 7 > imageSize
        || verifiedCallRva + 5 > imageSize
        || mapStateGlobalRva + sizeof(uintptr_t) > imageSize)
    {
        Logf(
            "[Reprocess] Verified build-1012 RVAs are outside the current executable image; aborting.");
        return false;
    }

    static const uint8_t expectedProcessorPrefix[] =
    {
        0x41, 0x57, 0x41, 0x56, 0x41, 0x55, 0x41, 0x54,
        0x56, 0x57, 0x55, 0x53, 0x48, 0x83, 0xEC, 0x48,
        0x48, 0x89, 0xCF, 0x48, 0x8D, 0x99, 0x88, 0x01,
        0x00, 0x00
    };

    uint8_t* processorAddress =
        base + static_cast<size_t>(
            processorRva);

    if (memcmp(
            processorAddress,
            expectedProcessorPrefix,
            sizeof(expectedProcessorPrefix)) != 0)
    {
        Logf(
            "[Reprocess] C2B600 signature mismatch; no internal call will be attempted.");
        LogBytes(
            processorAddress,
            sizeof(expectedProcessorPrefix),
            "C2B600 actual prefix");
        return false;
    }

    uint8_t* loadInstruction =
        base + static_cast<size_t>(
            verifiedLoadRva);

    if (loadInstruction[0] != 0x48
        || loadInstruction[1] != 0x8B
        || loadInstruction[2] != 0x0D)
    {
        Logf(
            "[Reprocess] Verified 7C760F mapState load signature mismatch; aborting.");
        return false;
    }

    int32_t loadDisplacement = 0;
    memcpy(
        &loadDisplacement,
        loadInstruction + 3,
        sizeof(loadDisplacement));

    uint8_t* resolvedLoadTarget =
        loadInstruction + 7 + loadDisplacement;

    if (resolvedLoadTarget
        != base + static_cast<size_t>(mapStateGlobalRva))
    {
        Logf(
            "[Reprocess] 7C760F resolves to RVA=0x%llX instead of mapState global 0x29CAFC8; aborting.",
            static_cast<unsigned long long>(
                resolvedLoadTarget >= base
                    ? resolvedLoadTarget - base
                    : 0));
        return false;
    }

    uint8_t* callInstruction =
        base + static_cast<size_t>(
            verifiedCallRva);

    if (callInstruction[0] != 0xE8)
    {
        Logf(
            "[Reprocess] Verified 7C7616 callsite no longer begins with E8; aborting.");
        return false;
    }

    int32_t callRelative = 0;
    memcpy(
        &callRelative,
        callInstruction + 1,
        sizeof(callRelative));

    uint8_t* resolvedCallTarget =
        callInstruction + 5 + callRelative;

    if (resolvedCallTarget != processorAddress)
    {
        Logf(
            "[Reprocess] Verified 7C7616 callsite resolves to RVA=0x%llX instead of C2B600; aborting.",
            static_cast<unsigned long long>(
                resolvedCallTarget >= base
                    ? resolvedCallTarget - base
                    : 0));
        return false;
    }

    uintptr_t mapState = 0;
    memcpy(
        &mapState,
        base + mapStateGlobalRva,
        sizeof(mapState));

    if (!IsReadablePointerValue(mapState))
    {
        Logf(
            "[Reprocess] mapState global 0x29CAFC8 is not readable.");
        return false;
    }

    uintptr_t childArray = 0;
    uint16_t childCount = 0;

    if (!ReadProcessExact(
            mapState + 0x28,
            &childArray,
            sizeof(childArray))
        || !ReadProcessExact(
            mapState + 0x30,
            &childCount,
            sizeof(childCount))
        || !IsReadablePointerValue(childArray)
        || childCount <= 64
        || childCount > 4096)
    {
        Logf(
            "[Reprocess] Invalid mapState child array/count mapState=%p childArray=%p childCount=%u.",
            reinterpret_cast<void*>(mapState),
            reinterpret_cast<void*>(childArray),
            static_cast<unsigned int>(childCount));
        return false;
    }

    const uintptr_t child64 =
        childArray
        + (static_cast<uintptr_t>(64) * 0x120);

    const uint32_t storyHash =
        Joaat(kStoryMapGroup);
    const uint32_t mapHash =
        Joaat(kMapGroup);
    const uint32_t bennyHash =
        Joaat(kBennysChangeSet);

    auto logC2B600DerivedVsCached =
        [&](const char* phase) -> bool
    {
        std::vector<uint32_t> derivedKeys;

        for (uint16_t childIndex = 1;
             childIndex < childCount;
             ++childIndex)
        {
            const uintptr_t child =
                childArray
                + (static_cast<uintptr_t>(childIndex) * 0x120);

            uintptr_t table = 0;
            uint16_t tableCount = 0;

            if (!ReadProcessExact(
                    child + 0x108,
                    &table,
                    sizeof(table))
                || !ReadProcessExact(
                    child + 0x110,
                    &tableCount,
                    sizeof(tableCount)))
            {
                Logf(
                    "[Reprocess] C2B600 mirror failed reading child=%u during %s.",
                    static_cast<unsigned int>(childIndex),
                    phase ? phase : "unknown phase");
                return false;
            }

            if (tableCount == 0)
                continue;

            if (!IsReadablePointerValue(table)
                || tableCount > 4096)
            {
                Logf(
                    "[Reprocess] C2B600 mirror rejected child=%u table=%p count=%u during %s.",
                    static_cast<unsigned int>(childIndex),
                    reinterpret_cast<void*>(table),
                    static_cast<unsigned int>(tableCount),
                    phase ? phase : "unknown phase");
                return false;
            }

            for (uint16_t entryIndex = 0;
                 entryIndex < tableCount;
                 ++entryIndex)
            {
                uint32_t pair[2]{};

                if (!ReadProcessExact(
                        table
                            + (static_cast<uintptr_t>(entryIndex) * 8),
                        pair,
                        sizeof(pair)))
                {
                    Logf(
                        "[Reprocess] C2B600 mirror failed reading child=%u entry=%u during %s.",
                        static_cast<unsigned int>(childIndex),
                        static_cast<unsigned int>(entryIndex),
                        phase ? phase : "unknown phase");
                    return false;
                }

                if (pair[0] == storyHash
                    || pair[0] == mapHash)
                {
                    derivedKeys.push_back(pair[1]);

                    Logf(
                        "[Reprocess] C2B600 mirror %s child=%u entry=%u group=0x%08X key=0x%08X%s.",
                        phase ? phase : "state",
                        static_cast<unsigned int>(childIndex),
                        static_cast<unsigned int>(entryIndex),
                        pair[0],
                        pair[1],
                        pair[1] == bennyHash
                            ? "  <== BENNY"
                            : "");
                }
            }
        }

        uint32_t cachedCount = 0;
        if (!ReadProcessExact(
                mapState + 0x1B0,
                &cachedCount,
                sizeof(cachedCount)))
        {
            Logf(
                "[Reprocess] Failed reading mapState+0x1B0 during %s.",
                phase ? phase : "unknown phase");
            return false;
        }

        std::vector<uint32_t> cachedKeys;
        const uint32_t maxReadableCachedKeys = 512;

        if (cachedCount <= maxReadableCachedKeys)
        {
            cachedKeys.reserve(cachedCount);

            for (uint32_t i = 0;
                 i < cachedCount;
                 ++i)
            {
                uint32_t key = 0;
                if (!ReadProcessExact(
                        mapState
                            + 0x1B4
                            + (static_cast<uintptr_t>(i) * 4),
                        &key,
                        sizeof(key)))
                {
                    Logf(
                        "[Reprocess] Failed reading cached filtered key index=%u during %s.",
                        i,
                        phase ? phase : "unknown phase");
                    return false;
                }

                cachedKeys.push_back(key);

                Logf(
                    "[Reprocess] C2B600 cached %s index=%u key=0x%08X%s.",
                    phase ? phase : "state",
                    i,
                    key,
                    key == bennyHash
                        ? "  <== BENNY"
                        : "");
            }
        }
        else
        {
            Logf(
                "[Reprocess] mapState+0x1B0 cached count=%u exceeds diagnostic cap during %s; keys will not be dereferenced.",
                cachedCount,
                phase ? phase : "unknown phase");
        }

        bool listsMatch =
            cachedCount == derivedKeys.size()
            && cachedCount <= maxReadableCachedKeys;

        if (listsMatch)
        {
            for (size_t i = 0;
                 i < derivedKeys.size();
                 ++i)
            {
                if (cachedKeys[i] != derivedKeys[i])
                {
                    listsMatch = false;
                    break;
                }
            }
        }

        bool derivedContainsBenny = false;
        for (uint32_t key : derivedKeys)
        {
            if (key == bennyHash)
            {
                derivedContainsBenny = true;
                break;
            }
        }

        bool cachedContainsBenny = false;
        for (uint32_t key : cachedKeys)
        {
            if (key == bennyHash)
            {
                cachedContainsBenny = true;
                break;
            }
        }

        Logf(
            "[Reprocess] C2B600 mirror-vs-cache %s derivedCount=%llu cachedCount=%u listsMatch=%s derivedBenny=%s cachedBenny=%s changePredicate=%s.",
            phase ? phase : "state",
            static_cast<unsigned long long>(derivedKeys.size()),
            cachedCount,
            listsMatch ? "yes" : "no",
            derivedContainsBenny ? "yes" : "no",
            cachedContainsBenny ? "yes" : "no",
            listsMatch ? "no" : "yes");

        return true;
    };

    auto readTargetState =
        [&](const char* phase,
            uintptr_t& table,
            uint16_t& count,
            uint16_t& capacity,
            bool& exactPair) -> bool
    {
        table = 0;
        count = 0;
        capacity = 0;
        exactPair = false;

        if (!ReadProcessExact(
                child64 + 0x108,
                &table,
                sizeof(table))
            || !ReadProcessExact(
                child64 + 0x110,
                &count,
                sizeof(count))
            || !ReadProcessExact(
                child64 + 0x112,
                &capacity,
                sizeof(capacity)))
        {
            Logf(
                "[Reprocess] Failed reading child64 table state during %s.",
                phase ? phase : "unknown phase");
            return false;
        }

        if (count != 0)
        {
            if (!IsReadablePointerValue(table)
                || count > 4096)
            {
                Logf(
                    "[Reprocess] Invalid child64 table during %s table=%p count=%u capacity=%u.",
                    phase ? phase : "unknown phase",
                    reinterpret_cast<void*>(table),
                    static_cast<unsigned int>(count),
                    static_cast<unsigned int>(capacity));
                return false;
            }

            for (uint16_t i = 0;
                 i < count;
                 ++i)
            {
                uint32_t first = 0;
                uint32_t second = 0;

                if (!ReadProcessExact(
                        table
                            + (static_cast<uintptr_t>(i) * 8),
                        &first,
                        sizeof(first))
                    || !ReadProcessExact(
                        table
                            + (static_cast<uintptr_t>(i) * 8)
                            + 4,
                        &second,
                        sizeof(second)))
                {
                    Logf(
                        "[Reprocess] Failed reading child64 entry %u during %s.",
                        static_cast<unsigned int>(i),
                        phase ? phase : "unknown phase");
                    return false;
                }

                if (first == storyHash
                    && second == bennyHash)
                    exactPair = true;
            }
        }

        Logf(
            "[Reprocess] child64 %s table=%p count=%u capacity=%u exactPair=%s.",
            phase ? phase : "state",
            reinterpret_cast<void*>(table),
            static_cast<unsigned int>(count),
            static_cast<unsigned int>(capacity),
            exactPair ? "yes" : "no");

        return true;
    };

    uintptr_t tableBefore = 0;
    uint16_t countBefore = 0;
    uint16_t capacityBefore = 0;
    bool exactPairBefore = false;

    if (!readTargetState(
            "before C2B600",
            tableBefore,
            countBefore,
            capacityBefore,
            exactPairBefore))
        return false;

    if (!exactPairBefore)
    {
        Logf(
            "[Reprocess] Refusing C2B600 because the exact GROUP_MAP_SP -> Benny association is not present.");
        return false;
    }

    if (!logC2B600DerivedVsCached(
            "before C2B600"))
        return false;

    Logf(
        "[Reprocess] CALLING verified Rockstar C2B600(mapState=%p) after exact Benny association insertion.",
        reinterpret_cast<void*>(mapState));

    using RockstarMapStateProcessor1012 =
        void(*)(
            void* mapState);

    RockstarMapStateProcessor1012 processor =
        reinterpret_cast<RockstarMapStateProcessor1012>(
            processorAddress);

    __try
    {
        processor(
            reinterpret_cast<void*>(mapState));
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        Logf(
            "[Reprocess] C2B600 raised SEH exception code=0x%08lX. No further internal reprocess call will be attempted.",
            static_cast<unsigned long>(
                GetExceptionCode()));
        return false;
    }

    uintptr_t tableAfter = 0;
    uint16_t countAfter = 0;
    uint16_t capacityAfter = 0;
    bool exactPairAfter = false;

    if (!readTargetState(
            "after C2B600",
            tableAfter,
            countAfter,
            capacityAfter,
            exactPairAfter))
        return false;

    if (!logC2B600DerivedVsCached(
            "after C2B600"))
        return false;

    Logf(
        "[Reprocess] C2B600 returned successfully; exactPairBefore=%s exactPairAfter=%s countBefore=%u countAfter=%u.",
        exactPairBefore ? "yes" : "no",
        exactPairAfter ? "yes" : "no",
        static_cast<unsigned int>(countBefore),
        static_cast<unsigned int>(countAfter));

    if (!exactPairAfter)
    {

        g_experimentalInternalGroupAddApplied = false;

        Logf(
            "[Reprocess] The exact child64 association was consumed/removed by C2B600; correlate this with the Benny map-state check.");
    }

    return true;
}

struct LegacyV65OverlayCandidate
{
    uintptr_t bennyAddress;
    uintptr_t recordAddress;
    uintptr_t allocationBase;
    uintptr_t regionBase;
    long dlcOffsetFromBenny;
    long groupOffsetFromBenny;
    uint32_t groupValue;
    uint32_t contiguousUnknown04;
    uint32_t contiguousFlags;
    int score;
    bool contiguousFiveDword;
};

struct LegacyV73OverlayGateState
{
    bool scanned;
    bool exactSingleMap;
    bool exactSingleStory;
    bool rewrittenToStory;
    bool rewriteVerified;
    bool rewriteRestoredOnFailure;
    int contiguousMapHits;
    int contiguousStoryHits;
    int relaxedMapHits;
    int relaxedStoryHits;
    uintptr_t recordAddress;
    uint32_t groupValue;
    uint32_t unknown04;
    uint32_t flags;
};

static LegacyV73OverlayGateState g_legacyV73OverlayGate{};

static bool LegacyV65AddressAlreadyTracked(
    const std::vector<uintptr_t>& addresses,
    uintptr_t value)
{
    for (uintptr_t existing : addresses)
    {
        if (existing == value)
            return true;
    }

    return false;
}

static unsigned long long LegacyV65AbsDistance(long value)
{
    return value < 0
        ? static_cast<unsigned long long>(
            -static_cast<long long>(value))
        : static_cast<unsigned long long>(value);
}

struct LegacyV88OverlayDiscoveryState
{
    bool anchorResolved;
    bool allocationResolved;
    bool scanned;
    uintptr_t lowriderChild;
    uintptr_t allocationBase;
    uintptr_t allocationEnd;
    uint32_t regionsExamined;
    uint32_t readFailures;
    uint64_t bytesExamined;
    uint32_t exactMapHits;
    uint32_t exactStoryHits;
};

static LegacyV88OverlayDiscoveryState g_legacyV88OverlayDiscovery{};

struct LegacyV89OverlayOwnerProbeState
{
    bool attempted;
    bool recordVerified;
    uintptr_t record;
    uintptr_t allocationBase;
    uintptr_t allocationEnd;
    uintptr_t inferredRunStart;
    uintptr_t inferredRunEnd;
    uint32_t inferredRunCount;
    uint32_t recordPointerHits;
    uint32_t bennyPointerHits;
    uint32_t groupPointerHits;
    uint32_t runStartPointerHits;
    uintptr_t firstRecordPointer;
    uintptr_t firstBennyPointer;
    uintptr_t firstGroupPointer;
    uintptr_t firstRunStartPointer;
    uint32_t regionsExamined;
    uint32_t readFailures;
    uint64_t bytesExamined;
};

static LegacyV89OverlayOwnerProbeState
    g_legacyV89OverlayOwnerProbe{};

static bool IsLegacyV89PlausibleOverlayRow(
    const uint32_t fields[5])
{
    if (!fields)
        return false;

    return fields[0] != 0U
        && fields[1] != 0U
        && fields[2] != 0U
        && fields[3] != 0U
        && fields[4] == 1U;
}

static void LogLegacyV89PointerNeighborhood(
    const char* label,
    uintptr_t pointerSlot,
    uintptr_t allocationBase,
    uintptr_t allocationEnd)
{
    if (!label
        || !pointerSlot
        || pointerSlot < allocationBase
        || pointerSlot >= allocationEnd)
    {
        return;
    }

    constexpr intptr_t radius = 0x80;
    for (intptr_t relative = -radius;
         relative <= radius;
         relative += static_cast<intptr_t>(sizeof(uintptr_t)))
    {
        const intptr_t signedAddress =
            static_cast<intptr_t>(pointerSlot)
            + relative;
        if (signedAddress <= 0)
            continue;

        const uintptr_t address =
            static_cast<uintptr_t>(signedAddress);
        if (address < allocationBase
            || address + sizeof(uintptr_t) > allocationEnd)
        {
            continue;
        }

        uintptr_t value = 0;
        if (!ReadProcessExact(
                address,
                &value,
                sizeof(value)))
        {
            continue;
        }

        Logf(
            "[LegacyOverlayV89] %s slotNeighborhood offset=%+lld slot=%p value=%p valueOffset=%s0x%llX.",
            label,
            static_cast<long long>(relative),
            reinterpret_cast<void*>(address),
            reinterpret_cast<void*>(value),
            (value >= allocationBase
                && value < allocationEnd)
                ? ""
                : "out:",
            static_cast<unsigned long long>(
                (value >= allocationBase
                    && value < allocationEnd)
                    ? value - allocationBase
                    : value));
    }
}

struct LegacyV91PointerRunProbe
{
    bool valid;
    bool backwardTruncated;
    bool forwardTruncated;
    uintptr_t recordSlot;
    uintptr_t regionBase;
    uintptr_t regionEnd;
    uintptr_t runStart;
    uintptr_t runEnd;
    uint32_t entryCount;
    uint32_t recordIndex;
    uint32_t runStartPointerHits;
    uint32_t runEndPointerHits;
    uint32_t recordSlotPointerHits;
    uint32_t regionBasePointerHits;
    uint32_t exactVectorTripleHits;
    uint32_t containingVectorTripleHits;
    uintptr_t firstRunStartPointer;
    uintptr_t firstRunEndPointer;
    uintptr_t firstRecordSlotPointer;
    uintptr_t firstRegionBasePointer;
    uintptr_t firstExactVectorTriple;
    uintptr_t firstContainingVectorTriple;
    uint32_t imageRunStartHits;
    uint32_t imageRegionBaseHits;
    uintptr_t firstImageRunStart;
    uintptr_t firstImageRegionBase;
};

static bool LegacyV91ReadOwnedPointer(
    uintptr_t slot,
    uintptr_t allocationBase,
    uintptr_t allocationEnd,
    uintptr_t& value)
{
    value = 0;
    if (!slot
        || allocationEnd <= allocationBase
        || !ReadProcessExact(
            slot,
            &value,
            sizeof(value))
        || value < allocationBase
        || value >= allocationEnd)
    {
        return false;
    }

    MEMORY_BASIC_INFORMATION mbi{};
    if (VirtualQuery(
            reinterpret_cast<LPCVOID>(value),
            &mbi,
            sizeof(mbi)) == 0
        || mbi.State != MEM_COMMIT
        || !IsReadableProtection(mbi.Protect))
    {
        return false;
    }

    return true;
}

static void ProbeLegacyV91PointerTableOwners(
    const uintptr_t* recordSlots,
    uint32_t recordSlotCount,
    uintptr_t allocationBase,
    uintptr_t allocationEnd)
{
    if (!recordSlots
        || recordSlotCount == 0
        || allocationEnd <= allocationBase)
    {
        return;
    }

    constexpr uint32_t maxRuns = 8;
    constexpr uint32_t maxWalkEntriesPerDirection = 16384;
    LegacyV91PointerRunProbe runs[maxRuns]{};
    const uint32_t runCount =
        recordSlotCount < maxRuns
            ? recordSlotCount
            : maxRuns;

    for (uint32_t i = 0; i < runCount; ++i)
    {
        const uintptr_t slot = recordSlots[i];
        if (!slot)
            continue;

        MEMORY_BASIC_INFORMATION slotMbi{};
        if (VirtualQuery(
                reinterpret_cast<LPCVOID>(slot),
                &slotMbi,
                sizeof(slotMbi)) == 0
            || slotMbi.State != MEM_COMMIT
            || !IsReadableProtection(slotMbi.Protect))
        {
            continue;
        }

        uintptr_t regionBase =
            reinterpret_cast<uintptr_t>(
                slotMbi.BaseAddress);
        uintptr_t regionEnd =
            regionBase
            + static_cast<uintptr_t>(
                slotMbi.RegionSize);
        if (regionBase < allocationBase)
            regionBase = allocationBase;
        if (regionEnd > allocationEnd)
            regionEnd = allocationEnd;

        uintptr_t targetValue = 0;
        if (!LegacyV91ReadOwnedPointer(
                slot,
                allocationBase,
                allocationEnd,
                targetValue))
        {
            continue;
        }

        uintptr_t runStart = slot;
        uintptr_t runEnd = slot + sizeof(uintptr_t);
        uint32_t backwardSteps = 0;
        uint32_t forwardSteps = 0;

        for (uint32_t step = 1;
             step <= maxWalkEntriesPerDirection;
             ++step)
        {
            const uintptr_t distance =
                static_cast<uintptr_t>(step)
                * sizeof(uintptr_t);
            if (slot < regionBase + distance)
                break;

            const uintptr_t candidate =
                slot - distance;
            uintptr_t value = 0;
            if (!LegacyV91ReadOwnedPointer(
                    candidate,
                    allocationBase,
                    allocationEnd,
                    value))
            {
                break;
            }

            runStart = candidate;
            backwardSteps = step;
        }

        if (backwardSteps
            == maxWalkEntriesPerDirection
            && runStart > regionBase)
        {
            runs[i].backwardTruncated = true;
        }

        for (uint32_t step = 1;
             step <= maxWalkEntriesPerDirection;
             ++step)
        {
            const uintptr_t distance =
                static_cast<uintptr_t>(step)
                * sizeof(uintptr_t);
            const uintptr_t candidate =
                slot + distance;
            if (candidate < slot
                || candidate + sizeof(uintptr_t)
                    > regionEnd)
            {
                break;
            }

            uintptr_t value = 0;
            if (!LegacyV91ReadOwnedPointer(
                    candidate,
                    allocationBase,
                    allocationEnd,
                    value))
            {
                break;
            }

            runEnd =
                candidate + sizeof(uintptr_t);
            forwardSteps = step;
        }

        if (forwardSteps
            == maxWalkEntriesPerDirection
            && runEnd < regionEnd)
        {
            runs[i].forwardTruncated = true;
        }

        if (runEnd <= runStart
            || (runEnd - runStart)
                % sizeof(uintptr_t) != 0)
        {
            continue;
        }

        runs[i].valid = true;
        runs[i].recordSlot = slot;
        runs[i].regionBase = regionBase;
        runs[i].regionEnd = regionEnd;
        runs[i].runStart = runStart;
        runs[i].runEnd = runEnd;
        runs[i].entryCount =
            static_cast<uint32_t>(
                (runEnd - runStart)
                / sizeof(uintptr_t));
        runs[i].recordIndex =
            static_cast<uint32_t>(
                (slot - runStart)
                / sizeof(uintptr_t));

        uintptr_t beforeValue = 0;
        uintptr_t afterValue = 0;
        const bool haveBefore =
            runStart >= regionBase + sizeof(uintptr_t)
            && ReadProcessExact(
                runStart - sizeof(uintptr_t),
                &beforeValue,
                sizeof(beforeValue));
        const bool haveAfter =
            runEnd + sizeof(uintptr_t) <= regionEnd
            && ReadProcessExact(
                runEnd,
                &afterValue,
                sizeof(afterValue));

        Logf(
            "[LegacyOverlayV91] pointerRun[%u] slot=%p region=%p..%p run=%p..%p entries=%u targetIndex=%u truncated{back=%s forward=%s} boundary{before=%s0x%llX after=%s0x%llX}.",
            i,
            reinterpret_cast<void*>(slot),
            reinterpret_cast<void*>(regionBase),
            reinterpret_cast<void*>(regionEnd),
            reinterpret_cast<void*>(runStart),
            reinterpret_cast<void*>(runEnd),
            runs[i].entryCount,
            runs[i].recordIndex,
            runs[i].backwardTruncated ? "yes" : "no",
            runs[i].forwardTruncated ? "yes" : "no",
            haveBefore ? "" : "unreadable:",
            static_cast<unsigned long long>(
                beforeValue),
            haveAfter ? "" : "unreadable:",
            static_cast<unsigned long long>(
                afterValue));
    }

    constexpr SIZE_T chunkSize =
        1024ULL * 1024ULL;
    constexpr SIZE_T qwordSize =
        sizeof(uintptr_t);
    constexpr SIZE_T scanOverlap =
        (sizeof(uintptr_t) * 3ULL) - 1ULL;
    std::vector<uint8_t> buffer(
        chunkSize + scanOverlap);

    uintptr_t cursor = allocationBase;
    uint32_t regionsExamined = 0;
    uint32_t readFailures = 0;
    uint64_t bytesExamined = 0;

    while (cursor >= allocationBase
        && cursor < allocationEnd)
    {
        MEMORY_BASIC_INFORMATION mbi{};
        if (VirtualQuery(
                reinterpret_cast<LPCVOID>(cursor),
                &mbi,
                sizeof(mbi)) == 0)
        {
            break;
        }

        const uintptr_t regionBase =
            reinterpret_cast<uintptr_t>(
                mbi.BaseAddress);
        const uintptr_t regionAllocationBase =
            reinterpret_cast<uintptr_t>(
                mbi.AllocationBase);
        uintptr_t regionEnd =
            regionBase
            + static_cast<uintptr_t>(
                mbi.RegionSize);

        if (regionEnd <= cursor)
            break;
        if (regionEnd > allocationEnd)
            regionEnd = allocationEnd;

        if (regionAllocationBase != allocationBase)
        {
            cursor = regionEnd;
            continue;
        }

        if (mbi.State == MEM_COMMIT
            && mbi.Type != MEM_IMAGE
            && IsReadableProtection(mbi.Protect)
            && IsWritableProtection(mbi.Protect))
        {
            ++regionsExamined;
            uintptr_t chunkAddress = regionBase;

            while (chunkAddress < regionEnd)
            {
                const SIZE_T remaining =
                    static_cast<SIZE_T>(
                        regionEnd - chunkAddress);
                const SIZE_T request =
                    remaining < (chunkSize + scanOverlap)
                        ? remaining
                        : (chunkSize + scanOverlap);

                SIZE_T bytesRead = 0;
                if (request >= qwordSize
                    && ReadProcessMemory(
                        GetCurrentProcess(),
                        reinterpret_cast<LPCVOID>(
                            chunkAddress),
                        buffer.data(),
                        request,
                        &bytesRead)
                    && bytesRead >= qwordSize)
                {
                    const SIZE_T primaryBytes =
                        bytesRead > chunkSize
                            ? chunkSize
                            : bytesRead;

                    SIZE_T offset =
                        static_cast<SIZE_T>(
                            (qwordSize
                                - (chunkAddress
                                    & (qwordSize - 1ULL)))
                            & (qwordSize - 1ULL));

                    for (;
                         offset < primaryBytes
                            && offset + qwordSize
                                <= bytesRead;
                         offset += qwordSize)
                    {
                        uintptr_t q0 = 0;
                        memcpy(
                            &q0,
                            buffer.data() + offset,
                            sizeof(q0));
                        const uintptr_t slot =
                            chunkAddress + offset;

                        uintptr_t q1 = 0;
                        uintptr_t q2 = 0;
                        const bool haveTriple =
                            offset
                                + (sizeof(uintptr_t) * 3ULL)
                                <= bytesRead;
                        if (haveTriple)
                        {
                            memcpy(
                                &q1,
                                buffer.data() + offset
                                    + sizeof(uintptr_t),
                                sizeof(q1));
                            memcpy(
                                &q2,
                                buffer.data() + offset
                                    + (sizeof(uintptr_t) * 2ULL),
                                sizeof(q2));
                        }

                        for (uint32_t i = 0;
                             i < runCount;
                             ++i)
                        {
                            LegacyV91PointerRunProbe& run =
                                runs[i];
                            if (!run.valid)
                                continue;

                            if (q0 == run.runStart)
                            {
                                ++run.runStartPointerHits;
                                if (!run.firstRunStartPointer)
                                    run.firstRunStartPointer = slot;
                            }

                            if (q0 == run.runEnd)
                            {
                                ++run.runEndPointerHits;
                                if (!run.firstRunEndPointer)
                                    run.firstRunEndPointer = slot;
                            }

                            if (q0 == run.recordSlot)
                            {
                                ++run.recordSlotPointerHits;
                                if (!run.firstRecordSlotPointer)
                                    run.firstRecordSlotPointer = slot;
                            }

                            if (q0 == run.regionBase)
                            {
                                ++run.regionBasePointerHits;
                                if (!run.firstRegionBasePointer)
                                    run.firstRegionBasePointer = slot;
                            }

                            if (haveTriple
                                && q0 == run.runStart
                                && q1 == run.runEnd
                                && q2 >= q1
                                && q2 <= run.regionEnd
                                && (q2 - run.regionBase)
                                    % sizeof(uintptr_t) == 0)
                            {
                                ++run.exactVectorTripleHits;
                                if (!run.firstExactVectorTriple)
                                    run.firstExactVectorTriple = slot;
                            }

                            if (haveTriple
                                && q0 == run.runStart
                                && q1 > run.recordSlot
                                && q1 <= run.runEnd
                                && q2 >= q1
                                && q2 <= run.regionEnd
                                && (q1 - run.regionBase)
                                    % sizeof(uintptr_t) == 0
                                && (q2 - run.regionBase)
                                    % sizeof(uintptr_t) == 0)
                            {
                                ++run.containingVectorTripleHits;
                                if (!run.firstContainingVectorTriple)
                                    run.firstContainingVectorTriple = slot;
                            }
                        }
                    }

                    bytesExamined += primaryBytes;
                }
                else if (request >= qwordSize)
                {
                    ++readFailures;
                }

                if (remaining <= chunkSize)
                    break;

                chunkAddress += chunkSize;
            }
        }

        cursor = regionEnd;
    }

    uint8_t* exeBase = nullptr;
    uint8_t* exeEnd = nullptr;
    if (GetExeRange(exeBase, exeEnd)
        && exeBase
        && exeEnd > exeBase)
    {
        const IMAGE_DOS_HEADER* dos =
            reinterpret_cast<const IMAGE_DOS_HEADER*>(
                exeBase);
        if (dos->e_magic == IMAGE_DOS_SIGNATURE)
        {
            const IMAGE_NT_HEADERS64* nt =
                reinterpret_cast<const IMAGE_NT_HEADERS64*>(
                    exeBase + dos->e_lfanew);
            if (nt->Signature == IMAGE_NT_SIGNATURE)
            {
                const IMAGE_SECTION_HEADER* section =
                    IMAGE_FIRST_SECTION(nt);

                for (WORD sectionIndex = 0;
                     sectionIndex
                        < nt->FileHeader.NumberOfSections;
                     ++sectionIndex,
                        ++section)
                {
                    if ((section->Characteristics
                            & IMAGE_SCN_MEM_READ) == 0
                        || (section->Characteristics
                            & IMAGE_SCN_MEM_EXECUTE) != 0)
                    {
                        continue;
                    }

                    const uintptr_t sectionStart =
                        reinterpret_cast<uintptr_t>(
                            exeBase)
                        + section->VirtualAddress;
                    const uintptr_t rawSectionEnd =
                        sectionStart
                        + static_cast<uintptr_t>(
                            section->Misc.VirtualSize);
                    const uintptr_t sectionEnd =
                        rawSectionEnd
                            < reinterpret_cast<uintptr_t>(
                                exeEnd)
                        ? rawSectionEnd
                        : reinterpret_cast<uintptr_t>(
                            exeEnd);

                    uintptr_t chunkAddress = sectionStart;
                    while (chunkAddress < sectionEnd)
                    {
                        const SIZE_T remaining =
                            static_cast<SIZE_T>(
                                sectionEnd - chunkAddress);
                        const SIZE_T request =
                            remaining < (chunkSize + scanOverlap)
                                ? remaining
                                : (chunkSize + scanOverlap);

                        SIZE_T bytesRead = 0;
                        if (request >= sizeof(uintptr_t)
                            && ReadProcessMemory(
                                GetCurrentProcess(),
                                reinterpret_cast<LPCVOID>(
                                    chunkAddress),
                                buffer.data(),
                                request,
                                &bytesRead)
                            && bytesRead >= sizeof(uintptr_t))
                        {
                            const SIZE_T primaryBytes =
                                bytesRead > chunkSize
                                    ? chunkSize
                                    : bytesRead;

                            SIZE_T offset =
                                static_cast<SIZE_T>(
                                    (sizeof(uintptr_t)
                                        - (chunkAddress
                                            & (sizeof(uintptr_t)
                                                - 1ULL)))
                                    & (sizeof(uintptr_t)
                                        - 1ULL));

                            for (;
                                 offset < primaryBytes
                                    && offset
                                        + sizeof(uintptr_t)
                                        <= bytesRead;
                                 offset += sizeof(uintptr_t))
                            {
                                uintptr_t value = 0;
                                memcpy(
                                    &value,
                                    buffer.data() + offset,
                                    sizeof(value));
                                const uintptr_t slot =
                                    chunkAddress + offset;

                                for (uint32_t i = 0;
                                     i < runCount;
                                     ++i)
                                {
                                    LegacyV91PointerRunProbe& run =
                                        runs[i];
                                    if (!run.valid)
                                        continue;

                                    if (value == run.runStart)
                                    {
                                        ++run.imageRunStartHits;
                                        if (!run.firstImageRunStart)
                                            run.firstImageRunStart = slot;
                                    }

                                    if (value == run.regionBase)
                                    {
                                        ++run.imageRegionBaseHits;
                                        if (!run.firstImageRegionBase)
                                            run.firstImageRegionBase = slot;
                                    }
                                }
                            }
                        }

                        if (remaining <= chunkSize)
                            break;

                        chunkAddress += chunkSize;
                    }
                }
            }
        }
    }

    Logf(
        "[LegacyOverlayV91] ownerSearch scannedMiB=%llu regions=%u readFailures=%u runs=%u.",
        static_cast<unsigned long long>(
            bytesExamined / (1024ULL * 1024ULL)),
        regionsExamined,
        readFailures,
        runCount);

    for (uint32_t i = 0; i < runCount; ++i)
    {
        const LegacyV91PointerRunProbe& run =
            runs[i];
        if (!run.valid)
            continue;

        Logf(
            "[LegacyOverlayV91] ownerSummary[%u] runOffset=0x%llX..0x%llX entries=%u targetIndex=%u sameAllocationRefs{runStart=%u runEnd=%u recordSlot=%u regionBase=%u vectorExact=%u vectorContains=%u} imageRefs{runStart=%u regionBase=%u} first{runStart=%p runEnd=%p recordSlot=%p regionBase=%p vectorExact=%p vectorContains=%p imageRunStart=%p imageRegionBase=%p}.",
            i,
            static_cast<unsigned long long>(
                run.runStart - allocationBase),
            static_cast<unsigned long long>(
                run.runEnd - allocationBase),
            run.entryCount,
            run.recordIndex,
            run.runStartPointerHits,
            run.runEndPointerHits,
            run.recordSlotPointerHits,
            run.regionBasePointerHits,
            run.exactVectorTripleHits,
            run.containingVectorTripleHits,
            run.imageRunStartHits,
            run.imageRegionBaseHits,
            reinterpret_cast<void*>(
                run.firstRunStartPointer),
            reinterpret_cast<void*>(
                run.firstRunEndPointer),
            reinterpret_cast<void*>(
                run.firstRecordSlotPointer),
            reinterpret_cast<void*>(
                run.firstRegionBasePointer),
            reinterpret_cast<void*>(
                run.firstExactVectorTriple),
            reinterpret_cast<void*>(
                run.firstContainingVectorTriple),
            reinterpret_cast<void*>(
                run.firstImageRunStart),
            reinterpret_cast<void*>(
                run.firstImageRegionBase));

        if (run.firstExactVectorTriple)
        {
            LogLegacyV89PointerNeighborhood(
                "v91ExactVectorOwner",
                run.firstExactVectorTriple,
                allocationBase,
                allocationEnd);
        }
        else if (run.firstContainingVectorTriple)
        {
            LogLegacyV89PointerNeighborhood(
                "v91ContainingVectorOwner",
                run.firstContainingVectorTriple,
                allocationBase,
                allocationEnd);
        }
        else if (run.runStartPointerHits == 1
            && run.firstRunStartPointer)
        {
            LogLegacyV89PointerNeighborhood(
                "v91RunStartOwner",
                run.firstRunStartPointer,
                allocationBase,
                allocationEnd);
        }
    }
}

static void ProbeLegacyV89OverlayOwner(
    uintptr_t record,
    uintptr_t allocationBase,
    uintptr_t allocationEnd)
{
    g_legacyV89OverlayOwnerProbe =
        LegacyV89OverlayOwnerProbeState{};
    g_legacyV89OverlayOwnerProbe.attempted = true;
    g_legacyV89OverlayOwnerProbe.record = record;
    g_legacyV89OverlayOwnerProbe.allocationBase =
        allocationBase;
    g_legacyV89OverlayOwnerProbe.allocationEnd =
        allocationEnd;

    constexpr uint32_t dlcHash = 0x61322A35U;
    constexpr uint32_t unknown04 = 0xF9904BBCU;
    constexpr uint32_t bennyHash = 0x4CDFC843U;
    constexpr uint32_t mapHash = 0xBCC89179U;
    constexpr uint32_t storyHash = 0x578F99E2U;
    constexpr uint32_t flags = 1U;
    constexpr uintptr_t rowSize =
        sizeof(uint32_t) * 5ULL;

    if (!record
        || allocationEnd <= allocationBase
        || record < allocationBase
        || record + rowSize > allocationEnd)
    {
        Logf(
            "[LegacyOverlayV89] REFUSED: invalid record/allocation bounds record=%p allocation=%p..%p.",
            reinterpret_cast<void*>(record),
            reinterpret_cast<void*>(allocationBase),
            reinterpret_cast<void*>(allocationEnd));
        return;
    }

    uint32_t exactFields[5]{};
    if (!ReadProcessExact(
            record,
            exactFields,
            sizeof(exactFields))
        || exactFields[0] != dlcHash
        || exactFields[1] != unknown04
        || exactFields[2] != bennyHash
        || (exactFields[3] != mapHash
            && exactFields[3] != storyHash)
        || exactFields[4] != flags)
    {
        Logf(
            "[LegacyOverlayV89] REFUSED: v88-selected record failed exact pre-probe validation.");
        return;
    }

    g_legacyV89OverlayOwnerProbe.recordVerified = true;

    for (int row = -6; row <= 6; ++row)
    {
        const intptr_t signedAddress =
            static_cast<intptr_t>(record)
            + (static_cast<intptr_t>(row)
                * static_cast<intptr_t>(rowSize));
        if (signedAddress <= 0)
            continue;

        const uintptr_t rowAddress =
            static_cast<uintptr_t>(signedAddress);
        if (rowAddress < allocationBase
            || rowAddress + rowSize > allocationEnd)
        {
            continue;
        }

        uint32_t fields[5]{};
        if (!ReadProcessExact(
                rowAddress,
                fields,
                sizeof(fields)))
        {
            continue;
        }

        Logf(
            "[LegacyOverlayV89] row[%+d] address=%p fields={0x%08X,0x%08X,0x%08X,0x%08X,0x%08X} plausible=%s.",
            row,
            reinterpret_cast<void*>(rowAddress),
            fields[0],
            fields[1],
            fields[2],
            fields[3],
            fields[4],
            IsLegacyV89PlausibleOverlayRow(fields)
                ? "yes"
                : "no");
    }

    uintptr_t runStart = record;
    uintptr_t runEnd = record + rowSize;
    uint32_t runCount = 1;
    constexpr uint32_t maxRowsPerDirection = 4096;

    for (uint32_t step = 1;
         step <= maxRowsPerDirection;
         ++step)
    {
        const uintptr_t distance =
            static_cast<uintptr_t>(step) * rowSize;
        if (record < allocationBase + distance)
            break;

        const uintptr_t candidate =
            record - distance;
        uint32_t fields[5]{};
        if (!ReadProcessExact(
                candidate,
                fields,
                sizeof(fields))
            || !IsLegacyV89PlausibleOverlayRow(fields))
        {
            break;
        }

        runStart = candidate;
        ++runCount;
    }

    for (uint32_t step = 1;
         step <= maxRowsPerDirection;
         ++step)
    {
        const uintptr_t distance =
            static_cast<uintptr_t>(step) * rowSize;
        const uintptr_t candidate =
            record + distance;
        if (candidate < record
            || candidate + rowSize > allocationEnd)
        {
            break;
        }

        uint32_t fields[5]{};
        if (!ReadProcessExact(
                candidate,
                fields,
                sizeof(fields))
            || !IsLegacyV89PlausibleOverlayRow(fields))
        {
            break;
        }

        runEnd = candidate + rowSize;
        ++runCount;
    }

    g_legacyV89OverlayOwnerProbe.inferredRunStart =
        runStart;
    g_legacyV89OverlayOwnerProbe.inferredRunEnd =
        runEnd;
    g_legacyV89OverlayOwnerProbe.inferredRunCount =
        runCount;

    Logf(
        "[LegacyOverlayV89] inferredRun start=%p(startOffset=0x%llX) end=%p(endOffset=0x%llX) rows=%u bytes=0x%llX targetIndex=%llu.",
        reinterpret_cast<void*>(runStart),
        static_cast<unsigned long long>(
            runStart - allocationBase),
        reinterpret_cast<void*>(runEnd),
        static_cast<unsigned long long>(
            runEnd - allocationBase),
        runCount,
        static_cast<unsigned long long>(
            runEnd - runStart),
        static_cast<unsigned long long>(
            (record - runStart) / rowSize));

    constexpr SIZE_T chunkSize =
        1024ULL * 1024ULL;
    constexpr SIZE_T overlap =
        sizeof(uintptr_t) - 1ULL;
    std::vector<uint8_t> buffer(
        chunkSize + overlap);

    const uintptr_t bennyAddress =
        record + (sizeof(uint32_t) * 2ULL);
    const uintptr_t groupAddress =
        record + (sizeof(uint32_t) * 3ULL);

    constexpr uint32_t maxTrackedPointerSlots = 8;
    uintptr_t recordPointerSlots[maxTrackedPointerSlots]{};
    uintptr_t runStartPointerSlots[maxTrackedPointerSlots]{};

    uintptr_t cursor = allocationBase;
    uint32_t regionsExamined = 0;
    uint32_t readFailures = 0;
    uint64_t bytesExamined = 0;

    while (cursor >= allocationBase
        && cursor < allocationEnd)
    {
        MEMORY_BASIC_INFORMATION mbi{};
        if (VirtualQuery(
                reinterpret_cast<LPCVOID>(cursor),
                &mbi,
                sizeof(mbi)) == 0)
        {
            break;
        }

        const uintptr_t regionBase =
            reinterpret_cast<uintptr_t>(
                mbi.BaseAddress);
        const uintptr_t regionAllocationBase =
            reinterpret_cast<uintptr_t>(
                mbi.AllocationBase);
        uintptr_t regionEnd =
            regionBase
            + static_cast<uintptr_t>(
                mbi.RegionSize);

        if (regionEnd <= cursor)
            break;

        if (regionEnd > allocationEnd)
            regionEnd = allocationEnd;

        if (regionAllocationBase != allocationBase)
        {
            cursor = regionEnd;
            continue;
        }

        if (mbi.State == MEM_COMMIT
            && mbi.Type != MEM_IMAGE
            && IsReadableProtection(mbi.Protect)
            && IsWritableProtection(mbi.Protect))
        {
            ++regionsExamined;
            uintptr_t chunkAddress = regionBase;

            while (chunkAddress < regionEnd)
            {
                const SIZE_T remaining =
                    static_cast<SIZE_T>(
                        regionEnd - chunkAddress);
                const SIZE_T request =
                    remaining < (chunkSize + overlap)
                        ? remaining
                        : (chunkSize + overlap);

                SIZE_T bytesRead = 0;
                if (request >= sizeof(uintptr_t)
                    && ReadProcessMemory(
                        GetCurrentProcess(),
                        reinterpret_cast<LPCVOID>(
                            chunkAddress),
                        buffer.data(),
                        request,
                        &bytesRead)
                    && bytesRead >= sizeof(uintptr_t))
                {
                    const SIZE_T primaryBytes =
                        bytesRead > chunkSize
                            ? chunkSize
                            : bytesRead;

                    SIZE_T offset =
                        static_cast<SIZE_T>(
                            (sizeof(uintptr_t)
                                - (chunkAddress
                                    & (sizeof(uintptr_t) - 1ULL)))
                            & (sizeof(uintptr_t) - 1ULL));

                    for (;
                         offset < primaryBytes
                            && offset + sizeof(uintptr_t)
                                <= bytesRead;
                         offset += sizeof(uintptr_t))
                    {
                        uintptr_t value = 0;
                        memcpy(
                            &value,
                            buffer.data() + offset,
                            sizeof(value));

                        const uintptr_t slot =
                            chunkAddress + offset;

                        if (value == record)
                        {
                            const uint32_t hitIndex =
                                g_legacyV89OverlayOwnerProbe.recordPointerHits;
                            ++g_legacyV89OverlayOwnerProbe.recordPointerHits;

                            if (hitIndex < maxTrackedPointerSlots)
                                recordPointerSlots[hitIndex] = slot;

                            if (!g_legacyV89OverlayOwnerProbe.firstRecordPointer)
                                g_legacyV89OverlayOwnerProbe.firstRecordPointer = slot;
                        }

                        if (value == bennyAddress)
                        {
                            ++g_legacyV89OverlayOwnerProbe.bennyPointerHits;
                            if (!g_legacyV89OverlayOwnerProbe.firstBennyPointer)
                                g_legacyV89OverlayOwnerProbe.firstBennyPointer = slot;
                        }

                        if (value == groupAddress)
                        {
                            ++g_legacyV89OverlayOwnerProbe.groupPointerHits;
                            if (!g_legacyV89OverlayOwnerProbe.firstGroupPointer)
                                g_legacyV89OverlayOwnerProbe.firstGroupPointer = slot;
                        }

                        if (value == runStart)
                        {
                            const uint32_t hitIndex =
                                g_legacyV89OverlayOwnerProbe.runStartPointerHits;
                            ++g_legacyV89OverlayOwnerProbe.runStartPointerHits;

                            if (hitIndex < maxTrackedPointerSlots)
                                runStartPointerSlots[hitIndex] = slot;

                            if (!g_legacyV89OverlayOwnerProbe.firstRunStartPointer)
                                g_legacyV89OverlayOwnerProbe.firstRunStartPointer = slot;
                        }
                    }

                    bytesExamined += primaryBytes;
                }
                else if (request >= sizeof(uintptr_t))
                {
                    ++readFailures;
                }

                if (remaining <= chunkSize)
                    break;

                chunkAddress += chunkSize;
            }
        }

        cursor = regionEnd;
    }

    g_legacyV89OverlayOwnerProbe.regionsExamined =
        regionsExamined;
    g_legacyV89OverlayOwnerProbe.readFailures =
        readFailures;
    g_legacyV89OverlayOwnerProbe.bytesExamined =
        bytesExamined;

    Logf(
        "[LegacyOverlayV89] pointerSummary scannedMiB=%llu regions=%u readFailures=%u direct{record=%u BennyField=%u groupField=%u runStart=%u} first{record=%p Benny=%p group=%p runStart=%p}.",
        static_cast<unsigned long long>(
            bytesExamined / (1024ULL * 1024ULL)),
        regionsExamined,
        readFailures,
        g_legacyV89OverlayOwnerProbe.recordPointerHits,
        g_legacyV89OverlayOwnerProbe.bennyPointerHits,
        g_legacyV89OverlayOwnerProbe.groupPointerHits,
        g_legacyV89OverlayOwnerProbe.runStartPointerHits,
        reinterpret_cast<void*>(
            g_legacyV89OverlayOwnerProbe.firstRecordPointer),
        reinterpret_cast<void*>(
            g_legacyV89OverlayOwnerProbe.firstBennyPointer),
        reinterpret_cast<void*>(
            g_legacyV89OverlayOwnerProbe.firstGroupPointer),
        reinterpret_cast<void*>(
            g_legacyV89OverlayOwnerProbe.firstRunStartPointer));

    const uint32_t trackedRecordPointers =
        g_legacyV89OverlayOwnerProbe.recordPointerHits
            < maxTrackedPointerSlots
        ? g_legacyV89OverlayOwnerProbe.recordPointerHits
        : maxTrackedPointerSlots;

    Logf(
        "[LegacyOverlayV90] discriminator recordStandalone=%s directRecordPointers=%u tracked=%u targetRecordOffset=0x%llX.",
        runCount == 1 ? "yes" : "no",
        g_legacyV89OverlayOwnerProbe.recordPointerHits,
        trackedRecordPointers,
        static_cast<unsigned long long>(
            record - allocationBase));

    for (uint32_t i = 0;
         i < trackedRecordPointers;
         ++i)
    {
        const uintptr_t slot = recordPointerSlots[i];
        if (!slot)
            continue;

        MEMORY_BASIC_INFORMATION slotMbi{};
        const SIZE_T queryResult = VirtualQuery(
            reinterpret_cast<LPCVOID>(slot),
            &slotMbi,
            sizeof(slotMbi));

        Logf(
            "[LegacyOverlayV90] recordPointer[%u] slot=%p slotOffset=0x%llX deltaToRecord=%+lld region=%p size=0x%llX protect=0x%08lX type=0x%08lX.",
            i,
            reinterpret_cast<void*>(slot),
            static_cast<unsigned long long>(
                slot - allocationBase),
            static_cast<long long>(
                static_cast<int64_t>(record)
                - static_cast<int64_t>(slot)),
            queryResult == sizeof(slotMbi)
                ? slotMbi.BaseAddress
                : nullptr,
            queryResult == sizeof(slotMbi)
                ? static_cast<unsigned long long>(slotMbi.RegionSize)
                : 0ULL,
            queryResult == sizeof(slotMbi)
                ? static_cast<unsigned long>(slotMbi.Protect)
                : 0UL,
            queryResult == sizeof(slotMbi)
                ? static_cast<unsigned long>(slotMbi.Type)
                : 0UL);

        LogLegacyV89PointerNeighborhood(
            "recordCandidate",
            slot,
            allocationBase,
            allocationEnd);
    }

    if (runStart != record)
    {
        const uint32_t trackedRunPointers =
            g_legacyV89OverlayOwnerProbe.runStartPointerHits
                < maxTrackedPointerSlots
            ? g_legacyV89OverlayOwnerProbe.runStartPointerHits
            : maxTrackedPointerSlots;

        for (uint32_t i = 0;
             i < trackedRunPointers;
             ++i)
        {
            const uintptr_t slot = runStartPointerSlots[i];
            if (!slot)
                continue;

            Logf(
                "[LegacyOverlayV90] runStartPointer[%u] slot=%p slotOffset=0x%llX.",
                i,
                reinterpret_cast<void*>(slot),
                static_cast<unsigned long long>(
                    slot - allocationBase));

            LogLegacyV89PointerNeighborhood(
                "runStartCandidate",
                slot,
                allocationBase,
                allocationEnd);
        }
    }

    if (trackedRecordPointers != 0)
    {
        ProbeLegacyV91PointerTableOwners(
            recordPointerSlots,
            trackedRecordPointers,
            allocationBase,
            allocationEnd);
    }
}

