    g_legacyV92ContextRegistry{};

static bool GetLegacyV92AllocationBounds(
    uintptr_t anchor,
    uintptr_t& allocationBase,
    uintptr_t& allocationEnd)
{
    allocationBase = 0;
    allocationEnd = 0;

    if (!anchor)
        return false;

    MEMORY_BASIC_INFORMATION anchorMbi{};
    if (VirtualQuery(
            reinterpret_cast<LPCVOID>(anchor),
            &anchorMbi,
            sizeof(anchorMbi)) == 0
        || anchorMbi.AllocationBase == nullptr
        || anchorMbi.Type == MEM_IMAGE)
    {
        return false;
    }

    allocationBase =
        reinterpret_cast<uintptr_t>(
            anchorMbi.AllocationBase);

    uintptr_t cursor = allocationBase;
    uintptr_t lastEnd = allocationBase;

    while (cursor >= allocationBase)
    {
        MEMORY_BASIC_INFORMATION mbi{};
        if (VirtualQuery(
                reinterpret_cast<LPCVOID>(cursor),
                &mbi,
                sizeof(mbi)) == 0)
        {
            break;
        }

        const uintptr_t regionBase =
            reinterpret_cast<uintptr_t>(
                mbi.BaseAddress);
        const uintptr_t regionAllocationBase =
            reinterpret_cast<uintptr_t>(
                mbi.AllocationBase);
        const uintptr_t regionEnd =
            regionBase
            + static_cast<uintptr_t>(
                mbi.RegionSize);

        if (regionEnd <= cursor)
            break;

        if (regionAllocationBase != allocationBase)
            break;

        if (regionEnd > lastEnd)
            lastEnd = regionEnd;

        cursor = regionEnd;
    }

    allocationEnd = lastEnd;
    return allocationEnd > allocationBase
        && anchor >= allocationBase
        && anchor < allocationEnd;
}

