static bool g_legacyV98OlderMutationCommitted = false;
static bool g_legacyV98OlderMutationFaulted = false;

static bool DecodeLegacyV98MemoryDisplacement(
    const uint8_t* instruction,
    const uint8_t* limit,
    bool requireRexW,
    uint8_t opcode0,
    uint8_t opcode1,
    bool twoByteOpcode,
    int32_t& displacement,
    size_t& instructionLength,
    bool& ripRelative)
{
    displacement = 0;
    instructionLength = 0;
    ripRelative = false;

    if (!instruction || !limit || instruction >= limit)
        return false;

    const uint8_t* p = instruction;
    bool operand16 = false;
    if (p < limit && *p == 0x66)
    {
        operand16 = true;
        ++p;
    }

    bool rexW = false;
    if (p < limit && (*p & 0xF0U) == 0x40U)
    {
        rexW = (*p & 0x08U) != 0;
        ++p;
    }

    if (requireRexW && !rexW)
        return false;

    if (twoByteOpcode)
    {
        if (p + 2 > limit || p[0] != opcode0 || p[1] != opcode1)
            return false;
        p += 2;
    }
    else
    {
        if (p + 1 > limit || p[0] != opcode0)
            return false;
        ++p;
    }

    (void)operand16;

    if (p >= limit)
        return false;

    const uint8_t modrm = *p++;
    const uint8_t mod = (modrm >> 6) & 0x03U;
    uint8_t rm = modrm & 0x07U;
    if (mod == 3)
        return false;

    bool sibPresent = false;
    uint8_t sibBase = 0;
    if (rm == 4)
    {
        if (p >= limit)
            return false;
        const uint8_t sib = *p++;
        sibPresent = true;
        sibBase = sib & 0x07U;
    }

    if (mod == 0)
    {
        if (!sibPresent && rm == 5)
        {
            if (p + 4 > limit)
                return false;
            memcpy(&displacement, p, sizeof(displacement));
            p += 4;
            ripRelative = true;
        }
        else if (sibPresent && sibBase == 5)
        {
            if (p + 4 > limit)
                return false;
            memcpy(&displacement, p, sizeof(displacement));
            p += 4;
        }
    }
    else if (mod == 1)
    {
        if (p + 1 > limit)
            return false;
        const int8_t disp8 = static_cast<int8_t>(*p++);
        displacement = static_cast<int32_t>(disp8);
    }
    else if (mod == 2)
    {
        if (p + 4 > limit)
            return false;
        memcpy(&displacement, p, sizeof(displacement));
        p += 4;
    }

    instructionLength = static_cast<size_t>(p - instruction);
    return true;
}

static bool FindLegacyV98ImmediateCall(
    uint8_t* base,
    uint8_t* end,
    uint8_t* functionStart,
    uint8_t* functionEnd,
    uint32_t immediateValue,
    uint8_t*& callsite,
    uint8_t*& target,
    uint32_t& matches)
{
    callsite = nullptr;
    target = nullptr;
    matches = 0;

    if (!base || !end || !functionStart || !functionEnd
        || functionEnd <= functionStart)
    {
        return false;
    }

    __try
    {
        for (uint8_t* p = functionStart;
             p + sizeof(uint32_t) <= functionEnd;
             ++p)
        {
            uint32_t value = 0;
            memcpy(&value, p, sizeof(value));
            if (value != immediateValue)
                continue;

            uint8_t* searchStart = p + sizeof(uint32_t);
            uint8_t* searchEnd = searchStart + 0x20;
            if (searchEnd > functionEnd)
                searchEnd = functionEnd;

            for (uint8_t* q = searchStart;
                 q + 5 <= searchEnd;
                 ++q)
            {
                if (q[0] != 0xE8)
                    continue;

                uint8_t* resolved = nullptr;
                if (!ResolveLegacyV86Rel32Call(
                        base,
                        end,
                        q,
                        resolved))
                {
                    continue;
                }

                ++matches;
                if (matches == 1)
                {
                    callsite = q;
                    target = resolved;
                }
                break;
            }
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        callsite = nullptr;
        target = nullptr;
        matches = 0;
        return false;
    }

    return matches == 1 && callsite && target;
}

static bool DiscoverLegacyV98Wrapper(
    uint8_t* base,
    uint8_t* end,
    const RUNTIME_FUNCTION* table,
    size_t tableCount)
{
    constexpr uint32_t storyGroup = 0x578F99E2U;
    constexpr uint32_t mapGroup = 0xBCC89179U;

    uint32_t candidates = 0;
    uintptr_t selectedWrapper = 0;
    uintptr_t selectedStoryCall = 0;
    uintptr_t selectedMapCall = 0;
    uintptr_t selectedGroupLoop = 0;

    __try
    {
        for (size_t i = 0; i < tableCount; ++i)
        {
            const RUNTIME_FUNCTION& entry = table[i];
            if (entry.BeginAddress >= entry.EndAddress
                || entry.EndAddress > static_cast<uint32_t>(end - base))
            {
                continue;
            }

            uint8_t* start = base + entry.BeginAddress;
            uint8_t* finish = base + entry.EndAddress;
            const size_t size = static_cast<size_t>(finish - start);
            if (size < 0x18 || size > 0x300)
                continue;

            uint8_t* storyCall = nullptr;
            uint8_t* storyTarget = nullptr;
            uint32_t storyMatches = 0;
            if (!FindLegacyV98ImmediateCall(
                    base,
                    end,
                    start,
                    finish,
                    storyGroup,
                    storyCall,
                    storyTarget,
                    storyMatches))
            {
                continue;
            }

            uint8_t* mapCall = nullptr;
            uint8_t* mapTarget = nullptr;
            uint32_t mapMatches = 0;
            if (!FindLegacyV98ImmediateCall(
                    base,
                    end,
                    start,
                    finish,
                    mapGroup,
                    mapCall,
                    mapTarget,
                    mapMatches)
                || mapCall <= storyCall
                || mapTarget != storyTarget)
            {
                continue;
            }

            ++candidates;

            if (candidates <= 8)
            {
                Logf(
                    "[UniversalLegacyV98] wrapperCandidate ordinal=%u wrapperRVA=0x%llX size=0x%llX storyCallRVA=0x%llX mapCallRVA=0x%llX sharedTargetRVA=0x%llX ordering=story-before-map.",
                    candidates,
                    static_cast<unsigned long long>(start - base),
                    static_cast<unsigned long long>(finish - start),
                    static_cast<unsigned long long>(storyCall - base),
                    static_cast<unsigned long long>(mapCall - base),
                    static_cast<unsigned long long>(storyTarget - base));
            }

            if (candidates == 1)
            {
                selectedWrapper = reinterpret_cast<uintptr_t>(start);
                selectedStoryCall = reinterpret_cast<uintptr_t>(storyCall);
                selectedMapCall = reinterpret_cast<uintptr_t>(mapCall);
                selectedGroupLoop = reinterpret_cast<uintptr_t>(storyTarget);
            }
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        g_legacyV98.faulted = true;
        return false;
    }

    g_legacyV98.wrapperCandidates = candidates;
    if (candidates != 1
        || !selectedWrapper
        || !selectedStoryCall
        || !selectedMapCall
        || !selectedGroupLoop)
    {
        return false;
    }

    g_legacyV98.wrapper = selectedWrapper;
    g_legacyV98.storyCallsite = selectedStoryCall;
    g_legacyV98.mapCallsite = selectedMapCall;
    g_legacyV98.groupLoop = selectedGroupLoop;
    g_legacyV98.wrapperResolved = true;
    g_legacyV98.groupLoopResolved = true;
    return true;
}

static bool DiscoverLegacyV98GroupLayout(
    uint8_t* base,
    uint8_t* end)
{
    uint8_t* loop = reinterpret_cast<uint8_t*>(g_legacyV98.groupLoop);
    if (!loop)
        return false;

    uint8_t* loopStart = nullptr;
    uint8_t* loopEnd = nullptr;
    if (!FindRuntimeFunctionBounds(
            base,
            end,
            loop,
            loopStart,
            loopEnd)
        || loopStart != loop
        || !loopEnd
        || loopEnd <= loopStart)
    {
        return false;
    }

    uint32_t candidates = 0;
    uint32_t selectedStride = 0;
    uint32_t selectedArrayOffset = 0;
    uint32_t selectedCountOffset = 0;
    uint32_t selectedHashOffset = 0;
    uintptr_t selectedWorkerCallsite = 0;
    uintptr_t selectedWorker = 0;

    __try
    {
        for (uint8_t* p = loopStart;
             p + 7 <= loopEnd;
             ++p)
        {
            if ((p[0] & 0xF8U) != 0x48U
                || p[1] != 0x69)
            {
                continue;
            }

            const uint8_t modrm = p[2];
            if (((modrm >> 6) & 0x03U) != 3)
                continue;

            uint32_t stride = 0;
            memcpy(&stride, p + 3, sizeof(stride));
            if (stride < 0x60
                || stride > 0x300
                || (stride & 0x07U) != 0)
            {
                continue;
            }

            uint8_t* afterImul = p + 7;
            uint8_t* nearEnd = afterImul + 0x28;
            if (nearEnd > loopEnd)
                nearEnd = loopEnd;

            uint32_t hashOffset = 0;
            uint8_t* workerCallsite = nullptr;
            uint8_t* worker = nullptr;
            bool hashAndCall = false;

            for (uint8_t* q = afterImul;
                 q < nearEnd;
                 ++q)
            {
                int32_t disp = 0;
                size_t movLength = 0;
                bool ripRelative = false;
                if (!DecodeLegacyV98MemoryDisplacement(
                        q,
                        nearEnd,
                        false,
                        0x8B,
                        0,
                        false,
                        disp,
                        movLength,
                        ripRelative)
                    || ripRelative
                    || disp < 0
                    || static_cast<uint32_t>(disp) >= stride)
                {
                    continue;
                }

                uint8_t* callSearchStart = q + movLength;
                uint8_t* callSearchEnd = callSearchStart + 8;
                if (callSearchEnd > nearEnd)
                    callSearchEnd = nearEnd;

                for (uint8_t* c = callSearchStart;
                     c + 5 <= callSearchEnd;
                     ++c)
                {
                    if (c[0] != 0xE8)
                        continue;

                    uint8_t* resolved = nullptr;
                    if (ResolveLegacyV86Rel32Call(
                            base,
                            end,
                            c,
                            resolved))
                    {
                        hashOffset = static_cast<uint32_t>(disp);
                        workerCallsite = c;
                        worker = resolved;
                        hashAndCall = true;
                    }
                    break;
                }

                if (hashAndCall)
                    break;
            }

            if (!hashAndCall)
                continue;

            uint32_t arrayOffset = 0;
            bool arrayFound = false;
            uint8_t* arrayInstruction = nullptr;
            uint8_t* backwardStart =
                p >= loopStart + 0x30 ? p - 0x30 : loopStart;
            for (uint8_t* q = backwardStart; q < p; ++q)
            {
                int32_t disp = 0;
                size_t length = 0;
                bool ripRelative = false;
                if (DecodeLegacyV98MemoryDisplacement(
                        q,
                        p,
                        true,
                        0x8B,
                        0,
                        false,
                        disp,
                        length,
                        ripRelative)
                    && !ripRelative
                    && disp >= 0
                    && disp <= 0x100)
                {
                    arrayOffset = static_cast<uint32_t>(disp);
                    arrayInstruction = q;
                    arrayFound = true;
                }
            }

            if (!arrayFound || !arrayInstruction)
                continue;

            uint32_t countOffset = 0;
            bool countFound = false;
            uint8_t* countSearchStart =
                arrayInstruction >= loopStart + 0x40
                    ? arrayInstruction - 0x40
                    : loopStart;

            for (uint8_t* q = countSearchStart;
                 q < arrayInstruction;
                 ++q)
            {
                if (q + 3 >= arrayInstruction || q[0] != 0x66)
                    continue;

                const uint8_t* op = q + 1;
                if (*op != 0x3B && *op != 0x39 && *op != 0x8B)
                    continue;

                int32_t disp = 0;
                size_t length = 0;
                bool ripRelative = false;
                if (DecodeLegacyV98MemoryDisplacement(
                        q,
                        arrayInstruction,
                        false,
                        *op,
                        0,
                        false,
                        disp,
                        length,
                        ripRelative)
                    && !ripRelative
                    && disp >= 0
                    && disp <= 0x100
                    && static_cast<uint32_t>(disp) != arrayOffset)
                {
                    countOffset = static_cast<uint32_t>(disp);
                    countFound = true;
                }
            }

            if (!countFound)
                continue;

            ++candidates;
            if (candidates == 1)
            {
                selectedStride = stride;
                selectedArrayOffset = arrayOffset;
                selectedCountOffset = countOffset;
                selectedHashOffset = hashOffset;
                selectedWorkerCallsite =
                    reinterpret_cast<uintptr_t>(workerCallsite);
                selectedWorker = reinterpret_cast<uintptr_t>(worker);
            }
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        g_legacyV98.faulted = true;
        return false;
    }

    if (candidates != 1
        || !selectedStride
        || !selectedWorkerCallsite
        || !selectedWorker)
    {
        return false;
    }

    g_legacyV98.childArrayOffset = selectedArrayOffset;
    g_legacyV98.childCountOffset = selectedCountOffset;
    g_legacyV98.childStride = selectedStride;
    g_legacyV98.childHashOffset = selectedHashOffset;
    g_legacyV98.workerCallsite = selectedWorkerCallsite;
    g_legacyV98.worker = selectedWorker;
    g_legacyV98.groupLayoutResolved = true;
    return true;
}

static bool ValidateLegacyV98Context(
    uintptr_t context,
    uintptr_t& childArray,
    uint16_t& childCount,
    LONG& lowriderIndex,
    uintptr_t& lowriderChild)
{
    childArray = 0;
    childCount = 0;
    lowriderIndex = -1;
    lowriderChild = 0;

    if (!context
        || !g_legacyV98.groupLayoutResolved
        || g_legacyV98.childStride == 0)
    {
        return false;
    }

    if (!ReadProcessExact(
            context + g_legacyV98.childArrayOffset,
            &childArray,
            sizeof(childArray))
        || !ReadProcessExact(
            context + g_legacyV98.childCountOffset,
            &childCount,
            sizeof(childCount))
        || !childArray
        || childCount == 0
        || childCount > 4096)
    {
        return false;
    }

    uint32_t lowriderMatches = 0;
    for (uint16_t i = 0; i < childCount; ++i)
    {
        const uintptr_t child =
            childArray
            + (static_cast<uintptr_t>(i)
                * static_cast<uintptr_t>(g_legacyV98.childStride));
        uint32_t hash = 0;
        if (!ReadProcessExact(
                child + g_legacyV98.childHashOffset,
                &hash,
                sizeof(hash)))
        {
            return false;
        }

        if (hash == 0x61322A35U)
        {
            ++lowriderMatches;
            if (lowriderMatches == 1)
            {
                lowriderIndex = static_cast<LONG>(i);
                lowriderChild = child;
            }
        }
    }

    return lowriderMatches == 1 && lowriderChild != 0;
}

static void CollectLegacyV98RipGlobals(
    uint8_t* functionStart,
    uint8_t* functionEnd,
    std::vector<uintptr_t>& globals)
{
    globals.clear();
    if (!functionStart || !functionEnd || functionEnd <= functionStart)
        return;

    for (uint8_t* p = functionStart;
         p + 7 <= functionEnd;
         ++p)
    {
        const uint8_t* q = p;
        if ((*q & 0xF0U) != 0x40U
            || (*q & 0x08U) == 0)
        {
            continue;
        }
        ++q;

        if (q + 6 > functionEnd || q[0] != 0x8B)
            continue;

        const uint8_t modrm = q[1];
        if (((modrm >> 6) & 0x03U) != 0
            || (modrm & 0x07U) != 5)
        {
            continue;
        }

        int32_t relative = 0;
        memcpy(&relative, q + 2, sizeof(relative));
        const uintptr_t globalAddress =
            reinterpret_cast<uintptr_t>(q + 6)
            + static_cast<int64_t>(relative);

        bool duplicate = false;
        for (size_t i = 0; i < globals.size(); ++i)
        {
            if (globals[i] == globalAddress)
            {
                duplicate = true;
                break;
            }
        }
        if (!duplicate)
            globals.push_back(globalAddress);
    }
}

static bool DiscoverLegacyV98Context(
    uint8_t* base,
    uint8_t* end,
    const RUNTIME_FUNCTION* table,
    size_t tableCount)
{
    if (!g_legacyV98.wrapperResolved
        || !g_legacyV98.groupLayoutResolved)
    {
        return false;
    }

    uint8_t* wrapper = reinterpret_cast<uint8_t*>(g_legacyV98.wrapper);
    uint32_t contextCandidates = 0;

    uintptr_t selectedOwner = 0;
    uintptr_t selectedCallsite = 0;
    uintptr_t selectedGlobal = 0;
    uintptr_t selectedContext = 0;
    uintptr_t selectedChildArray = 0;
    uint16_t selectedChildCount = 0;
    LONG selectedIndex = -1;
    uintptr_t selectedChild = 0;

    for (size_t i = 0; i < tableCount; ++i)
    {
        const RUNTIME_FUNCTION& entry = table[i];
        if (entry.BeginAddress >= entry.EndAddress
            || entry.EndAddress > static_cast<uint32_t>(end - base))
        {
            continue;
        }

        uint8_t* start = base + entry.BeginAddress;
        uint8_t* finish = base + entry.EndAddress;
        const size_t size = static_cast<size_t>(finish - start);
        if (size < 0x18 || size > 0x500)
            continue;

        std::vector<uint8_t*> wrapperCalls;
        for (uint8_t* p = start; p + 5 <= finish; ++p)
        {
            if (p[0] != 0xE8)
                continue;
            uint8_t* target = nullptr;
            if (ResolveLegacyV86Rel32Call(
                    base,
                    end,
                    p,
                    target)
                && target == wrapper)
            {
                wrapperCalls.push_back(p);
            }
        }

        if (wrapperCalls.size() != 1)
            continue;

        std::vector<uintptr_t> globals;
        CollectLegacyV98RipGlobals(start, finish, globals);
        if (globals.empty())
            continue;

        for (size_t g = 0; g < globals.size(); ++g)
        {
            uintptr_t context = 0;
            if (!ReadProcessExact(
                    globals[g],
                    &context,
                    sizeof(context))
                || !context)
            {
                continue;
            }

            uintptr_t childArray = 0;
            uint16_t childCount = 0;
            LONG lowriderIndex = -1;
            uintptr_t lowriderChild = 0;
            if (!ValidateLegacyV98Context(
                    context,
                    childArray,
                    childCount,
                    lowriderIndex,
                    lowriderChild))
            {
                continue;
            }

            ++contextCandidates;
            if (contextCandidates == 1)
            {
                selectedOwner = reinterpret_cast<uintptr_t>(start);
                selectedCallsite =
                    reinterpret_cast<uintptr_t>(wrapperCalls[0]);
                selectedGlobal = globals[g];
                selectedContext = context;
                selectedChildArray = childArray;
                selectedChildCount = childCount;
                selectedIndex = lowriderIndex;
                selectedChild = lowriderChild;
            }
        }
    }
    g_legacyV98.contextCandidates = contextCandidates;
    if (contextCandidates != 1
        || !selectedOwner
        || !selectedGlobal
        || !selectedContext
        || !selectedChild)
    {
        return false;
    }

    g_legacyV98.contextOwner = selectedOwner;
    g_legacyV98.contextOwnerCallsite = selectedCallsite;
    g_legacyV98.contextGlobal = selectedGlobal;
    g_legacyV98.context = selectedContext;
    g_legacyV98.childArray = selectedChildArray;
    g_legacyV98.childCount = selectedChildCount;
    g_legacyV98.lowriderIndex = selectedIndex;
    g_legacyV98.lowriderChild = selectedChild;
    g_legacyV98.contextOwnerResolved = true;
    g_legacyV98.contextResolved = true;
    g_legacyV98.childResolved = true;
    return true;
}

static uint16_t CountLegacyV98AssociatedHash(
    uintptr_t table,
    uint16_t count,
    uint32_t hash)
{
    if (!table || count == 0 || count > 512)
        return 0;

    uint16_t matches = 0;
    for (uint16_t i = 0; i < count; ++i)
    {
        uint32_t value = 0;
        if (!ReadProcessExact(
                table + (static_cast<uintptr_t>(i) * sizeof(uint32_t)),
                &value,
                sizeof(value)))
        {
            return 0xFFFF;
        }
        if (value == hash)
            ++matches;
    }
    return matches;
}

static bool DiscoverLegacyV98DescriptorLayout()
{
    const uintptr_t child = g_legacyV98.lowriderChild;
    const uint32_t childStride = g_legacyV98.childStride;
    if (!child || childStride < 0x40)
        return false;

    static const uint32_t descriptorStrides[] =
    {
        0x18U, 0x20U, 0x10U, 0x28U, 0x30U
    };

    uint32_t candidates = 0;

    for (uint32_t vectorOffset = 0x20;
         vectorOffset + 0x0C < childStride;
         vectorOffset += 8)
    {
        uintptr_t table = 0;
        uint16_t count = 0;
        uint16_t capacity = 0;
        if (!ReadProcessExact(
                child + vectorOffset,
                &table,
                sizeof(table))
            || !ReadProcessExact(
                child + vectorOffset + 8,
                &count,
                sizeof(count))
            || !ReadProcessExact(
                child + vectorOffset + 10,
                &capacity,
                sizeof(capacity))
            || !table
            || count == 0
            || count > 64
            || capacity < count
            || capacity > 512)
        {
            continue;
        }

        for (size_t ds = 0;
             ds < sizeof(descriptorStrides) / sizeof(descriptorStrides[0]);
             ++ds)
        {
            const uint32_t descriptorStride = descriptorStrides[ds];
            size_t readable = 0;
            const size_t bytes =
                static_cast<size_t>(count) * descriptorStride;
            if (!GetLegacyV57ReadableSpan(
                    table,
                    bytes,
                    readable)
                || readable < bytes)
            {
                continue;
            }

            for (uint32_t groupOffset = 0;
                 groupOffset <= 0x0C
                    && groupOffset + 4 <= descriptorStride;
                 groupOffset += 4)
            {
                uint16_t mapDescriptors = 0;
                uint16_t mapIndex = 0xFFFF;

                for (uint16_t i = 0; i < count; ++i)
                {
                    uint32_t group = 0;
                    if (!ReadProcessExact(
                            table
                                + (static_cast<uintptr_t>(i) * descriptorStride)
                                + groupOffset,
                            &group,
                            sizeof(group)))
                    {
                        mapDescriptors = 0xFFFF;
                        break;
                    }
                    if (group == 0xBCC89179U)
                    {
                        ++mapDescriptors;
                        mapIndex = i;
                    }
                }

                if (mapDescriptors != 1 || mapIndex == 0xFFFF)
                    continue;

                const uintptr_t mapDescriptor =
                    table
                    + (static_cast<uintptr_t>(mapIndex) * descriptorStride);

                for (uint32_t associatedOffset = 0;
                     associatedOffset + 10 <= descriptorStride;
                     associatedOffset += 8)
                {
                    if (associatedOffset == groupOffset)
                        continue;

                    uintptr_t associatedTable = 0;
                    uint16_t associatedCount = 0;
                    if (!ReadProcessExact(
                            mapDescriptor + associatedOffset,
                            &associatedTable,
                            sizeof(associatedTable))
                        || !ReadProcessExact(
                            mapDescriptor + associatedOffset + 8,
                            &associatedCount,
                            sizeof(associatedCount))
                        || !associatedTable
                        || associatedCount == 0
                        || associatedCount > 512)
                    {
                        continue;
                    }

                    const uint16_t mapBenny =
                        CountLegacyV98AssociatedHash(
                            associatedTable,
                            associatedCount,
                            0x4CDFC843U);
                    if (mapBenny != 1)
                        continue;

                    uint16_t storyBenny = 0;
                    bool storyReadable = true;
                    for (uint16_t i = 0; i < count; ++i)
                    {
                        const uintptr_t descriptor =
                            table
                            + (static_cast<uintptr_t>(i) * descriptorStride);
                        uint32_t group = 0;
                        if (!ReadProcessExact(
                                descriptor + groupOffset,
                                &group,
                                sizeof(group)))
                        {
                            storyReadable = false;
                            break;
                        }
                        if (group != 0x578F99E2U)
                            continue;

                        uintptr_t storyTable = 0;
                        uint16_t storyCount = 0;
                        if (!ReadProcessExact(
                                descriptor + associatedOffset,
                                &storyTable,
                                sizeof(storyTable))
                            || !ReadProcessExact(
                                descriptor + associatedOffset + 8,
                                &storyCount,
                                sizeof(storyCount))
                            || !storyTable
                            || storyCount == 0
                            || storyCount > 512)
                        {
                            storyReadable = false;
                            break;
                        }

                        const uint16_t local =
                            CountLegacyV98AssociatedHash(
                                storyTable,
                                storyCount,
                                0x4CDFC843U);
                        if (local == 0xFFFF)
                        {
                            storyReadable = false;
                            break;
                        }
                        storyBenny = static_cast<uint16_t>(storyBenny + local);
                    }

                    if (!storyReadable || storyBenny != 0)
                        continue;

                    ++candidates;
                    if (candidates == 1)
                    {
                        g_legacyV98.descriptorVectorOffset = vectorOffset;
                        g_legacyV98.descriptorCountOffset = vectorOffset + 8;
                        g_legacyV98.descriptorCapacityOffset = vectorOffset + 10;
                        g_legacyV98.descriptorStride = descriptorStride;
                        g_legacyV98.descriptorGroupOffset = groupOffset;
                        g_legacyV98.descriptorAssociatedOffset = associatedOffset;
                        g_legacyV98.descriptorAssociatedCountOffset =
                            associatedOffset + 8;
                        g_legacyV98.descriptorTable = table;
                        g_legacyV98.descriptorCount = count;
                        g_legacyV98.mapDescriptorIndex = mapIndex;
                        g_legacyV98.mapAssociatedCount = associatedCount;
                        g_legacyV98.mapBennyCount = mapBenny;
                        g_legacyV98.storyBennyCount = storyBenny;
                    }
                }
            }
        }
    }

    g_legacyV98.descriptorCandidates = candidates;
    g_legacyV98.descriptorResolved = candidates == 1;
    return g_legacyV98.descriptorResolved;
}

static bool DiscoverLegacyV98DerivedLayout()
{
    const uintptr_t child = g_legacyV98.lowriderChild;
    const uint32_t childStride = g_legacyV98.childStride;
    if (!child || childStride < 0x30)
        return false;

    constexpr uint32_t commonGroup = 0x5BF6578FU;
    constexpr uint32_t stockKey0 = 0xA0DF2C6FU;
    constexpr uint32_t stockKey1 = 0x37B569AAU;

    uint32_t candidates = 0;
    for (uint32_t vectorOffset = 0x20;
         vectorOffset + 0x14 < childStride;
         vectorOffset += 8)
    {
        uintptr_t table = 0;
        uint16_t count = 0;
        uint16_t capacity = 0;
        if (!ReadProcessExact(
                child + vectorOffset,
                &table,
                sizeof(table))
            || !ReadProcessExact(
                child + vectorOffset + 8,
                &count,
                sizeof(count))
            || !ReadProcessExact(
                child + vectorOffset + 10,
                &capacity,
                sizeof(capacity))
            || !table
            || count != 2
            || capacity < 2
            || capacity > 512)
        {
            continue;
        }

        uint32_t pairs[4]{};
        if (!ReadProcessExact(table, pairs, sizeof(pairs)))
            continue;

        if (pairs[0] != commonGroup
            || pairs[1] != stockKey0
            || pairs[2] != commonGroup
            || pairs[3] != stockKey1)
        {
            continue;
        }

        uint8_t flags = 0;
        ReadProcessExact(
            child + vectorOffset + 0x10,
            &flags,
            sizeof(flags));

        ++candidates;
        if (candidates == 1)
        {
            g_legacyV98.derivedVectorOffset = vectorOffset;
            g_legacyV98.derivedCountOffset = vectorOffset + 8;
            g_legacyV98.derivedCapacityOffset = vectorOffset + 10;
            g_legacyV98.derivedFlagsOffset = vectorOffset + 0x10;
            g_legacyV98.derivedTable = table;
            g_legacyV98.derivedCount = count;
            g_legacyV98.derivedCapacity = capacity;
            g_legacyV98.derivedFlags = flags;
        }
    }

    g_legacyV98.derivedCandidates = candidates;
    g_legacyV98.derivedResolved = candidates == 1;
    return g_legacyV98.derivedResolved;
}

static bool MatchLegacyV98BennyOverlayRecord(
    uintptr_t record,
    uint32_t& group)
{
    group = 0;
    uint32_t fields[5]{};
    if (!ReadProcessExact(record, fields, sizeof(fields)))
        return false;

    if (fields[0] != 0x61322A35U
        || fields[1] != 0xF9904BBCU
        || fields[2] != 0x4CDFC843U
        || (fields[3] != 0xBCC89179U
            && fields[3] != 0x578F99E2U)
        || fields[4] != 1U)
    {
        return false;
    }

    group = fields[3];
    return true;
}

static bool ProbeLegacyV98OverlayRegistryAtOffset(
    uintptr_t context,
    uintptr_t allocationBase,
    uintptr_t allocationEnd,
    uint32_t contextOffset,
    uintptr_t& registryStart,
    uint32_t& registryEntries,
    uint32_t& exactMapHits,
    uint32_t& exactStoryHits,
    uintptr_t& recordAddress)
{
    registryStart = 0;
    registryEntries = 0;
    exactMapHits = 0;
    exactStoryHits = 0;
    recordAddress = 0;

    if (!ReadProcessExact(
            context + contextOffset,
            &registryStart,
            sizeof(registryStart))
        || registryStart < allocationBase
        || registryStart >= allocationEnd
        || (registryStart & (sizeof(uintptr_t) - 1U)) != 0)
    {
        return false;
    }

    constexpr uint32_t maxEntries = 1024;
    bool terminated = false;
    for (uint32_t i = 0; i < maxEntries; ++i)
    {
        uintptr_t entry = 0;
        if (!ReadProcessExact(
                registryStart
                    + (static_cast<uintptr_t>(i) * sizeof(uintptr_t)),
                &entry,
                sizeof(entry)))
        {
            return false;
        }

        if (entry < allocationBase || entry >= allocationEnd)
        {
            terminated = true;
            break;
        }

        ++registryEntries;
        uint32_t group = 0;
        if (MatchLegacyV98BennyOverlayRecord(entry, group))
        {
            if (group == 0xBCC89179U)
                ++exactMapHits;
            else if (group == 0x578F99E2U)
                ++exactStoryHits;
            recordAddress = entry;
        }
    }

    if (!terminated
        || registryEntries < 8
        || (exactMapHits + exactStoryHits) != 1)
    {
        return false;
    }

    return true;
}

static bool DiscoverLegacyV98OverlayRegistry()
{
    if (!g_legacyV98.context || !g_legacyV98.lowriderChild)
        return false;

    uintptr_t allocationBase = 0;
    uintptr_t allocationEnd = 0;
    if (!GetLegacyV92AllocationBounds(
            g_legacyV98.lowriderChild,
            allocationBase,
            allocationEnd)
        || g_legacyV98.context < allocationBase
        || g_legacyV98.context >= allocationEnd)
    {
        return false;
    }

    uint32_t candidates = 0;
    for (uint32_t offset = 0;
         offset <= 0x80;
         offset += static_cast<uint32_t>(sizeof(uintptr_t)))
    {
        uintptr_t registry = 0;
        uint32_t entries = 0;
        uint32_t mapHits = 0;
        uint32_t storyHits = 0;
        uintptr_t record = 0;
        if (!ProbeLegacyV98OverlayRegistryAtOffset(
                g_legacyV98.context,
                allocationBase,
                allocationEnd,
                offset,
                registry,
                entries,
                mapHits,
                storyHits,
                record))
        {
            continue;
        }

        ++candidates;
        if (candidates == 1)
        {
            g_legacyV98.overlayRegistryOffset = offset;
            g_legacyV98.overlayRegistryStart = registry;
            g_legacyV98.overlayRegistryEntries = entries;
            g_legacyV98.overlayExactMapHits = mapHits;
            g_legacyV98.overlayExactStoryHits = storyHits;
            g_legacyV98.overlayRecord = record;
        }
    }

    g_legacyV98.overlayCandidates = candidates;
    g_legacyV98.overlayResolved = candidates == 1;
    return g_legacyV98.overlayResolved;
}

static bool FunctionContainsLegacyV98DescriptorCountAccess(
    uint8_t* start,
    uint8_t* finish,
    uint32_t descriptorCountOffset)
{
    if (!start || !finish || finish <= start)
        return false;

    for (uint8_t* p = start; p + 4 <= finish; ++p)
    {
        const uint8_t* q = p;
        if ((*q & 0xF0U) == 0x40U)
            ++q;
        if (q + 3 > finish || q[0] != 0x0F || q[1] != 0xB7)
            continue;

        int32_t disp = 0;
        size_t length = 0;
        bool ripRelative = false;
        if (DecodeLegacyV98MemoryDisplacement(
                p,
                finish,
                false,
                0x0F,
                0xB7,
                true,
                disp,
                length,
                ripRelative)
            && !ripRelative
            && disp >= 0
            && static_cast<uint32_t>(disp) == descriptorCountOffset)
        {
            return true;
        }
    }
    return false;
}

static bool HasLegacyV98AddTrueSetup(
    uint8_t* functionStart,
    uint8_t* callsite)
{
    if (!functionStart || !callsite || callsite <= functionStart)
        return false;

    uint8_t* scanStart =
        callsite >= functionStart + 0x30
            ? callsite - 0x30
            : functionStart;

    for (uint8_t* p = scanStart; p + 3 <= callsite; ++p)
    {

        if (p[0] == 0x41 && p[1] == 0xB1 && p[2] == 0x01)
            return true;

        if (p + 6 <= callsite
            && p[0] == 0x41
            && p[1] == 0xB9
            && p[2] == 0x01
            && p[3] == 0x00
            && p[4] == 0x00
            && p[5] == 0x00)
        {
            return true;
        }
    }
    return false;
}

static bool DecodeLegacyV98LeaDestination(
    const uint8_t* instruction,
    const uint8_t* limit,
    uint8_t& destinationRegister,
    size_t& instructionLength)
{
    destinationRegister = 0xFFU;
    instructionLength = 0;

    if (!instruction || !limit || instruction >= limit)
        return false;

    const uint8_t* p = instruction;
    uint8_t rex = 0;
    if (p < limit && (*p & 0xF0U) == 0x40U)
    {
        rex = *p;
        ++p;
    }

    if (p >= limit || *p != 0x8D)
        return false;
    ++p;

    if (p >= limit)
        return false;

    const uint8_t modrm = *p++;
    const uint8_t mod = (modrm >> 6) & 0x03U;
    if (mod == 3)
        return false;

    destinationRegister =
        static_cast<uint8_t>(
            ((modrm >> 3) & 0x07U)
            | ((rex & 0x04U) ? 0x08U : 0x00U));

    const uint8_t rm = modrm & 0x07U;
    bool sibPresent = false;
    uint8_t sibBase = 0;
    if (rm == 4)
    {
        if (p >= limit)
            return false;
        const uint8_t sib = *p++;
        sibPresent = true;
        sibBase = sib & 0x07U;
    }

    if (mod == 0)
    {
        if ((!sibPresent && rm == 5)
            || (sibPresent && sibBase == 5))
        {
            if (p + 4 > limit)
                return false;
            p += 4;
        }
    }
    else if (mod == 1)
    {
        if (p + 1 > limit)
            return false;
        ++p;
    }
    else if (mod == 2)
    {
        if (p + 4 > limit)
            return false;
        p += 4;
    }

    instructionLength =
        static_cast<size_t>(p - instruction);
    return instructionLength >= 2;
}

static bool HasLegacyV98PairPointerCallShape(
    uint8_t* functionStart,
    uint8_t* callsite)
{
    if (!functionStart || !callsite || callsite <= functionStart)
        return false;

    uint8_t* scanStart =
        callsite >= functionStart + 0x30
            ? callsite - 0x30
            : functionStart;

    bool rdxPointer = false;
    bool r8Pointer = false;

    for (uint8_t* p = scanStart; p < callsite; ++p)
    {
        uint8_t destination = 0xFFU;
        size_t length = 0;
        if (!DecodeLegacyV98LeaDestination(
                p,
                callsite,
                destination,
                length))
        {
            continue;
        }

        if (destination == 2U)
            rdxPointer = true;
        else if (destination == 8U)
            r8Pointer = true;

        if (rdxPointer && r8Pointer)
            return true;
    }

    return false;
}

static bool DiscoverLegacyV98Construction(
    uint8_t* base,
    uint8_t* end,
    const RUNTIME_FUNCTION* table,
    size_t tableCount)
{
    if (!g_legacyV98.descriptorResolved)
        return false;

    uint32_t candidates = 0;
    uintptr_t selectedOwner = 0;
    uintptr_t selectedCallsite = 0;
    uintptr_t selectedMutator = 0;

    __try
    {
        for (size_t i = 0; i < tableCount; ++i)
        {
            const RUNTIME_FUNCTION& entry = table[i];
            if (entry.BeginAddress >= entry.EndAddress
                || entry.EndAddress > static_cast<uint32_t>(end - base))
            {
                continue;
            }

            uint8_t* start = base + entry.BeginAddress;
            uint8_t* finish = base + entry.EndAddress;
            const size_t size = static_cast<size_t>(finish - start);
            if (size < 0x80 || size > 0x1000)
                continue;

            if (!FunctionContainsLegacyV98DescriptorCountAccess(
                    start,
                    finish,
                    g_legacyV98.descriptorCountOffset))
            {
                continue;
            }

            for (uint8_t* p = start; p + 5 <= finish; ++p)
            {
                if (p[0] != 0xE8
                    || !HasLegacyV98AddTrueSetup(start, p)
                    || !HasLegacyV98PairPointerCallShape(start, p))
                {
                    continue;
                }

                uint8_t* target = nullptr;
                if (!ResolveLegacyV86Rel32Call(
                        base,
                        end,
                        p,
                        target))
                {
                    continue;
                }

                uint8_t* targetStart = nullptr;
                uint8_t* targetEnd = nullptr;
                const bool targetHasPdata =
                    FindRuntimeFunctionBounds(
                        base,
                        end,
                        target,
                        targetStart,
                        targetEnd)
                    && targetStart
                    && targetEnd
                    && targetEnd > targetStart;
                const bool targetIsFunctionStart =
                    targetHasPdata && targetStart == target;

                const uint32_t ordinal = candidates + 1;
                if (ordinal <= 8)
                {
                    Logf(
                        "[UniversalLegacyV98] constructionCandidate ordinal=%u ownerRVA=0x%llX ownerSize=0x%llX callsiteRVA=0x%llX callOffset=0x%llX targetRVA=0x%llX targetPdata=%s targetStartRVA=0x%llX targetSize=0x%llX.",
                        ordinal,
                        static_cast<unsigned long long>(start - base),
                        static_cast<unsigned long long>(finish - start),
                        static_cast<unsigned long long>(p - base),
                        static_cast<unsigned long long>(p - start),
                        static_cast<unsigned long long>(target - base),
                        targetIsFunctionStart ? "start"
                            : (targetHasPdata ? "inside" : "no"),
                        targetHasPdata
                            ? static_cast<unsigned long long>(targetStart - base)
                            : 0ULL,
                        targetHasPdata
                            ? static_cast<unsigned long long>(targetEnd - targetStart)
                            : 0ULL);

                    LogBoundedBytes(
                        base,
                        end,
                        p,
                        0x30,
                        0x10,
                        "Universal Legacy v98e construction candidate callsite");
                }

                ++candidates;
                if (candidates == 1)
                {
                    selectedOwner = reinterpret_cast<uintptr_t>(start);
                    selectedCallsite = reinterpret_cast<uintptr_t>(p);
                    selectedMutator = reinterpret_cast<uintptr_t>(target);
                }
            }
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        g_legacyV98.faulted = true;
        return false;
    }

    g_legacyV98.constructionCandidates = candidates;
    if (candidates != 1
        || !selectedOwner
        || !selectedCallsite
        || !selectedMutator)
    {
        return false;
    }

    g_legacyV98.constructionOwner = selectedOwner;
    g_legacyV98.constructionCallsite = selectedCallsite;
    g_legacyV98.addMutator = selectedMutator;
    g_legacyV98.constructionResolved = true;
    return true;
}

static void LogLegacyV98UniversalResolverState(
    const char* phase,
    uint8_t* base)
{
    const auto rva = [base](uintptr_t address) -> unsigned long long
    {
        return base && address >= reinterpret_cast<uintptr_t>(base)
            ? static_cast<unsigned long long>(
                address - reinterpret_cast<uintptr_t>(base))
            : 0ULL;
    };

    Logf(
        "[UniversalLegacyV98] %s version=%d image=%s pdata=%s wrapper{ok=%s candidates=%u rva=0x%llX storyCall=0x%llX mapCall=0x%llX groupLoop=0x%llX worker=0x%llX} layout{ok=%s array=0x%X count=0x%X stride=0x%X hash=0x%X} context{ok=%s candidates=%u owner=0x%llX global=0x%llX context=%p array=%p count=%u index=%ld child=%p} descriptor{ok=%s candidates=%u vector=0x%X countOff=0x%X capOff=0x%X stride=0x%X groupOff=0x%X assocOff=0x%X assocCountOff=0x%X count=%u mapIndex=%u mapAssoc=%u mapBenny=%u storyBenny=%u} derived{ok=%s candidates=%u vector=0x%X countOff=0x%X capOff=0x%X flagsOff=0x%X count=%u cap=%u flags=0x%02X} overlay{ok=%s candidates=%u contextOff=0x%X registry=%p entries=%u mapHits=%u storyHits=%u record=%p} construction{ok=%s candidates=%u owner=0x%llX callsite=0x%llX mutator=0x%llX} oracle{checked=%s matched=%s} ready=%s mutationAttempted=no faulted=%s.",
        phase ? phase : "",
        g_legacyV98.gameVersion,
        g_legacyV98.imageValid ? "yes" : "no",
        g_legacyV98.runtimeTableValid ? "yes" : "no",
        g_legacyV98.wrapperResolved ? "yes" : "no",
        g_legacyV98.wrapperCandidates,
        rva(g_legacyV98.wrapper),
        rva(g_legacyV98.storyCallsite),
        rva(g_legacyV98.mapCallsite),
        rva(g_legacyV98.groupLoop),
        rva(g_legacyV98.worker),
        g_legacyV98.groupLayoutResolved ? "yes" : "no",
        g_legacyV98.childArrayOffset,
        g_legacyV98.childCountOffset,
        g_legacyV98.childStride,
        g_legacyV98.childHashOffset,
        g_legacyV98.contextResolved ? "yes" : "no",
        g_legacyV98.contextCandidates,
        rva(g_legacyV98.contextOwner),
        rva(g_legacyV98.contextGlobal),
        reinterpret_cast<void*>(g_legacyV98.context),
        reinterpret_cast<void*>(g_legacyV98.childArray),
        static_cast<unsigned int>(g_legacyV98.childCount),
        static_cast<long>(g_legacyV98.lowriderIndex),
        reinterpret_cast<void*>(g_legacyV98.lowriderChild),
        g_legacyV98.descriptorResolved ? "yes" : "no",
        g_legacyV98.descriptorCandidates,
        g_legacyV98.descriptorVectorOffset,
        g_legacyV98.descriptorCountOffset,
        g_legacyV98.descriptorCapacityOffset,
        g_legacyV98.descriptorStride,
        g_legacyV98.descriptorGroupOffset,
        g_legacyV98.descriptorAssociatedOffset,
        g_legacyV98.descriptorAssociatedCountOffset,
        static_cast<unsigned int>(g_legacyV98.descriptorCount),
        static_cast<unsigned int>(g_legacyV98.mapDescriptorIndex),
        static_cast<unsigned int>(g_legacyV98.mapAssociatedCount),
        static_cast<unsigned int>(g_legacyV98.mapBennyCount),
        static_cast<unsigned int>(g_legacyV98.storyBennyCount),
        g_legacyV98.derivedResolved ? "yes" : "no",
        g_legacyV98.derivedCandidates,
        g_legacyV98.derivedVectorOffset,
        g_legacyV98.derivedCountOffset,
        g_legacyV98.derivedCapacityOffset,
        g_legacyV98.derivedFlagsOffset,
        static_cast<unsigned int>(g_legacyV98.derivedCount),
        static_cast<unsigned int>(g_legacyV98.derivedCapacity),
        static_cast<unsigned int>(g_legacyV98.derivedFlags),
        g_legacyV98.overlayResolved ? "yes" : "no",
        g_legacyV98.overlayCandidates,
        g_legacyV98.overlayRegistryOffset,
        reinterpret_cast<void*>(g_legacyV98.overlayRegistryStart),
        g_legacyV98.overlayRegistryEntries,
        g_legacyV98.overlayExactMapHits,
        g_legacyV98.overlayExactStoryHits,
        reinterpret_cast<void*>(g_legacyV98.overlayRecord),
        g_legacyV98.constructionResolved ? "yes" : "no",
        g_legacyV98.constructionCandidates,
        rva(g_legacyV98.constructionOwner),
        rva(g_legacyV98.constructionCallsite),
        rva(g_legacyV98.addMutator),
        g_legacyV98.knownBuildOracleChecked ? "yes" : "no",
        g_legacyV98.knownBuildOracleMatched ? "yes" : "no",
        g_legacyV98.readyForMutationResearch ? "yes" : "no",
        g_legacyV98.faulted ? "yes" : "no");
}

static bool RunLegacyV98UniversalResolver(
    const char* phase)
{
    g_legacyV98 = LegacyV98UniversalResolverState{};
    g_legacyV98.attempted = true;
    g_legacyV98.gameVersion = getGameVersion();
    g_legacyV98.legacyImage = IsLegacyExecutableImage();

    if (!g_legacyV98.legacyImage)
        return false;

    uint8_t* base = nullptr;
    uint8_t* end = nullptr;
    if (!GetExeRange(base, end)
        || !base
        || !end
        || end <= base)
    {
        LogLegacyV98UniversalResolverState(phase, base);
        return false;
    }
    g_legacyV98.imageValid = true;

    const RUNTIME_FUNCTION* table = nullptr;
    size_t tableCount = 0;
    if (!GetLegacyV86RuntimeFunctionTable(
            base,
            end,
            table,
            tableCount))
    {
        LogLegacyV98UniversalResolverState(phase, base);
        return false;
    }
    g_legacyV98.runtimeTableValid = true;

    const bool wrapper =
        DiscoverLegacyV98Wrapper(base, end, table, tableCount);
    const bool layout =
        wrapper && DiscoverLegacyV98GroupLayout(base, end);
    const bool context =
        layout && DiscoverLegacyV98Context(base, end, table, tableCount);
    const bool descriptor =
        context && DiscoverLegacyV98DescriptorLayout();
    const bool derived =
        context && DiscoverLegacyV98DerivedLayout();
    const bool overlay =
        context && DiscoverLegacyV98OverlayRegistry();
    const bool construction =
        descriptor
        && DiscoverLegacyV98Construction(base, end, table, tableCount);

    (void)derived;
    (void)overlay;
    (void)construction;

    g_legacyV98.readyForMutationResearch =
        wrapper
        && layout
        && context
        && descriptor
        && g_legacyV98.derivedResolved
        && g_legacyV98.overlayResolved
        && g_legacyV98.constructionResolved
        && !g_legacyV98.faulted;

    if (g_legacyV98.gameVersion == 102)
    {
        g_legacyV98.knownBuildOracleChecked = true;
        g_legacyV98.knownBuildOracleMatched =
            g_legacyV98.readyForMutationResearch
            && g_legacyV98.childArrayOffset == 0x28U
            && g_legacyV98.childCountOffset == 0x30U
            && g_legacyV98.childStride == 0xF0U
            && g_legacyV98.childHashOffset == 0x60U
            && g_legacyV98.descriptorVectorOffset == 0x78U
            && g_legacyV98.descriptorCountOffset == 0x80U
            && g_legacyV98.derivedVectorOffset == 0xD8U
            && g_legacyV98.overlayRegistryOffset == 0x08U
            && g_legacyV98.constructionOwner
                == reinterpret_cast<uintptr_t>(base + 0x92A4B8)
            && g_legacyV98.constructionCallsite
                == reinterpret_cast<uintptr_t>(base + 0x92A985)
            && g_legacyV98.addMutator
                == reinterpret_cast<uintptr_t>(base + 0x95443C);
    }

    LogLegacyV98UniversalResolverState(phase, base);
    return g_legacyV98.readyForMutationResearch;
}

