static EnhancedV99UniversalResolverState g_enhancedV99{};

static bool EnhancedV99PrefixEquals(
    uint8_t* start,
    uint8_t* finish,
    const uint8_t* prefix,
    size_t prefixSize)
{
    return start
        && finish
        && finish > start
        && prefix
        && prefixSize != 0
        && static_cast<size_t>(finish - start) >= prefixSize
        && memcmp(start, prefix, prefixSize) == 0;
}

static bool EnhancedV99LooksLikeAbsoluteJump12(
    uint8_t* start,
    uint8_t* finish)
{
    return start
        && finish
        && finish > start
        && static_cast<size_t>(finish - start) >= 12
        && start[0] == 0x48
        && start[1] == 0xB8
        && start[10] == 0xFF
        && start[11] == 0xE0;
}

static uint32_t EnhancedV99CountDirectCallsToTarget(
    uint8_t* base,
    uint8_t* end,
    uint8_t* functionStart,
    uint8_t* functionEnd,
    uint8_t* target,
    uintptr_t* callsites,
    uint32_t callsiteCapacity)
{
    if (!base || !end || !functionStart || !functionEnd
        || functionEnd <= functionStart || !target)
    {
        return 0;
    }

    uint32_t matches = 0;
    for (uint8_t* p = functionStart; p + 5 <= functionEnd; ++p)
    {
        if (p[0] != 0xE8)
            continue;

        uint8_t* resolved = nullptr;
        if (!ResolveLegacyV86Rel32Call(base, end, p, resolved)
            || resolved != target)
        {
            continue;
        }

        if (callsites && matches < callsiteCapacity)
            callsites[matches] = reinterpret_cast<uintptr_t>(p);
        ++matches;
    }
    return matches;
}

static bool DiscoverEnhancedV99StructuralChain(
    uint8_t* base,
    uint8_t* end,
    const RUNTIME_FUNCTION* table,
    size_t tableCount)
{
    static const uint8_t groupLoopPrefix[16] =
    {
        0x41, 0x57,
        0x41, 0x56,
        0x41, 0x55,
        0x41, 0x54,
        0x56,
        0x57,
        0x55,
        0x53,
        0x48, 0x83, 0xEC, 0x48
    };

    static const uint8_t workerPrefix[14] =
    {
        0x41, 0x57,
        0x41, 0x56,
        0x41, 0x54,
        0x56,
        0x57,
        0x55,
        0x53,
        0x48, 0x83, 0xEC, 0x30
    };

    struct ChainCandidate
    {
        uintptr_t groupLoop;
        uintptr_t workerCallsite;
        uintptr_t worker;
        uintptr_t owner;
        uint32_t ownerCandidates;
        uint32_t ownerCalls;
        bool groupLoopDetoured;
        bool workerDetoured;
    };

    constexpr uint32_t maxChainCandidates = 64;
    ChainCandidate chains[maxChainCandidates]{};
    uint32_t rawChainCandidates = 0;
    uint32_t storedChainCandidates = 0;

    for (size_t i = 0; i < tableCount; ++i)
    {
        const RUNTIME_FUNCTION& rf = table[i];
        if (rf.BeginAddress >= rf.EndAddress
            || rf.EndAddress > static_cast<uint32_t>(end - base))
        {
            continue;
        }

        uint8_t* candidate = base + rf.BeginAddress;
        uint8_t* candidateEnd = base + rf.EndAddress;
        const bool naturalGroupLoop =
            EnhancedV99PrefixEquals(
                candidate,
                candidateEnd,
                groupLoopPrefix,
                sizeof(groupLoopPrefix));
        const bool detouredGroupLoop =
            !naturalGroupLoop
            && EnhancedV99LooksLikeAbsoluteJump12(
                candidate,
                candidateEnd);
        if (!naturalGroupLoop && !detouredGroupLoop)
            continue;

        for (uint8_t* p = candidate; p + 5 <= candidateEnd; ++p)
        {
            if (p[0] != 0xE8)
                continue;

            uint8_t* target = nullptr;
            if (!ResolveLegacyV86Rel32Call(base, end, p, target))
                continue;

            uint8_t* targetStart = nullptr;
            uint8_t* targetEnd = nullptr;
            if (!FindRuntimeFunctionBounds(
                    base,
                    end,
                    target,
                    targetStart,
                    targetEnd)
                || targetStart != target)
            {
                continue;
            }

            const bool naturalWorker =
                EnhancedV99PrefixEquals(
                    targetStart,
                    targetEnd,
                    workerPrefix,
                    sizeof(workerPrefix));
            const bool detouredWorker =
                !naturalWorker
                && EnhancedV99LooksLikeAbsoluteJump12(
                    targetStart,
                    targetEnd);
            if (!naturalWorker && !detouredWorker)
                continue;

            const uint32_t workerCalls =
                EnhancedV99CountDirectCallsToTarget(
                    base,
                    end,
                    candidate,
                    candidateEnd,
                    target,
                    nullptr,
                    0);
            if (workerCalls != 1)
                continue;

            ++rawChainCandidates;
            if (storedChainCandidates >= maxChainCandidates)
                continue;

            ChainCandidate& chain =
                chains[storedChainCandidates++];
            chain.groupLoop =
                reinterpret_cast<uintptr_t>(candidate);
            chain.workerCallsite =
                reinterpret_cast<uintptr_t>(p);
            chain.worker =
                reinterpret_cast<uintptr_t>(target);
            chain.groupLoopDetoured = detouredGroupLoop;
            chain.workerDetoured = detouredWorker;
        }
    }

    if (rawChainCandidates == 0
        || rawChainCandidates > maxChainCandidates
        || storedChainCandidates != rawChainCandidates)
    {
        Logf(
            "[UniversalEnhancedV99] structuralFilter rawChains=%u storedChains=%u overflow=%s qualifiedChains=0.",
            rawChainCandidates,
            storedChainCandidates,
            rawChainCandidates > maxChainCandidates ? "yes" : "no");
        g_enhancedV99.groupLoopCandidates = 0;
        return false;
    }

    for (size_t i = 0; i < tableCount; ++i)
    {
        const RUNTIME_FUNCTION& rf = table[i];
        if (rf.BeginAddress >= rf.EndAddress
            || rf.EndAddress > static_cast<uint32_t>(end - base))
        {
            continue;
        }

        uint8_t* ownerStart = base + rf.BeginAddress;
        uint8_t* ownerEnd = base + rf.EndAddress;
        uint32_t callsPerChain[maxChainCandidates]{};

        for (uint8_t* p = ownerStart; p + 5 <= ownerEnd; ++p)
        {
            if (p[0] != 0xE8)
                continue;

            uint8_t* target = nullptr;
            if (!ResolveLegacyV86Rel32Call(base, end, p, target))
                continue;

            const uintptr_t targetAddress =
                reinterpret_cast<uintptr_t>(target);
            for (uint32_t c = 0; c < storedChainCandidates; ++c)
            {
                if (targetAddress == chains[c].groupLoop)
                    ++callsPerChain[c];
            }
        }

        for (uint32_t c = 0; c < storedChainCandidates; ++c)
        {
            if (callsPerChain[c] != 3)
                continue;

            ChainCandidate& chain = chains[c];
            ++chain.ownerCandidates;
            if (chain.ownerCandidates == 1)
            {
                chain.owner =
                    reinterpret_cast<uintptr_t>(ownerStart);
                chain.ownerCalls = callsPerChain[c];
            }
        }
    }

    uint32_t qualifiedChains = 0;
    uintptr_t selectedGroupLoop = 0;
    uintptr_t selectedWorkerCallsite = 0;
    uintptr_t selectedWorker = 0;
    uintptr_t selectedOwner = 0;
    uint32_t selectedOwnerCandidates = 0;
    uint32_t selectedOwnerCalls = 0;

    for (uint32_t c = 0; c < storedChainCandidates; ++c)
    {
        const ChainCandidate& chain = chains[c];
        if (c < 16)
        {
            Logf(
                "[UniversalEnhancedV99] chainCandidate ordinal=%u groupLoopRVA=0x%llX workerCallRVA=0x%llX workerRVA=0x%llX entry{%s,%s} ownerCandidates=%u ownerRVA=0x%llX ownerCalls=%u qualifies=%s.",
                c + 1,
                static_cast<unsigned long long>(
                    chain.groupLoop
                    - reinterpret_cast<uintptr_t>(base)),
                static_cast<unsigned long long>(
                    chain.workerCallsite
                    - reinterpret_cast<uintptr_t>(base)),
                static_cast<unsigned long long>(
                    chain.worker
                    - reinterpret_cast<uintptr_t>(base)),
                chain.groupLoopDetoured ? "detoured" : "natural",
                chain.workerDetoured ? "detoured" : "natural",
                chain.ownerCandidates,
                chain.owner
                    ? static_cast<unsigned long long>(
                        chain.owner
                        - reinterpret_cast<uintptr_t>(base))
                    : 0ULL,
                chain.ownerCalls,
                chain.ownerCandidates == 1 ? "yes" : "no");
        }

        if (chain.ownerCandidates != 1
            || !chain.owner
            || chain.ownerCalls != 3)
        {
            continue;
        }

        ++qualifiedChains;
        if (qualifiedChains == 1)
        {
            selectedGroupLoop = chain.groupLoop;
            selectedWorkerCallsite = chain.workerCallsite;
            selectedWorker = chain.worker;
            selectedOwner = chain.owner;
            selectedOwnerCandidates = chain.ownerCandidates;
            selectedOwnerCalls = chain.ownerCalls;
        }
    }

    Logf(
        "[UniversalEnhancedV99] structuralFilter rawChains=%u storedChains=%u overflow=no qualifiedChains=%u.",
        rawChainCandidates,
        storedChainCandidates,
        qualifiedChains);

    g_enhancedV99.groupLoopCandidates = qualifiedChains;
    g_enhancedV99.ownerCandidates = selectedOwnerCandidates;

    if (qualifiedChains != 1
        || !selectedGroupLoop
        || !selectedWorkerCallsite
        || !selectedWorker
        || !selectedOwner
        || selectedOwnerCandidates != 1
        || selectedOwnerCalls != 3)
    {
        return false;
    }

    g_enhancedV99.groupLoop = selectedGroupLoop;
    g_enhancedV99.workerCallsite = selectedWorkerCallsite;
    g_enhancedV99.worker = selectedWorker;
    g_enhancedV99.owner = selectedOwner;
    g_enhancedV99.ownerCallsToGroupLoop = selectedOwnerCalls;
    g_enhancedV99.ownerResolved = true;
    g_enhancedV99.structuralResolved = true;
    return true;
}

static bool EnhancedV99IsOwnerGroupLoopCallsite(
    uint8_t* base,
    uint8_t* end,
    uintptr_t ownerAddress,
    uintptr_t groupLoopAddress,
    uintptr_t callsiteAddress)
{
    if (!base || !end || !ownerAddress || !groupLoopAddress || !callsiteAddress)
        return false;

    uint8_t* owner = reinterpret_cast<uint8_t*>(ownerAddress);
    uint8_t* ownerStart = nullptr;
    uint8_t* ownerEnd = nullptr;
    if (!FindRuntimeFunctionBounds(base, end, owner, ownerStart, ownerEnd)
        || ownerStart != owner
        || !ownerEnd
        || ownerEnd <= ownerStart)
    {
        return false;
    }

    uint8_t* callsite = reinterpret_cast<uint8_t*>(callsiteAddress);
    if (callsite < ownerStart || callsite + 5 > ownerEnd)
        return false;

    uint8_t* resolved = nullptr;
    return ResolveLegacyV86Rel32Call(base, end, callsite, resolved)
        && resolved == reinterpret_cast<uint8_t*>(groupLoopAddress);
}

static bool DiscoverEnhancedV99LiveContext(
    uint8_t* base,
    uint8_t* end)
{
    constexpr uint32_t storyGroup = 0x578F99E2U;
    constexpr uint32_t mplowrider = 0x61322A35U;

    const LONG observed = InterlockedCompareExchange(
        &g_v52C26F00ObservationCount,
        0,
        0);
    const LONG capacity = static_cast<LONG>(
        sizeof(g_v52C26F00CallerObservations)
        / sizeof(g_v52C26F00CallerObservations[0]));
    const LONG count = observed < capacity ? observed : capacity;

    uint32_t matches = 0;
    uintptr_t selectedContext = 0;
    uintptr_t selectedChild = 0;
    uintptr_t selectedCallsite = 0;

    for (LONG i = 0; i < count; ++i)
    {
        const V52C26F00CallerObservation& o =
            g_v52C26F00CallerObservations[i];

        if (o.groupHashValue != storyGroup
            || o.childField80 != mplowrider
            || !o.context
            || !o.child
            || !EnhancedV99IsOwnerGroupLoopCallsite(
                base,
                end,
                g_enhancedV99.owner,
                g_enhancedV99.groupLoop,
                o.callsite))
        {
            continue;
        }

        ++matches;
        if (matches == 1)
        {
            selectedContext = o.context;
            selectedChild = o.child;
            selectedCallsite = o.callsite;
        }
    }

    if (matches != 1
        || !selectedContext
        || !selectedChild
        || !selectedCallsite)
    {
        return false;
    }

    g_enhancedV99.context = selectedContext;
    g_enhancedV99.child = selectedChild;
    g_enhancedV99.naturalStoryCallsite = selectedCallsite;
    g_enhancedV99.naturalStoryCallResolved = true;
    g_enhancedV99.liveContextResolved = true;
    return true;
}

static bool EnhancedV99ValidateChildLayoutCandidate(
    uintptr_t array,
    uint16_t count,
    uint32_t stride,
    uint32_t hashOffset,
    uintptr_t targetChild,
    LONG& targetIndex)
{
    constexpr uint32_t mplowrider = 0x61322A35U;
    targetIndex = -1;

    if (!array || count == 0 || count > 4096
        || stride < 0x40 || stride > 0x400
        || hashOffset + sizeof(uint32_t) > stride
        || targetChild < array)
    {
        return false;
    }

    const uintptr_t delta = targetChild - array;
    if ((delta % stride) != 0)
        return false;

    const uintptr_t index = delta / stride;
    if (index >= count)
        return false;

    uint32_t targetHash = 0;
    if (!ReadProcessExact(
            targetChild + hashOffset,
            &targetHash,
            sizeof(targetHash))
        || targetHash != mplowrider)
    {
        return false;
    }

    uint32_t lowriderHits = 0;
    uint32_t distinctSample[64]{};
    uint32_t distinctCount = 0;

    const uint16_t sampleCount = count < 64 ? count : 64;
    for (uint16_t i = 0; i < count; ++i)
    {
        uint32_t hash = 0;
        if (!ReadProcessExact(
                array + (static_cast<uintptr_t>(i) * stride) + hashOffset,
                &hash,
                sizeof(hash))
            || hash == 0)
        {
            return false;
        }

        if (hash == mplowrider)
            ++lowriderHits;

        if (i < sampleCount)
        {
            for (uint32_t d = 0; d < distinctCount; ++d)
            {
                if (distinctSample[d] == hash)
                    return false;
            }

            distinctSample[distinctCount++] = hash;
        }
    }

    if (lowriderHits != 1
        || sampleCount < 4
        || distinctCount != sampleCount)
    {
        return false;
    }

    targetIndex = static_cast<LONG>(index);
    return true;
}

static bool DiscoverEnhancedV99ChildLayout()
{
    if (!g_enhancedV99.liveContextResolved
        || !g_enhancedV99.context
        || !g_enhancedV99.child)
    {
        return false;
    }

    constexpr uint32_t mplowrider = 0x61322A35U;
    uint32_t hashOffsets[16]{};
    uint32_t hashOffsetCount = 0;
    for (uint32_t off = 0; off <= 0x180; off += 4)
    {
        uint32_t value = 0;
        if (ReadProcessExact(
                g_enhancedV99.child + off,
                &value,
                sizeof(value))
            && value == mplowrider
            && hashOffsetCount < 16)
        {
            hashOffsets[hashOffsetCount++] = off;
        }
    }

    uint32_t candidates = 0;
    uint32_t selectedArrayOff = 0;
    uint32_t selectedCountOff = 0;
    uint32_t selectedStride = 0;
    uint32_t selectedHashOff = 0;
    uintptr_t selectedArray = 0;
    uint16_t selectedCount = 0;
    LONG selectedIndex = -1;

    for (uint32_t arrayOff = 0; arrayOff <= 0x80; arrayOff += 8)
    {
        uintptr_t array = 0;
        if (!ReadProcessExact(
                g_enhancedV99.context + arrayOff,
                &array,
                sizeof(array))
            || !array
            || g_enhancedV99.child < array)
        {
            continue;
        }

        const uint32_t countOff = arrayOff + static_cast<uint32_t>(sizeof(uintptr_t));
        if (countOff + sizeof(uint16_t) > 0x100)
            continue;

        uint16_t count = 0;
        if (!ReadProcessExact(
                g_enhancedV99.context + countOff,
                &count,
                sizeof(count))
            || count == 0
            || count > 4096)
        {
            continue;
        }

        const uintptr_t delta = g_enhancedV99.child - array;
        for (uint32_t stride = 0x80; stride <= 0x200; stride += 0x10)
        {
            if ((delta % stride) != 0)
                continue;
            const uintptr_t index = delta / stride;
            if (index >= count)
                continue;

            for (uint32_t h = 0; h < hashOffsetCount; ++h)
            {
                const uint32_t hashOff = hashOffsets[h];
                if (hashOff + sizeof(uint32_t) > stride)
                    continue;

                LONG candidateIndex = -1;
                if (!EnhancedV99ValidateChildLayoutCandidate(
                        array,
                        count,
                        stride,
                        hashOff,
                        g_enhancedV99.child,
                        candidateIndex))
                {
                    continue;
                }

                ++candidates;
                if (candidates <= 8)
                {
                    Logf(
                        "[UniversalEnhancedV99] layoutCandidate ordinal=%u arrayOff=0x%X countOff=0x%X stride=0x%X hashOff=0x%X count=%u index=%ld array=%p child=%p.",
                        candidates,
                        arrayOff,
                        countOff,
                        stride,
                        hashOff,
                        static_cast<unsigned int>(count),
                        candidateIndex,
                        reinterpret_cast<void*>(array),
                        reinterpret_cast<void*>(g_enhancedV99.child));
                }

                if (candidates == 1)
                {
                    selectedArrayOff = arrayOff;
                    selectedCountOff = countOff;
                    selectedStride = stride;
                    selectedHashOff = hashOff;
                    selectedArray = array;
                    selectedCount = count;
                    selectedIndex = candidateIndex;
                }
            }
        }
    }

    g_enhancedV99.layoutCandidates = candidates;
    if (candidates != 1)
        return false;

    g_enhancedV99.childArrayOffset = selectedArrayOff;
    g_enhancedV99.childCountOffset = selectedCountOff;
    g_enhancedV99.childStride = selectedStride;
    g_enhancedV99.childHashOffset = selectedHashOff;
    g_enhancedV99.childArray = selectedArray;
    g_enhancedV99.childCount = selectedCount;
    g_enhancedV99.childIndex = selectedIndex;
    g_enhancedV99.layoutResolved = true;
    return true;
}

static bool EnhancedV99AssociatedContains(
    uintptr_t table,
    uint16_t count,
    uint32_t wanted,
    uint16_t& matches)
{
    matches = 0;
    if (count == 0)
        return true;
    if (!table || count > 4096)
        return false;

    for (uint16_t i = 0; i < count; ++i)
    {
        uint32_t value = 0;
        if (!ReadProcessExact(
                table + (static_cast<uintptr_t>(i) * sizeof(uint32_t)),
                &value,
                sizeof(value)))
        {
            return false;
        }
        if (value == wanted)
            ++matches;
    }
    return true;
}

static bool DiscoverEnhancedV99DescriptorLayout()
{
    if (!g_enhancedV99.layoutResolved || !g_enhancedV99.child)
        return false;

    constexpr uint32_t groupMap = 0xBCC89179U;
    constexpr uint32_t groupStory = 0x578F99E2U;
    constexpr uint32_t benny = 0x4CDFC843U;
    constexpr uint16_t maxAssociatedPerDescriptor = 256;

    struct SourcePair
    {
        uint32_t group;
        uint32_t associated;
    };

    SourcePair sourcePairs[2][8]{};
    uint16_t sourcePairCounts[2]{};

    const LONG observed = InterlockedCompareExchange(
        &g_v51C272A0ObservationCount,
        0,
        0);
    const LONG observationCapacity = static_cast<LONG>(
        sizeof(g_v51C272A0CallerObservations)
        / sizeof(g_v51C272A0CallerObservations[0]));
    const LONG observationCount =
        observed < observationCapacity ? observed : observationCapacity;

    for (LONG i = 0; i < observationCount; ++i)
    {
        const V51C272A0CallerObservation& o =
            g_v51C272A0CallerObservations[i];

        if (o.arg2 != g_enhancedV99.child
            || o.groupBefore == 0
            || o.associatedBefore == 0)
        {
            continue;
        }

        const uint32_t semanticGroups[2] =
        {
            o.groupBefore,
            o.associatedBefore
        };
        const uint32_t semanticAssociated[2] =
        {
            o.associatedBefore,
            o.groupBefore
        };

        for (uint32_t orientation = 0; orientation < 2; ++orientation)
        {
            const uint32_t semanticGroup = semanticGroups[orientation];
            const uint32_t semanticValue = semanticAssociated[orientation];

            if (semanticGroup == benny || semanticValue == benny)
                continue;

            bool duplicate = false;
            for (uint16_t p = 0;
                 p < sourcePairCounts[orientation];
                 ++p)
            {
                if (sourcePairs[orientation][p].group == semanticGroup
                    && sourcePairs[orientation][p].associated == semanticValue)
                {
                    duplicate = true;
                    break;
                }
            }

            if (!duplicate
                && sourcePairCounts[orientation]
                    < static_cast<uint16_t>(
                        sizeof(sourcePairs[orientation])
                        / sizeof(sourcePairs[orientation][0])))
            {
                const uint16_t slot = sourcePairCounts[orientation]++;
                sourcePairs[orientation][slot].group = semanticGroup;
                sourcePairs[orientation][slot].associated = semanticValue;
            }
        }
    }

    Logf(
        "[UniversalEnhancedV99] descriptorSourceFingerprint direct=%u swapped=%u.",
        static_cast<unsigned int>(sourcePairCounts[0]),
        static_cast<unsigned int>(sourcePairCounts[1]));

    g_enhancedV99.descriptorSourcePairsObserved =
        sourcePairCounts[0] > sourcePairCounts[1]
            ? sourcePairCounts[0]
            : sourcePairCounts[1];

    if (sourcePairCounts[0] < 2 && sourcePairCounts[1] < 2)
        return false;

    uint32_t candidates = 0;
    uint32_t selectedVectorOff = 0;
    uint32_t selectedStride = 0;
    uint32_t selectedGroupOff = 0;
    uint32_t selectedAssocOff = 0;
    uint32_t selectedAssocCountOff = 0;
    uintptr_t selectedTable = 0;
    uint16_t selectedCount = 0;
    uint16_t selectedMapDescriptors = 0;
    uint16_t selectedStoryDescriptors = 0;
    uint16_t selectedMapBenny = 0;
    uint16_t selectedStoryBenny = 0;
    uint16_t selectedSourcePairsMatched = 0;
    uint16_t selectedSourcePairsObserved = 0;
    bool selectedFieldsSwapped = false;

    for (uint32_t orientation = 0; orientation < 2; ++orientation)
    {
        const uint16_t sourcePairCount = sourcePairCounts[orientation];
        if (sourcePairCount < 2)
            continue;

        const SourcePair* activeSourcePairs = sourcePairs[orientation];

        for (uint32_t vectorOff = 0;
             vectorOff + 0x0A <= g_enhancedV99.childStride;
             vectorOff += 8)
        {
            uintptr_t table = 0;
            uint16_t count = 0;
            uint16_t capacity = 0;

            if (!ReadProcessExact(
                    g_enhancedV99.child + vectorOff,
                    &table,
                    sizeof(table))
                || !ReadProcessExact(
                    g_enhancedV99.child + vectorOff + 8,
                    &count,
                    sizeof(count))
                || !table
                || count == 0
                || count > 64)
            {
                continue;
            }

            (void)ReadProcessExact(
                g_enhancedV99.child + vectorOff + 10,
                &capacity,
                sizeof(capacity));

            const uint32_t strides[] =
            {
                0x18U, 0x20U, 0x10U, 0x28U, 0x30U
            };
            const uint32_t groupOffsets[] = { 0x00U, 0x04U };
            const uint32_t assocOffsets[] = { 0x08U, 0x10U };

            for (uint32_t stride : strides)
            {
                for (uint32_t groupOff : groupOffsets)
                {
                    for (uint32_t assocOff : assocOffsets)
                    {
                        const uint32_t assocCountOff = assocOff + 8;
                        if (groupOff + sizeof(uint32_t) > stride
                            || assocOff + sizeof(uintptr_t) > stride
                            || assocCountOff + sizeof(uint16_t) > stride)
                        {
                            continue;
                        }

                        bool valid = true;
                        bool pairMatched[8]{};
                        uint16_t mapDescriptors = 0;
                        uint16_t storyDescriptors = 0;
                        uint16_t mapBenny = 0;
                        uint16_t storyBenny = 0;

                        for (uint16_t i = 0; i < count; ++i)
                        {
                            const uintptr_t record =
                                table + (static_cast<uintptr_t>(i) * stride);
                            uint32_t group = 0;
                            uintptr_t associated = 0;
                            uint16_t associatedCount = 0;

                            if (!ReadProcessExact(
                                    record + groupOff,
                                    &group,
                                    sizeof(group))
                                || !ReadProcessExact(
                                    record + assocOff,
                                    &associated,
                                    sizeof(associated))
                                || !ReadProcessExact(
                                    record + assocCountOff,
                                    &associatedCount,
                                    sizeof(associatedCount))
                                || associatedCount > maxAssociatedPerDescriptor
                                || (associatedCount != 0 && !associated))
                            {
                                valid = false;
                                break;
                            }

                            if (group == groupMap)
                                ++mapDescriptors;
                            else if (group == groupStory)
                                ++storyDescriptors;

                            for (uint16_t j = 0; j < associatedCount; ++j)
                            {
                                uint32_t value = 0;
                                if (!ReadProcessExact(
                                        associated
                                            + (static_cast<uintptr_t>(j)
                                                * sizeof(uint32_t)),
                                        &value,
                                        sizeof(value)))
                                {
                                    valid = false;
                                    break;
                                }

                                if (value == benny)
                                {
                                    if (group == groupMap)
                                        ++mapBenny;
                                    else if (group == groupStory)
                                        ++storyBenny;
                                }

                                for (uint16_t p = 0;
                                     p < sourcePairCount;
                                     ++p)
                                {
                                    if (!pairMatched[p]
                                        && group == activeSourcePairs[p].group
                                        && value == activeSourcePairs[p].associated)
                                    {
                                        pairMatched[p] = true;
                                    }
                                }
                            }

                            if (!valid)
                                break;
                        }

                        if (!valid)
                            continue;

                        uint16_t sourcePairsMatched = 0;
                        for (uint16_t p = 0; p < sourcePairCount; ++p)
                        {
                            if (pairMatched[p])
                                ++sourcePairsMatched;
                        }

                        if (sourcePairsMatched != sourcePairCount)
                            continue;

                        ++candidates;
                        if (candidates <= 8)
                        {
                            Logf(
                                "[UniversalEnhancedV99] descriptorCandidate ordinal=%u sourceOrientation=%s vectorOff=0x%X countOff=0x%X capOff=0x%X stride=0x%X groupOff=0x%X assocOff=0x%X assocCountOff=0x%X count=%u capacity=%u sourcePairs=%u/%u mapDescriptors=%u storyDescriptors=%u mapBenny=%u storyBenny=%u table=%p.",
                                candidates,
                                orientation != 0 ? "swapped" : "direct",
                                vectorOff,
                                vectorOff + 8,
                                vectorOff + 10,
                                stride,
                                groupOff,
                                assocOff,
                                assocCountOff,
                                static_cast<unsigned int>(count),
                                static_cast<unsigned int>(capacity),
                                static_cast<unsigned int>(sourcePairsMatched),
                                static_cast<unsigned int>(sourcePairCount),
                                static_cast<unsigned int>(mapDescriptors),
                                static_cast<unsigned int>(storyDescriptors),
                                static_cast<unsigned int>(mapBenny),
                                static_cast<unsigned int>(storyBenny),
                                reinterpret_cast<void*>(table));
                        }

                        if (candidates == 1)
                        {
                            selectedVectorOff = vectorOff;
                            selectedStride = stride;
                            selectedGroupOff = groupOff;
                            selectedAssocOff = assocOff;
                            selectedAssocCountOff = assocCountOff;
                            selectedTable = table;
                            selectedCount = count;
                            selectedMapDescriptors = mapDescriptors;
                            selectedStoryDescriptors = storyDescriptors;
                            selectedMapBenny = mapBenny;
                            selectedStoryBenny = storyBenny;
                            selectedSourcePairsMatched = sourcePairsMatched;
                            selectedSourcePairsObserved = sourcePairCount;
                            selectedFieldsSwapped = orientation != 0;
                        }
                    }
                }
            }
        }
    }

    g_enhancedV99.descriptorCandidates = candidates;
    if (candidates != 1)
        return false;

    g_enhancedV99.descriptorVectorOffset = selectedVectorOff;
    g_enhancedV99.descriptorCountOffset = selectedVectorOff + 8;
    g_enhancedV99.descriptorCapacityOffset = selectedVectorOff + 10;
    g_enhancedV99.descriptorStride = selectedStride;
    g_enhancedV99.descriptorGroupOffset = selectedGroupOff;
    g_enhancedV99.descriptorAssociatedOffset = selectedAssocOff;
    g_enhancedV99.descriptorAssociatedCountOffset = selectedAssocCountOff;
    g_enhancedV99.descriptorTable = selectedTable;
    g_enhancedV99.descriptorCount = selectedCount;
    g_enhancedV99.mapDescriptorCount = selectedMapDescriptors;
    g_enhancedV99.storyDescriptorCount = selectedStoryDescriptors;
    g_enhancedV99.mapBennyCount = selectedMapBenny;
    g_enhancedV99.storyBennyCount = selectedStoryBenny;
    g_enhancedV99.descriptorSourcePairsObserved = selectedSourcePairsObserved;
    g_enhancedV99.descriptorSourcePairsMatched = selectedSourcePairsMatched;
    g_enhancedV99.descriptorSourceFieldsSwapped = selectedFieldsSwapped;
    g_enhancedV99.descriptorResolved = true;
    return true;
}

static bool ResolveEnhancedV100StructuralBootstrapAtModuleLoad()
{
    if (g_enhancedV100.bootstrapAttempted)
        return g_enhancedV100.bootstrapReady;

    g_enhancedV100.bootstrapAttempted = true;

    if (!IsEnhancedExecutableImage())
        return false;

    uint8_t* base = nullptr;
    uint8_t* end = nullptr;
    if (!GetExeRange(base, end)
        || !base
        || !end
        || end <= base)
    {
        g_enhancedV100.bootstrapFaulted = true;
        return false;
    }

    const RUNTIME_FUNCTION* table = nullptr;
    size_t tableCount = 0;
    if (!GetLegacyV86RuntimeFunctionTable(
            base,
            end,
            table,
            tableCount))
    {
        g_enhancedV100.bootstrapFaulted = true;
        return false;
    }

    const EnhancedV99UniversalResolverState saved =
        g_enhancedV99;

    g_enhancedV99 =
        EnhancedV99UniversalResolverState{};
    g_enhancedV99.attempted = true;
    g_enhancedV99.enhancedImage = true;
    g_enhancedV99.imageValid = true;
    g_enhancedV99.runtimeTableValid = true;

    const bool structural =
        DiscoverEnhancedV99StructuralChain(
            base,
            end,
            table,
            tableCount);

    g_enhancedV100.structuralChains =
        g_enhancedV99.groupLoopCandidates;
    g_enhancedV100.owner =
        g_enhancedV99.owner;
    g_enhancedV100.groupLoop =
        g_enhancedV99.groupLoop;
    g_enhancedV100.workerCallsite =
        g_enhancedV99.workerCallsite;
    g_enhancedV100.worker =
        g_enhancedV99.worker;
    g_enhancedV100.bootstrapFaulted =
        g_enhancedV99.faulted;

    g_enhancedV99 = saved;

    if (!structural
        || g_enhancedV100.structuralChains != 1
        || !g_enhancedV100.owner
        || !g_enhancedV100.groupLoop
        || !g_enhancedV100.workerCallsite
        || !g_enhancedV100.worker
        || g_enhancedV100.bootstrapFaulted)
    {
        return false;
    }

    uint8_t* groupLoop =
        reinterpret_cast<uint8_t*>(
            g_enhancedV100.groupLoop);
    uint8_t* workerCallsite =
        reinterpret_cast<uint8_t*>(
            g_enhancedV100.workerCallsite);
    uint8_t* worker =
        reinterpret_cast<uint8_t*>(
            g_enhancedV100.worker);

    uint8_t* groupLoopStart = nullptr;
    uint8_t* groupLoopEnd = nullptr;
    if (!FindRuntimeFunctionBounds(
            base,
            end,
            groupLoop,
            groupLoopStart,
            groupLoopEnd)
        || groupLoopStart != groupLoop
        || !groupLoopEnd
        || groupLoopEnd <= groupLoopStart)
    {
        return false;
    }

    static const uint8_t expectedGroupLoopPrefix[16] =
    {
        0x41, 0x57,
        0x41, 0x56,
        0x41, 0x55,
        0x41, 0x54,
        0x56,
        0x57,
        0x55,
        0x53,
        0x48, 0x83, 0xEC, 0x48
    };

    if (!EnhancedV99PrefixEquals(
            groupLoopStart,
            groupLoopEnd,
            expectedGroupLoopPrefix,
            sizeof(expectedGroupLoopPrefix)))
    {
        return false;
    }

    uint8_t* resolvedWorker = nullptr;
    if (!ResolveLegacyV86Rel32Call(
            base,
            end,
            workerCallsite,
            resolvedWorker)
        || resolvedWorker != worker)
    {
        return false;
    }

    g_enhancedV100.bootstrapReady = true;
    return true;
}

static bool ResolveEnhancedV100LiveMutationLayout(
    void* context,
    void* child,
    uintptr_t callsite)
{
    if (!g_enhancedV100.bootstrapReady
        || !context
        || !child
        || !callsite)
    {
        return false;
    }

    if (g_enhancedV100.liveLayoutResolved)
        return false;

    g_enhancedV100.liveLayoutResolved = false;
    g_enhancedV100.childLayoutCandidates = 0;
    g_enhancedV100.descriptorLayoutCandidates = 0;
    g_enhancedV100.naturalStoryCallsite = 0;
    g_enhancedV100.lastContext =
        reinterpret_cast<uintptr_t>(context);
    g_enhancedV100.lastChild =
        reinterpret_cast<uintptr_t>(child);
    g_enhancedV100.lastChildArray = 0;
    g_enhancedV100.lastChildCount = 0;
    g_enhancedV100.lastChildIndex = -1;
    g_enhancedV100.childArrayOffset = 0;
    g_enhancedV100.childCountOffset = 0;
    g_enhancedV100.childStride = 0;
    g_enhancedV100.childHashOffset = 0;
    g_enhancedV100.lastDescriptorTable = 0;
    g_enhancedV100.lastDescriptorCount = 0;
    g_enhancedV100.descriptorVectorOffset = 0;
    g_enhancedV100.descriptorCountOffset = 0;
    g_enhancedV100.descriptorCapacityOffset = 0;
    g_enhancedV100.descriptorStride = 0;
    g_enhancedV100.descriptorGroupOffset = 0;
    g_enhancedV100.descriptorAssociatedOffset = 0;
    g_enhancedV100.descriptorAssociatedCountOffset = 0;
    g_enhancedV100.descriptorMapDescriptors = 0;
    g_enhancedV100.descriptorStoryDescriptors = 0;
    g_enhancedV100.descriptorMapBennyCount = 0;
    g_enhancedV100.descriptorStoryBennyCount = 0;

    uint8_t* base = nullptr;
    uint8_t* end = nullptr;
    if (!GetExeRange(base, end)
        || !base
        || !end
        || end <= base
        || !EnhancedV99IsOwnerGroupLoopCallsite(
            base,
            end,
            g_enhancedV100.owner,
            g_enhancedV100.groupLoop,
            callsite))
    {
        return false;
    }

    constexpr uint32_t mplowrider = 0x61322A35U;
    constexpr uint32_t groupMap = 0xBCC89179U;
    constexpr uint32_t groupStory = 0x578F99E2U;
    constexpr uint32_t benny = 0x4CDFC843U;
    constexpr uint16_t maxAssociatedPerDescriptor = 256;

    uint32_t hashOffsets[16]{};
    uint32_t hashOffsetCount = 0;
    const uintptr_t childAddress =
        reinterpret_cast<uintptr_t>(child);

    for (uint32_t off = 0; off <= 0x180; off += 4)
    {
        uint32_t value = 0;
        if (ReadProcessExact(
                childAddress + off,
                &value,
                sizeof(value))
            && value == mplowrider
            && hashOffsetCount < 16)
        {
            hashOffsets[hashOffsetCount++] = off;
        }
    }

    uint32_t childCandidates = 0;
    uint32_t selectedArrayOff = 0;
    uint32_t selectedCountOff = 0;
    uint32_t selectedStride = 0;
    uint32_t selectedHashOff = 0;
    uintptr_t selectedArray = 0;
    uint16_t selectedCount = 0;
    LONG selectedIndex = -1;
    const uintptr_t contextAddress =
        reinterpret_cast<uintptr_t>(context);

    for (uint32_t arrayOff = 0;
         arrayOff <= 0x80;
         arrayOff += static_cast<uint32_t>(sizeof(uintptr_t)))
    {
        uintptr_t array = 0;
        if (!ReadProcessExact(
                contextAddress + arrayOff,
                &array,
                sizeof(array))
            || !array
            || childAddress < array)
        {
            continue;
        }

        const uint32_t countOff =
            arrayOff
            + static_cast<uint32_t>(
                sizeof(uintptr_t));

        uint16_t count = 0;
        if (!ReadProcessExact(
                contextAddress + countOff,
                &count,
                sizeof(count))
            || count == 0
            || count > 4096)
        {
            continue;
        }

        const uintptr_t delta =
            childAddress - array;

        for (uint32_t stride = 0x80;
             stride <= 0x200;
             stride += 0x10)
        {
            if ((delta % stride) != 0)
                continue;

            const uintptr_t index =
                delta / stride;
            if (index >= count)
                continue;

            for (uint32_t h = 0;
                 h < hashOffsetCount;
                 ++h)
            {
                const uint32_t hashOff =
                    hashOffsets[h];
                if (hashOff + sizeof(uint32_t) > stride)
                    continue;

                LONG candidateIndex = -1;
                if (!EnhancedV99ValidateChildLayoutCandidate(
                        array,
                        count,
                        stride,
                        hashOff,
                        childAddress,
                        candidateIndex))
                {
                    continue;
                }

                ++childCandidates;
                if (childCandidates == 1)
                {
                    selectedArrayOff = arrayOff;
                    selectedCountOff = countOff;
                    selectedStride = stride;
                    selectedHashOff = hashOff;
                    selectedArray = array;
                    selectedCount = count;
                    selectedIndex = candidateIndex;
                }
            }
        }
    }

    g_enhancedV100.childLayoutCandidates =
        childCandidates;

    if (childCandidates != 1
        || !selectedArray
        || selectedCount == 0
        || selectedIndex < 0)
    {
        return false;
    }

    uint32_t descriptorCandidates = 0;
    uint32_t selectedVectorOff = 0;
    uint32_t selectedDescriptorStride = 0;
    uint32_t selectedGroupOff = 0;
    uint32_t selectedAssocOff = 0;
    uint32_t selectedAssocCountOff = 0;
    uintptr_t selectedDescriptorTable = 0;
    uint16_t selectedDescriptorCount = 0;
    uint16_t selectedMapDescriptors = 0;
    uint16_t selectedStoryDescriptors = 0;
    uint16_t selectedMapBenny = 0;
    uint16_t selectedStoryBenny = 0;

    const uint32_t descriptorStrides[] =
    {
        0x18U, 0x20U, 0x10U, 0x28U, 0x30U
    };
    const uint32_t groupOffsets[] =
    {
        0x00U, 0x04U
    };
    const uint32_t associatedOffsets[] =
    {
        0x08U, 0x10U
    };

    for (uint32_t vectorOff = 0;
         vectorOff + 0x0C <= selectedStride;
         vectorOff += static_cast<uint32_t>(sizeof(uintptr_t)))
    {
        uintptr_t tableAddress = 0;
        uint16_t count = 0;
        uint16_t capacity = 0;

        if (!ReadProcessExact(
                childAddress + vectorOff,
                &tableAddress,
                sizeof(tableAddress))
            || !ReadProcessExact(
                childAddress + vectorOff + 8,
                &count,
                sizeof(count))
            || !ReadProcessExact(
                childAddress + vectorOff + 10,
                &capacity,
                sizeof(capacity))
            || !tableAddress
            || count == 0
            || count > 64
            || capacity < count
            || capacity > 64)
        {
            continue;
        }

        for (uint32_t stride : descriptorStrides)
        {
            if (stride > kEnhancedV100MaxDescriptorStride)
                continue;

            for (uint32_t groupOff : groupOffsets)
            {
                for (uint32_t assocOff : associatedOffsets)
                {
                    const uint32_t assocCountOff =
                        assocOff + 8;

                    if (groupOff + sizeof(uint32_t) > stride
                        || assocOff + sizeof(uintptr_t) > stride
                        || assocCountOff + sizeof(uint16_t) > stride)
                    {
                        continue;
                    }

                    bool valid = true;
                    uint16_t mapDescriptors = 0;
                    uint16_t storyDescriptors = 0;
                    uint16_t mapBenny = 0;
                    uint16_t storyBenny = 0;

                    for (uint16_t i = 0;
                         i < count;
                         ++i)
                    {
                        const uintptr_t record =
                            tableAddress
                            + (static_cast<uintptr_t>(i)
                                * stride);

                        uint32_t group = 0;
                        uintptr_t associated = 0;
                        uint16_t associatedCount = 0;

                        if (!ReadProcessExact(
                                record + groupOff,
                                &group,
                                sizeof(group))
                            || !ReadProcessExact(
                                record + assocOff,
                                &associated,
                                sizeof(associated))
                            || !ReadProcessExact(
                                record + assocCountOff,
                                &associatedCount,
                                sizeof(associatedCount))
                            || associatedCount
                                > maxAssociatedPerDescriptor
                            || (associatedCount != 0
                                && !associated))
                        {
                            valid = false;
                            break;
                        }

                        if (group == groupMap)
                            ++mapDescriptors;
                        else if (group == groupStory)
                            ++storyDescriptors;

                        for (uint16_t j = 0;
                             j < associatedCount;
                             ++j)
                        {
                            uint32_t value = 0;
                            if (!ReadProcessExact(
                                    associated
                                    + (static_cast<uintptr_t>(j)
                                        * sizeof(uint32_t)),
                                    &value,
                                    sizeof(value)))
                            {
                                valid = false;
                                break;
                            }

                            if (value != benny)
                                continue;

                            if (group == groupMap)
                                ++mapBenny;
                            else if (group == groupStory)
                                ++storyBenny;
                        }

                        if (!valid)
                            break;
                    }

                    if (!valid
                        || mapDescriptors == 0
                        || mapBenny != 1
                        || storyBenny != 0)
                    {
                        continue;
                    }

                    ++descriptorCandidates;
                    if (descriptorCandidates == 1)
                    {
                        selectedVectorOff = vectorOff;
                        selectedDescriptorStride = stride;
                        selectedGroupOff = groupOff;
                        selectedAssocOff = assocOff;
                        selectedAssocCountOff =
                            assocCountOff;
                        selectedDescriptorTable =
                            tableAddress;
                        selectedDescriptorCount =
                            count;
                        selectedMapDescriptors =
                            mapDescriptors;
                        selectedStoryDescriptors =
                            storyDescriptors;
                        selectedMapBenny =
                            mapBenny;
                        selectedStoryBenny =
                            storyBenny;
                    }
                }
            }
        }
    }

    g_enhancedV100.descriptorLayoutCandidates =
        descriptorCandidates;

    if (descriptorCandidates != 1
        || !selectedDescriptorTable
        || selectedDescriptorCount == 0
        || selectedDescriptorStride == 0)
    {
        return false;
    }

    g_enhancedV100.naturalStoryCallsite =
        callsite;
    g_enhancedV100.lastContext =
        contextAddress;
    g_enhancedV100.lastChild =
        childAddress;
    g_enhancedV100.lastChildArray =
        selectedArray;
    g_enhancedV100.lastChildCount =
        selectedCount;
    g_enhancedV100.lastChildIndex =
        selectedIndex;
    g_enhancedV100.childArrayOffset =
        selectedArrayOff;
    g_enhancedV100.childCountOffset =
        selectedCountOff;
    g_enhancedV100.childStride =
        selectedStride;
    g_enhancedV100.childHashOffset =
        selectedHashOff;

    g_enhancedV100.lastDescriptorTable =
        selectedDescriptorTable;
    g_enhancedV100.lastDescriptorCount =
        selectedDescriptorCount;
    g_enhancedV100.descriptorVectorOffset =
        selectedVectorOff;
    g_enhancedV100.descriptorCountOffset =
        selectedVectorOff + 8;
    g_enhancedV100.descriptorCapacityOffset =
        selectedVectorOff + 10;
    g_enhancedV100.descriptorStride =
        selectedDescriptorStride;
    g_enhancedV100.descriptorGroupOffset =
        selectedGroupOff;
    g_enhancedV100.descriptorAssociatedOffset =
        selectedAssocOff;
    g_enhancedV100.descriptorAssociatedCountOffset =
        selectedAssocCountOff;
    g_enhancedV100.descriptorMapDescriptors =
        selectedMapDescriptors;
    g_enhancedV100.descriptorStoryDescriptors =
        selectedStoryDescriptors;
    g_enhancedV100.descriptorMapBennyCount =
        selectedMapBenny;
    g_enhancedV100.descriptorStoryBennyCount =
        selectedStoryBenny;
    g_enhancedV100.liveLayoutResolved = true;
    return true;
}

static void LogEnhancedV100IntegrationState(
    const char* phase)
{
    HMODULE exe =
        GetModuleHandleA(nullptr);
    const uintptr_t base =
        reinterpret_cast<uintptr_t>(
            exe);

    const auto rva = [base](uintptr_t address) -> unsigned long long
    {
        return base && address >= base
            ? static_cast<unsigned long long>(
                address - base)
            : 0ULL;
    };

    Logf(
        "[EnhancedV100] %s bootstrap{attempted=%s ready=%s faulted=%s chains=%u owner=0x%llX groupLoop=0x%llX workerCall=0x%llX worker=0x%llX} liveGate{attempts=%ld passed=%ld rejected=%ld resolved=%s callsite=0x%llX context=%p child=%p} childLayout{candidates=%u arrayOff=0x%X countOff=0x%X stride=0x%X hashOff=0x%X array=%p count=%u index=%ld} descriptorLayout{candidates=%u vectorOff=0x%X countOff=0x%X capOff=0x%X stride=0x%X groupOff=0x%X assocOff=0x%X assocCountOff=0x%X table=%p count=%u mapDescriptors=%u storyDescriptors=%u mapBenny=%u storyBenny=%u} mutation{attempts=%ld injected=%ld alreadyPresent=%ld rejected=%ld writeFaults=%ld restoreAttempts=%ld restoreVerified=%ld restoreFailures=%ld}.",
        phase ? phase : "",
        g_enhancedV100.bootstrapAttempted ? "yes" : "no",
        g_enhancedV100.bootstrapReady ? "yes" : "no",
        g_enhancedV100.bootstrapFaulted ? "yes" : "no",
        g_enhancedV100.structuralChains,
        rva(g_enhancedV100.owner),
        rva(g_enhancedV100.groupLoop),
        rva(g_enhancedV100.workerCallsite),
        rva(g_enhancedV100.worker),
        static_cast<long>(
            InterlockedCompareExchange(
                &g_enhancedV100.liveGateAttempts,
                0,
                0)),
        static_cast<long>(
            InterlockedCompareExchange(
                &g_enhancedV100.liveGatePassed,
                0,
                0)),
        static_cast<long>(
            InterlockedCompareExchange(
                &g_enhancedV100.liveGateRejected,
                0,
                0)),
        g_enhancedV100.liveLayoutResolved ? "yes" : "no",
        rva(g_enhancedV100.naturalStoryCallsite),
        reinterpret_cast<void*>(
            g_enhancedV100.lastContext),
        reinterpret_cast<void*>(
            g_enhancedV100.lastChild),
        g_enhancedV100.childLayoutCandidates,
        g_enhancedV100.childArrayOffset,
        g_enhancedV100.childCountOffset,
        g_enhancedV100.childStride,
        g_enhancedV100.childHashOffset,
        reinterpret_cast<void*>(
            g_enhancedV100.lastChildArray),
        static_cast<unsigned int>(
            g_enhancedV100.lastChildCount),
        static_cast<long>(
            g_enhancedV100.lastChildIndex),
        g_enhancedV100.descriptorLayoutCandidates,
        g_enhancedV100.descriptorVectorOffset,
        g_enhancedV100.descriptorCountOffset,
        g_enhancedV100.descriptorCapacityOffset,
        g_enhancedV100.descriptorStride,
        g_enhancedV100.descriptorGroupOffset,
        g_enhancedV100.descriptorAssociatedOffset,
        g_enhancedV100.descriptorAssociatedCountOffset,
        reinterpret_cast<void*>(
            g_enhancedV100.lastDescriptorTable),
        static_cast<unsigned int>(
            g_enhancedV100.lastDescriptorCount),
        static_cast<unsigned int>(
            g_enhancedV100.descriptorMapDescriptors),
        static_cast<unsigned int>(
            g_enhancedV100.descriptorStoryDescriptors),
        static_cast<unsigned int>(
            g_enhancedV100.descriptorMapBennyCount),
        static_cast<unsigned int>(
            g_enhancedV100.descriptorStoryBennyCount),
        static_cast<long>(
            InterlockedCompareExchange(
                &g_enhancedV100.mutationAttempts,
                0,
                0)),
        static_cast<long>(
            InterlockedCompareExchange(
                &g_enhancedV100.injected,
                0,
                0)),
        static_cast<long>(
            InterlockedCompareExchange(
                &g_enhancedV100.alreadyPresent,
                0,
                0)),
        static_cast<long>(
            InterlockedCompareExchange(
                &g_enhancedV100.rejected,
                0,
                0)),
        static_cast<long>(
            InterlockedCompareExchange(
                &g_enhancedV100.writeFaults,
                0,
                0)),
        static_cast<long>(
            InterlockedCompareExchange(
                &g_enhancedV100.restoreAttempts,
                0,
                0)),
        static_cast<long>(
            InterlockedCompareExchange(
                &g_enhancedV100.restoreVerified,
                0,
                0)),
        static_cast<long>(
            InterlockedCompareExchange(
                &g_enhancedV100.restoreFailures,
                0,
                0)));
}

static void LogEnhancedV99UniversalResolverState(
    const char* phase,
    uint8_t* base)
{
    const auto rva = [base](uintptr_t address) -> unsigned long long
    {
        return base && address >= reinterpret_cast<uintptr_t>(base)
            ? static_cast<unsigned long long>(
                address - reinterpret_cast<uintptr_t>(base))
            : 0ULL;
    };

    Logf(
        "[UniversalEnhancedV99] %s version=%d image=%s pdata=%s structural{ok=%s chains=%u ownerOk=%s ownerCandidates=%u owner=0x%llX ownerCalls=%u groupLoop=0x%llX workerCall=0x%llX worker=0x%llX} natural{ok=%s callsite=0x%llX context=%p child=%p} layout{ok=%s candidates=%u arrayOff=0x%X countOff=0x%X stride=0x%X hashOff=0x%X array=%p count=%u index=%ld} descriptor{ok=%s candidates=%u sourceOrientation=%s vectorOff=0x%X countOff=0x%X capOff=0x%X stride=0x%X groupOff=0x%X assocOff=0x%X assocCountOff=0x%X count=%u sourcePairs=%u/%u mapDescriptors=%u storyDescriptors=%u mapBenny=%u storyBenny=%u} oracle{checked=%s matched=%s} ready=%s mutationAttempted=no faulted=%s.",
        phase ? phase : "",
        g_enhancedV99.gameVersion,
        g_enhancedV99.imageValid ? "yes" : "no",
        g_enhancedV99.runtimeTableValid ? "yes" : "no",
        g_enhancedV99.structuralResolved ? "yes" : "no",
        g_enhancedV99.groupLoopCandidates,
        g_enhancedV99.ownerResolved ? "yes" : "no",
        g_enhancedV99.ownerCandidates,
        rva(g_enhancedV99.owner),
        g_enhancedV99.ownerCallsToGroupLoop,
        rva(g_enhancedV99.groupLoop),
        rva(g_enhancedV99.workerCallsite),
        rva(g_enhancedV99.worker),
        g_enhancedV99.naturalStoryCallResolved ? "yes" : "no",
        rva(g_enhancedV99.naturalStoryCallsite),
        reinterpret_cast<void*>(g_enhancedV99.context),
        reinterpret_cast<void*>(g_enhancedV99.child),
        g_enhancedV99.layoutResolved ? "yes" : "no",
        g_enhancedV99.layoutCandidates,
        g_enhancedV99.childArrayOffset,
        g_enhancedV99.childCountOffset,
        g_enhancedV99.childStride,
        g_enhancedV99.childHashOffset,
        reinterpret_cast<void*>(g_enhancedV99.childArray),
        static_cast<unsigned int>(g_enhancedV99.childCount),
        g_enhancedV99.childIndex,
        g_enhancedV99.descriptorResolved ? "yes" : "no",
        g_enhancedV99.descriptorCandidates,
        g_enhancedV99.descriptorResolved
            ? (g_enhancedV99.descriptorSourceFieldsSwapped
                ? "swapped" : "direct")
            : "unresolved",
        g_enhancedV99.descriptorVectorOffset,
        g_enhancedV99.descriptorCountOffset,
        g_enhancedV99.descriptorCapacityOffset,
        g_enhancedV99.descriptorStride,
        g_enhancedV99.descriptorGroupOffset,
        g_enhancedV99.descriptorAssociatedOffset,
        g_enhancedV99.descriptorAssociatedCountOffset,
        static_cast<unsigned int>(g_enhancedV99.descriptorCount),
        static_cast<unsigned int>(g_enhancedV99.descriptorSourcePairsMatched),
        static_cast<unsigned int>(g_enhancedV99.descriptorSourcePairsObserved),
        static_cast<unsigned int>(g_enhancedV99.mapDescriptorCount),
        static_cast<unsigned int>(g_enhancedV99.storyDescriptorCount),
        static_cast<unsigned int>(g_enhancedV99.mapBennyCount),
        static_cast<unsigned int>(g_enhancedV99.storyBennyCount),
        g_enhancedV99.knownBuildOracleChecked ? "yes" : "no",
        g_enhancedV99.knownBuildOracleMatched ? "yes" : "no",
        g_enhancedV99.readyForMutationResearch ? "yes" : "no",
        g_enhancedV99.faulted ? "yes" : "no");
}

static bool RunEnhancedV99UniversalResolver(
    const char* phase)
{
    g_enhancedV99 = EnhancedV99UniversalResolverState{};
    g_enhancedV99.attempted = true;
    g_enhancedV99.gameVersion = getGameVersion();
    g_enhancedV99.enhancedImage = IsEnhancedExecutableImage();

    uint8_t* base = nullptr;
    uint8_t* end = nullptr;
    if (!g_enhancedV99.enhancedImage
        || !GetExeRange(base, end)
        || !base
        || !end
        || end <= base)
    {
        LogEnhancedV99UniversalResolverState(phase, base);
        return false;
    }
    g_enhancedV99.imageValid = true;

    const RUNTIME_FUNCTION* table = nullptr;
    size_t tableCount = 0;
    if (!GetLegacyV86RuntimeFunctionTable(
            base,
            end,
            table,
            tableCount))
    {
        LogEnhancedV99UniversalResolverState(phase, base);
        return false;
    }
    g_enhancedV99.runtimeTableValid = true;

    const bool structural = DiscoverEnhancedV99StructuralChain(
        base,
        end,
        table,
        tableCount);
    const bool live = structural && DiscoverEnhancedV99LiveContext(base, end);
    const bool layout = live && DiscoverEnhancedV99ChildLayout();
    const bool descriptor = layout && DiscoverEnhancedV99DescriptorLayout();

    (void)descriptor;

    g_enhancedV99.readyForMutationResearch =
        structural
        && live
        && layout
        && g_enhancedV99.descriptorResolved
        && !g_enhancedV99.faulted;

    if (g_enhancedV99.gameVersion == 1012)
    {
        g_enhancedV99.knownBuildOracleChecked = true;
        g_enhancedV99.knownBuildOracleMatched =
            g_enhancedV99.readyForMutationResearch
            && g_enhancedV99.owner
                == reinterpret_cast<uintptr_t>(base + 0x00C25610ULL)
            && g_enhancedV99.naturalStoryCallsite
                == reinterpret_cast<uintptr_t>(base + 0x00C25F4EULL)
            && g_enhancedV99.groupLoop
                == reinterpret_cast<uintptr_t>(base + 0x00C26F00ULL)
            && g_enhancedV99.workerCallsite
                == reinterpret_cast<uintptr_t>(base + 0x00C26F83ULL)
            && g_enhancedV99.worker
                == reinterpret_cast<uintptr_t>(base + 0x00C272A0ULL)
            && g_enhancedV99.childArrayOffset == 0x28U
            && g_enhancedV99.childCountOffset == 0x30U
            && g_enhancedV99.childStride == 0x120U
            && g_enhancedV99.childHashOffset == 0x80U
            && g_enhancedV99.descriptorVectorOffset == 0x98U
            && g_enhancedV99.descriptorCountOffset == 0xA0U;
    }

    LogEnhancedV99UniversalResolverState(phase, base);
    return g_enhancedV99.readyForMutationResearch;
}

static bool ResolveLegacyV92OverlayFromContextRegistry(
    const char* phase)
{
    g_legacyV73OverlayGate =
        LegacyV73OverlayGateState{};
    g_legacyV92ContextRegistry =
        LegacyV92ContextRegistryState{};
    g_legacyV92ContextRegistry.attempted = true;

    if (!IsLegacyExecutableImage()
        || getGameVersion() != 102)
    {
        return false;
    }

    uint8_t* base = nullptr;
    uint8_t* end = nullptr;
    if (!GetExeRange(base, end)
        || !base
        || !end
        || end <= base)
    {
        return false;
    }

    uint8_t* ownerStart = nullptr;
    uint8_t* ownerEnd = nullptr;
    uint8_t* wrapper = nullptr;
    uint8_t* prePass = nullptr;
    uintptr_t contextGlobal = 0;
    uintptr_t context = 0;
    LONG lowriderIndex = -1;
    uintptr_t lowriderChild = 0;

    const bool contextResolved =
        ResolveLegacyV64NaturalOwner(
            base,
            end,
            ownerStart,
            ownerEnd,
            wrapper,
            prePass,
            contextGlobal,
            context,
            lowriderIndex,
            lowriderChild);

    g_legacyV92ContextRegistry.contextResolved =
        contextResolved;
    g_legacyV92ContextRegistry.context = context;
    g_legacyV92ContextRegistry.lowriderChild =
        lowriderChild;

    if (!contextResolved
        || !context
        || !lowriderChild)
    {
        Logf(
            "[LegacyOverlayV92] REFUSED phase=%s: validated Legacy context/Lowriders child is not ready.",
            phase ? phase : "");
        return false;
    }

    uintptr_t allocationBase = 0;
    uintptr_t allocationEnd = 0;
    if (!GetLegacyV92AllocationBounds(
            lowriderChild,
            allocationBase,
            allocationEnd))
    {
        Logf(
            "[LegacyOverlayV92] REFUSED phase=%s: could not establish Rockstar allocation bounds from Lowriders child=%p.",
            phase ? phase : "",
            reinterpret_cast<void*>(lowriderChild));
        return false;
    }

    g_legacyV92ContextRegistry.allocationResolved = true;
    g_legacyV92ContextRegistry.allocationBase =
        allocationBase;
    g_legacyV92ContextRegistry.allocationEnd =
        allocationEnd;

    if (context < allocationBase
        || context + 0x10ULL > allocationEnd)
    {
        Logf(
            "[LegacyOverlayV92] REFUSED phase=%s: resolved context=%p is outside Lowriders Rockstar allocation=%p..%p.",
            phase ? phase : "",
            reinterpret_cast<void*>(context),
            reinterpret_cast<void*>(allocationBase),
            reinterpret_cast<void*>(allocationEnd));
        return false;
    }

    uintptr_t registryStart = 0;
    if (!ReadProcessExact(
            context + 0x08ULL,
            &registryStart,
            sizeof(registryStart))
        || registryStart < allocationBase
        || registryStart >= allocationEnd)
    {
        Logf(
            "[LegacyOverlayV92] REFUSED phase=%s: context+0x08 did not resolve to a same-allocation registry pointer. context=%p value=%p.",
            phase ? phase : "",
            reinterpret_cast<void*>(context),
            reinterpret_cast<void*>(registryStart));
        return false;
    }

    g_legacyV92ContextRegistry.registryRead = true;
    g_legacyV92ContextRegistry.registryStart =
        registryStart;

    uintptr_t previousValue = 0;
    const bool previousOwned =
        registryStart >= allocationBase + sizeof(uintptr_t)
        && LegacyV91ReadOwnedPointer(
            registryStart - sizeof(uintptr_t),
            allocationBase,
            allocationEnd,
            previousValue);

    g_legacyV92ContextRegistry.startBoundaryVerified =
        !previousOwned;

    if (previousOwned)
    {
        Logf(
            "[LegacyOverlayV92] REFUSED phase=%s: context+0x08 points inside an owned-pointer run rather than its first entry. registry=%p previous=%p.",
            phase ? phase : "",
            reinterpret_cast<void*>(registryStart),
            reinterpret_cast<void*>(previousValue));
        return false;
    }

    constexpr uint32_t maxRegistryEntries = 4096;
    constexpr uint32_t dlcHash = 0x61322A35U;
    constexpr uint32_t unknown04 = 0xF9904BBCU;
    constexpr uint32_t bennyHash = 0x4CDFC843U;
    constexpr uint32_t mapHash = 0xBCC89179U;
    constexpr uint32_t storyHash = 0x578F99E2U;
    constexpr uint32_t flags = 1U;

    uint32_t registryEntries = 0;
    uint32_t exactMapHits = 0;
    uint32_t exactStoryHits = 0;
    uint32_t targetIndex = 0xFFFFFFFFU;
    uintptr_t selectedRecord = 0;
    uint32_t selectedGroup = 0;

    for (uint32_t i = 0;
         i < maxRegistryEntries;
         ++i)
    {
        const uintptr_t slot =
            registryStart
            + static_cast<uintptr_t>(i)
                * sizeof(uintptr_t);

        uintptr_t record = 0;
        if (!LegacyV91ReadOwnedPointer(
                slot,
                allocationBase,
                allocationEnd,
                record))
        {
            g_legacyV92ContextRegistry.endBoundaryVerified =
                true;
            break;
        }

        ++registryEntries;

        uint32_t fields[5]{};
        if (!ReadProcessExact(
                record,
                fields,
                sizeof(fields)))
        {
            continue;
        }

        if (fields[0] != dlcHash
            || fields[1] != unknown04
            || fields[2] != bennyHash
            || fields[4] != flags
            || (fields[3] != mapHash
                && fields[3] != storyHash))
        {
            continue;
        }

        if (fields[3] == mapHash)
            ++exactMapHits;
        else
            ++exactStoryHits;

        if (exactMapHits + exactStoryHits == 1)
        {
            targetIndex = i;
            selectedRecord = record;
            selectedGroup = fields[3];
        }

        Logf(
            "[LegacyOverlayV92] exactCandidate index=%u slot=%p record=%p recordOffset=0x%llX group=%s(0x%08X).",
            i,
            reinterpret_cast<void*>(slot),
            reinterpret_cast<void*>(record),
            static_cast<unsigned long long>(
                record - allocationBase),
            fields[3] == storyHash
                ? "GROUP_MAP_SP"
                : "GROUP_MAP",
            fields[3]);
    }

    if (registryEntries == maxRegistryEntries)
    {
        uintptr_t nextValue = 0;
        if (LegacyV91ReadOwnedPointer(
                registryStart
                    + static_cast<uintptr_t>(
                        maxRegistryEntries)
                        * sizeof(uintptr_t),
                allocationBase,
                allocationEnd,
                nextValue))
        {
            g_legacyV92ContextRegistry.truncated = true;
        }
        else
        {
            g_legacyV92ContextRegistry.endBoundaryVerified =
                true;
        }
    }

    const uintptr_t registryEnd =
        registryStart
        + static_cast<uintptr_t>(
            registryEntries)
            * sizeof(uintptr_t);

    g_legacyV92ContextRegistry.registryEnd =
        registryEnd;
    g_legacyV92ContextRegistry.registryEntries =
        registryEntries;
    g_legacyV92ContextRegistry.exactMapHits =
        exactMapHits;
    g_legacyV92ContextRegistry.exactStoryHits =
        exactStoryHits;
    g_legacyV92ContextRegistry.targetIndex =
        targetIndex;
    g_legacyV92ContextRegistry.recordAddress =
        selectedRecord;

    Logf(
        "[LegacyOverlayV92] SUMMARY phase=%s context=%p contextRegistryField=%p registry=%p..%p entries=%u boundaries{start=%s end=%s} truncated=%s exact{GROUP_MAP=%u GROUP_MAP_SP=%u} targetIndex=%u record=%p.",
        phase ? phase : "",
        reinterpret_cast<void*>(context),
        reinterpret_cast<void*>(context + 0x08ULL),
        reinterpret_cast<void*>(registryStart),
        reinterpret_cast<void*>(registryEnd),
        registryEntries,
        g_legacyV92ContextRegistry.startBoundaryVerified
            ? "yes"
            : "no",
        g_legacyV92ContextRegistry.endBoundaryVerified
            ? "yes"
            : "no",
        g_legacyV92ContextRegistry.truncated
            ? "yes"
            : "no",
        exactMapHits,
        exactStoryHits,
        targetIndex,
        reinterpret_cast<void*>(selectedRecord));

    if (!g_legacyV92ContextRegistry.startBoundaryVerified
        || !g_legacyV92ContextRegistry.endBoundaryVerified
        || g_legacyV92ContextRegistry.truncated
        || registryEntries == 0
        || exactMapHits + exactStoryHits != 1
        || selectedRecord == 0)
    {
        Logf(
            "[LegacyOverlayV92] REFUSED: direct context registry requires clean pointer-run boundaries and exactly one exact Benny overlay record. No allocation/process scan fallback is used by the production path.");
        return false;
    }

    g_legacyV73OverlayGate.scanned = true;
    g_legacyV73OverlayGate.contiguousMapHits =
        static_cast<int>(exactMapHits);
    g_legacyV73OverlayGate.contiguousStoryHits =
        static_cast<int>(exactStoryHits);
    g_legacyV73OverlayGate.relaxedMapHits = 0;
    g_legacyV73OverlayGate.relaxedStoryHits = 0;
    g_legacyV73OverlayGate.recordAddress =
        selectedRecord;
    g_legacyV73OverlayGate.groupValue =
        selectedGroup;
    g_legacyV73OverlayGate.unknown04 =
        unknown04;
    g_legacyV73OverlayGate.flags =
        flags;
    g_legacyV73OverlayGate.exactSingleMap =
        exactMapHits == 1
        && exactStoryHits == 0
        && selectedGroup == mapHash;
    g_legacyV73OverlayGate.exactSingleStory =
        exactStoryHits == 1
        && exactMapHits == 0
        && selectedGroup == storyHash;

    Logf(
        "[LegacyOverlayV77] overlayGate source=v92-context-registry scanned=%s exactSingleMap=%s exactSingleStory=%s record=%p group=0x%08X unknown04=0x%08X flags=0x%08X.",
        g_legacyV73OverlayGate.scanned ? "yes" : "no",
        g_legacyV73OverlayGate.exactSingleMap
            ? "yes"
            : "no",
        g_legacyV73OverlayGate.exactSingleStory
            ? "yes"
            : "no",
        reinterpret_cast<void*>(
            g_legacyV73OverlayGate.recordAddress),
        g_legacyV73OverlayGate.groupValue,
        g_legacyV73OverlayGate.unknown04,
        g_legacyV73OverlayGate.flags);

    return true;
}

static bool ScanLegacyV88OverlayFromLowriderAllocation(
    const char* phase)
{
    g_legacyV73OverlayGate = LegacyV73OverlayGateState{};
    g_legacyV88OverlayDiscovery = LegacyV88OverlayDiscoveryState{};

    if (!IsLegacyExecutableImage()
        || getGameVersion() != 102)
    {
        return false;
    }

    uint8_t* base = nullptr;
    uint8_t* end = nullptr;
    if (!GetExeRange(base, end)
        || !base
        || !end
        || end <= base)
    {
        return false;
    }

    uint8_t* ownerStart = nullptr;
    uint8_t* ownerEnd = nullptr;
    uint8_t* wrapper = nullptr;
    uint8_t* prePass = nullptr;
    uintptr_t contextGlobal = 0;
    uintptr_t context = 0;
    LONG lowriderIndex = -1;
    uintptr_t lowriderChild = 0;

    const bool anchorResolved =
        ResolveLegacyV64NaturalOwner(
            base,
            end,
            ownerStart,
            ownerEnd,
            wrapper,
            prePass,
            contextGlobal,
            context,
            lowriderIndex,
            lowriderChild);

    g_legacyV88OverlayDiscovery.anchorResolved =
        anchorResolved;
    g_legacyV88OverlayDiscovery.lowriderChild =
        lowriderChild;

    if (!anchorResolved || !lowriderChild)
    {
        Logf(
            "[LegacyOverlayV88] REFUSED phase=%s: structurally resolved mplowrider allocation anchor is not ready. No process-wide fallback was used.",
            phase ? phase : "");
        return false;
    }

    MEMORY_BASIC_INFORMATION anchorMbi{};
    if (VirtualQuery(
            reinterpret_cast<LPCVOID>(lowriderChild),
            &anchorMbi,
            sizeof(anchorMbi)) == 0
        || anchorMbi.AllocationBase == nullptr
        || anchorMbi.Type == MEM_IMAGE)
    {
        Logf(
            "[LegacyOverlayV88] REFUSED phase=%s: could not establish a non-image Rockstar allocation for child=%p.",
            phase ? phase : "",
            reinterpret_cast<void*>(lowriderChild));
        return false;
    }

    const uintptr_t allocationBase =
        reinterpret_cast<uintptr_t>(
            anchorMbi.AllocationBase);
    g_legacyV88OverlayDiscovery.allocationResolved = true;
    g_legacyV88OverlayDiscovery.allocationBase =
        allocationBase;

    constexpr uint32_t dlcHash = 0x61322A35U;
    constexpr uint32_t unknown04 = 0xF9904BBCU;
    constexpr uint32_t bennyHash = 0x4CDFC843U;
    constexpr uint32_t mapHash = 0xBCC89179U;
    constexpr uint32_t storyHash = 0x578F99E2U;
    constexpr uint32_t flags = 1U;

    constexpr SIZE_T chunkSize =
        1024ULL * 1024ULL;
    constexpr SIZE_T recordSize =
        sizeof(uint32_t) * 5;
    constexpr SIZE_T overlap =
        recordSize - sizeof(uint32_t);

    std::vector<uint8_t> buffer(
        chunkSize + overlap);

    uintptr_t cursor = allocationBase;
    uintptr_t allocationEnd = allocationBase;
    uintptr_t selectedRecord = 0;
    uint32_t selectedGroup = 0;
    uint32_t exactMapHits = 0;
    uint32_t exactStoryHits = 0;
    uint32_t regionsExamined = 0;
    uint32_t readFailures = 0;
    uint64_t bytesExamined = 0;

    Logf(
        "[LegacyOverlayV88] BEGIN phase=%s child=%p childOffset=0x%llX allocationBase=%p. Searching only this Rockstar allocation for exact [mplowrider,0xF9904BBC,Benny,GROUP_MAP[_SP],1].",
        phase ? phase : "",
        reinterpret_cast<void*>(lowriderChild),
        static_cast<unsigned long long>(
            lowriderChild - allocationBase),
        reinterpret_cast<void*>(allocationBase));

    while (cursor >= allocationBase)
    {
        MEMORY_BASIC_INFORMATION mbi{};
        if (VirtualQuery(
                reinterpret_cast<LPCVOID>(cursor),
                &mbi,
                sizeof(mbi)) == 0)
        {
            break;
        }

        const uintptr_t regionBase =
            reinterpret_cast<uintptr_t>(
                mbi.BaseAddress);
        const uintptr_t regionAllocationBase =
            reinterpret_cast<uintptr_t>(
                mbi.AllocationBase);
        const uintptr_t regionEnd =
            regionBase
            + static_cast<uintptr_t>(
                mbi.RegionSize);

        if (regionEnd <= cursor)
            break;

        if (regionAllocationBase != allocationBase)
        {
            if (regionBase >= allocationBase)
                break;

            cursor = regionEnd;
            continue;
        }

        if (regionEnd > allocationEnd)
            allocationEnd = regionEnd;

        if (mbi.State == MEM_COMMIT
            && mbi.Type != MEM_IMAGE
            && IsReadableProtection(mbi.Protect)
            && IsWritableProtection(mbi.Protect))
        {
            ++regionsExamined;
            uintptr_t chunkAddress = regionBase;

            while (chunkAddress < regionEnd)
            {
                const SIZE_T remaining =
                    static_cast<SIZE_T>(
                        regionEnd - chunkAddress);
                const SIZE_T request =
                    remaining < (chunkSize + overlap)
                        ? remaining
                        : (chunkSize + overlap);

                SIZE_T bytesRead = 0;
                if (request >= recordSize
                    && ReadProcessMemory(
                        GetCurrentProcess(),
                        reinterpret_cast<LPCVOID>(
                            chunkAddress),
                        buffer.data(),
                        request,
                        &bytesRead)
                    && bytesRead >= recordSize)
                {
                    const SIZE_T primaryBytes =
                        bytesRead > chunkSize
                            ? chunkSize
                            : bytesRead;

                    SIZE_T offset =
                        static_cast<SIZE_T>(
                            (4ULL
                                - (chunkAddress & 3ULL))
                            & 3ULL);

                    for (;
                         offset < primaryBytes
                            && offset + recordSize
                                <= bytesRead;
                         offset += sizeof(uint32_t))
                    {
                        uint32_t fields[5]{};
                        memcpy(
                            fields,
                            buffer.data() + offset,
                            sizeof(fields));

                        if (fields[0] != dlcHash
                            || fields[1] != unknown04
                            || fields[2] != bennyHash
                            || fields[4] != flags
                            || (fields[3] != mapHash
                                && fields[3] != storyHash))
                        {
                            continue;
                        }

                        const uintptr_t record =
                            chunkAddress + offset;

                        if (fields[3] == mapHash)
                            ++exactMapHits;
                        else
                            ++exactStoryHits;

                        if (exactMapHits
                                + exactStoryHits
                            == 1)
                        {
                            selectedRecord = record;
                            selectedGroup = fields[3];
                        }

                        Logf(
                            "[LegacyOverlayV88] exactCandidate record=%p recordOffset=0x%llX group=%s(0x%08X).",
                            reinterpret_cast<void*>(
                                record),
                            static_cast<unsigned long long>(
                                record - allocationBase),
                            fields[3] == storyHash
                                ? "GROUP_MAP_SP"
                                : "GROUP_MAP",
                            fields[3]);
                    }

                    bytesExamined += primaryBytes;
                }
                else if (request >= recordSize)
                {
                    ++readFailures;
                }

                if (remaining <= chunkSize)
                    break;

                chunkAddress += chunkSize;
            }
        }

        cursor = regionEnd;
    }

    g_legacyV88OverlayDiscovery.scanned = true;
    g_legacyV88OverlayDiscovery.allocationEnd =
        allocationEnd;
    g_legacyV88OverlayDiscovery.regionsExamined =
        regionsExamined;
    g_legacyV88OverlayDiscovery.readFailures =
        readFailures;
    g_legacyV88OverlayDiscovery.bytesExamined =
        bytesExamined;
    g_legacyV88OverlayDiscovery.exactMapHits =
        exactMapHits;
    g_legacyV88OverlayDiscovery.exactStoryHits =
        exactStoryHits;

    g_legacyV73OverlayGate.scanned = true;
    g_legacyV73OverlayGate.contiguousMapHits =
        static_cast<int>(exactMapHits);
    g_legacyV73OverlayGate.contiguousStoryHits =
        static_cast<int>(exactStoryHits);
    g_legacyV73OverlayGate.relaxedMapHits = 0;
    g_legacyV73OverlayGate.relaxedStoryHits = 0;

    if (exactMapHits + exactStoryHits == 1
        && selectedRecord != 0)
    {
        g_legacyV73OverlayGate.recordAddress =
            selectedRecord;
        g_legacyV73OverlayGate.groupValue =
            selectedGroup;
        g_legacyV73OverlayGate.unknown04 =
            unknown04;
        g_legacyV73OverlayGate.flags =
            flags;
        g_legacyV73OverlayGate.exactSingleMap =
            exactMapHits == 1
            && exactStoryHits == 0
            && selectedGroup == mapHash;
        g_legacyV73OverlayGate.exactSingleStory =
            exactStoryHits == 1
            && exactMapHits == 0
            && selectedGroup == storyHash;
    }

    Logf(
        "[LegacyOverlayV88] SUMMARY phase=%s child=%p allocation=%p..%p spanMiB=%llu regions=%u scannedMiB=%llu exact{GROUP_MAP=%u GROUP_MAP_SP=%u} readFailures=%u unique=%s.",
        phase ? phase : "",
        reinterpret_cast<void*>(lowriderChild),
        reinterpret_cast<void*>(allocationBase),
        reinterpret_cast<void*>(allocationEnd),
        static_cast<unsigned long long>(
            allocationEnd > allocationBase
                ? (allocationEnd - allocationBase)
                    / (1024ULL * 1024ULL)
                : 0ULL),
        regionsExamined,
        static_cast<unsigned long long>(
            bytesExamined / (1024ULL * 1024ULL)),
        exactMapHits,
        exactStoryHits,
        readFailures,
        (exactMapHits + exactStoryHits == 1)
            ? "yes"
            : "no");

    Logf(
        "[LegacyOverlayV77] overlayGate source=v88-allocation scanned=%s exactSingleMap=%s exactSingleStory=%s record=%p group=0x%08X unknown04=0x%08X flags=0x%08X.",
        g_legacyV73OverlayGate.scanned ? "yes" : "no",
        g_legacyV73OverlayGate.exactSingleMap
            ? "yes"
            : "no",
        g_legacyV73OverlayGate.exactSingleStory
            ? "yes"
            : "no",
        reinterpret_cast<void*>(
            g_legacyV73OverlayGate.recordAddress),
        g_legacyV73OverlayGate.groupValue,
        g_legacyV73OverlayGate.unknown04,
        g_legacyV73OverlayGate.flags);

    if (exactMapHits + exactStoryHits != 1)
    {
        Logf(
            "[LegacyOverlayV88] REFUSED: allocation-bounded discovery requires exactly one exact parsed overlay record. No process-wide fallback is used on the production path.");
        return false;
    }

    if (g_diagnosticsEnabled)
    {
        ProbeLegacyV89OverlayOwner(
            selectedRecord,
            allocationBase,
            allocationEnd);
    }

    return true;
}

static void ScanLegacyV65OverlayCandidates(
    const char* phase)
{
    g_legacyV73OverlayGate = LegacyV73OverlayGateState{};

    if (!IsLegacyExecutableImage()
        || getGameVersion() != 102)
    {
        return;
    }

    const uint32_t dlcHash = Joaat(kDlcName);
    const uint32_t bennyHash = Joaat(kBennysChangeSet);
    const uint32_t mapHash = Joaat(kMapGroup);
    const uint32_t storyHash = Joaat(kStoryMapGroup);

    SYSTEM_INFO si{};
    GetSystemInfo(&si);

    uintptr_t cursor = reinterpret_cast<uintptr_t>(
        si.lpMinimumApplicationAddress);
    const uintptr_t maximum = reinterpret_cast<uintptr_t>(
        si.lpMaximumApplicationAddress);

    uintptr_t selfStart = 0;
    uintptr_t selfEnd = 0;
    GetSelfModuleRange(selfStart, selfEnd);

    MEMORY_BASIC_INFORMATION stackMbi{};
    VirtualQuery(
        reinterpret_cast<LPCVOID>(&cursor),
        &stackMbi,
        sizeof(stackMbi));
    const uintptr_t stackAllocationBase =
        reinterpret_cast<uintptr_t>(
            stackMbi.AllocationBase);

    constexpr SIZE_T chunkSize =
        1024ULL * 1024ULL;
    constexpr SIZE_T dwordOverlap =
        sizeof(uint32_t) - 1;
    constexpr size_t maxStoredBennyHits = 256;
    constexpr size_t neighborhoodRadius = 0x100;

    std::vector<uint8_t> buffer(
        chunkSize + dwordOverlap);
    std::vector<uintptr_t> bennyHits;

    SIZE_T bytesExamined = 0;
    uint32_t regionsExamined = 0;
    uint32_t rawBennyHits = 0;
    uint32_t readFailures = 0;
    bool truncated = false;

    Logf(
        "[LegacyOverlayV65] BEGIN phase=%s observation-only scan dlc=0x%08X Benny=0x%08X GROUP_MAP=0x%08X GROUP_MAP_SP=0x%08X. No overlay/setup2/runtime state is modified by this probe.",
        phase ? phase : "",
        dlcHash,
        bennyHash,
        mapHash,
        storyHash);

    while (cursor < maximum)
    {
        MEMORY_BASIC_INFORMATION mbi{};
        if (VirtualQuery(
                reinterpret_cast<LPCVOID>(cursor),
                &mbi,
                sizeof(mbi)) == 0)
        {
            break;
        }

        const uintptr_t regionBase =
            reinterpret_cast<uintptr_t>(
                mbi.BaseAddress);
        uintptr_t regionEnd = regionBase
            + static_cast<uintptr_t>(
                mbi.RegionSize);
        if (regionEnd <= cursor)
            break;

        const uintptr_t allocationBase =
            reinterpret_cast<uintptr_t>(
                mbi.AllocationBase);

        const bool overlapsSelf =
            selfStart != 0
            && selfEnd > selfStart
            && regionBase < selfEnd
            && regionEnd > selfStart;

        const bool isCurrentStack =
            stackAllocationBase != 0
            && allocationBase == stackAllocationBase;

        if (mbi.State == MEM_COMMIT
            && mbi.Type != MEM_IMAGE
            && IsReadableProtection(mbi.Protect)
            && IsWritableProtection(mbi.Protect)
            && !overlapsSelf
            && !isCurrentStack)
        {
            ++regionsExamined;
            uintptr_t chunkAddress = regionBase;

            while (chunkAddress < regionEnd)
            {
                const SIZE_T remaining =
                    static_cast<SIZE_T>(
                        regionEnd - chunkAddress);
                const SIZE_T request =
                    remaining < (chunkSize + dwordOverlap)
                        ? remaining
                        : (chunkSize + dwordOverlap);

                SIZE_T bytesRead = 0;
                if (request >= sizeof(uint32_t)
                    && ReadProcessMemory(
                        GetCurrentProcess(),
                        reinterpret_cast<LPCVOID>(
                            chunkAddress),
                        buffer.data(),
                        request,
                        &bytesRead)
                    && bytesRead >= sizeof(uint32_t))
                {
                    const SIZE_T primaryBytes =
                        bytesRead > chunkSize
                            ? chunkSize
                            : bytesRead;

                    SIZE_T offset =
                        static_cast<SIZE_T>(
                            (4ULL
                                - (chunkAddress & 3ULL))
                            & 3ULL);

                    for (;
                         offset + sizeof(uint32_t)
                            <= primaryBytes;
                         offset += sizeof(uint32_t))
                    {
                        uint32_t value = 0;
                        memcpy(
                            &value,
                            buffer.data() + offset,
                            sizeof(value));
                        if (value != bennyHash)
                            continue;

                        const uintptr_t hit =
                            chunkAddress + offset;
                        ++rawBennyHits;

                        if (!LegacyV65AddressAlreadyTracked(
                                bennyHits,
                                hit))
                        {
                            if (bennyHits.size()
                                < maxStoredBennyHits)
                            {
                                bennyHits.push_back(hit);
                            }
                            else
                            {
                                truncated = true;
                            }
                        }
                    }

                    bytesExamined += primaryBytes;
                }
                else
                {
                    ++readFailures;
                }

                if (remaining <= chunkSize)
                    break;
                chunkAddress += chunkSize;
            }
        }

        cursor = regionEnd;
    }

    std::vector<LegacyV65OverlayCandidate>
        candidates;
    int contiguousMapHits = 0;
    int contiguousStoryHits = 0;
    int relaxedMapHits = 0;
    int relaxedStoryHits = 0;

    for (uintptr_t bennyAddress : bennyHits)
    {
        MEMORY_BASIC_INFORMATION mbi{};
        if (VirtualQuery(
                reinterpret_cast<LPCVOID>(
                    bennyAddress),
                &mbi,
                sizeof(mbi)) == 0
            || mbi.State != MEM_COMMIT
            || mbi.Type == MEM_IMAGE
            || !IsReadableProtection(mbi.Protect))
        {
            continue;
        }

        const uintptr_t regionBase =
            reinterpret_cast<uintptr_t>(
                mbi.BaseAddress);
        const uintptr_t regionEnd = regionBase
            + static_cast<uintptr_t>(
                mbi.RegionSize);

        uintptr_t windowStart =
            bennyAddress > neighborhoodRadius
                ? bennyAddress - neighborhoodRadius
                : regionBase;
        if (windowStart < regionBase)
            windowStart = regionBase;

        uintptr_t windowEnd =
            bennyAddress + neighborhoodRadius
            + sizeof(uint32_t);
        if (windowEnd < bennyAddress
            || windowEnd > regionEnd)
        {
            windowEnd = regionEnd;
        }

        if (windowEnd <= windowStart
            || windowEnd - windowStart
                < sizeof(uint32_t))
        {
            continue;
        }

        const size_t windowSize =
            static_cast<size_t>(
                windowEnd - windowStart);
        std::vector<uint8_t> window(windowSize);
        SIZE_T windowRead = 0;
        if (!ReadProcessMemory(
                GetCurrentProcess(),
                reinterpret_cast<LPCVOID>(
                    windowStart),
                window.data(),
                window.size(),
                &windowRead)
            || windowRead < sizeof(uint32_t))
        {
            continue;
        }

        long nearestDlcOffset = 0;
        long nearestGroupOffset = 0;
        uint32_t nearestGroupValue = 0;
        bool haveDlc = false;
        bool haveGroup = false;
        unsigned long long nearestDlcDistance =
            ~0ULL;
        unsigned long long nearestGroupDistance =
            ~0ULL;

        SIZE_T offset =
            static_cast<SIZE_T>(
                (4ULL - (windowStart & 3ULL))
                & 3ULL);

        for (;
             offset + sizeof(uint32_t)
                <= windowRead;
             offset += sizeof(uint32_t))
        {
            uint32_t value = 0;
            memcpy(
                &value,
                window.data() + offset,
                sizeof(value));

            const uintptr_t address =
                windowStart + offset;
            const long relative =
                static_cast<long>(
                    static_cast<long long>(address)
                    - static_cast<long long>(
                        bennyAddress));
            const unsigned long long distance =
                LegacyV65AbsDistance(relative);

            if (value == dlcHash
                && distance < nearestDlcDistance)
            {
                haveDlc = true;
                nearestDlcDistance = distance;
                nearestDlcOffset = relative;
            }

            if ((value == mapHash
                    || value == storyHash)
                && distance
                    < nearestGroupDistance)
            {
                haveGroup = true;
                nearestGroupDistance = distance;
                nearestGroupOffset = relative;
                nearestGroupValue = value;
            }
        }

        bool contiguousFiveDword = false;
        uintptr_t recordAddress = 0;
        uint32_t contiguousUnknown04 = 0;
        uint32_t contiguousFlags = 0;
        uint32_t contiguousGroup = 0;

        if (bennyAddress >= regionBase + 8
            && bennyAddress + 12 <= regionEnd)
        {
            uint32_t fields[5]{};
            if (ReadProcessExact(
                    bennyAddress - 8,
                    fields,
                    sizeof(fields))
                && fields[0] == dlcHash
                && fields[2] == bennyHash
                && (fields[3] == mapHash
                    || fields[3] == storyHash))
            {
                contiguousFiveDword = true;
                recordAddress = bennyAddress - 8;
                contiguousUnknown04 = fields[1];
                contiguousGroup = fields[3];
                contiguousFlags = fields[4];
                nearestDlcOffset = -8;
                nearestDlcDistance = 8;
                haveDlc = true;
                nearestGroupOffset = 4;
                nearestGroupDistance = 4;
                nearestGroupValue = fields[3];
                haveGroup = true;
            }
        }

        if (!haveDlc || !haveGroup)
            continue;

        if (nearestDlcDistance > 0x80ULL
            || nearestGroupDistance > 0x80ULL)
        {
            continue;
        }

        int score = 0;
        score += contiguousFiveDword ? 200 : 0;
        score += nearestDlcDistance <= 0x20ULL
            ? 50
            : (nearestDlcDistance <= 0x40ULL
                ? 30
                : 10);
        score += nearestGroupDistance <= 0x20ULL
            ? 50
            : (nearestGroupDistance <= 0x40ULL
                ? 30
                : 10);
        if (contiguousFiveDword
            && contiguousFlags == 1U)
        {
            score += 25;
        }

        LegacyV65OverlayCandidate candidate{};
        candidate.bennyAddress = bennyAddress;
        candidate.recordAddress =
            contiguousFiveDword
                ? recordAddress
                : bennyAddress;
        candidate.allocationBase =
            reinterpret_cast<uintptr_t>(
                mbi.AllocationBase);
        candidate.regionBase = regionBase;
        candidate.dlcOffsetFromBenny =
            nearestDlcOffset;
        candidate.groupOffsetFromBenny =
            nearestGroupOffset;
        candidate.groupValue =
            contiguousFiveDword
                ? contiguousGroup
                : nearestGroupValue;
        candidate.contiguousUnknown04 =
            contiguousUnknown04;
        candidate.contiguousFlags =
            contiguousFlags;
        candidate.score = score;
        candidate.contiguousFiveDword =
            contiguousFiveDword;
        candidates.push_back(candidate);

        if (contiguousFiveDword)
        {
            if (candidate.groupValue == storyHash)
                ++contiguousStoryHits;
            else
                ++contiguousMapHits;
        }
        else
        {
            if (candidate.groupValue == storyHash)
                ++relaxedStoryHits;
            else
                ++relaxedMapHits;
        }

        Logf(
            "[LegacyOverlayV65] candidate[%llu] score=%d Benny=%p record=%p allocationBase=%p regionBase=%p dlcOffset=%+ld groupOffset=%+ld group=%s(0x%08X) contiguous5=%s unknown04=0x%08X flags=0x%08X.",
            static_cast<unsigned long long>(
                candidates.size() - 1),
            score,
            reinterpret_cast<void*>(
                candidate.bennyAddress),
            reinterpret_cast<void*>(
                candidate.recordAddress),
            reinterpret_cast<void*>(
                candidate.allocationBase),
            reinterpret_cast<void*>(
                candidate.regionBase),
            candidate.dlcOffsetFromBenny,
            candidate.groupOffsetFromBenny,
            candidate.groupValue == storyHash
                ? "GROUP_MAP_SP"
                : "GROUP_MAP",
            candidate.groupValue,
            candidate.contiguousFiveDword
                ? "yes"
                : "no",
            candidate.contiguousUnknown04,
            candidate.contiguousFlags);

        if (g_diagnosticsEnabled && g_deepMemoryDiagnostics)
        {
            LogMemoryWindowSized(
                candidate.bennyAddress,
                96,
                160,
                "Legacy v65 overlay candidate");
        }
    }

    g_legacyV73OverlayGate.scanned = true;
    g_legacyV73OverlayGate.contiguousMapHits = contiguousMapHits;
    g_legacyV73OverlayGate.contiguousStoryHits = contiguousStoryHits;
    g_legacyV73OverlayGate.relaxedMapHits = relaxedMapHits;
    g_legacyV73OverlayGate.relaxedStoryHits = relaxedStoryHits;

    if (contiguousMapHits + contiguousStoryHits == 1
        && candidates.size() == 1
        && candidates[0].contiguousFiveDword)
    {
        g_legacyV73OverlayGate.recordAddress =
            candidates[0].recordAddress;
        g_legacyV73OverlayGate.groupValue =
            candidates[0].groupValue;
        g_legacyV73OverlayGate.unknown04 =
            candidates[0].contiguousUnknown04;
        g_legacyV73OverlayGate.flags =
            candidates[0].contiguousFlags;
        g_legacyV73OverlayGate.exactSingleMap =
            contiguousMapHits == 1
            && contiguousStoryHits == 0
            && candidates[0].groupValue == mapHash
            && candidates[0].contiguousUnknown04 == 0xF9904BBCU
            && candidates[0].contiguousFlags == 1U;
        g_legacyV73OverlayGate.exactSingleStory =
            contiguousMapHits == 0
            && contiguousStoryHits == 1
            && candidates[0].groupValue == storyHash
            && candidates[0].contiguousUnknown04 == 0xF9904BBCU
            && candidates[0].contiguousFlags == 1U;
    }

    Logf(
        "[LegacyOverlayV65] SUMMARY phase=%s regions=%u scannedMiB=%llu rawBennyHits=%u storedBennyHits=%llu candidates=%llu contiguous{GROUP_MAP=%d GROUP_MAP_SP=%d} relaxedOnly{GROUP_MAP=%d GROUP_MAP_SP=%d} readFailures=%u truncated=%s.",
        phase ? phase : "",
        regionsExamined,
        static_cast<unsigned long long>(
            bytesExamined / (1024ULL * 1024ULL)),
        rawBennyHits,
        static_cast<unsigned long long>(
            bennyHits.size()),
        static_cast<unsigned long long>(
            candidates.size()),
        contiguousMapHits,
        contiguousStoryHits,
        relaxedMapHits,
        relaxedStoryHits,
        readFailures,
        truncated ? "yes" : "no");

    Logf(
        "[LegacyOverlayV77] overlayGate scanned=%s exactSingleMap=%s exactSingleStory=%s record=%p group=0x%08X unknown04=0x%08X flags=0x%08X contiguous{map=%d story=%d} relaxed{map=%d story=%d}.",
        g_legacyV73OverlayGate.scanned ? "yes" : "no",
        g_legacyV73OverlayGate.exactSingleMap ? "yes" : "no",
        g_legacyV73OverlayGate.exactSingleStory ? "yes" : "no",
        reinterpret_cast<void*>(
            g_legacyV73OverlayGate.recordAddress),
        g_legacyV73OverlayGate.groupValue,
        g_legacyV73OverlayGate.unknown04,
        g_legacyV73OverlayGate.flags,
        g_legacyV73OverlayGate.contiguousMapHits,
        g_legacyV73OverlayGate.contiguousStoryHits,
        g_legacyV73OverlayGate.relaxedMapHits,
        g_legacyV73OverlayGate.relaxedStoryHits);

    if (contiguousMapHits + contiguousStoryHits == 1)
    {
        Logf(
            "[LegacyOverlayV65] HIGH-VALUE: exactly one contiguous [mplowrider,unknown,Benny,GROUP_MAP[_SP],flags] candidate exists. Do not write it yet; compare its unknown04/flags/relative offsets and surrounding DWORD signature against the known-working overlayinfo-edited run.");
    }
    else if (candidates.empty())
    {
        Logf(
            "[LegacyOverlayV65] No local mplowrider+Benny+GROUP_MAP[_SP] candidate was found around any parsed Benny hash. Legacy overlayinfo may use indirection; the next step would be owner/back-reference mapping rather than a blind hash write.");
    }
    else
    {
        Logf(
            "[LegacyOverlayV65] Multiple plausible records remain. Use the stock-vs-edited overlayinfo A/B delta to select the exact Legacy classification field; no candidate is mutated in v65.");
    }
}

static bool ApplyLegacyV76OverlayStoryClassification()
{
    if (!g_legacyV73OverlayGate.scanned
        || !g_legacyV73OverlayGate.exactSingleMap
        || g_legacyV73OverlayGate.recordAddress == 0)
    {
        Logf(
            "[LegacyOverlayV77] REFUSED: expected exactly one stock parsed overlay record [mplowrider,0xF9904BBC,Benny,GROUP_MAP,1]. No overlay field was written.");
        return false;
    }

    uint32_t before[5]{};
    uint32_t after[5]{};
    bool readable = false;
    bool writable = false;
    bool faulted = false;
    const uintptr_t record = g_legacyV73OverlayGate.recordAddress;

    MEMORY_BASIC_INFORMATION mbi{};
    if (VirtualQuery(
            reinterpret_cast<const void*>(record),
            &mbi,
            sizeof(mbi)) == sizeof(mbi))
    {
        const DWORD protect = mbi.Protect & 0xFFU;
        readable = mbi.State == MEM_COMMIT
            && protect != PAGE_NOACCESS
            && protect != PAGE_EXECUTE
            && (mbi.Protect & PAGE_GUARD) == 0;
        writable = readable
            && (protect == PAGE_READWRITE
                || protect == PAGE_WRITECOPY
                || protect == PAGE_EXECUTE_READWRITE
                || protect == PAGE_EXECUTE_WRITECOPY);
    }

    __try
    {
        memcpy(before, reinterpret_cast<const void*>(record), sizeof(before));
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        faulted = true;
    }

    const bool exactStock =
        !faulted
        && readable
        && writable
        && before[0] == 0x61322A35U
        && before[1] == 0xF9904BBCU
        && before[2] == 0x4CDFC843U
        && before[3] == 0xBCC89179U
        && before[4] == 1U;

    if (!exactStock)
    {
        Logf(
            "[LegacyOverlayV77] REFUSED: stock record verification failed record=%p readable=%s writable=%s faulted=%s fields=[0x%08X,0x%08X,0x%08X,0x%08X,0x%08X].",
            reinterpret_cast<void*>(record),
            readable ? "yes" : "no",
            writable ? "yes" : "no",
            faulted ? "yes" : "no",
            before[0], before[1], before[2], before[3], before[4]);
        return false;
    }

    faulted = false;
    __try
    {
        *reinterpret_cast<volatile uint32_t*>(record + 0x0C) = 0x578F99E2U;
        MemoryBarrier();
        memcpy(after, reinterpret_cast<const void*>(record), sizeof(after));
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        faulted = true;
    }

    const bool writeCompleted = !faulted;
    g_legacyV73OverlayGate.rewriteVerified =
        writeCompleted
        && after[0] == before[0]
        && after[1] == before[1]
        && after[2] == before[2]
        && after[3] == 0x578F99E2U
        && after[4] == before[4];
    g_legacyV73OverlayGate.rewrittenToStory =
        g_legacyV73OverlayGate.rewriteVerified;

    bool immediateRollbackVerified = false;
    if (!g_legacyV73OverlayGate.rewriteVerified && writeCompleted)
    {
        __try
        {
            *reinterpret_cast<volatile uint32_t*>(record + 0x0C) = 0xBCC89179U;
            MemoryBarrier();

            uint32_t rollback[5]{};
            memcpy(rollback, reinterpret_cast<const void*>(record), sizeof(rollback));
            immediateRollbackVerified =
                rollback[0] == before[0]
                && rollback[1] == before[1]
                && rollback[2] == before[2]
                && rollback[3] == 0xBCC89179U
                && rollback[4] == before[4];
        }
        __except(EXCEPTION_EXECUTE_HANDLER)
        {
            immediateRollbackVerified = false;
        }
    }

    Logf(
        "[LegacyOverlayV77] rewrite record=%p writeCompleted=%s verified=%s faulted=%s group=0x%08X->0x%08X invariant{dlc=%s unknown04=%s Benny=%s flags=%s} immediateRollback=%s.",
        reinterpret_cast<void*>(record),
        writeCompleted ? "yes" : "no",
        g_legacyV73OverlayGate.rewriteVerified ? "yes" : "no",
        faulted ? "yes" : "no",
        before[3],
        after[3],
        after[0] == before[0] ? "yes" : "no",
        after[1] == before[1] ? "yes" : "no",
        after[2] == before[2] ? "yes" : "no",
        after[4] == before[4] ? "yes" : "no",
        immediateRollbackVerified ? "verified" : "not-needed/failed");

    return g_legacyV73OverlayGate.rewriteVerified;
}

static bool RestoreLegacyV76OverlayClassificationOnFailure()
{
    if (!g_legacyV73OverlayGate.rewrittenToStory
        || g_legacyV73OverlayGate.recordAddress == 0)
    {
        return true;
    }

    const uintptr_t record = g_legacyV73OverlayGate.recordAddress;
    bool restored = false;
    __try
    {
        uint32_t* fields = reinterpret_cast<uint32_t*>(record);
        if (fields[0] == 0x61322A35U
            && fields[1] == 0xF9904BBCU
            && fields[2] == 0x4CDFC843U
            && fields[3] == 0x578F99E2U
            && fields[4] == 1U)
        {
            fields[3] = 0xBCC89179U;
            MemoryBarrier();
            restored = fields[3] == 0xBCC89179U;
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        restored = false;
    }

    g_legacyV73OverlayGate.rewriteRestoredOnFailure = restored;
    Logf(
        "[LegacyOverlayV77] failureRollback record=%p restoredToGROUP_MAP=%s.",
        reinterpret_cast<void*>(record),
        restored ? "yes" : "no");
    return restored;
}

static bool VerifyLegacyV76OverlayStoryClassification()
{
    if (!g_legacyV73OverlayGate.recordAddress)
        return false;

    bool verified = false;
    __try
    {
        const uint32_t* fields = reinterpret_cast<const uint32_t*>(
            g_legacyV73OverlayGate.recordAddress);
        verified =
            fields[0] == 0x61322A35U
            && fields[1] == 0xF9904BBCU
            && fields[2] == 0x4CDFC843U
            && fields[3] == 0x578F99E2U
            && fields[4] == 1U;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        verified = false;
    }
    return verified;
}

using RockstarLegacyV73ConstructionPairOwner =
    void(*)(void* child, uint32_t* group, uint32_t* associated);

struct LegacyV73ConstructionReplayState
{
    bool attempted;
    bool v72Resolved;
    bool overlayVerified;
    bool ownerAbiVerified;
    bool descriptorAppliedConstruction;
    bool descriptorVerifiedConstruction;
    bool descriptorRestoredConstruction;
    bool constructionCalled;
    bool constructionFaulted;
    bool stockDerivedBefore;
    bool pairPresentAfterConstruction;
    bool exactDerivedAfterConstruction;
    bool availableAfterConstruction;
    bool lateOwnerResolved;
    bool descriptorAppliedLate;
    bool descriptorVerifiedLate;
    bool descriptorRestoredLate;
    bool lateOwnerCalled;
    bool lateOwnerFaulted;
    bool pairPresentAfterLate;
    bool availableAfterLate;
    uintptr_t child;
    uintptr_t constructionOwner;
    uintptr_t lateOwner;
    uint16_t derivedCountBefore;
    uint16_t derivedCapacityBefore;
    uint16_t derivedCountAfterConstruction;
    uint16_t derivedCapacityAfterConstruction;
    uint16_t derivedCountAfterLate;
    uint16_t derivedCapacityAfterLate;
    LONG naturalCallsBeforeLate;
    LONG naturalCallsAfterLate;
    LONG storyBeforeLate;
    LONG storyAfterLate;
    LONG mapBeforeLate;
    LONG mapAfterLate;
    LONG lowriderBeforeLate;
    LONG lowriderAfterLate;
};

static LegacyV73ConstructionReplayState g_legacyV73{};

static bool g_legacyV87RetrySafe = false;
static uint32_t g_legacyV87AutomaticRetryCount = 0;

static bool IsLegacyV87ConstructionCommitted()
{
    return g_legacyV73.attempted
        && g_legacyV73.v72Resolved
        && g_legacyV73.overlayVerified
        && g_legacyV73.ownerAbiVerified
        && g_legacyV73.constructionCalled
        && !g_legacyV73.constructionFaulted
        && g_legacyV73.descriptorAppliedConstruction
        && g_legacyV73.descriptorVerifiedConstruction
        && g_legacyV73.descriptorRestoredConstruction
        && g_legacyV73.stockDerivedBefore
        && g_legacyV73.pairPresentAfterConstruction
        && g_legacyV73.exactDerivedAfterConstruction;
}

static bool IsLegacyV87CachedStockOverlayReusable()
{
    if (!g_legacyV73OverlayGate.scanned
        || !g_legacyV73OverlayGate.exactSingleMap
        || g_legacyV73OverlayGate.recordAddress == 0
        || !g_legacyV73OverlayGate.rewriteRestoredOnFailure)
    {
        return false;
    }

    bool exactStock = false;
    __try
    {
        const uint32_t* fields = reinterpret_cast<const uint32_t*>(
            g_legacyV73OverlayGate.recordAddress);
        exactStock =
            fields[0] == 0x61322A35U
            && fields[1] == 0xF9904BBCU
            && fields[2] == 0x4CDFC843U
            && fields[3] == 0xBCC89179U
            && fields[4] == 1U;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        exactStock = false;
    }

    return exactStock;
}

static uint16_t CountLegacyV73DerivedPair(
    const LegacyV67DerivedSetup2Snapshot& snapshot,
    uint32_t first,
    uint32_t second)
{
    uint16_t hits = 0;
    if (!snapshot.valid)
        return 0;

    for (uint16_t i = 0; i < snapshot.captured; ++i)
    {
        if (snapshot.first[i] == first
            && snapshot.second[i] == second)
        {
            ++hits;
        }
    }
    return hits;
}

static bool VerifyLegacyV73ConstructionOwnerAbi(
    uint8_t* base,
    uint8_t* end,
    uint8_t*& owner)
{
    owner = nullptr;
    if (!base || !end || end <= base)
        return false;

    uint8_t* candidate = base + 0x92A4B8;
    if (candidate >= end || candidate + 0x80 > end)
        return false;

    uint8_t* start = nullptr;
    uint8_t* finish = nullptr;
    if (!FindRuntimeFunctionBounds(
            base,
            end,
            candidate,
            start,
            finish)
        || start != candidate
        || finish <= start
        || static_cast<size_t>(finish - start) != 0x4F4)
    {
        return false;
    }

    static const uint8_t argumentCapture[] =
    {
        0x49, 0x8B, 0xF0,
        0x4C, 0x8B, 0xFA,
        0x48, 0x8B, 0xF9
    };

    static const uint8_t descriptorGate[] =
    {
        0x44, 0x0F, 0xB7, 0x8F, 0x80, 0x00, 0x00, 0x00,
        0x41, 0x8B, 0x07
    };

    static const uint8_t associatedRead[] = { 0x8B, 0x06 };

    bool argumentCaptureVerified = false;
    bool descriptorGateVerified = false;
    bool associatedReadVerified = false;
    bool readFaulted = false;
    __try
    {

        argumentCaptureVerified =
            memcmp(
                candidate + 0x1F,
                argumentCapture,
                sizeof(argumentCapture)) == 0;
        descriptorGateVerified =
            memcmp(
                candidate + 0x2D,
                descriptorGate,
                sizeof(descriptorGate)) == 0;
        associatedReadVerified =
            memcmp(
                candidate + 0x70,
                associatedRead,
                sizeof(associatedRead)) == 0;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        argumentCaptureVerified = false;
        descriptorGateVerified = false;
        associatedReadVerified = false;
        readFaulted = true;
    }

    const bool verified =
        argumentCaptureVerified
        && descriptorGateVerified
        && associatedReadVerified;

    Logf(
        "[LegacySetup2V77] ownerAbi candidateRVA=0x92A4B8 bounds=yes size=0x4F4 checks{argumentCapture@+0x1F=%s descriptorGate@+0x2D=%s associatedRead@+0x70=%s} readFaulted=%s verified=%s.",
        argumentCaptureVerified ? "yes" : "no",
        descriptorGateVerified ? "yes" : "no",
        associatedReadVerified ? "yes" : "no",
        readFaulted ? "yes" : "no",
        verified ? "yes" : "no");

    if (verified)
        owner = candidate;
    return verified;
}

static bool VerifyLegacyV77ConstructionAddSemantics(
    uint8_t* base,
    uint8_t* end,
    uint8_t* constructionOwner)
{
    if (!base || !end || end <= base || !constructionOwner)
        return false;

    uint8_t* addMutator = base + 0x95443C;
    uint8_t* addCallsite = base + 0x92A985;
    uint8_t* mutatorStart = nullptr;
    uint8_t* mutatorEnd = nullptr;

    const bool mutatorBounds =
        addMutator < end
        && FindRuntimeFunctionBounds(
            base,
            end,
            addMutator,
            mutatorStart,
            mutatorEnd)
        && mutatorStart == addMutator
        && mutatorEnd > mutatorStart;

    bool callVerified = false;
    bool addTrueVerified = false;
    bool faulted = false;

    __try
    {
        if (constructionOwner == base + 0x92A4B8
            && addCallsite >= constructionOwner
            && addCallsite + 5 <= constructionOwner + 0x4F4
            && addCallsite[0] == 0xE8)
        {
            int32_t relative = 0;
            memcpy(&relative, addCallsite + 1, sizeof(relative));
            callVerified = addCallsite + 5 + relative == addMutator;

            uint8_t* scanStart =
                addCallsite >= constructionOwner + 0x20
                    ? addCallsite - 0x20
                    : constructionOwner;
            for (uint8_t* p = scanStart; p + 3 <= addCallsite; ++p)
            {
                if (p[0] == 0x41
                    && p[1] == 0xB1
                    && p[2] == 0x01)
                {
                    addTrueVerified = true;
                    break;
                }
            }
        }
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        callVerified = false;
        addTrueVerified = false;
        faulted = true;
    }

    const bool verified =
        mutatorBounds
        && callVerified
        && addTrueVerified
        && !faulted;

    Logf(
        "[LegacyStableV77] addSemantics mutatorRVA=0x95443C bounds=%s callsiteRVA=0x92A985 targetVerified=%s addTrueNearby=%s faulted=%s verified=%s.",
        mutatorBounds ? "yes" : "no",
        callVerified ? "yes" : "no",
        addTrueVerified ? "yes" : "no",
        faulted ? "yes" : "no",
        verified ? "yes" : "no");

    return verified;
}

static bool VerifyLegacyV73TemporaryDescriptor(
    uintptr_t child)
{
    uintptr_t temporaryTable = 0;
    uint16_t temporaryCount = 0;
    uint16_t mapDescriptorIndex = 0xFFFF;
    uintptr_t mapAssociatedTable = 0;
    uint16_t mapAssociatedCount = 0;
    uint16_t mapBennyCount = 0;
    uint16_t storyBennyCount = 0;

    return g_legacyV61.applied
        && g_legacyV61.verified
        && g_legacyV61.child == child
        && InspectLegacyV61DescriptorFingerprint(
            child,
            false,
            temporaryTable,
            temporaryCount,
            mapDescriptorIndex,
            mapAssociatedTable,
            mapAssociatedCount,
            mapBennyCount,
            storyBennyCount)
        && temporaryTable == g_legacyV61.temporaryTable
        && temporaryCount == g_legacyV61.temporaryCount
        && storyBennyCount == 1
        && mapBennyCount == 0
        && InspectLegacyV66TemporaryVectorInvariants(child);
}

static bool RunLegacyV73ConstructionPairReplay()
{
    if (!IsLegacyExecutableImage()
        || getGameVersion() != 102)
    {
        return false;
    }

    if (g_legacyV73.attempted)
    {
        const BennysMapState current = CaptureBennysMapState();
        Logf(
            "[LegacySetup2V77] construction path is already latched this session; refusing duplicate 0x92A4B8 invocation. available=%s.",
            IsBennysMapAvailable(current) ? "yes" : "no");
        return IsBennysMapAvailable(current);
    }

    g_legacyV73 = LegacyV73ConstructionReplayState{};

    g_legacyV73.overlayVerified =
        VerifyLegacyV76OverlayStoryClassification();

    HMODULE module = GetModuleHandleA(nullptr);
    if (!module)
        return false;

    uint8_t* base = reinterpret_cast<uint8_t*>(module);
    const IMAGE_DOS_HEADER* dos =
        reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
    if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        return false;

    const IMAGE_NT_HEADERS64* nt =
        reinterpret_cast<const IMAGE_NT_HEADERS64*>(
            base + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE
        || nt->OptionalHeader.SizeOfImage == 0)
    {
        return false;
    }
    uint8_t* end = base + nt->OptionalHeader.SizeOfImage;

    uint8_t* naturalOwnerStart = nullptr;
    uint8_t* naturalOwnerEnd = nullptr;
    uint8_t* naturalWrapper = nullptr;
    uint8_t* naturalPrePass = nullptr;
    uintptr_t contextGlobal = 0;
    uintptr_t context = 0;
    LONG lowriderIndex = -1;
    uintptr_t lowriderChild = 0;

    const bool contextResolved =
        ResolveLegacyV64NaturalOwner(
            base,
            end,
            naturalOwnerStart,
            naturalOwnerEnd,
            naturalWrapper,
            naturalPrePass,
            contextGlobal,
            context,
            lowriderIndex,
            lowriderChild);

    uint8_t* constructionOwner = nullptr;
    g_legacyV73.ownerAbiVerified =
        VerifyLegacyV73ConstructionOwnerAbi(
            base,
            end,
            constructionOwner);
    const bool addSemanticsVerified =
        g_legacyV73.ownerAbiVerified
        && VerifyLegacyV77ConstructionAddSemantics(
            base,
            end,
            constructionOwner);

    g_legacyV73.v72Resolved =
        contextResolved && addSemanticsVerified;
    g_legacyV73.child =
        contextResolved ? lowriderChild : 0;
    g_legacyV73.constructionOwner =
        reinterpret_cast<uintptr_t>(constructionOwner);

    Logf(
        "[LegacyStableV77] context resolved=%s context=%p lowriderIndex=%ld child=%p descriptorStockFingerprint=%s addSemantics=%s.",
        contextResolved ? "yes" : "no",
        reinterpret_cast<void*>(context),
        static_cast<long>(lowriderIndex),
        reinterpret_cast<void*>(lowriderChild),
        contextResolved ? "yes" : "no",
        addSemanticsVerified ? "yes" : "no");

    Logf(
        "[LegacySetup2V77] gate stableContext=%s overlayStoryVerified=%s overlayRecord=%p ownerAbiVerified=%s constructionOwner=%p(rva=0x%llX).",
        g_legacyV73.v72Resolved ? "yes" : "no",
        g_legacyV73.overlayVerified ? "yes" : "no",
        reinterpret_cast<void*>(
            g_legacyV73OverlayGate.recordAddress),
        g_legacyV73.ownerAbiVerified ? "yes" : "no",
        constructionOwner,
        constructionOwner
            ? static_cast<unsigned long long>(
                constructionOwner - base)
            : 0ULL);

    if (!g_legacyV73.v72Resolved
        || !g_legacyV73.overlayVerified
        || !g_legacyV73.ownerAbiVerified
        || g_legacyV73.child == 0)
    {
        Logf(
            "[LegacySetup2V77] REFUSED: stable construction gate failed. Expected the exact verified GROUP_MAP_SP overlay classification, validated Lowriders context/fingerprint, and build-102 0x92A4B8 add=true semantics. No descriptor write or Rockstar construction call was attempted.");
        return false;
    }

    if (!ApplyLegacyV61DescriptorView(g_legacyV73.child))
    {

        if (g_legacyV61.restoreFailed)
            g_legacyV73.attempted = true;

        Logf(
            "[LegacySetup2V77] REFUSED: exact XML-equivalent descriptor view could not be applied. Construction processor was not called. retrySafe=%s.",
            !g_legacyV73.attempted ? "yes" : "no");
        return false;
    }

    g_legacyV73.descriptorAppliedConstruction =
        g_legacyV61.applied
        && g_legacyV61.verified
        && g_legacyV61.child == g_legacyV73.child;
    g_legacyV73.descriptorVerifiedConstruction =
        g_legacyV73.descriptorAppliedConstruction
        && VerifyLegacyV73TemporaryDescriptor(
            g_legacyV73.child);

    LegacyV67DerivedSetup2Snapshot before =
        CaptureLegacyV67DerivedSetup2Snapshot(
            g_legacyV73.child,
            "v77 stable pre-construction exact stock derived baseline");
    g_legacyV73.derivedCountBefore = before.count;
    g_legacyV73.derivedCapacityBefore = before.capacity;
    g_legacyV73.stockDerivedBefore =
        before.valid
        && before.count == 2
        && before.capacity == 2
        && before.flagsE8 == 0x09
        && before.captured >= 2
        && before.first[0] == 0x5BF6578FU
        && before.second[0] == 0xA0DF2C6FU
        && before.first[1] == 0x5BF6578FU
        && before.second[1] == 0x37B569AAU
        && CountLegacyV73DerivedPair(
            before,
            0x578F99E2U,
            0x4CDFC843U) == 0;

    if (!g_legacyV73.descriptorVerifiedConstruction
        || !g_legacyV73.stockDerivedBefore)
    {
        Logf(
            "[LegacySetup2V77] REFUSED: pre-construction temporary descriptor or exact stock 2/2 derived baseline failed verification. Restoring descriptor without calling Rockstar.");
        g_legacyV73.descriptorRestoredConstruction =
            RestoreLegacyV61DescriptorView();
        if (!g_legacyV73.descriptorRestoredConstruction)
            g_legacyV73.attempted = true;
        return false;
    }

    uint32_t storyGroup = 0x578F99E2U;
    uint32_t benny = 0x4CDFC843U;
    RockstarLegacyV73ConstructionPairOwner owner =
        reinterpret_cast<
            RockstarLegacyV73ConstructionPairOwner>(
                constructionOwner);

    g_legacyV73.attempted = true;

    __try
    {
        owner(
            reinterpret_cast<void*>(
                g_legacyV73.child),
            &storyGroup,
            &benny);
        g_legacyV73.constructionCalled = true;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        g_legacyV73.constructionFaulted = true;
        g_legacyV73.constructionCalled = false;
    }

    LegacyV67DerivedSetup2Snapshot afterConstruction =
        CaptureLegacyV67DerivedSetup2Snapshot(
            g_legacyV73.child,
            "v77 stable post-construction before descriptor restore");
    g_legacyV73.derivedCountAfterConstruction =
        afterConstruction.count;
    g_legacyV73.derivedCapacityAfterConstruction =
        afterConstruction.capacity;

    const uint16_t storyBennyAfterConstruction =
        CountLegacyV73DerivedPair(
            afterConstruction,
            0x578F99E2U,
            0x4CDFC843U);
    g_legacyV73.pairPresentAfterConstruction =
        storyBennyAfterConstruction == 1;
    g_legacyV73.exactDerivedAfterConstruction =
        afterConstruction.valid
        && afterConstruction.count == 3
        && afterConstruction.capacity >= 3
        && afterConstruction.flagsE8 == 0x09
        && afterConstruction.captured >= 3
        && afterConstruction.first[0] == 0x5BF6578FU
        && afterConstruction.second[0] == 0xA0DF2C6FU
        && afterConstruction.first[1] == 0x5BF6578FU
        && afterConstruction.second[1] == 0x37B569AAU
        && storyBennyAfterConstruction == 1;

    g_legacyV73.descriptorRestoredConstruction =
        RestoreLegacyV61DescriptorView();

    const BennysMapState constructionState =
        CaptureBennysMapState();
    g_legacyV73.availableAfterConstruction =
        IsBennysMapAvailable(constructionState);

    Logf(
        "[LegacySetup2V77] constructionCall called=%s faulted=%s descriptor{applied=%s verified=%s restored=%s} derived{count=%u/%u->%u/%u pairStoryBenny=%s exact3=%s} available=%s.",
        g_legacyV73.constructionCalled ? "yes" : "no",
        g_legacyV73.constructionFaulted ? "yes" : "no",
        g_legacyV73.descriptorAppliedConstruction ? "yes" : "no",
        g_legacyV73.descriptorVerifiedConstruction ? "yes" : "no",
        g_legacyV73.descriptorRestoredConstruction ? "yes" : "no",
        static_cast<unsigned int>(g_legacyV73.derivedCountBefore),
        static_cast<unsigned int>(g_legacyV73.derivedCapacityBefore),
        static_cast<unsigned int>(g_legacyV73.derivedCountAfterConstruction),
        static_cast<unsigned int>(g_legacyV73.derivedCapacityAfterConstruction),
        g_legacyV73.pairPresentAfterConstruction ? "yes" : "no",
        g_legacyV73.exactDerivedAfterConstruction ? "yes" : "no",
        g_legacyV73.availableAfterConstruction ? "yes" : "no");
    LogBennysMapState(
        "[LegacySetup2V77] post-construction state",
        constructionState);

    const bool stableSuccess =
        g_legacyV73.constructionCalled
        && !g_legacyV73.constructionFaulted
        && g_legacyV73.descriptorAppliedConstruction
        && g_legacyV73.descriptorVerifiedConstruction
        && g_legacyV73.descriptorRestoredConstruction
        && g_legacyV73.stockDerivedBefore
        && g_legacyV73.pairPresentAfterConstruction
        && g_legacyV73.exactDerivedAfterConstruction
        && g_legacyV73.availableAfterConstruction;

    Logf(
        "[LegacySetup2V77] hardenedResult success=%s called=%s faulted=%s descriptorRestored=%s stock2of2=%s exact3of3=%s pairStoryBenny=%s available=%s lateOwnerRetired=yes.",
        stableSuccess ? "yes" : "no",
        g_legacyV73.constructionCalled ? "yes" : "no",
        g_legacyV73.constructionFaulted ? "yes" : "no",
        g_legacyV73.descriptorRestoredConstruction ? "yes" : "no",
        g_legacyV73.stockDerivedBefore ? "yes" : "no",
        g_legacyV73.exactDerivedAfterConstruction ? "yes" : "no",
        g_legacyV73.pairPresentAfterConstruction ? "yes" : "no",
        g_legacyV73.availableAfterConstruction ? "yes" : "no");

    return stableSuccess;
}


static bool IsLegacyV98OlderMutationLayoutSafe()
{
    return IsOlderLegacyLowridersBuild()
        && g_legacyV98.readyForMutationResearch
        && !g_legacyV98.faulted
        && g_legacyV98.contextCandidates == 1
        && g_legacyV98.descriptorCandidates == 1
        && g_legacyV98.derivedCandidates == 1
        && g_legacyV98.overlayCandidates == 1
        && g_legacyV98.constructionCandidates == 1
        && g_legacyV98.childArrayOffset == 0x28U
        && g_legacyV98.childCountOffset == 0x30U
        && g_legacyV98.childStride == 0xF0U
        && g_legacyV98.childHashOffset == 0x60U
        && g_legacyV98.descriptorVectorOffset == 0x78U
        && g_legacyV98.descriptorCountOffset == 0x80U
        && g_legacyV98.descriptorCapacityOffset == 0x82U
        && g_legacyV98.descriptorStride == 0x18U
        && g_legacyV98.descriptorGroupOffset == 0x00U
        && g_legacyV98.descriptorAssociatedOffset == 0x08U
        && g_legacyV98.descriptorAssociatedCountOffset == 0x10U
        && g_legacyV98.descriptorCount == 2
        && g_legacyV98.mapDescriptorIndex == 1
        && g_legacyV98.mapAssociatedCount == 4
        && g_legacyV98.mapBennyCount == 1
        && g_legacyV98.storyBennyCount == 0
        && g_legacyV98.derivedVectorOffset == 0xD8U
        && g_legacyV98.derivedCountOffset == 0xE0U
        && g_legacyV98.derivedCapacityOffset == 0xE2U
        && g_legacyV98.derivedFlagsOffset == 0xE8U
        && g_legacyV98.derivedCount == 2
        && g_legacyV98.derivedCapacity == 2
        && g_legacyV98.derivedFlags == 0x09U
        && g_legacyV98.overlayRegistryOffset == 0x08U
        && g_legacyV98.overlayExactMapHits == 1
        && g_legacyV98.overlayExactStoryHits == 0
        && g_legacyV98.overlayRecord != 0
        && g_legacyV98.lowriderChild != 0
        && g_legacyV98.constructionOwner != 0
        && g_legacyV98.constructionCallsite != 0
        && g_legacyV98.addMutator != 0;
}

static bool VerifyLegacyV98OlderConstructionOwnerAbi()
{
    if (!IsLegacyV98OlderMutationLayoutSafe())
        return false;

    uint8_t* base = nullptr;
    uint8_t* end = nullptr;
    if (!GetExeRange(base, end)
        || !base
        || !end
        || end <= base)
    {
        return false;
    }

    uint8_t* owner =
        reinterpret_cast<uint8_t*>(
            g_legacyV98.constructionOwner);
    uint8_t* callsite =
        reinterpret_cast<uint8_t*>(
            g_legacyV98.constructionCallsite);
    uint8_t* mutator =
        reinterpret_cast<uint8_t*>(
            g_legacyV98.addMutator);

    uint8_t* ownerStart = nullptr;
    uint8_t* ownerEnd = nullptr;
    uint8_t* mutatorStart = nullptr;
    uint8_t* mutatorEnd = nullptr;

    const bool ownerBounds =
        owner >= base
        && owner < end
        && FindRuntimeFunctionBounds(
            base,
            end,
            owner,
            ownerStart,
            ownerEnd)
        && ownerStart == owner
        && ownerEnd > ownerStart;

    const bool mutatorBounds =
        mutator >= base
        && mutator < end
        && FindRuntimeFunctionBounds(
            base,
            end,
            mutator,
            mutatorStart,
            mutatorEnd)
        && mutatorStart == mutator
        && mutatorEnd > mutatorStart;

    if (!ownerBounds
        || !mutatorBounds
        || callsite < owner
        || callsite + 5 > ownerEnd)
    {
        return false;
    }

    static const uint8_t argumentCapture[] =
    {
        0x49, 0x8B, 0xF0,
        0x4C, 0x8B, 0xFA,
        0x48, 0x8B, 0xF9
    };

    static const uint8_t descriptorGate[] =
    {
        0x44, 0x0F, 0xB7, 0x8F, 0x80, 0x00, 0x00, 0x00,
        0x41, 0x8B, 0x07
    };

    static const uint8_t associatedRead[] =
    {
        0x8B, 0x06
    };

    bool argumentCaptureVerified = false;
    bool descriptorGateVerified = false;
    bool associatedReadVerified = false;
    bool callVerified = false;
    bool callShapeVerified = false;
    bool addTrueVerified = false;
    bool faulted = false;

    __try
    {
        argumentCaptureVerified =
            owner + 0x28 <= ownerEnd
            && memcmp(
                owner + 0x1F,
                argumentCapture,
                sizeof(argumentCapture)) == 0;

        descriptorGateVerified =
            owner + 0x38 <= ownerEnd
            && memcmp(
                owner + 0x2D,
                descriptorGate,
                sizeof(descriptorGate)) == 0;

        associatedReadVerified =
            owner + 0x72 <= ownerEnd
            && memcmp(
                owner + 0x70,
                associatedRead,
                sizeof(associatedRead)) == 0;

        if (callsite[0] == 0xE8)
        {
            int32_t relative = 0;
            memcpy(
                &relative,
                callsite + 1,
                sizeof(relative));
            callVerified =
                callsite + 5 + relative == mutator;
        }

        callShapeVerified =
            HasLegacyV98PairPointerCallShape(
                owner,
                callsite);

        addTrueVerified =
            HasLegacyV98AddTrueSetup(
                owner,
                callsite);
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        faulted = true;
    }

    const bool verified =
        !faulted
        && argumentCaptureVerified
        && descriptorGateVerified
        && associatedReadVerified
        && callVerified
        && callShapeVerified
        && addTrueVerified;

    Logf(
        "[UniversalLegacyV104] ownerAbi owner=%p size=0x%llX callsite=%p offset=0x%llX mutator=%p checks{argumentCapture=%s descriptorGate=%s associatedRead=%s rel32Target=%s pairPointers=%s addTrue=%s} faulted=%s verified=%s.",
        owner,
        static_cast<unsigned long long>(
            ownerEnd - owner),
        callsite,
        static_cast<unsigned long long>(
            callsite - owner),
        mutator,
        argumentCaptureVerified ? "yes" : "no",
        descriptorGateVerified ? "yes" : "no",
        associatedReadVerified ? "yes" : "no",
        callVerified ? "yes" : "no",
        callShapeVerified ? "yes" : "no",
        addTrueVerified ? "yes" : "no",
        faulted ? "yes" : "no",
        verified ? "yes" : "no");

    return verified;
}

static bool TryLoadBennysMapOlderLegacyUniversal(bool manualRetry)
{
    if (!IsOlderLegacyLowridersBuild())
        return false;

    BennysMapState state =
        CaptureBennysMapState();

    if (IsBennysMapReadyForOlderLegacy(state))
    {
        ActivateBennysInterior(state);
        return true;
    }

    if (g_legacyV98OlderMutationCommitted)
    {
        LogBennysMapState(
            "[UniversalLegacyV104] construction was already committed; waiting for Benny's to finish streaming.",
            state);
        return false;
    }

    if (g_legacyV98OlderMutationAttempted)
    {
        Logf(
            "[UniversalLegacyV104] REFUSED: the dynamic construction call was already attempted this session and will not be repeated. faulted=%s.",
            g_legacyV98OlderMutationFaulted ? "yes" : "no");
        return false;
    }

    const bool resolved =
        RunLegacyV98UniversalResolver(
            manualRetry
                ? "manual v104 older-Legacy mutation gate"
                : "initial v104 older-Legacy mutation gate");

    if (!resolved
        || !IsLegacyV98OlderMutationLayoutSafe())
    {
        Logf(
            "[UniversalLegacyV104] Runtime resolver did not satisfy the exact frozen Legacy layout/fingerprint gate. No memory write or Rockstar construction call was attempted; falling back to the targeted IPL compatibility path.");
        return false;
    }

    if (!VerifyLegacyV98OlderConstructionOwnerAbi())
    {
        Logf(
            "[UniversalLegacyV104] Runtime construction owner failed the frozen ABI/call-shape proof. No memory write or Rockstar construction call was attempted; falling back to the targeted IPL compatibility path.");
        return false;
    }

    g_legacyV73OverlayGate =
        LegacyV73OverlayGateState{};
    g_legacyV73OverlayGate.scanned = true;
    g_legacyV73OverlayGate.exactSingleMap = true;
    g_legacyV73OverlayGate.contiguousMapHits = 1;
    g_legacyV73OverlayGate.contiguousStoryHits = 0;
    g_legacyV73OverlayGate.recordAddress =
        g_legacyV98.overlayRecord;
    g_legacyV73OverlayGate.groupValue =
        0xBCC89179U;
    g_legacyV73OverlayGate.unknown04 =
        0xF9904BBCU;
    g_legacyV73OverlayGate.flags = 1U;

    if (!ApplyLegacyV76OverlayStoryClassification())
    {
        Logf(
            "[UniversalLegacyV104] Exact overlay record was resolved but the verified GROUP_MAP -> GROUP_MAP_SP rewrite was refused. Falling back without touching setup2 descriptors.");
        return false;
    }

    g_legacyV61AllowUniversalOlderBuild = true;
    const bool descriptorApplied =
        ApplyLegacyV61DescriptorView(
            g_legacyV98.lowriderChild);
    g_legacyV61AllowUniversalOlderBuild = false;

    if (!descriptorApplied)
    {
        RestoreLegacyV76OverlayClassificationOnFailure();
        Logf(
            "[UniversalLegacyV104] Exact temporary descriptor view could not be applied. Overlay rollback was attempted and the Rockstar construction owner was not called.");
        return false;
    }

    const bool temporaryDescriptorVerified =
        VerifyLegacyV73TemporaryDescriptor(
            g_legacyV98.lowriderChild);

    LegacyV67DerivedSetup2Snapshot before =
        CaptureLegacyV67DerivedSetup2Snapshot(
            g_legacyV98.lowriderChild,
            "v104 older-Legacy pre-construction exact stock derived baseline");

    const bool stockDerived =
        before.valid
        && before.count == 2
        && before.capacity == 2
        && before.flagsE8 == 0x09
        && before.captured >= 2
        && before.first[0] == 0x5BF6578FU
        && before.second[0] == 0xA0DF2C6FU
        && before.first[1] == 0x5BF6578FU
        && before.second[1] == 0x37B569AAU
        && CountLegacyV73DerivedPair(
            before,
            0x578F99E2U,
            0x4CDFC843U) == 0;

    if (!temporaryDescriptorVerified
        || !stockDerived)
    {
        const bool descriptorRestored =
            RestoreLegacyV61DescriptorView();
        const bool overlayRestored =
            RestoreLegacyV76OverlayClassificationOnFailure();

        Logf(
            "[UniversalLegacyV104] REFUSED before construction: temporaryDescriptor=%s exactStockDerived=%s descriptorRestored=%s overlayRestored=%s.",
            temporaryDescriptorVerified ? "yes" : "no",
            stockDerived ? "yes" : "no",
            descriptorRestored ? "yes" : "no",
            overlayRestored ? "yes" : "no");
        return false;
    }

    uint32_t storyGroup =
        0x578F99E2U;
    uint32_t benny =
        0x4CDFC843U;

    RockstarLegacyV73ConstructionPairOwner owner =
        reinterpret_cast<
            RockstarLegacyV73ConstructionPairOwner>(
                g_legacyV98.constructionOwner);

    g_legacyV98OlderMutationAttempted = true;
    g_legacyV98.mutationAttempted = true;

    bool constructionCalled = false;
    bool constructionFaulted = false;

    __try
    {
        owner(
            reinterpret_cast<void*>(
                g_legacyV98.lowriderChild),
            &storyGroup,
            &benny);
        constructionCalled = true;
    }
    __except(EXCEPTION_EXECUTE_HANDLER)
    {
        constructionFaulted = true;
        constructionCalled = false;
    }

    LegacyV67DerivedSetup2Snapshot after =
        CaptureLegacyV67DerivedSetup2Snapshot(
            g_legacyV98.lowriderChild,
            "v104 older-Legacy post-construction before descriptor restore");

    const uint16_t storyBennyAfter =
        CountLegacyV73DerivedPair(
            after,
            0x578F99E2U,
            0x4CDFC843U);

    const bool pairPresent =
        storyBennyAfter == 1;

    const bool exactDerived =
        after.valid
        && after.count == 3
        && after.capacity >= 3
        && after.flagsE8 == 0x09
        && after.captured >= 3
        && after.first[0] == 0x5BF6578FU
        && after.second[0] == 0xA0DF2C6FU
        && after.first[1] == 0x5BF6578FU
        && after.second[1] == 0x37B569AAU
        && pairPresent;

    const bool descriptorRestored =
        RestoreLegacyV61DescriptorView();

    const bool committed =
        constructionCalled
        && !constructionFaulted
        && descriptorRestored
        && pairPresent
        && exactDerived;

    g_legacyV98OlderMutationCommitted =
        committed;
    g_legacyV98OlderMutationFaulted =
        constructionFaulted
        || !descriptorRestored;

    if (!committed)
    {
        const bool overlayRestored =
            RestoreLegacyV76OverlayClassificationOnFailure();

        Logf(
            "[UniversalLegacyV104] FAILED construction commit called=%s faulted=%s descriptorRestored=%s pairStoryBenny=%s exact3of3=%s overlayRollback=%s. The dynamic construction call is latched and will not be repeated this session.",
            constructionCalled ? "yes" : "no",
            constructionFaulted ? "yes" : "no",
            descriptorRestored ? "yes" : "no",
            pairPresent ? "yes" : "no",
            exactDerived ? "yes" : "no",
            overlayRestored ? "yes" : "no");
        return false;
    }

    state = CaptureBennysMapState();
    if (IsBennysMapReadyForOlderLegacy(state))
    {
        ActivateBennysInterior(state);
        LogBennysMapState(
            "[UniversalLegacyV104] SUCCESS: runtime-resolved Legacy construction loaded Benny's.",
            state);
        return true;
    }

    LogBennysMapState(
        "[UniversalLegacyV104] Construction committed exactly once; retaining the verified GROUP_MAP_SP overlay classification while passive streaming completes.",
        state);
    return false;
}

static bool TryLoadBennysMap(bool manualRetry)
{
    BennysMapState state = CaptureBennysMapState();
    const bool olderLegacyFallback = IsOlderLegacyLowridersBuild();
    const bool alreadyAvailable = olderLegacyFallback
        ? IsBennysMapReadyForOlderLegacy(state)
        : IsBennysMapAvailable(state);

    if (alreadyAvailable)
    {

        if (IsLegacyExecutableImage()
            && getGameVersion() == 102
            && manualRetry
            && g_diagnosticsEnabled
            && g_deepMemoryDiagnostics)
        {
            Logf(
                "[Info] Legacy v77 deep A/B capture requested while Benny is already available.");
            DiscoverLegacyV59PostConstructionLowriderRecord(true);
            LogLegacyV59PostConstructionState(
                "Benny-already-available deep A/B scan");
            LogLegacyV60DeepCandidateAnalysis(
                "Benny-already-available deep A/B scan");

            const uintptr_t workingChild =
                FindLegacyV68UniqueWorkingLowriderChild();
            if (workingChild)
            {
                LogLegacyV68DerivedSpanFingerprint(
                    workingChild,
                    "working XML baseline");
            }
        }

        ActivateBennysInterior(state);
        LogBennysMapState("[OK] Benny's map was already available.", state);
        return true;
    }

    if (IsEnhancedVersion())
    {
        Logf("[Warn] Enhanced build detected: retired raw EXECUTE_CONTENT_CHANGESET 0x%016llX will NOT be called.", static_cast<unsigned long long>(kExecuteContentChangesetNative));
        Logf("[Warn] ScriptHookV Enhanced cannot safely resolve this retired command on the tested Enhanced runtime; skipping it to prevent a hard fatal.");

        bool internalGroupAddApplied = false;

        if (g_experimentalInternalGroupAdd)
        {
            internalGroupAddApplied =
                TryMutateBennyStoryGroupEntryViaRockstar1012(true);

            if (internalGroupAddApplied)
            {
                bool reprocessCalled = false;

                if (g_experimentalMapStateReprocess)
                {
                    reprocessCalled =
                        TryReprocessEnhancedMapStateViaRockstar1012();

                    Logf(
                        "[Reprocess] ExperimentalMapStateReprocess result=%s.",
                        reprocessCalled ? "call-completed" : "not-called/failed");
                }
                else
                {
                    Logf(
                        "[Info] ExperimentalMapStateReprocess is disabled; C2B600 will not be called.");
                }

                int settleMs = ReadIniInt(
                    g_iniPath,
                    "Settings",
                    "ExperimentalInternalGroupAddSettleMs",
                    1500);

                if (settleMs < 0)
                    settleMs = 0;
                if (settleMs > 5000)
                    settleMs = 5000;

                if (settleMs != 0)
                    WAIT(static_cast<DWORD>(settleMs));

                state = CaptureBennysMapState();

                if (IsBennysMapAvailable(state))
                {
                    ActivateBennysInterior(state);
                    LogBennysMapState(
                        reprocessCalled
                            ? "[OK] Benny's map became available after C2F090 insertion + C2B600 map-state reprocess."
                            : "[OK] Benny's map became available after allocator-safe C2F090 GROUP_MAP_SP -> Benny insertion.",
                        state);
                    return true;
                }

                LogBennysMapState(
                    reprocessCalled
                        ? "[Experiment] C2F090 insertion + C2B600 reprocess completed, but Benny's map is not yet detectable."
                        : "[Experiment] C2F090 inserted the exact GROUP_MAP_SP -> Benny association, but Benny's map is not yet detectable.",
                    state);

                if (reprocessCalled)
                {
                    Logf(
                        "[Experiment] C2B600 is therefore either not the final activation stage or must run at a different construction/state-transition time. The log records whether it consumed the exact child64 association.");
                }
                else
                {
                    Logf(
                        "[Experiment] This means the association write itself is correct, but a construction-time/later consumer step is still required to activate the content.");
                }
            }
            else
            {
                Logf(
                    "[InternalAdd] Experimental C2F090 association insertion was not performed or could not be verified.");
            }
        }
        else
        {
            Logf(
                "[Info] ExperimentalInternalGroupAdd is disabled; verified C2F090 will not be called.");
        }

        bool memoryPatchApplied = false;

        if (g_experimentalMemoryPatch)
        {
            memoryPatchApplied =
                ProbeOrApplyExperimentalBennyMemoryPatch1012(true);
        }
        else
        {
            Logf("[Info] ExperimentalMemoryPatch is disabled; skipping the obsolete transient-candidate write probe.");
        }

        if (memoryPatchApplied)
        {
            int settleMs = ReadIniInt(
                g_iniPath,
                "Settings",
                "ExperimentalMemoryPatchSettleMs",
                1000);

            if (settleMs < 0)
                settleMs = 0;
            if (settleMs > 5000)
                settleMs = 5000;

            if (settleMs != 0)
                WAIT(static_cast<DWORD>(settleMs));

            state = CaptureBennysMapState();
            if (IsBennysMapAvailable(state))
            {
                ActivateBennysInterior(state);
                LogBennysMapState(
                    "[OK] Benny's map became available after the experimental GROUP_MAP -> GROUP_MAP_SP data patch.",
                    state);
                return true;
            }

            Logf("[Patch] Experimental group-hash patch is applied, but Benny's was not immediately detectable. It will remain applied for passive probing; press F11 to restore it.");
        }
        else if (g_experimentalMemoryPatch)
        {
            Logf("[Info] Enhanced memory probe did not apply a group-hash patch. No whole GROUP_MAP or REQUEST_IPL fallback will be used.");
        }
        else
        {
            Logf("[Info] No memory write was attempted. Enhanced group-table diagnostics will inspect the runtime +0x108/+0x110 structure instead.");
        }

        return false;
    }

    if (olderLegacyFallback)
    {
        if (TryLoadBennysMapOlderLegacyUniversal(manualRetry))
            return true;

        if (g_legacyV98OlderMutationCommitted)
            return false;

        return TryLoadBennysMapOlderLegacyIplFallback(manualRetry);
    }

    if (!manualRetry)
        g_legacyV87RetrySafe = false;

    Logf(
        "[Info] %sLegacy v77 stock-XML stable path (v92 context-registry controller): v86 resolves the validated Legacy context, context+0x08 resolves Rockstar's overlay pointer registry, and exactly one verified Benny overlay row is selected without an allocation scan. v87 readiness retry and the one-shot 0x92A4B8 construction boundary are retained.",
        manualRetry ? "Manual " : "Automatic/initial ");

    if (manualRetry
        && g_diagnosticsEnabled
        && g_deepMemoryDiagnostics)
    {
        DiscoverLegacyV59PostConstructionLowriderRecord(true);
        LogLegacyV59PostConstructionState("manual v77 deep diagnostic scan");
        LogLegacyV60DeepCandidateAnalysis("manual v77 deep diagnostic scan");
        LogLegacyV63StateOwnerMap(true);
    }

    if (g_legacyV73.attempted)
    {
        Logf(
            "[LegacyStartupV87] construction latch already set; no overlay rewrite, descriptor mutation, or duplicate 0x92A4B8 call will be attempted. committed=%s available=%s.",
            IsLegacyV87ConstructionCommitted() ? "yes" : "no",
            IsBennysMapAvailable(state) ? "yes" : "no");
        return IsBennysMapAvailable(state);
    }

    const bool cachedOverlayReusable =
        !manualRetry && IsLegacyV87CachedStockOverlayReusable();
    if (cachedOverlayReusable)
    {
        Logf(
            "[LegacyStartupV92] Reusing the previously verified stock overlay record after clean rollback; context registry resolution skipped record=%p.",
            reinterpret_cast<void*>(g_legacyV73OverlayGate.recordAddress));
    }
    else
    {
        if (manualRetry
            && g_diagnosticsEnabled
            && g_deepMemoryDiagnostics)
        {
            ScanLegacyV65OverlayCandidates(
                "manual deep historical process-wide overlay cross-check");
            ScanLegacyV88OverlayFromLowriderAllocation(
                "manual deep historical v88 allocation cross-check");
        }

        ResolveLegacyV92OverlayFromContextRegistry(
            manualRetry
                ? "manual v92 context-registry pre-rewrite"
                : "automatic/initial v92 context-registry pre-rewrite");
    }

    if (!ApplyLegacyV76OverlayStoryClassification())
    {
        g_legacyV87RetrySafe =
            !g_legacyV73.attempted
            && !g_legacyV61.applied
            && !g_legacyV61.restoreFailed;
        Logf(
            "[LegacyOverlayV77] Overlay rewrite gate failed; stable setup2 construction pass will not run. automaticRetryEligible=%s.",
            g_legacyV87RetrySafe ? "yes" : "no");
        return false;
    }

    const bool replayAvailable =
        RunLegacyV73ConstructionPairReplay();

    LogLegacyV61DescriptorState("after v77 stable setup2 construction pass");
    state = CaptureBennysMapState();

    if (replayAvailable && IsBennysMapAvailable(state))
    {
        g_legacyV87RetrySafe = false;
        ActivateBennysInterior(state);
        LogBennysMapState(
            "[LegacyOverlayV77] SUCCESS: stock overlayinfo was classified to GROUP_MAP_SP at runtime and the frozen setup2 construction pass loaded Benny's.",
            state);
        Logf(
            "[LegacyStableV77] SUCCESS stockXml=yes overlayExact=yes overlayRewriteVerified=%s descriptorRollbackVerified=%s derivedExact3of3=%s pairStoryBenny=%s available=yes heavyDiscoveryUsed=%s.",
            g_legacyV73OverlayGate.rewriteVerified ? "yes" : "no",
            g_legacyV73.descriptorRestoredConstruction ? "yes" : "no",
            g_legacyV73.exactDerivedAfterConstruction ? "yes" : "no",
            g_legacyV73.pairPresentAfterConstruction ? "yes" : "no",
            (manualRetry && g_diagnosticsEnabled && g_deepMemoryDiagnostics)
                ? "yes"
                : "no");
        return true;
    }

    if (IsLegacyV87ConstructionCommitted())
    {
        g_legacyV87RetrySafe = false;
        LogBennysMapState(
            "[LegacyStartupV87] Construction committed exactly once but Benny is not detectable yet; retaining GROUP_MAP_SP overlay classification and waiting for passive availability.",
            state);
        return false;
    }

    const bool overlayRestored =
        RestoreLegacyV76OverlayClassificationOnFailure();
    g_legacyV87RetrySafe =
        overlayRestored
        && !g_legacyV73.attempted
        && !g_legacyV61.applied
        && !g_legacyV61.restoreFailed;

    LogBennysMapState(
        "[LegacyOverlayV77] Combined stock-XML attempt stopped before committed construction; overlay rollback was attempted.",
        state);
    Logf(
        "[LegacyStartupV87] preConstructionFailure=yes overlayRollback=%s descriptorClean=%s automaticRetryEligible=%s.",
        overlayRestored ? "yes" : "no",
        (!g_legacyV61.applied && !g_legacyV61.restoreFailed) ? "yes" : "no",
        g_legacyV87RetrySafe ? "yes" : "no");
    return false;
}

static bool IsEnhancedV100FrozenProductionHealthy()
{
    if (!g_enhancedV100.bootstrapAttempted
        || !g_enhancedV100.bootstrapReady
        || g_enhancedV100.bootstrapFaulted
        || !g_enhancedV100.liveLayoutResolved
        || g_enhancedV100.structuralChains != 1
        || g_enhancedV100.childLayoutCandidates != 1
        || g_enhancedV100.descriptorLayoutCandidates != 1)
    {
        return false;
    }

    const LONG liveAttempts =
        InterlockedCompareExchange(
            &g_enhancedV100.liveGateAttempts,
            0,
            0);
    const LONG livePassed =
        InterlockedCompareExchange(
            &g_enhancedV100.liveGatePassed,
            0,
            0);
    const LONG liveRejected =
        InterlockedCompareExchange(
            &g_enhancedV100.liveGateRejected,
            0,
            0);
    const LONG mutationAttempts =
        InterlockedCompareExchange(
            &g_enhancedV100.mutationAttempts,
            0,
            0);
    const LONG injected =
        InterlockedCompareExchange(
            &g_enhancedV100.injected,
            0,
            0);
    const LONG alreadyPresent =
        InterlockedCompareExchange(
            &g_enhancedV100.alreadyPresent,
            0,
            0);
    const LONG writeFaults =
        InterlockedCompareExchange(
            &g_enhancedV100.writeFaults,
            0,
            0);
    const LONG restoreAttempts =
        InterlockedCompareExchange(
            &g_enhancedV100.restoreAttempts,
            0,
            0);
    const LONG restoreVerified =
        InterlockedCompareExchange(
            &g_enhancedV100.restoreVerified,
            0,
            0);
    const LONG restoreFailures =
        InterlockedCompareExchange(
            &g_enhancedV100.restoreFailures,
            0,
            0);

    const bool injectedCleanly =
        injected == 1
        && alreadyPresent == 0
        && restoreAttempts == 1
        && restoreVerified == 1;

    const bool alreadySatisfied =
        injected == 0
        && alreadyPresent == 1
        && restoreAttempts == 0
        && restoreVerified == 0;

    return liveAttempts == 1
        && livePassed == 1
        && liveRejected == 0
        && mutationAttempts == 1
        && (injectedCleanly || alreadySatisfied)
        && writeFaults == 0
        && restoreFailures == 0;
}

static bool IsProductionStartupSuccess(
    bool enhanced,
    bool loaded)
{
    if (!loaded)
        return false;

    if (!enhanced)
        return true;

    return IsEnhancedV100FrozenProductionHealthy();
}

static bool IsProductionStartupPending(
    bool enhanced,
    bool loaded)
{
    if (enhanced
        || loaded)
    {
        return false;
    }

    return g_legacyV87RetrySafe
        || IsLegacyV87ConstructionCommitted()
        || (IsOlderLegacyLowridersBuild()
            && g_legacyV98OlderMutationCommitted);
}

static void EmitProductionFailureDiagnostics(
    bool enhanced,
    const char* reason)
{
    if (g_productionLogFinalized)
        return;

    Logf(
        "[Failure] Production startup validation failed: %s",
        reason ? reason : "unspecified failure");

    if (enhanced)
    {
        LogEnhancedV100IntegrationState(
            "production failure");
        RunEnhancedV99UniversalResolver(
            "production failure read-only proof");
    }
    else
    {
        RunLegacyV98UniversalResolver(
            "production failure read-only proof");
    }

    RunDiagnostics(
        reason ? reason : "production startup failure");

    FinalizeProductionFailureLog(
        enhanced,
        reason);
}

static void ResolveProductionStartupLog(
    bool enhanced,
    bool loaded,
    const char* failureReason)
{
    if (g_productionLogFinalized)
        return;

    if (IsProductionStartupSuccess(
            enhanced,
            loaded))
    {
        FinalizeProductionSuccessLog(
            enhanced);
        return;
    }

    if (IsProductionStartupPending(
            enhanced,
            loaded))
    {
        return;
    }

    EmitProductionFailureDiagnostics(
        enhanced,
        failureReason);
}

void ScriptMain()
{
    g_logEnabled =
        (ReadIniInt(
            g_iniPath,
            "Settings",
            "EnableLog",
            1) != 0);

    g_diagnosticsEnabled = true;
    g_deepMemoryDiagnostics =
        (ReadIniInt(
            g_iniPath,
            "Settings",
            "DeepMemoryDiagnostics",
            0) != 0);

    g_showNotification =
        g_showNotification
        && (ReadIniInt(
            g_iniPath,
            "Settings",
            "ShowNotification",
            1) != 0);

    g_bennysGarageDoorRecoveryEnabled =
        (ReadIniInt(
            g_iniPath,
            "Settings",
            "GarageDoorRecovery",
            1) != 0);

    g_bennysAllowEmergencyVehicles =
        ReadIniBool(
            g_bennysSettingsPath,
            "SETTINGS",
            "AllowEmergencyVehicles",
            true);

    g_bennysAllowServiceVehicles =
        ReadIniBool(
            g_bennysSettingsPath,
            "SETTINGS",
            "AllowServiceVehicles",
            true);

    g_bennysAllowUtilityVehicles =
        ReadIniBool(
            g_bennysSettingsPath,
            "SETTINGS",
            "AllowUtilityVehicles",
            true);

    g_bennysAllowOversizedVehicles =
        ReadIniBool(
            g_bennysSettingsPath,
            "SETTINGS",
            "AllowOversizedVehicles",
            true);

    g_experimentalMemoryPatch = false;
    g_experimentalInternalGroupAdd = false;
    g_experimentalMapStateReprocess = false;
    g_experimentalOverlayDescriptorRewrite = false;

    if (g_logEnabled)
        ResetLogFile();

    const int gameVersion = getGameVersion();
    const bool enhanced = IsEnhancedVersion();

    if (enhanced)
    {
        g_enhancedV93.gameVersionConfirmed =
            (gameVersion == 1012);
    }

    if (!enhanced
        && gameVersion == 102
        && g_deepMemoryDiagnostics
        && !g_legacyNaturalHookAttempted)
    {
        InstallLegacyNaturalDescriptorHookAtModuleLoad();
    }

    Logf("BennysMapLoader starting...");
    Logf("[Info] Internal name: BennysMapLoader");
    LogLoadedModuleIdentity();
    LogEarlyConstructionSnapshot();
    LogSetup2LoaderProbeState("startup");
    LogConstructionC2F090HookState("startup");
    LogC27931MidFilterProbeState("startup (v55 Enhanced stable path)");
    LogV46C27740SourcePairState("startup");
    LogV50LowriderCallerObservations("startup");
    LogV51C272A0OuterCallerObservations("startup");
    LogV52C26F00SourceIteratorCallerObservations("startup");
    LogEnhancedV93StructuralSemanticState("startup");
    LogV49OverlayClassificationState("startup (v81 retired downstream overlay classifier)");
    LogV78EnhancedReplayProbeState("startup");
    LogV79LateReplayState("startup before late replay");
    LogC27E80PreDiscardPairProbeState("startup (disabled in v55)");
    LogC2A390ExtractorProbeState("startup (disabled in v55)");
    Logf("[Info] Detected edition: %s", GetEditionTag(enhanced));
    Logf("[Info] getGameVersion()=%d", gameVersion);
    Logf("[Info] Logging=%s diagnostics=%s deepMemoryDiagnostics=%s garageDoorRecovery=%s experimentalMemoryPatch=%s experimentalInternalGroupAdd=%s experimentalMapStateReprocess=%s experimentalOverlayDescriptorRewrite=%s", g_logEnabled ? "on" : "off", g_diagnosticsEnabled ? "on" : "off", g_deepMemoryDiagnostics ? "on" : "off", g_bennysGarageDoorRecoveryEnabled ? "on" : "off", g_experimentalMemoryPatch ? "on" : "off", g_experimentalInternalGroupAdd ? "on" : "off", g_experimentalMapStateReprocess ? "on" : "off", g_experimentalOverlayDescriptorRewrite ? "on" : "off");
    Logf("[Info] Cross-build garage-door recovery is %s. It preloads the stock shutter model, keeps the original 15 m exterior approach trigger, closes after the player crosses into the workshop, and reopens only for an allowed current vehicle; it is not tied to a GTA build number.", g_bennysGarageDoorRecoveryEnabled ? "enabled" : "disabled");
    Logf("[Info] Garage-door vehicle policy mirrors BennysMotorworksRevamped.ini: AllowEmergencyVehicles=%s AllowServiceVehicles=%s AllowUtilityVehicles=%s AllowOversizedVehicles=%s; boats/cycles/helicopters/planes are always rejected and on-foot opening is disabled.", g_bennysAllowEmergencyVehicles ? "true" : "false", g_bennysAllowServiceVehicles ? "true" : "false", g_bennysAllowUtilityVehicles ? "true" : "false", g_bennysAllowOversizedVehicles ? "true" : "false");
    if (enhanced)
    {
        Logf("[Info] v100b tightened production integration is active. Enhanced Benny patching is limited to the verified C26F00 construction path; Legacy build-102 mutation behavior is unchanged; v99d/v98e read-only resolvers are retained for automatic failure diagnostics only.");
    }
    else
    {
        Logf("[Info] Legacy v104 enables the v98e universal resolver as a strictly gated one-shot construction path for older Legacy builds when the runtime layout, overlay row, descriptor vectors, derived vector, and construction ABI all match the proven Legacy fingerprint. Frozen build-102 v92/v77 and Enhanced behavior remain unchanged.");
        LogLegacyNaturalDescriptorState("startup");
        LogLegacyV59PostConstructionState("startup");
    }
    Logf("[Info] Target DLC:       %s -> 0x%08X", kDlcName, Joaat(kDlcName));
    Logf("[Info] Registered group: %s -> 0x%08X", kMapGroup, Joaat(kMapGroup));
    Logf("[Info] Story map group:  %s -> 0x%08X", kStoryMapGroup, Joaat(kStoryMapGroup));
    Logf("[Info] Target changeset: %s -> 0x%08X", kBennysChangeSet, Joaat(kBennysChangeSet));
    if (!enhanced && IsOlderLegacyLowridersBuild())
    {
        Logf("[Info] Older Legacy compatibility is active: Benny's seven known Lowriders IPLs may be requested once as a targeted fallback. Whole GROUP_MAP, ON_ENTER_MP, and ON_ENTER_SP remain disabled.");
    }
    else
    {
        Logf("[Info] This build intentionally does not call REQUEST_IPL, ON_ENTER_MP, ON_ENTER_SP, or EXECUTE_CONTENT_CHANGESET_GROUP_FOR_ALL(GROUP_MAP).");
    }
    DumpBuild1012OwnerGateState();
    if (enhanced)
        Logf("[Info] Enhanced safety: retired raw EXECUTE_CONTENT_CHANGESET is disabled because ScriptHookV cannot resolve it on this build.");

    WAIT(0);

    LogSetup2LoaderProbeState("after first script frame");
    LogConstructionC2F090HookState("after first script frame");
    LogC27931MidFilterProbeState("after first script frame (v55 Enhanced stable path)");
    LogV46C27740SourcePairState("after first script frame");
    LogV50LowriderCallerObservations("after first script frame");
    LogV51C272A0OuterCallerObservations("after first script frame");
    LogV52C26F00SourceIteratorCallerObservations("after first script frame");
    LogEnhancedV93StructuralSemanticState("after first script frame");
    LogV49OverlayClassificationState("after first script frame (v81 retired downstream overlay classifier)");
    LogV78EnhancedReplayProbeState("after first script frame before late replay");
    LogV79LateReplayState("after first script frame before late replay");

    if (enhanced && g_v79EnhancedLateReplayExperiment)
    {
        Logf("[EnhancedLateReplayV79] BEGIN: invoking the verified original C26F00 only after natural startup processing has completed. Expected precondition: Benny unavailable and naturalSuppressed=1.");
        const bool lateReplaySuccess =
            RunV79EnhancedLateC26F00Replay();
        Logf(
            "[EnhancedLateReplayV79] END success=%s. This is the SHVDN-timing proof: success means no original C25F4E startup race is required.",
            lateReplaySuccess ? "yes" : "no");
        LogV79LateReplayState("after late replay");
    }

    if (enhanced)
    {
        Logf(
            "[EnhancedSetup2V85] first-frame setup2{candidates=%ld injected=%ld restoreVerified=%ld restoreFailures=%ld sourceStoryBenny=%ld normalizedMapBenny=%ld} overlayinfo{active=no retired=yes v84WorkerCandidates=%ld v84Applied=%ld} downstream{GROUP_MAP+Benny=%ld GROUP_MAP_SP+Benny=%ld}.",
            static_cast<long>(g_v54DescriptorCandidateHits),
            static_cast<long>(g_v54DescriptorInjectedHits),
            static_cast<long>(g_v54DescriptorRestoreVerifiedHits),
            static_cast<long>(g_v55DescriptorRestoreFailureHits),
            static_cast<long>(g_v55SourceStoryBennyProducedHits),
            static_cast<long>(g_v55DownstreamMapBennyProducedHits),
            static_cast<long>(g_v84OverlayWorkerCandidateHits),
            static_cast<long>(g_v82OverlayAppliedHits),
            static_cast<long>(g_midFilterExactMapBennyHits),
            static_cast<long>(g_midFilterExactStoryBennyHits));
    }

    if (!enhanced)
    {
        LogLegacyNaturalDescriptorState("after first script frame");
        LogLegacyV59PostConstructionState("after first script frame");
    }
    LogC27E80PreDiscardPairProbeState("after first script frame (disabled in v55)");
    LogC2A390ExtractorProbeState("after first script frame (disabled in v55)");

    Logf(
        "[CallerLoopV50] first-frame summary totalCalls=%ld lowriderCalls=%ld triggerPairHits=%ld syntheticCalls=%ld C2F090{total=%ld add=%ld} C27931{total=%ld storyBenny=%ld}.",
        static_cast<long>(g_v46C27740TotalCalls),
        static_cast<long>(g_v46LowriderCalls),
        static_cast<long>(g_v46TriggerPairHits),
        static_cast<long>(g_v46SyntheticCalls),
        static_cast<long>(g_constructionHookTotalCalls),
        static_cast<long>(g_constructionHookAddCalls),
        static_cast<long>(g_midFilterTotalHits),
        static_cast<long>(g_midFilterExactStoryBennyHits));

    Logf(
        "[OuterLoopV51] first-frame summary c272Calls=%ld lowriderOutputs=%ld observations=%ld triggerCall=%ld callerReturn=%p callsite=%p.",
        static_cast<long>(
            g_v51C272A0TotalCalls),
        static_cast<long>(
            g_v51C272A0LowriderCalls),
        static_cast<long>(
            g_v51C272A0ObservationCount),
        static_cast<long>(
            g_v51TriggerGlobalCallNumber),
        reinterpret_cast<void*>(
            g_v51TriggerCallerReturn),
        reinterpret_cast<void*>(
            g_v51TriggerCallsite));

    Logf(
        "[NaturalPathV54] first-frame summary c26f00Calls=%ld lowriderInvocations=%ld observations=%ld triggerCall=%ld callerReturn=%p callsite=%p.",
        static_cast<long>(
            g_v52C26F00TotalCalls),
        static_cast<long>(
            g_v52C26F00LowriderCalls),
        static_cast<long>(
            g_v52C26F00ObservationCount),
        static_cast<long>(
            g_v52TriggerGlobalCallNumber),
        reinterpret_cast<void*>(
            g_v52TriggerCallerReturn),
        reinterpret_cast<void*>(
            g_v52TriggerCallsite));

    Logf(
        "[NaturalDescriptorV55] first-frame candidates=%ld alreadyPresent=%ld injected=%ld rejected=%ld writeFaults=%ld restoreAttempts=%ld restoreVerified=%ld restoreFailures=%ld sourceStoryBenny=%ld normalizedMapBenny=%ld storyAtMidFilter=%ld active=%ld lastChild=%p descriptorTable=%p count=%u->%u.",
        static_cast<long>(g_v54DescriptorCandidateHits),
        static_cast<long>(g_v54DescriptorAlreadyPresentHits),
        static_cast<long>(g_v54DescriptorInjectedHits),
        static_cast<long>(g_v54DescriptorRejectedHits),
        static_cast<long>(g_v55DescriptorWriteFaultHits),
        static_cast<long>(g_v54DescriptorRestoreAttempts),
        static_cast<long>(g_v54DescriptorRestoreVerifiedHits),
        static_cast<long>(g_v55DescriptorRestoreFailureHits),
        static_cast<long>(g_v55SourceStoryBennyProducedHits),
        static_cast<long>(g_v55DownstreamMapBennyProducedHits),
        static_cast<long>(g_v54ExactStoryBennyProducedHits),
        static_cast<long>(g_v54DescriptorActive),
        reinterpret_cast<void*>(g_v54LastChild),
        reinterpret_cast<void*>(g_v54LastOriginalDescriptorTable),
        static_cast<unsigned int>(g_v54LastOriginalDescriptorCount),
        static_cast<unsigned int>(g_v54LastTemporaryDescriptorCount));

    if (enhanced)
    {
        Logf(
            "[EnhancedReplayV78] first-frame totalC25F4ECallsiteHits=%ld lowriderOrdinal=%ld logicalBridgeResolves=%ld hookInstalled=%s failure=%lu(%s) v79LateReplayRetired=yes v55NaturalMutationRestored=yes.",
            static_cast<long>(g_v78C25F4ECallsiteTotalCalls),
            static_cast<long>(g_v78LowriderC25F4EOrdinal),
            static_cast<long>(g_v78LogicalBridgeResolveHits),
            g_v78C25F4ECallsiteHookInstalled ? "yes" : "no",
            static_cast<unsigned long>(g_v78C25F4ECallsiteFailureCode),
            GetV78C25F4ECallsiteFailureReason());
    }

    if (enhanced)
    {
        LogEnhancedV100IntegrationState(
            "first-frame live integration");
    }

    bool loaded = TryLoadBennysMap(false);

    LogSetup2LoaderProbeState("after initial diagnostics");
    LogConstructionC2F090HookState("after initial diagnostics");
    LogC27931MidFilterProbeState("after initial diagnostics (v55 Enhanced stable path)");
    LogV46C27740SourcePairState("after initial diagnostics");
    LogV50LowriderCallerObservations("after initial diagnostics");
    LogV51C272A0OuterCallerObservations("after initial diagnostics");
    LogV52C26F00SourceIteratorCallerObservations("after initial diagnostics");
    LogEnhancedV93StructuralSemanticState("after initial diagnostics");
    LogV78EnhancedReplayProbeState("after initial diagnostics");
    LogV79LateReplayState("after initial diagnostics");
    if (!enhanced)
    {
        LogLegacyNaturalDescriptorState("after initial diagnostics");
        LogLegacyV59PostConstructionState("after initial diagnostics");
        LogLegacyV61DescriptorState("after initial diagnostics (inactive in v63)");
    }
    LogC27E80PreDiscardPairProbeState("after initial diagnostics (disabled in v55)");
    LogC2A390ExtractorProbeState("after initial diagnostics (disabled in v55)");

    ResolveProductionStartupLog(
        enhanced,
        loaded,
        enhanced
            ? "Enhanced v100b tightened startup/mutation validation failed."
            : "Legacy startup path failed before a retryable/committed state.");

    const bool productionSuccess =
        IsProductionStartupSuccess(
            enhanced,
            loaded);

    if (g_showNotification)
    {
        if (productionSuccess)
            Notify("~b~~h~[ Benny's Map Loader ]~h~~w~  ~w~~h~Loaded~w~");
        else if (!enhanced
            && (IsLegacyV87ConstructionCommitted()
                || (IsOlderLegacyLowridersBuild()
                    && g_legacyV98OlderMutationCommitted)))
            Notify("~b~~h~[ Benny's Map Loader ]~h~~w~  Legacy content constructed - waiting for streaming");
        else if (!enhanced && g_legacyV87RetrySafe)
            Notify("~y~~h~[ Benny's Map Loader ]~h~~w~  Legacy startup not ready - retrying automatically");
        else if (!enhanced)
            Notify("~r~~h~[ Benny's Map Loader ]~h~~w~  Legacy stable load failed - check log");
        else
            Notify("~r~~h~[ Benny's Map Loader ]~h~~w~  Load failed - check BennysMapLoader.log");
    }

    ULONGLONG nextLegacyStableRetry =
        (!enhanced && !loaded && g_legacyV87RetrySafe)
            ? GetTickCount64() + 1000ULL
            : 0ULL;
    ULONGLONG nextPassiveProbe = 0;

    while (true)
    {
        WAIT(0);

        MaintainBennysGarageDoorRecovery(
            GetTickCount64());

        if (!enhanced
            && !loaded
            && g_legacyV87RetrySafe
            && !g_legacyV73.attempted
            && GetTickCount64() >= nextLegacyStableRetry)
        {
            const bool cachedOverlay =
                IsLegacyV87CachedStockOverlayReusable();

            nextLegacyStableRetry =
                GetTickCount64() + 1000ULL;
            ++g_legacyV87AutomaticRetryCount;

            Logf(
                "[LegacyStartupV92] automaticRetry #%u cachedOverlay=%s constructionLatched=no.",
                static_cast<unsigned int>(g_legacyV87AutomaticRetryCount),
                cachedOverlay ? "yes" : "no");

            loaded = TryLoadBennysMap(false);

            ResolveProductionStartupLog(
                false,
                loaded,
                "Legacy automatic retry reached a terminal frozen-path failure.");

            if (loaded && g_showNotification)
            {
                Notify(
                    "~b~~h~[ Benny's Map Loader ]~h~~w~  ~w~~h~Loaded after automatic Legacy retry~w~");
            }
        }

        if (!loaded && GetTickCount64() >= nextPassiveProbe)
        {
            nextPassiveProbe = GetTickCount64() + 1000ULL;
            BennysMapState state = CaptureBennysMapState();
            const bool passiveReady = IsOlderLegacyLowridersBuild()
                ? IsBennysMapReadyForOlderLegacy(state)
                : IsBennysMapAvailable(state);

            if (passiveReady)
            {
                loaded = true;
                ActivateBennysInterior(state);
                LogBennysMapState("[OK] Benny's map appeared after startup and was adopted.", state);

                ResolveProductionStartupLog(
                    enhanced,
                    loaded,
                    "Benny's map remained unavailable after startup.");
            }
        }
    }
}
